function renderOperationSummary() {
  const summary = state.operationSummary || { total: 0, today: 0, categories: [], actors: [] };
  const items = [
    ["今日操作", summary.today || 0, "实时记录"],
    ["累计记录", summary.total || 0, "最多保留 5,000 条"],
    ["涉及模块", summary.categories?.length || 0, "按模块筛选"],
    ["操作人员", summary.actors?.length || 0, "预留多角色账号"],
  ];
  document.querySelector("#operation-log-summary").innerHTML = items.map(([label, value, detail]) => `
    <div class="operation-summary-item"><span>${escapeHtml(label)}</span><strong>${escapeHtml(value)}</strong><small>${escapeHtml(detail)}</small></div>`).join("");
}

function renderOperationActorOptions() {
  const select = document.querySelector("#operation-actor-filter");
  const selected = select.value || "all";
  select.innerHTML = '<option value="all">全部操作人</option>' + (state.operationSummary?.actors || [])
    .map((actor) => `<option value="${escapeHtml(actor)}">${escapeHtml(actor)}</option>`).join("");
  if ([...select.options].some((option) => option.value === selected)) select.value = selected;
}

function operationMetadataText(metadata) {
  if (!metadata || typeof metadata !== "object") return "—";
  const pairs = Object.entries(metadata).filter(([, value]) => value !== null && value !== "" && value !== undefined).slice(0, 4);
  if (!pairs.length) return "—";
  return pairs.map(([key, value]) => `${key}: ${Array.isArray(value) ? value.join(", ") : String(value)}`).join(" · ");
}

function renderOperationTable() {
  const body = document.querySelector("#operation-log-table-body");
  if (!state.operationLogs.length) {
    body.innerHTML = '<tr><td colspan="6" class="question-table-empty">尚无符合条件的操作记录</td></tr>';
    return;
  }
  body.innerHTML = state.operationLogs.map((item) => `
    <tr>
      <td><div class="operation-time">${escapeHtml(formatTaskTime(item.createdAt))}<span>${escapeHtml(item.id.slice(-8))}</span></div></td>
      <td><div class="operation-target"><strong>${escapeHtml(item.actor)}</strong><span>${escapeHtml(item.actorRole)}${item.actorId ? ` · ${escapeHtml(String(item.actorId).slice(0, 18))}` : ""}</span></div></td>
      <td><div class="operation-target"><strong>${escapeHtml(operationCategoryLabels[item.category] || item.category)}</strong><span>${escapeHtml(operationActionLabels[item.action] || item.action)}</span></div></td>
      <td><div class="operation-target"><strong>${escapeHtml(item.targetType)}</strong><span>${escapeHtml(item.targetId || "—")}</span></div></td>
      <td class="operation-summary-copy">${escapeHtml(item.summary)}</td>
      <td class="operation-metadata">${escapeHtml(operationMetadataText(item.metadata))}</td>
    </tr>`).join("");
}

async function loadOperationLogs() {
  const query = new URLSearchParams({
    query: document.querySelector("#operation-search").value.trim(),
    category: document.querySelector("#operation-category-filter").value,
    actor: document.querySelector("#operation-actor-filter").value,
    limit: "200",
  });
  try {
    const payload = await requestJson(`/api/admin/operation-logs?${query}`);
    state.operationLogs = payload.items;
    state.operationSummary = payload.summary;
    renderOperationSummary();
    renderOperationActorOptions();
    renderOperationTable();
  } catch (error) {
    document.querySelector("#operation-log-table-body").innerHTML = `<tr><td colspan="6" class="question-table-empty">读取失败：${escapeHtml(friendlyError(error))}</td></tr>`;
  }
}

function questionOptionListHtml(options = [], variant = "") {
  const items = (Array.isArray(options) ? options : []).map((option, index) => {
    const value = option && typeof option === "object" ? option : { text: option };
    return {
      key: String(value.key || value.label || String.fromCharCode(65 + index)).trim(),
      text: String(value.text || value.content || "").trim(),
    };
  }).filter((option) => option.text);
  if (!items.length) return "";
  const className = ["question-option-list", variant].filter(Boolean).join(" ");
  return `<div class="${className}">${items.map((option) => `<div class="question-option-item"><b>${escapeHtml(option.key)}</b><span>${escapeHtml(option.text)}</span></div>`).join("")}</div>`;
}

function knowledgeInspectionQuestion(result = {}) {
  return result.question && typeof result.question === "object" ? result.question : {
    id: result.questionId,
    stem: result.stem,
    bookId: result.bookId,
    version: result.questionVersion,
    chapter: result.currentPath || result.currentKnowledgePath || result.chapter,
  };
}

function knowledgeInspectionAgent(result = {}, number) {
  if (number === 1) return result.agent1 || { features: result.agent1Features || null };
  if (number === 2 && Array.isArray(result.agent1Trajectories)) {
    return {
      trace: result.agent1Trajectories.flatMap((trajectory) => trajectory.steps || []),
      diagnostics: result.agent2NavigationDiagnostics || [],
      classificationOutcome: result.classificationOutcome || "",
      error: result.error || "",
    };
  }
  if (number === 2) return result.agent2 || result.classification || result.firstPass || {};
  return result.agent3 || result.agent3Verification || result.agent2Verification || result.verification || result.secondPass || {};
}

function knowledgeInspectionArray(value) {
  if (Array.isArray(value)) return value;
  if (value == null || value === "") return [];
  return [value];
}

function knowledgeInspectionPath(value) {
  if (Array.isArray(value)) return value.map((item) => typeof item === "string" ? item : (item.title || item.name || item.path || item.nodeId || "")).filter(Boolean).join(" > ");
  if (value && typeof value === "object") return value.path || value.knowledgePath || value.title || value.name || value.nodeId || "";
  return String(value || "");
}

function knowledgeInspectionSuggestedPath(result = {}) {
  const agent1 = knowledgeInspectionAgent(result, 2);
  const agent2 = knowledgeInspectionAgent(result, 3);
  return knowledgeInspectionPath(
    result.suggestedKnowledgePath || result.suggestedPath || result.targetKnowledgePath
      || agent2.primaryNode?.path || agent2.recommendedPath || agent2.knowledgePath || agent2.targetPath
      || agent1.recommendedPath || agent1.knowledgePath || agent1.targetPath,
  );
}

function knowledgeInspectionPrimaryNodeRole(result = {}) {
  const agent3 = knowledgeInspectionAgent(result, 3);
  return normalizeQuestionFingerprintPrimaryNodeRole(
    result.reviewSelection?.primaryNodeRole
      || agent3.primaryNodeRole
      || agent3.suggestion?.primaryNodeRole
      || agent3.verification?.primaryNodeRole,
  );
}

// structureNodes：调用方可以传"这道题该看的那棵树"的节点（2026-09-27）。
// 归属确认弹窗按题目自己的教材加载树，而题库页那棵树由另一个教材筛选驱动——不显式传就会用错册，
// 结论里的节点只能显示成裸 id。
function knowledgeInspectionRequiredNodes(result = {}, structureNodes = null) {
  const agent2 = knowledgeInspectionAgent(result, 3);
  const sourceNodes = Array.isArray(structureNodes) ? structureNodes : (state.knowledgeStructure?.nodes || []);
  const nodeMap = new Map(sourceNodes.map((node) => [node.id, node]));
  const supplied = knowledgeInspectionArray(agent2.requiredNodes);
  const nodes = supplied.length ? supplied.map((node) => ({
    id: String(node?.id || node?.nodeId || ""),
    path: knowledgeInspectionPath(node),
  })).filter((node) => node.id || node.path) : knowledgeInspectionArray(agent2.requiredNodeIds).map((id) => ({
    id: String(id),
    path: knowledgeInspectionPath(nodeMap.get(String(id))) || String(id),
  }));
  const primaryId = String(agent2.primaryNodeId || agent2.primaryNode?.id || "");
  const primaryNodeRole = knowledgeInspectionPrimaryNodeRole(result);
  if (primaryNodeRole === "core" && primaryId && !nodes.some((node) => node.id === primaryId)) {
    nodes.unshift({ id: primaryId, path: knowledgeInspectionPath(agent2.primaryNode || nodeMap.get(primaryId)) || knowledgeInspectionSuggestedPath(result) || primaryId });
  }
  return nodes.filter((node, index, items) => node.id
    && !(primaryNodeRole === "scope_anchor" && node.id === primaryId)
    && items.findIndex((item) => item.id === node.id) === index);
}

function knowledgeInspectionCurrentPath(result = {}) {
  const question = knowledgeInspectionQuestion(result);
  return knowledgeInspectionPath(result.currentKnowledgePath || result.currentPath || question.knowledgeFingerprint?.knowledgePath || question.chapter);
}

function knowledgeInspectionIssues(result = {}) {
  return knowledgeInspectionArray(result.issues || result.issueTypes || result.issue)
    .map((issue) => typeof issue === "string" ? issue : (issue.type || issue.code || issue.label || ""))
    .filter(Boolean);
}

function knowledgeInspectionStatus(result = {}) {
  return String(result.status || result.reviewStatus || "pending_review");
}

function knowledgeInspectionCanReview(result = {}) {
  return ["pending_review", "recommended", "completed", "ready_for_human"].includes(knowledgeInspectionStatus(result));
}

function knowledgeInspectionResolvedNodeId(result = {}) {
  const agent2 = knowledgeInspectionAgent(result, 3);
  return String(agent2.primaryNodeId || agent2.primaryNode?.id || "").trim();
}

function knowledgeInspectionApplyBlockReason(result = {}) {
  if (result.answerConflict) return "结构化答案与已核验答案冲突，请先编辑题目并重新巡检。";
  if (result.hasNewerResult) return "这是一条旧巡检记录，同一题已有更新建议，请打开最新建议。";
  if (!knowledgeInspectionCanReview(result)) return "这条巡检结果当前不能采纳。";
  if (!knowledgeInspectionResolvedNodeId(result)) return "本次巡检没有形成明确知识节点，不能直接采纳。请重新巡检，或先编辑题目和知识树。";
  return "";
}

function knowledgeInspectionCanApply(result = {}) {
  return !knowledgeInspectionApplyBlockReason(result);
}

