function selectedKnowledgeDossier() {
  return state.knowledgeDossiers.find((item) => item.id === state.selectedKnowledgeDossierId) || null;
}

function renderKnowledgeDossierSummary() {
  const summary = state.knowledgeDossierSummary || {};
  const metrics = [
    ["规范概念", summary.total || 0],
    ["已激活", summary.active || 0],
    ["待人工审核", summary.needsReview || 0],
    ["待审增量", summary.pendingDeltas || 0],
  ];
  document.querySelector("#knowledge-dossier-summary").innerHTML = metrics.map(([label, value]) => `
    <div class="knowledge-dossier-metric"><strong>${escapeHtml(value)}</strong><span>${escapeHtml(label)}</span></div>`).join("");
}

function renderKnowledgeDossierList() {
  const container = document.querySelector("#knowledge-dossier-list");
  if (!state.knowledgeDossiers.length) {
    container.innerHTML = `<div class="knowledge-dossier-empty">当前范围还没有知识档案。<br />可先编译，再逐份核验边界与证据。</div>`;
    return;
  }
  container.innerHTML = state.knowledgeDossiers.map((dossier) => {
    const locations = dossier.occurrences?.length || 0;
    return `<button class="${dossier.id === state.selectedKnowledgeDossierId ? "is-active" : ""}" type="button" data-knowledge-dossier-id="${escapeHtml(dossier.id)}">
      <strong>${escapeHtml(dossier.canonicalName)}</strong>
      <span>${escapeHtml(knowledgeDossierStatusLabels[dossier.status] || dossier.status)} · ${locations} 个教材位置 · v${escapeHtml(dossier.version || 1)}</span>
    </button>`;
  }).join("");
}

function knowledgeDossierReviewDecision(dossier, itemType, itemId, fallbackEvidenceChunkIds = []) {
  return (dossier.reviewDecisions || []).find((item) => item.itemType === itemType && item.itemId === itemId) || {
    itemType,
    itemId,
    status: "pending_review",
    note: "",
    evidenceChunkIds: fallbackEvidenceChunkIds,
  };
}

function knowledgeDossierEvidenceLibrary(dossier) {
  const evidenceById = new Map();
  const add = (chunkId, source = {}) => {
    const id = String(chunkId || "").trim();
    if (!id) return;
    const current = evidenceById.get(id) || { chunkId: id, excerpt: "", pdfPage: 0, printedPage: 0, path: "" };
    evidenceById.set(id, {
      chunkId: id,
      excerpt: current.excerpt || source.excerpt || "",
      pdfPage: current.pdfPage || source.pdfPage || source.pdfPageStart || 0,
      printedPage: current.printedPage || source.printedPage || source.printedPageStart || 0,
      path: current.path || source.path || "",
    });
  };
  (dossier.claims || []).forEach((claim) => (claim.evidence || []).forEach((item) => add(item.chunkId, item)));
  (dossier.occurrences || []).forEach((occurrence) => (occurrence.chunkIds || []).forEach((chunkId) => add(chunkId, occurrence)));
  return [...evidenceById.values()];
}

function knowledgeDossierFamilyRowHtml(family) {
  const actions = family.actions || [];
  const actionText = actions.length === 1 ? actions[0] : (actions.length ? actions.join(" / ") : "待补");
  const requiredKnowledge = (family.requiredKnowledge || []).map((item) => item.name || item.id).filter(Boolean);
  const textbookAnchors = (family.textbookAnchors?.length ? family.textbookAnchors : [family.textbookAnchor])
    .filter(Boolean)
    .map((item) => item.path || item.name || item.id)
    .filter(Boolean);
  return `<div class="knowledge-dossier-family-link">
    <strong>${escapeHtml(family.name || family.id)}</strong>
    <span>教材锚点：${escapeHtml(textbookAnchors.join("；") || family.knowledgePath || "未标注")}</span>
    <small>后台目录锚点：${escapeHtml(family.coreKnowledge?.name || "未标注")} · 覆盖知识：${escapeHtml(requiredKnowledge.join("、") || "未标注")}</small>
    <small>考查动作：${escapeHtml(actionText)} · ${escapeHtml(family.memberCount || 0)} 道题 · ${escapeHtml(questionFamilyStatusLabels[family.status] || family.status)}</small>
  </div>`;
}

function knowledgeDossierFamilyCoverageHtml(dossier) {
  const coverage = dossier.familyCoverage || {};
  const summary = coverage.summary || {};
  const confirmedFamilies = coverage.confirmedFamilies || [];
  const pendingFamilies = coverage.pendingFamilies || [];
  const familySets = coverage.familySets || [];
  const coveredMethods = coverage.coveredMethods || [];
  const gaps = coverage.gaps || [];
  const risks = coverage.risks || [];
  const familyMap = new Map([...confirmedFamilies, ...pendingFamilies].map((family) => [family.id, family]));
  const methodsHtml = coveredMethods.length ? coveredMethods.map((method) => {
    const familyNames = (method.familyIds || []).map((id) => familyMap.get(id)?.name || id);
    return `<div class="knowledge-dossier-derived-row"><strong>${escapeHtml(method.action)}</strong><span>${escapeHtml(familyNames.join("、"))}</span><small>${escapeHtml(method.familyCount || 0)} 个题族 · ${escapeHtml(method.questionCount || 0)} 道去重题目</small></div>`;
  }).join("") : '<span class="knowledge-dossier-inline-empty">尚无已确认且动作清晰的考法</span>';
  const familiesHtml = confirmedFamilies.length
    ? confirmedFamilies.map(knowledgeDossierFamilyRowHtml).join("")
    : '<span class="knowledge-dossier-inline-empty">当前概念尚无已确认题族</span>';
  const setsHtml = familySets.length ? familySets.map((familySet) => `<div class="knowledge-dossier-derived-row">
    <strong>${escapeHtml(familySet.setPath || familySet.name)}</strong>
    <span>${escapeHtml(familySet.knowledgePath || "未标注教材位置")}</span>
    <small>命中 ${escapeHtml((familySet.matchedFamilyIds || []).length)} 个对应题族 · 集内 ${escapeHtml(familySet.familyCount || 0)} 个题族 · ${escapeHtml(familySet.questionCount || 0)} 道去重题目</small>
  </div>`).join("") : '<span class="knowledge-dossier-inline-empty">对应题族尚未归入题族集</span>';
  const gapsHtml = gaps.length ? gaps.map((gap) => {
    if (gap.code === "family_action_unresolved") {
      return `<div class="knowledge-dossier-derived-row warning"><strong>${escapeHtml(gap.familyName || gap.familyId)}</strong><span>尚未形成统一考查动作</span></div>`;
    }
    return `<div class="knowledge-dossier-derived-row warning"><strong>${escapeHtml(gap.conceptName || dossier.canonicalName)}</strong><span>暂无已确认题族</span><small>${escapeHtml((gap.occurrencePaths || []).join(" · ") || "教材位置待核")}</small></div>`;
  }).join("") : '<span class="knowledge-dossier-inline-empty">当前未发现题库覆盖缺口</span>';
  const risksHtml = risks.length ? risks.map((risk) => {
    const family = familyMap.get(risk.familyId);
    const missingNames = (risk.missingActiveEvidenceNodeIds || []).map((nodeId) => family?.requiredKnowledge?.find((item) => item.id === nodeId)?.name || nodeId);
    return `<div class="knowledge-dossier-derived-row risk"><strong>${escapeHtml(risk.familyName || risk.familyId)}</strong><span>${escapeHtml((risk.riskCodes || []).map((code) => knowledgeDossierFamilyRiskLabels[code] || code).join("；"))}</span>${missingNames.length ? `<small>待补证据：${escapeHtml(missingNames.join("、"))}</small>` : ""}</div>`;
  }).join("") : '<span class="knowledge-dossier-inline-empty">当前未发现题族审核风险</span>';
  return `<section class="knowledge-dossier-family-coverage">
    <div class="knowledge-dossier-section-title"><strong>题族覆盖</strong><span>动态</span></div>
    <div class="knowledge-dossier-derived-metrics">
      <div><strong>${escapeHtml(summary.confirmedFamilyCount || 0)}</strong><span>已确认题族</span></div>
      <div><strong>${escapeHtml(summary.coveredMethodCount || 0)}</strong><span>已覆盖考法</span></div>
      <div><strong>${escapeHtml(summary.questionCount || 0)}</strong><span>去重题目</span></div>
      <div><strong>${escapeHtml(summary.gapCount || 0)}</strong><span>题库缺口</span></div>
      <div class="${summary.riskFamilyCount ? "has-risk" : ""}"><strong>${escapeHtml(summary.riskFamilyCount || 0)}</strong><span>审核风险</span></div>
    </div>
    <div class="knowledge-dossier-derived-grid">
      <details ${coveredMethods.length ? "open" : ""}><summary>已覆盖考法 · ${coveredMethods.length}</summary><div>${methodsHtml}</div></details>
      <details><summary>对应题族 · ${confirmedFamilies.length}${pendingFamilies.length ? `，另 ${pendingFamilies.length} 个未计入覆盖` : ""}</summary><div>${familiesHtml}</div></details>
      <details><summary>所属题族集 · ${familySets.length}</summary><div>${setsHtml}</div></details>
      <details ${!coveredMethods.length && gaps.length ? "open" : ""}><summary>题库缺口 · ${gaps.length}</summary><div>${gapsHtml}</div></details>
      <details><summary>审核风险 · ${risks.length}</summary><div>${risksHtml}</div></details>
    </div>
  </section>`;
}

function knowledgeDossierEvidenceBindingsHtml(dossier, decision, open = false) {
  const library = knowledgeDossierEvidenceLibrary(dossier);
  const selectedIds = new Set(decision.evidenceChunkIds || []);
  return `<details class="knowledge-dossier-evidence-bindings" ${open ? "open" : ""}>
    <summary>教材原文与证据绑定 ${selectedIds.size ? `· 已选 ${selectedIds.size} 份` : ""}</summary>
    <div>${library.length ? library.map((evidence) => `<label class="knowledge-dossier-evidence-option">
      <input type="checkbox" data-review-evidence value="${escapeHtml(evidence.chunkId)}" ${selectedIds.has(evidence.chunkId) ? "checked" : ""} />
      <span><strong>${escapeHtml(evidence.excerpt || "当前档案未保存该片段摘录")}</strong><small>片段 ${escapeHtml(evidence.chunkId)} · PDF ${escapeHtml(evidence.pdfPage || "-")} · 教材 ${escapeHtml(evidence.printedPage || "-")} 页${evidence.path ? ` · ${escapeHtml(evidence.path)}` : ""}</small></span>
    </label>`).join("") : `<span class="knowledge-dossier-inline-empty">当前档案还没有可绑定的教材证据</span>`}</div>
  </details>`;
}

function knowledgeDossierReviewDecisionsHtml(decision, compact = false) {
  const statuses = [
    ["approved", "通过"],
    ["insufficient_evidence", "证据不足"],
    ["rejected", "驳回"],
    ["pending_review", compact ? "待审核" : "恢复待审核"],
  ];
  return `<div class="knowledge-dossier-review-decisions" role="group" aria-label="审核结论">${statuses.map(([status, label]) => `<button class="${decision.status === status ? "is-selected" : ""}" type="button" data-dossier-review-status="${status}">${label}</button>`).join("")}</div>`;
}

function knowledgeDossierReviewSupportHtml(decision) {
  return `<div class="knowledge-dossier-review-support">
    <details class="knowledge-dossier-review-note"><summary>审核说明${decision.note ? " · 已填写" : ""}</summary><label><textarea data-review-note rows="2" placeholder="说明驳回、证据不足或修改依据">${escapeHtml(decision.note || "")}</textarea></label></details>
  </div>`;
}

function knowledgeDossierReviewFooterHtml(dossier, decision) {
  return `<div class="knowledge-dossier-review-footer">
    ${knowledgeDossierReviewDecisionsHtml(decision)}
    ${knowledgeDossierReviewSupportHtml(decision)}
  </div>`;
}

function knowledgeDossierClaimEvidenceHtml(claim) {
  const evidence = claim.evidence || [];
  return `<details class="knowledge-dossier-claim-evidence">
    <summary>${evidence.length} 份教材证据</summary>
    <div>${evidence.length ? evidence.map((item, index) => `<div class="knowledge-dossier-evidence-editor" data-evidence-index="${index}">
      <div class="knowledge-dossier-evidence-editor-head"><strong>证据 ${index + 1}</strong><button type="button" data-dossier-editor-action="remove-evidence" data-item-id="${escapeHtml(claim.id)}" data-index="${index}">移除</button></div>
      <div class="knowledge-dossier-evidence-meta">
        <label>片段 ID<input data-evidence-field="chunkId" value="${escapeHtml(item.chunkId || "")}" /></label>
        <label>PDF 页<input data-evidence-field="pdfPage" type="number" min="0" value="${escapeHtml(item.pdfPage || 0)}" /></label>
        <label>教材页<input data-evidence-field="printedPage" type="number" min="0" value="${escapeHtml(item.printedPage || 0)}" /></label>
      </div>
      <label>教材原文<textarea data-evidence-field="excerpt" rows="3">${escapeHtml(item.excerpt || "")}</textarea></label>
    </div>`).join("") : `<span class="knowledge-dossier-inline-empty">尚未关联教材证据</span>`}
      <button class="knowledge-dossier-add-inline" type="button" data-dossier-editor-action="add-evidence" data-item-id="${escapeHtml(claim.id)}">添加证据</button>
    </div>
  </details>`;
}

function knowledgeDossierReviewProgress(dossier) {
  const decisions = dossier.reviewDecisions || [];
  const approved = decisions.filter((item) => item.status === "approved").length;
  return { approved, total: decisions.length };
}

function knowledgeDossierTargetOptions(dossier, relation) {
  const targets = (state.knowledgeDossierRelationTargets || []).filter((item) => item.id !== dossier.id);
  const hasCurrent = !relation.targetDossierId || targets.some((item) => item.id === relation.targetDossierId);
  return `${relation.targetDossierId && !hasCurrent ? `<option value="${escapeHtml(relation.targetDossierId)}" selected>${escapeHtml(relation.targetName || relation.targetDossierId)}</option>` : ""}<option value="">请选择目标档案</option>${targets.map((item) => `<option value="${escapeHtml(item.id)}" data-target-name="${escapeHtml(item.canonicalName)}" ${item.id === relation.targetDossierId ? "selected" : ""}>${escapeHtml(item.canonicalName)} · ${escapeHtml(knowledgeDossierStatusLabels[item.status] || item.status)}</option>`).join("")}`;
}

function renderKnowledgeDossierDetail() {
  const container = document.querySelector("#knowledge-dossier-detail");
  const dossier = selectedKnowledgeDossier();
  if (!dossier) {
    container.innerHTML = `<div class="knowledge-dossier-empty">从左侧选择一份知识档案查看详情</div>`;
    return;
  }
  const verification = dossier.verification || {};
  const verificationCopy = verification.verifiedAt
    ? `引用覆盖 ${Math.round(Number(verification.evidenceCoverage || 0) * 100)}% · 声明${verification.claimsVerified ? "通过" : "未通过"} · 边界${verification.boundaryComplete ? "完整" : "待补"} · 来源角色${verification.sourceRolesClear ? "清晰" : "待核"}`
    : "尚未执行独立核验";
  const definitionDecision = knowledgeDossierReviewDecision(dossier, "definition", "definition");
  const boundaryItems = dossier.boundaryItems || [
    ...(dossier.inclusionCriteria || []).map((text, index) => ({ id: `legacy-inclusion-${index}`, kind: "inclusion", text })),
    ...(dossier.exclusionCriteria || []).map((text, index) => ({ id: `legacy-exclusion-${index}`, kind: "exclusion", text })),
  ];
  const claimChecks = new Map((verification.claimChecks || []).map((item) => [item.claimId, item]));
  const progress = knowledgeDossierReviewProgress(dossier);
  const rawDossier = { ...dossier };
  delete rawDossier.affectedFamilies;
  delete rawDossier.familyCoverage;
  container.innerHTML = `
    <div class="knowledge-dossier-detail-head">
      <div><strong>${escapeHtml(dossier.canonicalName)}</strong><div><span class="knowledge-dossier-status ${escapeHtml(dossier.status)}">${escapeHtml(knowledgeDossierStatusLabels[dossier.status] || dossier.status)}</span><span class="knowledge-dossier-review-progress">人工审核 ${progress.approved}/${progress.total}</span></div></div>
      <small>v${escapeHtml(dossier.version || 1)} · ${escapeHtml(formatTaskTime(dossier.updatedAt))}</small>
    </div>
    <form class="knowledge-dossier-form" id="knowledge-dossier-form">
      <section class="knowledge-dossier-basic">
        <div class="knowledge-dossier-section-title"><strong>基本信息</strong></div>
        <div class="knowledge-dossier-basic-grid">
          <label>规范概念名称<input name="canonicalName" value="${escapeHtml(dossier.canonicalName)}" required /></label>
          <label>别名<input name="aliases" value="${escapeHtml((dossier.aliases || []).join("、"))}" placeholder="用顿号或逗号分隔" /></label>
        </div>
      </section>
      ${knowledgeDossierFamilyCoverageHtml(dossier)}
      <section class="knowledge-dossier-review-unit status-${escapeHtml(definitionDecision.status)}" data-review-item data-review-item-type="definition" data-review-item-id="definition" data-review-status="${escapeHtml(definitionDecision.status)}">
        <div class="knowledge-dossier-review-head"><div><strong>概念定义</strong></div><em data-review-status-label>${escapeHtml(knowledgeDossierReviewStatusLabels[definitionDecision.status] || definitionDecision.status)}</em></div>
        <label>定义内容<textarea data-dossier-definition rows="3">${escapeHtml(dossier.definition || "")}</textarea></label>
        ${knowledgeDossierEvidenceBindingsHtml(dossier, definitionDecision)}
        ${knowledgeDossierReviewFooterHtml(dossier, definitionDecision)}
      </section>
      <section class="knowledge-dossier-review-section">
        <div class="knowledge-dossier-section-title"><strong>概念边界</strong></div>
        <div class="knowledge-dossier-boundary-groups">
          ${["inclusion", "exclusion"].map((kind) => `<div class="knowledge-dossier-boundary-group">
            <div class="knowledge-dossier-boundary-group-head"><strong>${kind === "inclusion" ? "纳入边界" : "排除边界"}</strong><button type="button" data-dossier-editor-action="add-boundary" data-kind="${kind}">添加一条</button></div>
            ${boundaryItems.filter((item) => item.kind === kind).map((item) => {
              const decision = knowledgeDossierReviewDecision(dossier, kind, item.id);
              return `<section class="knowledge-dossier-review-unit status-${escapeHtml(decision.status)}" data-review-item data-review-item-type="${kind}" data-review-item-id="${escapeHtml(item.id)}" data-review-status="${escapeHtml(decision.status)}" data-boundary-kind="${kind}">
                <div class="knowledge-dossier-review-head knowledge-dossier-boundary-review-head"><div><strong>${kind === "inclusion" ? "纳入" : "排除"}</strong></div><div class="knowledge-dossier-boundary-actions">${knowledgeDossierReviewDecisionsHtml(decision, true)}<button class="knowledge-dossier-remove" type="button" data-dossier-editor-action="remove-boundary" data-item-id="${escapeHtml(item.id)}">删除</button></div></div>
                <textarea data-boundary-text rows="2">${escapeHtml(item.text || "")}</textarea>
                ${knowledgeDossierEvidenceBindingsHtml(dossier, decision)}
                ${knowledgeDossierReviewSupportHtml(decision)}
              </section>`;
            }).join("") || `<span class="knowledge-dossier-inline-empty">尚未填写${kind === "inclusion" ? "纳入" : "排除"}边界</span>`}
          </div>`).join("")}
        </div>
      </section>
      <section class="knowledge-dossier-review-section">
        <div class="knowledge-dossier-section-title"><strong>事实声明</strong><button type="button" data-dossier-editor-action="add-claim">添加声明</button></div>
        <div class="knowledge-dossier-review-list">${(dossier.claims || []).map((claim, index) => {
          const evidenceIds = (claim.evidence || []).map((item) => item.chunkId).filter(Boolean);
          const decision = knowledgeDossierReviewDecision(dossier, "claim", claim.id, evidenceIds);
          const check = claimChecks.get(claim.id);
          return `<section class="knowledge-dossier-review-unit status-${escapeHtml(decision.status)}" data-review-item data-review-item-type="claim" data-review-item-id="${escapeHtml(claim.id)}" data-review-status="${escapeHtml(decision.status)}" data-dossier-claim>
            <div class="knowledge-dossier-review-head"><div><strong>事实 ${index + 1}</strong>${check ? `<span class="knowledge-dossier-agent-check ${check.supported ? "passed" : "failed"}">独立核验：${check.supported ? "支持" : "未支持"}${check.issue ? ` · ${escapeHtml(check.issue)}` : ""}</span>` : ""}</div><div><em data-review-status-label>${escapeHtml(knowledgeDossierReviewStatusLabels[decision.status] || decision.status)}</em><button class="knowledge-dossier-remove" type="button" data-dossier-editor-action="remove-claim" data-item-id="${escapeHtml(claim.id)}">删除</button></div></div>
            <textarea data-claim-statement rows="2">${escapeHtml(claim.statement || "")}</textarea>
            ${knowledgeDossierClaimEvidenceHtml(claim)}
            ${knowledgeDossierReviewFooterHtml(dossier, decision)}
          </section>`;
        }).join("") || `<span class="knowledge-dossier-inline-empty">尚未建立事实声明</span>`}</div>
      </section>
      <section class="knowledge-dossier-review-section">
        <div class="knowledge-dossier-section-title"><strong>概念关系</strong><button type="button" data-dossier-editor-action="add-relation">添加关系</button></div>
        <div class="knowledge-dossier-review-list">${(dossier.relations || []).map((relation, index) => {
          const decision = knowledgeDossierReviewDecision(dossier, "relation", relation.id, relation.evidenceChunkIds || []);
          const formalTypes = ["is_a", "part_of", "prerequisite_for", "supplements", "contrasts_with", "confusable_with"];
          return `<section class="knowledge-dossier-review-unit status-${escapeHtml(decision.status)}" data-review-item data-review-item-type="relation" data-review-item-id="${escapeHtml(relation.id)}" data-review-status="${escapeHtml(decision.status)}" data-dossier-relation>
            <div class="knowledge-dossier-review-head"><div><strong>关系 ${index + 1}</strong></div><div><em data-review-status-label>${escapeHtml(knowledgeDossierReviewStatusLabels[decision.status] || decision.status)}</em><button class="knowledge-dossier-remove" type="button" data-dossier-editor-action="remove-relation" data-item-id="${escapeHtml(relation.id)}">删除</button></div></div>
            <div class="knowledge-dossier-relation-grid">
              <label>关系类型<select data-relation-field="type">${!formalTypes.includes(relation.type) ? `<option value="${escapeHtml(relation.type)}" selected>${escapeHtml(knowledgeDossierRelationTypeLabels[relation.type] || relation.type)}</option>` : ""}${formalTypes.map((type) => `<option value="${type}" ${relation.type === type ? "selected" : ""}>${knowledgeDossierRelationTypeLabels[type]}</option>`).join("")}</select></label>
              <label>方向<select data-relation-field="direction">${Object.entries(knowledgeDossierDirectionLabels).map(([value, label]) => `<option value="${value}" ${relation.direction === value ? "selected" : ""}>${label}</option>`).join("")}</select></label>
              <label>目标档案<select data-relation-field="targetDossierId">${knowledgeDossierTargetOptions(dossier, relation)}</select></label>
              <label>目标名称<input data-relation-field="targetName" value="${escapeHtml(relation.targetName || "")}" /></label>
            </div>
            <label>关系依据<textarea data-relation-field="reason" rows="2">${escapeHtml(relation.reason || "")}</textarea></label>
            ${knowledgeDossierEvidenceBindingsHtml(dossier, decision)}
            ${knowledgeDossierReviewFooterHtml(dossier, decision)}
          </section>`;
        }).join("") || `<span class="knowledge-dossier-inline-empty">当前概念尚无正式关系</span>`}</div>
      </section>
      <details class="knowledge-dossier-occurrences">
        <summary>教材出现位置 · ${(dossier.occurrences || []).length} 处</summary>
        <div><div class="knowledge-dossier-occurrence-head"><button type="button" data-dossier-editor-action="add-occurrence">添加位置</button></div>
        ${(dossier.occurrences || []).map((occurrence, index) => `<section class="knowledge-dossier-occurrence-editor" data-dossier-occurrence data-occurrence-index="${index}">
          <div class="knowledge-dossier-occurrence-title"><strong>${escapeHtml(knowledgeDossierRoleLabels[occurrence.role] || occurrence.role)} · ${escapeHtml(occurrence.path || "未关联目录")}</strong><button type="button" data-dossier-editor-action="remove-occurrence" data-index="${index}">删除</button></div>
          <div class="knowledge-dossier-occurrence-grid">
            <label>目录节点 ID<input data-occurrence-field="nodeId" value="${escapeHtml(occurrence.nodeId || "")}" /></label>
            <label>目录路径<input data-occurrence-field="path" value="${escapeHtml(occurrence.path || "")}" /></label>
            <label>来源角色<select data-occurrence-field="role">${Object.entries(knowledgeDossierRoleLabels).map(([value, label]) => `<option value="${value}" ${occurrence.role === value ? "selected" : ""}>${label}</option>`).join("")}</select></label>
            <label>片段 ID（逗号分隔）<input data-occurrence-field="chunkIds" value="${escapeHtml((occurrence.chunkIds || []).join("、"))}" /></label>
            <label>PDF 起页<input type="number" min="0" data-occurrence-field="pdfPageStart" value="${escapeHtml(occurrence.pdfPageStart || 0)}" /></label>
            <label>PDF 止页<input type="number" min="0" data-occurrence-field="pdfPageEnd" value="${escapeHtml(occurrence.pdfPageEnd || 0)}" /></label>
            <label>教材起页<input type="number" min="0" data-occurrence-field="printedPageStart" value="${escapeHtml(occurrence.printedPageStart || 0)}" /></label>
            <label>教材止页<input type="number" min="0" data-occurrence-field="printedPageEnd" value="${escapeHtml(occurrence.printedPageEnd || 0)}" /></label>
          </div>
          <label>教材原文<textarea data-occurrence-field="excerpt" rows="3">${escapeHtml(occurrence.excerpt || "")}</textarea></label>
        </section>`).join("") || `<span class="knowledge-dossier-inline-empty">尚未关联教材目录位置</span>`}</div>
      </details>
      <details class="knowledge-dossier-verification"><summary>独立核验 · ${escapeHtml(verificationCopy)}</summary><div>${verification.verifierNotes ? `<span>${escapeHtml(verification.verifierNotes)}</span>` : ""}${verification.conflicts?.length ? `<span>未解决冲突：${escapeHtml(verification.conflicts.join("；"))}</span>` : ""}${verification.warnings?.length ? `<span>提醒：${escapeHtml(verification.warnings.join("；"))}</span>` : ""}</div></details>
      <details class="knowledge-dossier-advanced"><summary>高级：原始 JSON（只读）</summary><pre>${escapeHtml(JSON.stringify(rawDossier, null, 2))}</pre></details>
      <div class="knowledge-dossier-form-actions">
        <button class="secondary-action" type="button" data-dossier-action="archive">归档</button>
        <button class="secondary-action" type="button" data-dossier-action="verify">独立核验</button>
        <button class="secondary-action" type="submit">保存修改</button>
        <button class="primary-action" type="button" data-dossier-action="activate" ${dossier.status === "active" ? "disabled" : ""}>激活档案</button>
      </div>
    </form>`;
}

function renderKnowledgeDossierDeltas() {
  const section = document.querySelector("#knowledge-dossier-deltas");
  const container = document.querySelector("#knowledge-dossier-delta-list");
  section.hidden = !state.knowledgeDossierDeltas.length;
  if (!state.knowledgeDossierDeltas.length) {
    container.innerHTML = "";
    return;
  }
  container.innerHTML = state.knowledgeDossierDeltas.map((delta) => `
    <div class="knowledge-dossier-delta">
      <div><strong>${escapeHtml(delta.title)}</strong><span>${escapeHtml(delta.reason)}</span><small>${escapeHtml(delta.sourceAgent)} · ${escapeHtml(formatTaskTime(delta.createdAt))}</small></div>
      <div class="knowledge-dossier-delta-actions"><button class="secondary-action" type="button" data-dossier-delta-action="rejected" data-id="${escapeHtml(delta.id)}">拒绝</button><button class="primary-action" type="button" data-dossier-delta-action="applied" data-id="${escapeHtml(delta.id)}">采纳</button></div>
    </div>`).join("");
}

function renderKnowledgeDossiers() {
  const selectedNode = libraryWorkspace.dossierNode();
  document.querySelector("#knowledge-dossier-scope").textContent = selectedNode
    ? `当前范围：${selectedNode.path}`
    : "选择左侧目录，编译或审核该范围内的规范知识概念";
  document.querySelector("#compile-knowledge-dossiers").disabled = !selectedNode;
  renderKnowledgeDossierSummary();
  renderKnowledgeDossierList();
  renderKnowledgeDossierDetail();
  renderKnowledgeDossierDeltas();
}

let knowledgeDossierLoadSequence = 0;
async function loadKnowledgeDossiers() {
  const sequence = ++knowledgeDossierLoadSequence;
  const bookId = document.querySelector("#question-book-filter").value;
  if (!bookId || bookId === "all" || libraryWorkspace.needsDossierSelection()) {
    state.knowledgeDossiers = [];
    state.knowledgeDossierSummary = null;
    state.knowledgeDossierTreeSummary = null;
    state.knowledgeDossierDeltas = [];
    state.knowledgeDossierRelationTargets = [];
    renderKnowledgeDossiers();
    renderKnowledgeTree();
    if (libraryWorkspace.needsDossierSelection()) {
      document.querySelector("#knowledge-dossier-list").innerHTML = '<div class="knowledge-tree-empty">请先选择左侧高亮的档案节点；没有映射时可点击「映射编辑」。</div>';
    }
    return;
  }
  try {
    const params = new URLSearchParams({
      bookId,
      directory: "source",
      status: document.querySelector("#knowledge-dossier-status").value,
      query: document.querySelector("#knowledge-dossier-search").value.trim(),
    });
    if (libraryWorkspace.dossierNodeId()) params.set("nodeId", libraryWorkspace.dossierNodeId());
    const payload = await requestJson(`/api/admin/knowledge-dossiers?${params}`);
    if (sequence !== knowledgeDossierLoadSequence) return;
    state.knowledgeDossiers = payload.items || [];
    state.knowledgeDossierSummary = payload.summary || null;
    state.knowledgeDossierTreeSummary = payload.treeSummary || null;
    state.knowledgeDossierDeltas = payload.deltas || [];
    state.knowledgeDossierRelationTargets = payload.relationTargets || [];
    if (!state.knowledgeDossiers.some((item) => item.id === state.selectedKnowledgeDossierId)) {
      state.selectedKnowledgeDossierId = state.knowledgeDossiers[0]?.id || "";
    }
    renderKnowledgeDossiers();
    renderKnowledgeTree();
  } catch (error) {
    if (sequence !== knowledgeDossierLoadSequence) return;
    state.knowledgeDossierTreeSummary = null;
    renderKnowledgeTree();
    setKnowledgeDossierFeedback(`读取失败：${friendlyError(error)}`, "error");
  }
}

async function compileKnowledgeDossiers() {
  const bookId = document.querySelector("#question-book-filter").value;
  if (!bookId || bookId === "all" || !libraryWorkspace.dossierNodeId()) {
    setKnowledgeDossierFeedback("请先选择一本教材和左侧目录范围。", "error");
    return;
  }
  const button = document.querySelector("#compile-knowledge-dossiers");
  button.disabled = true;
  setKnowledgeDossierFeedback("正在从当前教材范围编译规范概念和逐条证据，请稍候。", "loading");
  try {
    const payload = await requestJson("/api/admin/knowledge-dossiers/compile", {
      method: "POST",
      body: JSON.stringify({ bookId, nodeId: libraryWorkspace.dossierNodeId(), directory: "source" }),
    });
    setKnowledgeDossierFeedback(`编译完成：新增 ${payload.dossiers?.length || 0} 份草稿，生成 ${payload.deltas?.length || 0} 条待审核增量。`);
    await loadKnowledgeDossiers();
  } catch (error) {
    setKnowledgeDossierFeedback(`编译失败：${friendlyError(error)}`, "error");
  } finally {
    button.disabled = false;
  }
}

function knowledgeDossierEditorId(prefix) {
  const token = window.crypto?.randomUUID?.() || `${Date.now()}-${Math.random().toString(16).slice(2)}`;
  return `${prefix}-${token}`;
}

function knowledgeDossierSplitValues(value) {
  return String(value || "").split(/[\r\n,，、]+/).map((item) => item.trim()).filter(Boolean);
}

function collectKnowledgeDossierEditor(form = document.querySelector("#knowledge-dossier-form")) {
  const dossier = selectedKnowledgeDossier();
  if (!dossier || !form) return null;
  const data = new FormData(form);
  const boundaryItems = [...form.querySelectorAll("[data-review-item][data-boundary-kind]")].map((unit) => ({
    id: unit.dataset.reviewItemId,
    kind: unit.dataset.boundaryKind,
    text: unit.querySelector("[data-boundary-text]")?.value.trim() || "",
  }));
  const claims = [...form.querySelectorAll("[data-dossier-claim]")].map((unit) => ({
    id: unit.dataset.reviewItemId,
    statement: unit.querySelector("[data-claim-statement]")?.value.trim() || "",
    evidence: [...unit.querySelectorAll("[data-evidence-index]")].map((row) => ({
      chunkId: row.querySelector('[data-evidence-field="chunkId"]')?.value.trim() || "",
      pdfPage: Number(row.querySelector('[data-evidence-field="pdfPage"]')?.value) || 0,
      printedPage: Number(row.querySelector('[data-evidence-field="printedPage"]')?.value) || 0,
      excerpt: row.querySelector('[data-evidence-field="excerpt"]')?.value.trim() || "",
    })),
  }));
  const occurrences = [...form.querySelectorAll("[data-dossier-occurrence]")].map((row) => ({
    nodeId: row.querySelector('[data-occurrence-field="nodeId"]')?.value.trim() || "",
    path: row.querySelector('[data-occurrence-field="path"]')?.value.trim() || "",
    role: row.querySelector('[data-occurrence-field="role"]')?.value || "mentions",
    chunkIds: knowledgeDossierSplitValues(row.querySelector('[data-occurrence-field="chunkIds"]')?.value),
    pdfPageStart: Number(row.querySelector('[data-occurrence-field="pdfPageStart"]')?.value) || 0,
    pdfPageEnd: Number(row.querySelector('[data-occurrence-field="pdfPageEnd"]')?.value) || 0,
    printedPageStart: Number(row.querySelector('[data-occurrence-field="printedPageStart"]')?.value) || 0,
    printedPageEnd: Number(row.querySelector('[data-occurrence-field="printedPageEnd"]')?.value) || 0,
    excerpt: row.querySelector('[data-occurrence-field="excerpt"]')?.value.trim() || "",
  }));
  const relations = [...form.querySelectorAll("[data-dossier-relation]")].map((unit) => ({
    id: unit.dataset.reviewItemId,
    type: unit.querySelector('[data-relation-field="type"]')?.value || "uncertain",
    targetDossierId: unit.querySelector('[data-relation-field="targetDossierId"]')?.value || "",
    targetName: unit.querySelector('[data-relation-field="targetName"]')?.value.trim() || "",
    direction: unit.querySelector('[data-relation-field="direction"]')?.value || "outgoing",
    reason: unit.querySelector('[data-relation-field="reason"]')?.value.trim() || "",
    evidenceChunkIds: [...unit.querySelectorAll("[data-review-evidence]:checked")].map((item) => item.value),
    status: unit.dataset.reviewStatus === "approved" ? "confirmed" : "pending_review",
  }));
  const claimEvidenceIds = new Map(claims.map((claim) => [claim.id, claim.evidence.map((item) => item.chunkId).filter(Boolean)]));
  const relationEvidenceIds = new Map(relations.map((relation) => [relation.id, relation.evidenceChunkIds]));
  const reviewDecisions = [...form.querySelectorAll("[data-review-item]")].map((unit) => {
    const itemType = unit.dataset.reviewItemType;
    const itemId = unit.dataset.reviewItemId;
    let evidenceChunkIds = [...unit.querySelectorAll("[data-review-evidence]:checked")].map((item) => item.value);
    if (itemType === "claim") evidenceChunkIds = claimEvidenceIds.get(itemId) || [];
    if (itemType === "relation") evidenceChunkIds = relationEvidenceIds.get(itemId) || [];
    return {
      itemType,
      itemId,
      status: unit.dataset.reviewStatus || "pending_review",
      note: unit.querySelector("[data-review-note]")?.value.trim() || "",
      evidenceChunkIds,
    };
  });
  return {
    canonicalName: String(data.get("canonicalName") || "").trim(),
    aliases: knowledgeDossierSplitValues(data.get("aliases")),
    definition: form.querySelector("[data-dossier-definition]")?.value.trim() || "",
    boundaryItems,
    inclusionCriteria: boundaryItems.filter((item) => item.kind === "inclusion").map((item) => item.text).filter(Boolean),
    exclusionCriteria: boundaryItems.filter((item) => item.kind === "exclusion").map((item) => item.text).filter(Boolean),
    claims,
    occurrences,
    relations,
    reviewDecisions,
  };
}

function replaceSelectedKnowledgeDossierDraft(patch) {
  const dossier = selectedKnowledgeDossier();
  if (!dossier) return;
  state.knowledgeDossiers = state.knowledgeDossiers.map((item) => item.id === dossier.id ? { ...item, ...patch } : item);
  renderKnowledgeDossierDetail();
}

function mutateKnowledgeDossierEditor(button) {
  const draft = collectKnowledgeDossierEditor();
  if (!draft) return;
  const action = button.dataset.dossierEditorAction;
  if (action === "add-boundary") {
    draft.boundaryItems.push({ id: knowledgeDossierEditorId("dossier-boundary"), kind: button.dataset.kind || "inclusion", text: "" });
  } else if (action === "remove-boundary") {
    draft.boundaryItems = draft.boundaryItems.filter((item) => item.id !== button.dataset.itemId);
    draft.reviewDecisions = draft.reviewDecisions.filter((item) => item.itemId !== button.dataset.itemId);
  } else if (action === "add-claim") {
    draft.claims.push({ id: knowledgeDossierEditorId("dossier-claim"), statement: "", evidence: [] });
  } else if (action === "remove-claim") {
    draft.claims = draft.claims.filter((item) => item.id !== button.dataset.itemId);
    draft.reviewDecisions = draft.reviewDecisions.filter((item) => item.itemId !== button.dataset.itemId);
  } else if (action === "add-relation") {
    draft.relations.push({ id: knowledgeDossierEditorId("dossier-relation"), type: "is_a", targetDossierId: "", targetName: "", direction: "outgoing", reason: "", evidenceChunkIds: [], status: "pending_review" });
  } else if (action === "remove-relation") {
    draft.relations = draft.relations.filter((item) => item.id !== button.dataset.itemId);
    draft.reviewDecisions = draft.reviewDecisions.filter((item) => item.itemId !== button.dataset.itemId);
  } else if (action === "add-occurrence") {
    draft.occurrences.push({ nodeId: "", path: "", role: "mentions", chunkIds: [], pdfPageStart: 0, pdfPageEnd: 0, printedPageStart: 0, printedPageEnd: 0, excerpt: "" });
  } else if (action === "remove-occurrence") {
    draft.occurrences.splice(Number(button.dataset.index), 1);
  } else if (action === "add-evidence") {
    draft.claims.find((item) => item.id === button.dataset.itemId)?.evidence.push({ chunkId: "", pdfPage: 0, printedPage: 0, excerpt: "" });
  } else if (action === "remove-evidence") {
    draft.claims.find((item) => item.id === button.dataset.itemId)?.evidence.splice(Number(button.dataset.index), 1);
  }
  draft.inclusionCriteria = draft.boundaryItems.filter((item) => item.kind === "inclusion").map((item) => item.text).filter(Boolean);
  draft.exclusionCriteria = draft.boundaryItems.filter((item) => item.kind === "exclusion").map((item) => item.text).filter(Boolean);
  replaceSelectedKnowledgeDossierDraft(draft);
}

function setKnowledgeDossierReviewStatus(unit, status) {
  if (!unit || !knowledgeDossierReviewStatusLabels[status]) return;
  Object.keys(knowledgeDossierReviewStatusLabels).forEach((value) => unit.classList.remove(`status-${value}`));
  unit.classList.add(`status-${status}`);
  unit.dataset.reviewStatus = status;
  const label = unit.querySelector("[data-review-status-label]");
  if (label) label.textContent = knowledgeDossierReviewStatusLabels[status];
  unit.querySelectorAll("[data-dossier-review-status]").forEach((button) => {
    button.classList.toggle("is-selected", button.dataset.dossierReviewStatus === status);
  });
  const detail = document.querySelector("#knowledge-dossier-detail");
  const units = [...detail.querySelectorAll("[data-review-item]")];
  const approved = units.filter((item) => item.dataset.reviewStatus === "approved").length;
  const progress = detail.querySelector(".knowledge-dossier-review-progress");
  if (progress) progress.textContent = `人工审核 ${approved}/${units.length}`;
}

function knowledgeDossierReviewUnitHasEvidence(unit) {
  if (unit.dataset.reviewItemType === "claim") {
    return [...unit.querySelectorAll('[data-evidence-field="chunkId"]')].some((input) => input.value.trim());
  }
  return Boolean(unit.querySelector("[data-review-evidence]:checked"));
}

function reviewKnowledgeDossierUnit(button) {
  const unit = button.closest("[data-review-item]");
  const status = button.dataset.dossierReviewStatus;
  if (!unit) return;
  if (status === "approved" && !knowledgeDossierReviewUnitHasEvidence(unit)) {
    setKnowledgeDossierFeedback("通过前请先为这一项关联至少一份教材证据。", "error");
    unit.querySelector(".knowledge-dossier-evidence-bindings, .knowledge-dossier-claim-evidence")?.setAttribute("open", "");
    return;
  }
  setKnowledgeDossierReviewStatus(unit, status);
  setKnowledgeDossierFeedback("审核结论已在当前页面更新，保存后正式生效。", "");
}

function updateKnowledgeDossierRelationField(target) {
  const unit = target.closest("[data-dossier-relation]");
  if (!unit) return;
  if (target.matches('[data-relation-field="targetDossierId"]')) {
    const option = target.selectedOptions?.[0];
    const nameInput = unit.querySelector('[data-relation-field="targetName"]');
    if (nameInput && option?.dataset.targetName) nameInput.value = option.dataset.targetName;
  }
  if (target.matches('[data-relation-field="type"]')) {
    const direction = unit.querySelector('[data-relation-field="direction"]');
    if (["contrasts_with", "confusable_with"].includes(target.value)) direction.value = "bidirectional";
    else if (direction.value === "bidirectional") direction.value = "outgoing";
  }
}

async function persistKnowledgeDossier(status = "") {
  const dossier = selectedKnowledgeDossier();
  const draft = collectKnowledgeDossierEditor();
  if (!dossier || !draft) return null;
  const nextStatus = status || (dossier.status === "active" ? "needs_review" : dossier.status);
  return requestJson(`/api/admin/knowledge-dossiers/${encodeURIComponent(dossier.id)}`, {
    method: "PUT",
    body: JSON.stringify({ ...draft, status: nextStatus }),
  });
}

async function saveKnowledgeDossier(event) {
  event.preventDefault();
  try {
    const payload = await persistKnowledgeDossier();
    if (!payload) return;
    state.selectedKnowledgeDossierId = payload.dossier.id;
    setKnowledgeDossierFeedback("逐项修改和审核结论已保存。", "");
    await loadKnowledgeDossiers();
  } catch (error) {
    setKnowledgeDossierFeedback(`保存失败：${friendlyError(error)}`, "error");
  }
}

async function actOnKnowledgeDossier(action) {
  const dossier = selectedKnowledgeDossier();
  if (!dossier) return;
  const button = document.querySelector(`[data-dossier-action="${action}"]`);
  if (button) button.disabled = true;
  try {
    if (action === "verify") {
      setKnowledgeDossierFeedback("独立核验 Agent 正在逐条检查引用和边界。", "loading");
      await requestJson(`/api/admin/knowledge-dossiers/${encodeURIComponent(dossier.id)}/verify`, { method: "POST", body: "{}" });
      setKnowledgeDossierFeedback("独立核验完成，请查看核验结论。", "");
    } else {
      const status = action === "activate" ? "active" : "archived";
      if (action === "activate" && !window.confirm("确认激活这份知识档案吗？激活后可作为后续检索和教研依据。")) return;
      if (action === "activate") await persistKnowledgeDossier(status);
      else await requestJson(`/api/admin/knowledge-dossiers/${encodeURIComponent(dossier.id)}`, {
        method: "PUT",
        body: JSON.stringify({ status }),
      });
      setKnowledgeDossierFeedback(action === "activate" ? "知识档案已激活。" : "知识档案已归档。", "");
    }
    await loadKnowledgeDossiers();
  } catch (error) {
    const detail = error?.payload?.details?.problems?.length
      ? `（${error.payload.details.problems.map((problem) => errorMessages[problem] || problem).join("；")}）`
      : "";
    setKnowledgeDossierFeedback(`操作失败：${friendlyError(error)}${detail}`, "error");
  } finally {
    if (button) button.disabled = false;
  }
}

async function reviewKnowledgeDossierDelta(id, decision) {
  try {
    await requestJson(`/api/admin/knowledge-dossier-deltas/${encodeURIComponent(id)}/review`, {
      method: "POST",
      body: JSON.stringify({ decision }),
    });
    setKnowledgeDossierFeedback(decision === "applied" ? "增量建议已采纳并写入待核档案。" : "增量建议已拒绝。", "");
    await loadKnowledgeDossiers();
  } catch (error) {
    setKnowledgeDossierFeedback(`审核失败：${friendlyError(error)}`, "error");
  }
}

function renderKnowledgeInspectionSummary() {
  const summary = state.knowledgeInspectionSummary || {};
  const results = state.knowledgeInspectionResults;
  const value = (keys, fallback) => {
    for (const key of keys) if (summary[key] != null) return summary[key];
    return fallback;
  };
  // DEC-100（产品手册 §4.6.12）：记录状态四态的口径来自 summary.auditReviewCounts；
  // 后端还没提供该字段时降级显示 0（不报错），也不再回落到已废止的旧人工结论计数。
  const auditCounts = summary.auditReviewCounts && typeof summary.auditReviewCounts === "object" ? summary.auditReviewCounts : {};
  const auditCount = (auditState) => (Number.isFinite(Number(auditCounts[auditState])) ? Number(auditCounts[auditState]) : 0);
  const recordMetrics = ["pending_review", "reviewed", "repaired", "ignored"].map((auditState) => ({
    auditState,
    label: knowledgeInspectionAuditStateLabels[auditState],
    hint: knowledgeInspectionAuditStateHints[auditState],
    count: auditCount(auditState),
  }));
  // 「正在巡检」「高风险」保留为过程／风险展示，不是记录状态。
  const processMetrics = [
    { label: "正在巡检", hint: "过程：Agent 1–3 是否还在跑", count: value(["running", "inProgress"], results.filter((item) => knowledgeInspectionStatus(item).includes("running")).length) },
    { label: "高风险", hint: "风险展示：问题的影响面", count: value(["highRisk", "high"], results.filter((item) => item.risk === "high").length) },
  ];
  // 确定性体检项（DEC-100）：summary.ruleFindingsByCode 是 code→计数，summary.ruleFindingsPassed 是通过留档的行数。
  // 中文标题从后端下发的词表取（前端不另写一份 map，见 AGENTS §5）；两个字段都缺失时整组不渲染，不留空壳。
  const ruleCountsByCode = summary.ruleFindingsByCode && typeof summary.ruleFindingsByCode === "object" ? summary.ruleFindingsByCode : {};
  const ruleCounts = Object.entries(ruleCountsByCode)
    .map(([code, count]) => ({ code, count: Number.isFinite(Number(count)) ? Number(count) : 0 }))
    .filter((item) => item.count > 0);
  const rulePassed = Number.isFinite(Number(summary.ruleFindingsPassed)) ? Number(summary.ruleFindingsPassed) : null;
  // 没体检成的书：后端给 summary.ruleFindingsUnavailable = { reason, books }——必须在摘要里说得出来，
  // 否则"未体检"会看起来像"没有数据"甚至"通过"。
  const ruleUnavailable = summary.ruleFindingsUnavailable && typeof summary.ruleFindingsUnavailable === "object" ? summary.ruleFindingsUnavailable : null;
  const ruleUnavailableBooks = ruleUnavailable && Array.isArray(ruleUnavailable.books) ? ruleUnavailable.books.map((book) => String(book || "")).filter(Boolean) : [];
  const hasRuleMetricCards = ruleCounts.length > 0 || rulePassed != null;
  const hasRuleFindings = hasRuleMetricCards || Boolean(ruleUnavailable);
  const ruleGroup = !hasRuleFindings ? "" : `
    <div class="knowledge-inspection-metric-group is-rule-findings">
      <span class="knowledge-inspection-metric-group-label">确定性体检项<small>服务端规则算出，与 AI 结论分开</small></span>
      ${hasRuleMetricCards ? `<div class="knowledge-inspection-metric-row is-rule-findings">
        ${ruleCounts.map((item) => `<div class="knowledge-inspection-metric is-rule" data-rule-code="${escapeHtml(item.code)}" title="${escapeHtml(knowledgeInspectionRuleFindingTitleByCode(item.code))}"><strong>${escapeHtml(item.count)}</strong><span>${escapeHtml(knowledgeInspectionRuleFindingTitleByCode(item.code))}</span><small>规则项 · ${escapeHtml(item.code)}</small></div>`).join("")}
        ${rulePassed == null ? "" : `<div class="knowledge-inspection-metric is-rule is-pass" data-rule-code="confirmed"><strong>${escapeHtml(rulePassed)}</strong><span>通过留档</span><small>无规则项命中 · 已留档</small></div>`}
      </div>` : ""}
      ${ruleUnavailable ? `<p class="knowledge-inspection-rule-findings-unavailable">有${ruleUnavailableBooks.length ? escapeHtml(ruleUnavailableBooks.length) : "若干"}本教材没体检成（<b>未体检 ≠ 通过</b>）：${escapeHtml(String(ruleUnavailable.reason || "该教材还没有可检索的正文／知识结构"))}${ruleUnavailableBooks.length ? `（${escapeHtml(ruleUnavailableBooks.join("、"))}）` : ""}</p>` : ""}
    </div>`;
  document.querySelector("#knowledge-inspection-summary").innerHTML = `
    <div class="knowledge-inspection-metric-group">
      <span class="knowledge-inspection-metric-group-label">记录状态<small>人工处理进度，只有这四态</small></span>
      <div class="knowledge-inspection-metric-row">${recordMetrics.map((metric) => `
        <div class="knowledge-inspection-metric is-record" data-audit-state="${escapeHtml(metric.auditState)}"><strong>${escapeHtml(metric.count || 0)}</strong><span>${escapeHtml(metric.label)}</span><small>${escapeHtml(metric.hint)}</small></div>
      `).join("")}</div>
    </div>
    <div class="knowledge-inspection-metric-group is-process">
      <span class="knowledge-inspection-metric-group-label">过程与风险<small>不是记录状态</small></span>
      <div class="knowledge-inspection-metric-row is-process">${processMetrics.map((metric) => `
        <div class="knowledge-inspection-metric is-process"><strong>${escapeHtml(metric.count || 0)}</strong><span>${escapeHtml(metric.label)}</span><small>${escapeHtml(metric.hint)}</small></div>
      `).join("")}</div>
    </div>
    ${ruleGroup}
  `;
}

function setKnowledgeInspectionFeedback(message = "", tone = "") {
  const element = document.querySelector("#knowledge-inspection-feedback");
  element.hidden = !message;
  element.textContent = message;
  element.className = `knowledge-inspection-feedback${tone ? ` ${tone}` : ""}`;
}

function renderKnowledgeInspectionJob() {
  const element = document.querySelector("#knowledge-inspection-job");
  const job = state.knowledgeInspectionJob;
  if (!job) {
    element.hidden = true;
    return;
  }
  const total = Math.max(1, Number(job.total || job.questionCount || 1));
  const agent1Processed = Math.max(0, Number(job.agent1Processed ?? job.agent1Completed ?? 0));
  const agent2Processed = Math.max(0, Number(job.agent2Processed ?? job.agent2Completed ?? 0));
  const completedUnits = Math.min(total * 2, agent1Processed + agent2Processed);
  const status = String(job.status || "queued");
  const stage = String(job.stage || job.currentStage || "");
  const reviewReady = Math.max(0, Number(job.reviewReady || 0));
  const agent2Queued = Math.max(0, Number(job.agent2Queued || 0));
  const agent1Position = job.agent1CurrentQuestionIndex
    ? `Agent 1→2：第 ${job.agent1CurrentQuestionIndex}/${total} 题${job.agent1CurrentDepth ? ` · 第 ${job.agent1CurrentDepth} 层` : ""}`
    : `Agent 1→2：${agent1Processed}/${total}`;
  const agent2Position = job.agent2CurrentQuestionIndex
    ? `Agent 3：第 ${job.agent2CurrentQuestionIndex}/${total} 题`
    : `Agent 3：${agent2Processed}/${total}`;
  const stageLabels = { pipeline: `${agent1Position}；${agent2Position}`, agent1: "Agent 1 正在提取特征，随后交给 Agent 2 分层归类", agent2: "Agent 3 正在核验教材与题族", finalizing: "正在整理待审建议" };
  const label = stageLabels[stage] || job.progressMessage || knowledgeInspectionStatusLabels[status] || "正在生成巡检建议";
  element.hidden = false;
  element.innerHTML = `<strong>${escapeHtml(label)}</strong><progress max="${escapeHtml(total * 2)}" value="${escapeHtml(completedUnits)}"></progress><span aria-label="Agent 1 到 Agent 2 ${escapeHtml(agent1Processed)} · Agent 3 ${escapeHtml(agent2Processed)}">Agent 1→2 ${escapeHtml(agent1Processed)}/${escapeHtml(total)} · Agent 3 ${escapeHtml(agent2Processed)}/${escapeHtml(total)}${agent2Queued ? ` · 队列 ${escapeHtml(agent2Queued)}` : ""}${reviewReady ? ` · 已可审核 ${escapeHtml(reviewReady)}` : ""}${job.failed ? ` · 失败 ${escapeHtml(job.failed)}` : ""}${job.error ? ` · ${escapeHtml(friendlyError(job.error))}` : ""}</span>`;
}

function renderKnowledgeInspectionTable() {
  const body = document.querySelector("#knowledge-inspection-table-body");
  if (!state.knowledgeInspectionResults.length) {
    body.innerHTML = '<tr><td colspan="5" class="question-table-empty">当前筛选下没有巡检建议。启动巡检后，AI 建议会在这里等待人工确认。</td></tr>';
    return;
  }
  body.innerHTML = state.knowledgeInspectionResults.map((result) => {
    const question = knowledgeInspectionQuestion(result);
    const status = knowledgeInspectionStatus(result);
    // DEC-100（产品手册 §4.6.12）：列表状态列显示的是**记录状态四态**（auditReview.state）；
    // 过程状态（正在巡检／过期／失败）与「题目已变更、旧结论作废」另起徽标，避免把过程当记录状态。
    const audit = knowledgeInspectionAuditReview(result);
    const isProcessStatus = ["queued", "running", "agent1_running", "agent2_running", "processing", "stale", "failed", "interrupted"].includes(status);
    const risk = String(result.risk || result.riskLevel || "medium");
    const issues = knowledgeInspectionIssues(result);
    const suggestedPath = knowledgeInspectionSuggestedPath(result);
    const requiredNodes = knowledgeInspectionRequiredNodes(result);
    const agreement = result.agreement === true || result.consensus === true
      ? "Agent 2 与 Agent 3 意见一致"
      : (result.agreement === false || result.hasDisagreement ? "Agent 2 与 Agent 3 存在分歧" : "等待人工综合判断");
    return `<tr>
      <td><div class="knowledge-inspection-question-cell"><strong>${escapeHtml(question.stem || "题目内容暂不可用")}</strong>${questionOptionListHtml(question.options, "compact")}<span>${escapeHtml(question.id || result.questionId || "")} · ${escapeHtml(questionBookName(question.bookId || result.bookId || ""))}${question.version ? ` · v${escapeHtml(question.version)}` : ""}</span><small>当前：${escapeHtml(knowledgeInspectionCurrentPath(result) || "未归属")}</small></div></td>
      <td><div class="knowledge-inspection-suggestion-cell"><strong>${escapeHtml(suggestedPath || "尚未形成明确建议")}</strong>${requiredNodes.length > 1 ? `<span class="knowledge-inspection-required-summary">最小充分知识集 ${requiredNodes.length} 项</span><small>${escapeHtml(requiredNodes.map((node) => node.path).join(" · "))}</small>` : ""}<span class="knowledge-inspection-source-tag is-ai">AI</span><span>${escapeHtml(agreement)}</span><small>只诊断不改库：采纳与改库请在「完善题目」里完成</small></div></td>
      <td><div class="knowledge-inspection-tags"><span class="risk ${escapeHtml(risk)}">${escapeHtml(knowledgeInspectionRiskLabels[risk] || risk)}</span>${issues.map((issue) => `<span>${escapeHtml(knowledgeInspectionIssueLabel(issue, issue === result.issue ? result.issueLabel : ""))}</span>`).join("") || "<span>知识归类复核</span>"}</div>${knowledgeInspectionRuleFindingsHtml(result)}</td>
      <td><div class="knowledge-inspection-state"><span class="${escapeHtml(audit.state)}">${escapeHtml(knowledgeInspectionAuditStateLabels[audit.state])}</span>${audit.invalidated ? '<span class="knowledge-inspection-invalidated-flag">题目已变更，旧结论作废</span>' : ""}${isProcessStatus ? `<span class="${escapeHtml(status)}">${escapeHtml(knowledgeInspectionStatusLabels[status] || status)}</span>` : ""}<small>${escapeHtml(audit.at ? `${knowledgeInspectionAuditActorLabel(audit) || "人工"} · ${formatTaskTime(audit.at)}` : formatTaskTime(result.updatedAt || result.createdAt))}</small></div></td>
      <td><button class="secondary-action" data-knowledge-inspection-action="review" data-question-id="${escapeHtml(question.id || result.questionId || "")}" data-result-id="${escapeHtml(result.id || result.resultId || "")}" type="button">${result.isHistoricalRecord ? "查看旧记录" : (result.answerConflict ? "查看冲突" : "查看结论")}</button></td>
    </tr>`;
  }).join("");
}

function blindGoldReviewUiResult(result) {
  return result === "confirmed" ? "confirmed_current" : (result || "pending_review");
}

function blindGoldReviewApiResult(result) {
  return result === "confirmed_current" ? "confirmed" : result;
}

const blindGoldV1RevisionRiskSeeds = [
  { order: 5, requiredStages: ["family"], reason: "题族事实与成员一致性需要重新核对" },
  { order: 6, requiredStages: ["family"], reason: "核心知识或最小充分知识与题族定义不一致，统一预检追加" },
  { order: 7, requiredStages: ["family"], reason: "核心知识或最小充分知识与题族定义不一致，统一预检追加" },
  { order: 8, requiredStages: ["family"], reason: "冻结题族状态与金标裁决需要重新核对" },
  { order: 9, requiredStages: ["family"], reason: "核心知识或最小充分知识与题族定义不一致，统一预检追加" },
  { order: 10, requiredStages: ["family"], reason: "成熟题族缺少冻结留存成员，且题族状态需要重新核对" },
  { order: 11, requiredStages: ["family"], reason: "核心知识或最小充分知识与题族定义不一致，统一预检追加" },
  { order: 12, requiredStages: ["family"], reason: "成熟题族缺少冻结留存成员，且题族状态需要重新核对" },
  { order: 14, requiredStages: ["family"], reason: "冻结题族仍处于待审核状态" },
  { order: 15, requiredStages: ["family"], reason: "冻结题族仍处于待审核状态" },
  { order: 16, requiredStages: ["family"], reason: "冻结题族仍处于待审核状态" },
];

function blindGoldReviewIsRevisionBatch(batch = state.blindGoldReviewBatch) {
  return Boolean(batch?.source?.parentReviewBatchId || batch?.source?.parentBatchId
    || batch?.parentBatchId || batch?.revisionOfBatchId);
}

function blindGoldRevisionRequiredStages(item = {}, batch = state.blindGoldReviewBatch) {
  const revisionReview = item.revisionReview || item.revisionScope || item.reReview || {};
  const sourceRiskIds = batch?.source?.riskQuestionIds || batch?.revisionReview?.riskQuestionIds || [];
  const rawStages = revisionReview.requiredStages || item.requiredReviewStages || item.reReviewRequiredStages || [];
  const stages = new Set((Array.isArray(rawStages) ? rawStages : [rawStages]).map((stage) => {
    const value = String(stage || "").toLowerCase();
    if (value.includes("content") || value.includes("knowledge") || value.includes("answer")) return "content";
    if (value.includes("family")) return "family";
    return "";
  }).filter(Boolean));
  if (revisionReview.contentRequired || item.requiresContentReview) stages.add("content");
  if (revisionReview.familyRequired || item.requiresFamilyReview) stages.add("family");
  if (!stages.size && sourceRiskIds.includes(item.questionId)) stages.add("family");
  return [...stages];
}

function blindGoldRevisionItemIsInherited(item = {}, batch = state.blindGoldReviewBatch) {
  if (!blindGoldReviewIsRevisionBatch(batch)) return false;
  const revisionReview = item.revisionReview || item.revisionScope || item.reReview || {};
  if (revisionReview.inherited === false || revisionReview.status === "requires_review") return false;
  return blindGoldRevisionRequiredStages(item, batch).length === 0;
}

function blindGoldReviewItemIsReadOnly(item = selectedBlindGoldReviewItem(), batch = state.blindGoldReviewBatch) {
  return batch?.status === "frozen" || blindGoldRevisionItemIsInherited(item, batch);
}

function blindGoldRevisionNextVersion(version = "V1") {
  const number = Number(String(version || "").match(/(\d+)/)?.[1]) || 1;
  return `V${number + 1}`;
}

function blindGoldRevisionTitle(batch, version) {
  const base = String(batch?.title || "20题盲测金标集").replace(/\s*V\d+\s*$/i, "");
  return `${base}${version}`;
}

function blindGoldRevisionRisks(batch = state.blindGoldReviewBatch) {
  if (!batch) return [];
  const supplied = batch.revisionRisks || batch.revisionReview?.risks || batch.snapshot?.revisionRisks
    || batch.executionEligibility?.risks || [];
  let source = Array.isArray(supplied) && supplied.length
    ? supplied
    : (String(batch.version || "").toUpperCase() === "V1" ? blindGoldV1RevisionRiskSeeds : []);

  // Frozen revision batches keep the risk contract under revisionReview rather
  // than duplicating a UI-only revisionRisks field. Derive the visible list from
  // those immutable audit facts so a frozen parent can still open its V3 draft.
  if (!source.length && blindGoldReviewIsRevisionBatch(batch)) {
    const review = batch.revisionReview || {};
    const issueByQuestionId = new Map();
    (Array.isArray(review.qualificationIssues) ? review.qualificationIssues : []).forEach((issue) => {
      const questionId = String(issue?.questionId || "").trim();
      if (!questionId) return;
      if (!issueByQuestionId.has(questionId)) issueByQuestionId.set(questionId, []);
      issueByQuestionId.get(questionId).push(issue);
    });
    const riskIds = [
      ...(Array.isArray(review.reopenedQuestionIds) ? review.reopenedQuestionIds : []),
      ...(Array.isArray(review.requestedRiskQuestionIds) ? review.requestedRiskQuestionIds : []),
      ...(Array.isArray(batch.source?.riskQuestionIds) ? batch.source.riskQuestionIds : []),
    ].map((questionId) => String(questionId || "").trim()).filter(Boolean);
    const uniqueRiskIds = [...new Set(riskIds)];
    source = uniqueRiskIds.map((questionId) => {
      const issues = issueByQuestionId.get(questionId) || [];
      const stages = [...new Set(issues.flatMap((issue) => (
        Array.isArray(issue?.requiredStages) ? issue.requiredStages : []
      )))].filter(Boolean);
      const reason = [...new Set(issues.map((issue) => String(issue?.message || issue?.label || "").trim()).filter(Boolean))]
        .slice(0, 3).join("；");
      return {
        questionId,
        requiredStages: stages.length ? stages : ["family"],
        reason: reason || "冻结批次修订审计要求人工复核",
      };
    });
  }

  const items = batch.items || [];
  const seen = new Set();
  return source.map((risk) => {
    const value = typeof risk === "string" ? { questionId: risk } : risk;
    const item = items.find((entry) => entry.questionId === value.questionId)
      || items.find((entry) => Number(entry.order) === Number(value.order));
    if (!item?.questionId || seen.has(item.questionId)) return null;
    seen.add(item.questionId);
    const requiredStages = blindGoldRevisionRequiredStages({
      ...item,
      revisionReview: { ...(item.revisionReview || {}), requiredStages: value.requiredStages || value.stages || ["family"] },
    }, batch);
    return {
      questionId: item.questionId,
      order: item.order,
      stem: item.question?.stem || "题干暂缺",
      requiredStages: requiredStages.length ? requiredStages : ["family"],
      reason: value.reason || value.message || value.description || "金标一致性预检要求人工复核",
    };
  }).filter(Boolean);
}

function blindGoldProvenanceLabel(value) {
  const key = String(value || "");
  return blindGoldProvenanceLabels[key] || key || "未标明";
}

function blindGoldProvenanceSummary(source = {}, fields = []) {
  return `预填来源：${fields.map(([label, key]) => `${label}=${blindGoldProvenanceLabel(source?.[key])}`).join(" · ")}`;
}

function blindGoldReviewStageIsComplete(review) {
  return ["confirmed", "corrected", "disputed"].includes(String(review?.result || ""));
}

function blindGoldQuestionRequiresScoringPoints(question = {}) {
  return subjectiveQuestionTypes.has(String(question.type || "").trim());
}

function blindGoldReviewItemResult(item = {}) {
  const contentComplete = blindGoldReviewStageIsComplete(item.contentReview);
  const familyComplete = blindGoldReviewStageIsComplete(item.familyReview)
    && item.familyReview.basedOnKnowledgeDigest === item.knowledgeDigest;
  if (!contentComplete || !familyComplete) return "pending_review";
  if (item.contentReview.result === "disputed" || item.familyReview.result === "disputed") return "disputed";
  if (item.contentReview.result === "corrected" || item.familyReview.result === "corrected") return "corrected";
  return "confirmed_current";
}

// Recompute the visible batch counters from the item objects we already have.
// The API summary may belong to an older GET that raced with a save response;
// the item revision is the source of truth for the current screen.
function blindGoldReviewSummaryFromItems(items = [], fallback = {}) {
  const list = Array.isArray(items) ? items : [];
  const completed = list.filter((item) => blindGoldReviewItemResult(item) !== "pending_review");
  const disputed = completed.filter((item) => blindGoldReviewItemResult(item) === "disputed");
  const corrected = completed.filter((item) => blindGoldReviewItemResult(item) === "corrected");
  const confirmed = completed.filter((item) => blindGoldReviewItemResult(item) === "confirmed_current");
  return {
    ...(fallback && typeof fallback === "object" ? fallback : {}),
    total: list.length,
    completed: completed.length,
    pending: list.length - completed.length,
    confirmed: confirmed.length,
    corrected: corrected.length,
    disputed: disputed.length,
    accuracyEligible: completed.length - disputed.length,
    readyToFreeze: list.length > 0 && completed.length === list.length,
  };
}

// 覆盖门禁预检结果。页面徽标读取的是已保存的审核状态，无法反映“保存之后才被判定
// 不合格”的题目；这里把服务端预检结果落到每道题上，使审核员不必等到冻结才发现问题。
function blindGoldPreflightIssues(questionId = "") {
  const preflight = state.blindGoldPreflight;
  if (!preflight || preflight.batchId !== state.blindGoldReviewBatch?.id) return [];
  return preflight.issuesByQuestionId?.[questionId] || [];
}

function blindGoldPreflightIssueSummary(issues = []) {
  const labels = issues
    .map((issue) => blindGoldReviewSemanticIssueText(issue))
    .filter(Boolean);
  return labels.slice(0, 2).join("；");
}

function blindGoldPreflightBlockedQuestionIds() {
  const preflight = state.blindGoldPreflight;
  if (!preflight || preflight.batchId !== state.blindGoldReviewBatch?.id) return [];
  return Object.keys(preflight.issuesByQuestionId || {});
}

async function refreshBlindGoldPreflight(options = {}) {
  const batch = state.blindGoldReviewBatch;
  if (!batch || batch.status === "frozen") {
    state.blindGoldPreflight = null;
    return null;
  }
  try {
    const payload = await requestJson(
      `/api/admin/knowledge-classification/gold-review/sets/${encodeURIComponent(batch.id)}/family-reviews/preflight`,
      { method: "POST", body: "{}" },
    );
    const validation = payload.validation || {};
    const issuesByQuestionId = {};
    (validation.issues || []).forEach((issue) => {
      const questionId = String(issue.questionId || "");
      if (!questionId) return;
      (issuesByQuestionId[questionId] ||= []).push(issue);
    });
    state.blindGoldPreflight = {
      batchId: batch.id,
      valid: validation.valid !== false,
      issueCount: Number(validation.issueCount) || 0,
      questionCount: Number(validation.questionCount) || 0,
      issuesByQuestionId,
      at: Date.now(),
    };
  } catch (error) {
    state.blindGoldPreflight = null;
    if (!options.quiet) throw error;
  }
  return state.blindGoldPreflight;
}

function blindGoldReviewItemStage(item = {}) {
  const batch = state.blindGoldReviewBatch;
  const contentComplete = blindGoldReviewStageIsComplete(item.contentReview);
  const familyComplete = blindGoldReviewStageIsComplete(item.familyReview)
    && item.familyReview.basedOnKnowledgeDigest === item.knowledgeDigest;
  const hasBusinessDrift = ["question_drift", "knowledge_drift"].includes(item.businessSync?.status);
  if (hasBusinessDrift) return { key: "business_drift", label: "正式数据待同步", risk: "正式题目或知识已更新" };
  if (blindGoldReviewIsRevisionBatch(batch)) {
    const requiredStages = blindGoldRevisionRequiredStages(item, batch);
    if (!requiredStages.length) return { key: "inherited_complete", label: "继承完成", risk: "沿用冻结父版本人工金标" };
    if (!contentComplete) return { key: "content_re_review", label: "内容待重审", risk: "需重新审核答案、证据或知识" };
    if (!familyComplete) return { key: "family_re_review", label: "题族待重审", risk: "需重新审核题族裁决" };
    if (item.contentReview.result === "disputed" || item.familyReview.result === "disputed") {
      return { key: "disputed", label: "争议待复核", risk: "不计入准确率" };
    }
    if (blindGoldPreflightIssues(item.questionId).length) return blindGoldPreflightStage(item);
    return { key: "ready", label: "可冻结", risk: "本次风险阶段已完成" };
  }
  if (!contentComplete) return { key: "content_pending", label: "答案知识待审", risk: "" };
  if (!familyComplete) return { key: "family_pending", label: "答案知识完成 · 题族待审", risk: "" };
  if (item.contentReview.result === "disputed" || item.familyReview.result === "disputed") {
    return { key: "disputed", label: "争议待复核", risk: "不计入准确率" };
  }
  if (blindGoldPreflightIssues(item.questionId).length) return blindGoldPreflightStage(item);
  return { key: "ready", label: "可冻结", risk: "两阶段已完成" };
}

function blindGoldPreflightStage(item = {}) {
  const summary = blindGoldPreflightIssueSummary(blindGoldPreflightIssues(item.questionId));
  return { key: "preflight_blocked", label: "预检阻断", risk: summary ? `预检未通过：${summary}` : "预检未通过，需重新审核题族裁决" };
}

function blindGoldReviewItemRisk(item = {}) {
  const preflightIssues = blindGoldPreflightIssues(item.questionId);
  if (preflightIssues.length) {
    const summary = blindGoldPreflightIssueSummary(preflightIssues);
    return summary ? `预检阻断：${summary}` : "预检阻断，需重新审核题族裁决";
  }
  const revisionStage = blindGoldReviewItemStage(item);
  const evidence = blindGoldReviewHumanAnswerKnowledge(item).textbookEvidence || [];
  if (["question_drift", "knowledge_drift"].includes(item.businessSync?.status)) return "正式数据已更新，需重新载入";
  if (["inherited_complete", "content_re_review", "family_re_review", "ready"].includes(revisionStage.key)) return revisionStage.risk;
  if (blindGoldReviewItemResult(item) === "disputed") return "存在争议，不计入准确率";
  if (!evidence.length) return "缺少教材证据";
  if (blindGoldReviewReplayMode(item) === "unmatched") return "无匹配题，重点核对新题族";
  if (blindGoldReviewReplayMode(item) === "singleton") return "单题题族，注意样本不足";
  return "";
}

function blindGoldReviewPreferredResult(item = {}) {
  const combined = blindGoldReviewItemResult(item);
  if (combined !== "pending_review") return combined;
  return "";
}

function selectedBlindGoldReviewItem() {
  return state.blindGoldReviewBatch?.items?.find((item) => item.questionId === state.selectedBlindGoldQuestionId) || null;
}

function blindGoldReviewCatalogCache(item = selectedBlindGoldReviewItem()) {
  const bookId = String(item?.question?.bookId || "");
  const structure = state.blindGoldKnowledgeStructures.get(bookId) || null;
  const families = state.blindGoldFamilyCatalogs.get(bookId) || null;
  const batch = state.blindGoldReviewBatch;
  const batchId = String(batch?.id || "");
  const batchRevision = Number(batch?.revision || 0);
  let cache = state.blindGoldReviewCatalogCaches.get(bookId);
  if (!cache
    || cache.structure !== structure
    || cache.families !== families
    || cache.batchId !== batchId
    || cache.batchRevision !== batchRevision) {
    cache = {
      structure,
      families,
      batchId,
      batchRevision,
      knowledgeIndex: null,
      knowledgeNodes: null,
      normalizedFamilies: null,
      normalizedFamiliesById: new Map(),
      familiesByQuestion: new Map(),
      familyMapsByQuestion: new Map(),
    };
    state.blindGoldReviewCatalogCaches.set(bookId, cache);
  }
  return cache;
}

function invalidateBlindGoldReviewCatalogCaches(bookId = "") {
  if (bookId) state.blindGoldReviewCatalogCaches.delete(String(bookId));
  else state.blindGoldReviewCatalogCaches.clear();
}

function blindGoldReviewKnowledgeIndexForItem(item, structure = null) {
  const cache = blindGoldReviewCatalogCache(item);
  const currentStructure = structure || cache.structure;
  if (!cache.knowledgeIndex || cache.structure !== currentStructure) {
    cache.structure = currentStructure;
    cache.knowledgeIndex = blindGoldReviewKnowledgeNodeIndex(currentStructure || {});
  }
  return cache.knowledgeIndex;
}

function blindGoldReviewNodeKey(node = {}) {
  if (node.id) return `id:${node.id}`;
  if (node.path) return `path:${node.path}`;
  return node.title ? `title:${node.title}` : "";
}

function blindGoldKnowledgePathSegments(value = {}) {
  const path = value && typeof value === "object"
    ? (value.path || value.knowledgePath || "")
    : value;
  return String(path || "").split(/[>＞]/)
    .map((segment) => blindGoldNormalizedKnowledgeText(segment))
    .filter(Boolean);
}

function blindGoldKnowledgeNodeCovers(coveredValue = {}, expectedValue = {}) {
  if (blindGoldKnowledgeNodesCompatible(coveredValue, expectedValue)) return true;
  const coveredPath = blindGoldKnowledgePathSegments(coveredValue);
  const expectedPath = blindGoldKnowledgePathSegments(expectedValue);
  if (!coveredPath.length || !expectedPath.length || coveredPath.length >= expectedPath.length) return false;
  return coveredPath.every((segment, index) => segment === expectedPath[index]);
}

function blindGoldKnowledgeNodeIsWithin(scopeValue = {}, actualValue = {}) {
  return blindGoldKnowledgeNodeCovers(scopeValue, actualValue);
}

function blindGoldReviewNodeLabel(node = {}) {
  return node.path || node.title || node.name || node.label || node.id || "未命名知识点";
}

function blindGoldReviewNodeShortLabel(node = {}) {
  const pathParts = String(node.path || "").split(/\s*>\s*/).map((part) => part.trim()).filter(Boolean);
  return node.title || node.name || node.label || pathParts[pathParts.length - 1] || node.id || "该知识";
}

function blindGoldReviewPushNode(map, node) {
  if (typeof node === "string") node = { title: node };
  if (!node || typeof node !== "object") return;
  const normalized = {
    id: String(node.id || node.nodeId || ""),
    title: String(node.title || node.name || node.label || node.displayTitle || ""),
    path: String(node.path || node.knowledgePath || ""),
    ...(node.parentId ? { parentId: String(node.parentId) } : {}),
    ...(node.kind ? { kind: String(node.kind) } : {}),
    ...(node.canonicalNodeId ? { canonicalNodeId: String(node.canonicalNodeId) } : {}),
    ...(Array.isArray(node.aliasNodeIds) && node.aliasNodeIds.length
      ? { aliasNodeIds: [...new Set(node.aliasNodeIds.map((id) => String(id || "").trim()).filter(Boolean))] }
      : {}),
  };
  const key = blindGoldReviewNodeKey(normalized);
  if (!key) return;
  const existing = map.get(key);
  if (!existing) {
    map.set(key, normalized);
    return;
  }
  map.set(key, {
    ...existing,
    ...Object.fromEntries(Object.entries(normalized).filter(([, value]) => String(value || "").trim())),
    ...(normalized.aliasNodeIds?.length || existing.aliasNodeIds?.length
      ? { aliasNodeIds: [...new Set([...(existing.aliasNodeIds || []), ...(normalized.aliasNodeIds || [])])] }
      : {}),
  });
}

function blindGoldReviewKnowledgeNodes(item = selectedBlindGoldReviewItem()) {
  const cache = blindGoldReviewCatalogCache(item);
  if (cache.knowledgeNodes) return cache.knowledgeNodes;
  const map = new Map();
  const addFamily = (family) => {
    if (!family) return;
    const normalizedFamily = blindGoldReviewCatalogFamily(family, item);
    blindGoldReviewPushNode(map, normalizedFamily.coreKnowledge);
    (normalizedFamily.requiredKnowledge || []).forEach((node) => blindGoldReviewPushNode(map, node));
    (normalizedFamily.textbookAnchors || []).forEach((node) => blindGoldReviewPushNode(map, node));
  };
  const addItem = (entry) => {
    const answerKnowledge = blindGoldReviewHumanAnswerKnowledge(entry);
    const addKnowledgeValue = (value) => {
      if (!value) return;
      if (Array.isArray(value)) {
        value.forEach(addKnowledgeValue);
        return;
      }
      blindGoldReviewPushNode(map, value);
    };
    const addKnowledgeRecord = (value = {}) => {
      if (!value || typeof value !== "object") return;
      addKnowledgeValue(value.coreKnowledge || value.primaryKnowledge || value.primaryKnowledgePoint);
      addKnowledgeValue(value.requiredKnowledge || value.knowledgePoints || value.subKnowledgePoints);
      addKnowledgeValue(value.optionKnowledge);
      addKnowledgeValue(value.scoringPoints);
    };
    const addStoredNodes = (value = {}) => {
      const ids = value.knowledgeNodeIds || [];
      const labels = value.knowledgeLabels || [];
      ids.forEach((id, index) => blindGoldReviewPushNode(map, {
        id,
        title: labels[index] || "",
      }));
      labels.slice(ids.length).forEach((label) => blindGoldReviewPushNode(map, { title: label }));
    };
    blindGoldReviewPushNode(map, answerKnowledge.coreKnowledge);
    (answerKnowledge.requiredKnowledge || []).forEach((node) => blindGoldReviewPushNode(map, node));
    (answerKnowledge.optionKnowledge || []).forEach(addStoredNodes);
    (answerKnowledge.atomicStatements || []).forEach(addStoredNodes);
    (answerKnowledge.scoringPoints || []).forEach(addStoredNodes);
    addKnowledgeRecord(entry.officialBaseline?.answerKnowledge);
    addKnowledgeRecord(entry.finalGold?.answerKnowledge || entry.finalGold?.answerAndEvidence || entry.finalGold?.knowledgeGold);
    addKnowledgeRecord(entry.sourceMaterials?.sourceAnswer);
    const familyGold = blindGoldReviewStoredFamilyGold(entry);
    (familyGold.families || []).forEach(addFamily);
    addFamily(familyGold.candidateFamily);
  };
  (state.blindGoldReviewBatch?.items || [])
    .filter((entry) => !item?.question?.bookId || entry.question?.bookId === item.question.bookId)
    .forEach(addItem);
  const structure = state.blindGoldKnowledgeStructures.get(item?.question?.bookId || "");
  (structure?.nodes || []).filter((node) => !node.kind || node.kind === "knowledge")
    .forEach((node) => blindGoldReviewPushNode(map, node));
  // Reconcile legacy IDs/labels against the freshly loaded tree so a renamed
  // or re-keyed node remains searchable under its current canonical path.
  const index = blindGoldReviewKnowledgeNodeIndex(structure);
  const normalizedMap = new Map();
  map.forEach((node) => blindGoldReviewPushNode(
    normalizedMap,
    blindGoldReviewNormalizeKnowledgeNode(node, index, node),
  ));
  cache.knowledgeNodes = [...normalizedMap.values()]
    .sort((left, right) => blindGoldReviewNodeLabel(left).localeCompare(blindGoldReviewNodeLabel(right), "zh-CN"));
  return cache.knowledgeNodes;
}

function blindGoldReviewResolveNode(value, item = selectedBlindGoldReviewItem()) {
  const raw = String(value || "").trim();
  const nodes = blindGoldReviewKnowledgeNodes(item);
  if (!raw) return { id: "", title: "", path: "" };
  const exact = nodes.find((node) => blindGoldReviewNodeKey(node) === raw);
  if (exact) return exact;
  const [, prefix, payload = ""] = raw.match(/^(id|path|title):(.*)$/i) || [];
  if (!prefix || !payload) return { id: "", title: "", path: "" };
  if (prefix.toLowerCase() === "id") {
    const byAnyId = nodes.find((node) => blindGoldKnowledgeNodeIds(node).includes(payload));
    if (byAnyId) return byAnyId;
  }
  const normalizedPayload = blindGoldNormalizedKnowledgeText(payload);
  if (prefix.toLowerCase() === "path") {
    const byPath = nodes.find((node) => blindGoldNormalizedKnowledgeText(node.path || node.knowledgePath) === normalizedPayload);
    if (byPath) return byPath;
  }
  if (prefix.toLowerCase() === "title") {
    const byTitle = nodes.find((node) => blindGoldNormalizedKnowledgeText(node.title || node.name || node.label) === normalizedPayload);
    if (byTitle) return byTitle;
  }
  return { id: "", title: "", path: "" };
}

function blindGoldReviewNodeOptions(nodes, selectedNodes = [], includePlaceholder = false) {
  const selected = (selectedNodes || []).filter(blindGoldKnowledgeNodeExists);
  return `${includePlaceholder ? '<option value="">请选择知识点</option>' : ""}${nodes.map((node) => {
    const key = blindGoldReviewNodeKey(node);
    const isSelected = selected.some((candidate) => blindGoldKnowledgeNodesCompatible(candidate, node));
    return `<option value="${escapeHtml(key)}" ${isSelected ? "selected" : ""}>${escapeHtml(blindGoldReviewNodeLabel(node))}</option>`;
  }).join("")}`;
}

function blindGoldReviewStoredKnowledgeNodes(knowledgeNodeIds = [], knowledgeLabels = [], nodes = []) {
  const ids = Array.isArray(knowledgeNodeIds) ? knowledgeNodeIds : [];
  const labels = Array.isArray(knowledgeLabels) ? knowledgeLabels : [];
  const selected = ids.map((id, index) => {
    const exact = nodes.find((node) => blindGoldKnowledgeNodeIds(node).includes(String(id)));
    return exact || {
      id,
      title: labels[index] || "",
      path: "",
    };
  });
  labels.slice(ids.length).forEach((label) => {
    const exactLabelMatch = nodes.find((node) => blindGoldReviewNodeLabel(node) === label && (node.id || node.path));
    const normalizedLabel = blindGoldNormalizedKnowledgeText(label);
    const match = exactLabelMatch
      || nodes.find((node) => blindGoldNormalizedKnowledgeText(blindGoldReviewNodeLabel(node)) === normalizedLabel && (node.id || node.path))
      || nodes.find((node) => blindGoldNormalizedKnowledgeText(blindGoldReviewNodeLabel(node)) === normalizedLabel)
      || { id: "", title: label, path: "" };
    selected.push(match);
  });
  const seen = new Set();
  return selected.filter((node) => {
    const key = blindGoldReviewNodeKey(node);
    if (!key || seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function blindGoldReviewKnowledgeNodeIndex(structure = {}) {
  const byId = new Map();
  const byPath = new Map();
  const byTitle = new Map();
  const nodes = Array.isArray(structure?.nodes) ? structure.nodes : [];
  nodes.forEach((node) => {
    if (!node || typeof node !== "object") return;
    const ids = blindGoldKnowledgeNodeIds(node);
    ids.forEach((id) => {
      if (!byId.has(id)) byId.set(id, node);
    });
    [node.path, node.knowledgePath].forEach((path) => {
      const key = blindGoldNormalizedKnowledgeText(path);
      if (key && !byPath.has(key)) byPath.set(key, node);
    });
    [node.displayTitle, node.title, node.name, node.label].forEach((title) => {
      const key = blindGoldNormalizedKnowledgeText(title);
      if (!key) return;
      if (!byTitle.has(key)) byTitle.set(key, node);
      else if (byTitle.get(key) !== node) byTitle.set(key, null);
    });
  });
  return { byId, byPath, byTitle };
}

function blindGoldReviewNormalizeKnowledgeNode(value = {}, index = {}, fallback = {}) {
  const raw = value && typeof value === "object" ? value : { id: value };
  const rawIds = blindGoldKnowledgeNodeIds(raw);
  let matched = rawIds.map((id) => index.byId?.get(id)).find(Boolean) || null;
  if (!matched) {
    const pathKey = blindGoldNormalizedKnowledgeText(raw.path || raw.knowledgePath);
    if (pathKey) matched = index.byPath?.get(pathKey) || null;
  }
  if (!matched) {
    const titleKey = blindGoldNormalizedKnowledgeText(raw.title || raw.name || raw.label || raw.displayTitle);
    if (titleKey) matched = index.byTitle?.get(titleKey) || null;
  }
  if (!matched) {
    const fallbackIds = blindGoldKnowledgeNodeIds(fallback);
    matched = fallbackIds.map((id) => index.byId?.get(id)).find(Boolean) || null;
  }
  if (!matched) {
    const fallbackPath = blindGoldNormalizedKnowledgeText(fallback.path || fallback.knowledgePath);
    if (fallbackPath) matched = index.byPath?.get(fallbackPath) || null;
  }
  if (!matched) {
    const fallbackTitle = blindGoldNormalizedKnowledgeText(fallback.title || fallback.name || fallback.label || fallback.displayTitle);
    if (fallbackTitle) matched = index.byTitle?.get(fallbackTitle) || null;
  }
  if (!matched) {
    return {
      ...raw,
      id: String(raw.id || raw.nodeId || ""),
      title: String(raw.title || raw.name || raw.label || raw.displayTitle || fallback.title || fallback.name || fallback.label || ""),
      path: String(raw.path || raw.knowledgePath || fallback.path || fallback.knowledgePath || ""),
      ...(raw.parentId || fallback.parentId ? { parentId: String(raw.parentId || fallback.parentId) } : {}),
    };
  }
  const matchedIds = blindGoldKnowledgeNodeIds(matched);
  const legacyIds = [...new Set([...rawIds, ...blindGoldKnowledgeNodeIds(fallback)])]
    .filter((id) => id && !matchedIds.includes(id));
  return {
    ...raw,
    ...matched,
    id: String(matched.id || raw.id || raw.nodeId || ""),
    title: String(matched.displayTitle || matched.title || matched.name || matched.label || raw.title || raw.name || raw.label || ""),
    path: String(matched.path || matched.knowledgePath || raw.path || raw.knowledgePath || ""),
    ...(matched.parentId || raw.parentId ? { parentId: String(matched.parentId || raw.parentId) } : {}),
    ...(matched.kind || raw.kind ? { kind: String(matched.kind || raw.kind) } : {}),
    ...(matched.canonicalNodeId || raw.canonicalNodeId ? { canonicalNodeId: String(matched.canonicalNodeId || raw.canonicalNodeId) } : {}),
    ...(legacyIds.length ? { aliasNodeIds: [...new Set([...(matched.aliasNodeIds || []), ...(raw.aliasNodeIds || []), ...legacyIds])] } : {}),
  };
}

function blindGoldReviewNormalizeKnowledgeNodeList(values = [], ids = [], index = {}, options = {}) {
  const sourceValues = Array.isArray(values) ? values : [];
  const sourceIds = Array.isArray(ids) ? ids : (ids ? [ids] : []);
  const normalized = sourceValues.map((value, valueIndex) => blindGoldReviewNormalizeKnowledgeNode(
    value,
    index,
    sourceIds[valueIndex] ? { id: sourceIds[valueIndex] } : {},
  ));
  sourceIds.forEach((id) => {
    if (!String(id || "").trim()) return;
    const candidate = blindGoldReviewNormalizeKnowledgeNode({ id }, index);
    if (!normalized.some((node) => blindGoldKnowledgeNodesCompatible(node, candidate))) normalized.push(candidate);
  });
  return blindGoldUniqueKnowledgeNodes(normalized.filter(blindGoldKnowledgeNodeExists));
}

function blindGoldReviewCatalogFamily(family = {}, item = selectedBlindGoldReviewItem()) {
  const structure = state.blindGoldKnowledgeStructures.get(item?.question?.bookId || family.bookId || "");
  const index = blindGoldReviewKnowledgeIndexForItem(item, structure);
  const backendDirectoryAnchorNodeId = String(family.backendDirectoryAnchorNodeId
    || family.scopeAnchorNodeId
    || family.coreKnowledgeNodeId
    || family.knowledgeNodeId
    || "");
  const userDirectoryAnchorNodeId = String(family.userDirectoryAnchorNodeId
    || family.locationNodeId
    || family.knowledgeNodeId
    || family.textbookAnchorNodeIds?.[0]
    || "");
  const coreValue = family.scopeAnchor && typeof family.scopeAnchor === "object"
    ? family.scopeAnchor
    : (family.coreKnowledge && typeof family.coreKnowledge === "object"
      ? family.coreKnowledge
      : (family.scopeAnchorNode || family.coreKnowledgeNode || family.textbookAnchor || {
        id: backendDirectoryAnchorNodeId,
        title: family.primaryKnowledgePoint,
        path: family.knowledgePath,
      }));
  const coreKnowledge = blindGoldReviewNormalizeKnowledgeNode(coreValue, index, {
    id: backendDirectoryAnchorNodeId,
    title: family.primaryKnowledgePoint,
    path: family.knowledgePath,
  });
  const requiredValues = [
    ...(Array.isArray(family.coverageKnowledge) ? family.coverageKnowledge : []),
    ...(Array.isArray(family.requiredKnowledge) ? family.requiredKnowledge : []),
    ...(Array.isArray(family.coverageKnowledgeNodes) ? family.coverageKnowledgeNodes : []),
    ...(Array.isArray(family.requiredKnowledgeNodes) ? family.requiredKnowledgeNodes : []),
  ];
  const requiredIds = Array.isArray(family.coverageKnowledgeNodeIds) && family.coverageKnowledgeNodeIds.length
    ? family.coverageKnowledgeNodeIds
    : (family.requiredKnowledgeNodeIds || []);
  const requiredKnowledge = blindGoldReviewNormalizeKnowledgeNodeList(requiredValues, requiredIds, index);
  const textbookValues = [
    ...(Array.isArray(family.textbookAnchors) ? family.textbookAnchors : []),
    ...(Array.isArray(family.textbookAnchorNodes) ? family.textbookAnchorNodes : []),
    ...(family.textbookAnchor && typeof family.textbookAnchor === "object" ? [family.textbookAnchor] : []),
  ];
  const textbookAnchors = blindGoldReviewNormalizeKnowledgeNodeList(
    textbookValues,
    Array.isArray(family.textbookAnchorNodeIds) && family.textbookAnchorNodeIds.length
      ? family.textbookAnchorNodeIds
      : (family.textbookAnchorIds || []),
    index,
  );
  const requiredKnowledgeNodeIds = requiredKnowledge.map((node) => node.id).filter(Boolean);
  const textbookAnchorNodeIds = textbookAnchors.map((node) => node.id).filter(Boolean);
  return {
    ...family,
    scopeAnchor: coreKnowledge,
    backendDirectoryAnchorNodeId: coreKnowledge.id || backendDirectoryAnchorNodeId,
    userDirectoryAnchorNodeId,
    scopeAnchorNodeId: coreKnowledge.id || backendDirectoryAnchorNodeId,
    coreKnowledge,
    coreKnowledgeNodeId: coreKnowledge.id || backendDirectoryAnchorNodeId,
    coverageKnowledge: requiredKnowledge,
    coverageKnowledgeNodeIds: requiredKnowledgeNodeIds,
    requiredKnowledge,
    requiredKnowledgeNodeIds,
    textbookAnchors,
    textbookAnchorNodeIds,
    independentMemberCount: Number(family.independentMemberCount ?? family.memberCount) || 0,
  };
}

function blindGoldReviewFamilies(item = selectedBlindGoldReviewItem()) {
  const cache = blindGoldReviewCatalogCache(item);
  const itemCacheKey = `${item?.questionId || ""}:${Number(item?.revision || 0)}:${Number(item?.updatedAt || 0)}`;
  const cachedFamilies = cache.familiesByQuestion.get(itemCacheKey);
  if (cachedFamilies) return cachedFamilies;
  if (!cache.normalizedFamilies) {
    cache.normalizedFamilies = (cache.families || [])
      .filter((family) => family?.id && family.status !== "rejected")
      .map((family) => blindGoldReviewCatalogFamily(family, item));
    cache.normalizedFamiliesById = new Map(cache.normalizedFamilies.map((family) => [family.id, family]));
  }
  const map = new Map();
  const addFamily = (family, source = "historical_snapshot") => {
    if (!family?.id || family.status === "rejected") return;
    const normalized = source === "current_catalog"
      ? (cache.normalizedFamiliesById.get(family.id) || blindGoldReviewCatalogFamily(family, item))
      : blindGoldReviewCatalogFamily(family, item);
    const existing = map.get(family.id);
    if (!existing) {
      map.set(family.id, {
        ...normalized,
        familySource: source,
        isHistoricalSnapshot: source === "historical_snapshot",
        ...(source === "historical_snapshot" ? { historicalStatus: normalized.status || "" } : {}),
      });
      return;
    }
    if (source === "current_catalog") {
      map.set(family.id, {
        ...existing,
        ...normalized,
        familySource: "current_catalog",
        isHistoricalSnapshot: false,
        historicalSnapshot: existing.isHistoricalSnapshot ? existing : existing.historicalSnapshot,
      });
      return;
    }
    map.set(family.id, {
      ...existing,
      historicalSnapshot: { ...normalized, familySource: "historical_snapshot", isHistoricalSnapshot: true },
    });
  };
  const storedFamilyGold = blindGoldReviewStoredFamilyGold(item);
  (storedFamilyGold.families || []).forEach((family) => addFamily(family, "historical_snapshot"));
  (state.blindGoldFamilyCatalogs.get(item?.question?.bookId || "") || [])
    .forEach((family) => addFamily(family, "current_catalog"));
  const result = [...map.values()]
    .sort((left, right) => String(left.name || left.id).localeCompare(String(right.name || right.id), "zh-CN"));
  cache.familiesByQuestion.set(itemCacheKey, result);
  cache.familyMapsByQuestion.set(itemCacheKey, new Map(result.map((family) => [family.id, family])));
  return result;
}

function blindGoldReviewFormalFamilies(item = selectedBlindGoldReviewItem()) {
  return blindGoldReviewFamilies(item).filter((family) => !blindGoldReviewFamilyIsHistorical(family));
}

function blindGoldReviewFamilyIsHistorical(family = {}) {
  return family?.isHistoricalSnapshot === true && family?.familySource !== "current_catalog";
}

function blindGoldReviewFamilyStatusLabel(family = {}) {
  if (blindGoldReviewFamilyIsHistorical(family)) return "历史快照 · 仅供追溯，不可提交";
  if (family.status === "pending_review") return "待审核";
  if (family.status && family.status !== "confirmed") return family.status;
  return "";
}

// The review draft may retain family ids that no longer exist in the formal
// catalog. Keep those ids visible for auditability, but make the distinction
// explicit anywhere a reviewer can select a family.
function blindGoldFamilyPickerSource(option = {}) {
  return option?.dataset?.familySource === "historical_snapshot"
    ? "historical_snapshot"
    : "current_catalog";
}

function blindGoldFamilyPickerGroups(options = []) {
  const groups = [
    {
      source: "current_catalog",
      label: "当前正式题族目录",
      options: [],
    },
    {
      source: "historical_snapshot",
      label: "历史快照题族 · 仅供追溯",
      options: [],
    },
  ];
  const groupBySource = new Map(groups.map((group) => [group.source, group]));
  options.forEach((option) => groupBySource.get(blindGoldFamilyPickerSource(option))?.options.push(option));
  return groups.filter((group) => group.options.length);
}

function blindGoldReviewFamilyHistoricalIds(item = selectedBlindGoldReviewItem(), familyGold = null) {
  const value = familyGold || item?.humanGold?.familyGold || item?.finalGold?.familyGold || item?.familyGold || {};
  const ids = [...new Set([
    value.decision === "join_existing" ? value.primaryFamilyId : "",
    ...(Array.isArray(value.relatedFamilyIds) ? value.relatedFamilyIds : []),
  ].map((id) => String(id || "").trim()).filter(Boolean))];
  return ids.filter((id) => blindGoldReviewFamilyIsHistorical(blindGoldReviewFamilyById(id, item)));
}

function blindGoldReviewFamilyHistoricalNames(item = selectedBlindGoldReviewItem(), familyGold = null) {
  return blindGoldReviewFamilyHistoricalIds(item, familyGold)
    .map((id) => blindGoldReviewFamilyName(id, item))
    .filter(Boolean);
}

function blindGoldFormalFamilyNameList(ids = [], item = selectedBlindGoldReviewItem()) {
  return [...new Set((Array.isArray(ids) ? ids : []).map((id) => String(id || "").trim()).filter(Boolean))]
    .map((id) => blindGoldReviewFamilyName(id, item))
    .filter(Boolean);
}

function blindGoldFormalFamilyMembershipLabel(membership = {}) {
  const role = membership.isPrimary ? "主题族" : (membership.coverageRole === "required" ? "作答必需关联" : "普通关联");
  const membershipStatus = membership.reviewStatus === "confirmed" ? "归属已确认" : "归属待审核";
  const definitionStatus = membership.familyStatus === "confirmed" ? "定义已确认" : "定义待审核";
  return `${membership.familyName || membership.familyId} · ${role} · ${definitionStatus} · ${membershipStatus}`;
}

function blindGoldFormalFamilyManagerTarget(item = selectedBlindGoldReviewItem()) {
  const memberships = Array.isArray(item?.formalFamilySync?.currentMemberships)
    ? item.formalFamilySync.currentMemberships
    : [];
  const pending = memberships.find((membership) => membership.reviewStatus !== "confirmed");
  const target = pending || memberships.find((membership) => membership.isPrimary) || memberships[0] || {};
  return {
    familyId: String(target.familyId || "").trim(),
    familyName: String(target.familyName || target.familyId || "").trim(),
    questionId: String(item?.questionId || "").trim(),
    membershipPending: Boolean(pending),
  };
}

function renderBlindGoldFormalFamilySync(item = selectedBlindGoldReviewItem()) {
  const element = document.querySelector("#blind-gold-formal-family-sync");
  if (!element) return;
  const sync = item?.formalFamilySync;
  if (!item || !sync || sync.status === "not_available") {
    element.hidden = true;
    element.className = "blind-gold-formal-family-sync";
    element.innerHTML = "";
    return;
  }
  const currentNames = sync.currentMemberships?.length
    ? sync.currentMemberships.map(blindGoldFormalFamilyMembershipLabel)
    : blindGoldFormalFamilyNameList(sync.currentFamilyIds, item);
  const draftOverride = blindGoldFormalFamilyDraftOverride(item);
  const historicalDraftIds = (sync.draftFamilyIds || [])
    .map((id) => String(id || "").trim())
    .filter(Boolean);
  const draftFamilyIds = draftOverride?.familyIds || sync.draftFamilyIds || [];
  const draftNames = blindGoldFormalFamilyNameList(draftFamilyIds, item);
  const historicalDraftNames = historicalDraftIds
    .filter((id) => blindGoldReviewFamilyIsHistorical(blindGoldReviewFamilyById(id, item)))
    .map((id) => blindGoldReviewFamilyName(id, item))
    .filter(Boolean);
  const issueLabels = {
    draft_family_missing: "金标草稿引用的题族已不在当前正式目录",
    current_family_added: "当前正式题目新增了金标草稿未记录的题族",
    primary_family_changed: "当前正式主题族与本批草稿不同",
    membership_pending: "当前正式题目与题族的成员归属仍待审核（不等于题族定义错误）",
    family_definition_pending: "当前正式题族定义仍待审核（不等于本题金标裁决错误）",
  };
  const issues = [...new Set((sync.issues || []).map((issue) => issueLabels[issue.code] || issue.message || issue.code).filter(Boolean))];
  const structuralIssueCodes = new Set(["draft_family_missing", "current_family_added", "primary_family_changed"]);
  const structuralDrift = sync.status === "drift"
    && (sync.issues || []).some((issue) => structuralIssueCodes.has(issue.code));
  const membershipPending = (sync.issues || []).some((issue) => issue.code === "membership_pending");
  const definitionPending = (sync.issues || []).some((issue) => issue.code === "family_definition_pending");
  const historicalNotice = historicalDraftNames.length
    ? `历史题族裁决“${historicalDraftNames.join("、")}”只用于追溯当时判断，不能作为本次提交值；请改选当前正式目录题族，或取消关联。`
    : "";
  const drift = structuralDrift || historicalDraftNames.length > 0;
  const pending = !drift && (membershipPending || definitionPending);
  const title = historicalDraftNames.length
    ? "草稿含历史题族"
    : (drift
      ? "正式题族关系已更新"
      : (membershipPending
        ? "正式题族已同步，成员归属待审核"
        : (definitionPending ? "正式题族已同步，定义待审核" : "正式题族关系已同步")));
  const summary = historicalNotice || (drift
    ? "当前正式关系与本批金标草稿存在差异；系统不会自动改写金标裁决。"
    : (pending
      ? "题族已找到，但正式成员归属或题族定义还未确认；这与本题的金标题族裁决是两个审核层次。"
      : "当前正式题族关系与本批金标草稿一致。"));
  const currentText = currentNames.length ? currentNames.join("；") : "当前未归入正式题族";
  const historicalDraftText = sync.draftFamilyIds?.length
    ? blindGoldFormalFamilyNameList(sync.draftFamilyIds, item).join("；")
    : "本批草稿未记录正式题族";
  const draftText = draftOverride ? historicalDraftText : (draftNames.length ? draftNames.join("；") : "本批草稿未记录正式题族");
  const temporaryDraftNotice = draftOverride
    ? `当前待提交草稿（临时）：${draftNames.length ? draftNames.join("；") : "当前未归入正式题族"}`
    : "";
  const canSync = Boolean(sync.currentFamilyIds?.length)
    && !["question_drift", "knowledge_drift"].includes(item.businessSync?.status)
    && state.blindGoldReviewBatch?.status !== "frozen"
    && !blindGoldRevisionItemIsInherited(item);
  const managerTarget = blindGoldFormalFamilyManagerTarget(item);
  const bookId = String(item.question?.bookId || "");
  const catalogReady = Boolean(bookId
    && state.blindGoldKnowledgeStructures.has(bookId)
    && state.blindGoldFamilyCatalogs.has(bookId)
    && !state.blindGoldCatalogRequests.has(bookId));
  const managerAvailable = Boolean(managerTarget.familyId)
    && catalogReady
    && !blindGoldReviewItemIsReadOnly(item, state.blindGoldReviewBatch)
    && !["question_drift", "knowledge_drift"].includes(item.businessSync?.status);
  const pendingMemberships = (sync.currentMemberships || [])
    .filter((membership) => membership.reviewStatus !== "confirmed");
  const confirmMembershipActions = managerAvailable && pendingMemberships.length
    ? `<div class="blind-gold-formal-family-confirm-actions">${pendingMemberships.map((membership) => `<button type="button" class="secondary-action" data-confirm-blind-gold-formal-membership data-family-id="${escapeHtml(membership.familyId)}" data-question-id="${escapeHtml(item.questionId)}" data-membership-revision="${escapeHtml(String(membership.membershipRevision || 0))}" title="确认题目归属于正式题族“${escapeHtml(membership.familyName || membership.familyId)}”">确认“${escapeHtml(membership.familyName || membership.familyId)}”归属</button>`).join("")}</div>`
    : "";
  element.hidden = false;
  element.className = `blind-gold-formal-family-sync${drift ? " has-drift" : (pending ? " has-pending" : "")}`;
  element.innerHTML = `<strong>${escapeHtml(title)}</strong><span>${escapeHtml(summary)}</span>
    <small>当前正式关系：${escapeHtml(currentText)}</small>
    <small>本批金标草稿：${escapeHtml(draftText)}</small>
    ${temporaryDraftNotice ? `<small>${escapeHtml(temporaryDraftNotice)}（尚未保存或确认）</small>` : ""}
    ${historicalNotice ? `<small>历史项：${escapeHtml(historicalDraftNames.join("、"))}（仅供追溯，不可提交）</small>` : ""}
    ${issues.length ? `<small>需要处理：${escapeHtml(issues.join("；"))}</small>` : ""}
    ${drift && !historicalNotice ? "<small>请重新核对并保存题族裁决；如无法判断，可选择“存在争议”。</small>" : ""}
    ${pending ? "<small>刷新只重新读取目录，不会把“归属待审核”自动变成“归属已确认；若主题族不对，也不会替你改主归属。请先在题族成员管理中确认、驳回或调整本题，再回到本页保存。</small>" : ""}
    ${confirmMembershipActions}
    ${(managerAvailable && (pending || drift || definitionPending)) ? `<div class="blind-gold-formal-family-sync-actions"><button type="button" class="secondary-action" id="open-blind-gold-formal-family-manager" title="打开题族管理并定位到本题的正式题族关系">打开题族管理</button>${drift && canSync ? `<button type="button" class="secondary-action" id="sync-blind-gold-formal-family-draft" title="只把当前正式题族关系填入本页待审草稿，不会自动保存或确认">按当前正式关系填入待审草稿</button>` : ""}</div>` : (drift && canSync ? `<div class="blind-gold-formal-family-sync-actions"><button type="button" class="secondary-action" id="sync-blind-gold-formal-family-draft" title="只把当前正式题族关系填入本页待审草稿，不会自动保存或确认">按当前正式关系填入待审草稿</button></div>` : "")}`;
}

function applyBlindGoldFormalFamilySyncToDraft() {
  const item = selectedBlindGoldReviewItem();
  const sync = item?.formalFamilySync;
  const primarySelect = document.querySelector("#blind-gold-existing-family");
  const relatedSelect = document.querySelector("#blind-gold-related-families");
  if (!item || !sync || !primarySelect || !relatedSelect || !sync.currentFamilyIds?.length) return false;
  const formalFamilies = blindGoldReviewFormalFamilies(item);
  const formalIds = new Set(formalFamilies.map((family) => String(family.id || "").trim()).filter(Boolean));
  const currentIds = [...new Set(sync.currentFamilyIds.map((id) => String(id || "").trim()).filter((id) => formalIds.has(id)))];
  const primaryId = formalIds.has(sync.currentPrimaryFamilyId)
    ? String(sync.currentPrimaryFamilyId)
    : (currentIds[0] || "");
  if (!primaryId) {
    openBlindGoldReviewAlert("当前正式关系没有可用的正式题族，请先在题目归属中确认题族。");
    return false;
  }
  const membershipById = new Map((sync.currentMemberships || []).map((membership) => [String(membership.familyId || ""), membership]));
  primarySelect.value = primaryId;
  const relatedFamilyIds = currentIds.filter((id) => id !== primaryId);
  const relatedFamilyRelations = relatedFamilyIds.map((familyId) => {
    const membership = membershipById.get(familyId) || {};
    return blindGoldRelatedFamilyRelation(familyId, {
      coverageRole: membership.coverageRole,
      requiredForAnswer: membership.coverageRole !== "reference",
    });
  });
  state.blindGoldFormalFamilyDraftOverrides.set(blindGoldFormalFamilyDraftOverrideKey(item), {
    batchId: String(state.blindGoldReviewBatch?.id || ""),
    questionId: String(item.questionId || ""),
    itemRevision: Number(item.revision || 0),
    primaryFamilyId: primaryId,
    relatedFamilyIds,
    relatedFamilyRelations,
    familyIds: [primaryId, ...relatedFamilyIds],
  });
  [...relatedSelect.options].forEach((option) => {
    if (!option.value) return;
    const id = String(option.value);
    const selected = id !== primaryId && currentIds.includes(id);
    const membership = membershipById.get(id);
    option.selected = selected;
    if (membership) {
      const coverageRole = membership.coverageRole === "reference" ? "reference" : "required";
      option.dataset.coverageRole = coverageRole;
      option.dataset.requiredForAnswer = String(coverageRole === "required");
    }
  });
  renderQuestionFamilyMultiselect("blind-gold-primary");
  syncBlindGoldFamilyOptionEligibility(primaryId);
  renderBlindGoldRelatedFamilyPicker();
  renderBlindGoldFamilyContributions(item);
  syncBlindGoldReviewStages(item);
  setBlindGoldReviewFeedback("已将当前正式题族关系填入待审草稿；尚未保存，也没有自动确认。请核对本题贡献知识后提交审核。", "success");
  return true;
}

async function openBlindGoldFormalFamilyManager() {
  const item = selectedBlindGoldReviewItem();
  const target = blindGoldFormalFamilyManagerTarget(item);
  if (!item || !target.familyId) {
    openBlindGoldReviewAlert("当前题目没有可定位的正式题族关系，请先重新载入题族目录。");
    return;
  }
  const questionBookId = String(item.question?.bookId || "").trim();
  state.questionLibrary = "official";
  state.questionLibraryTab = "library";
  state.questionWorkspaceMode = "families";
  state.questionFamilyManagementMode = false;
  state.selectedKnowledgeNodeId = "";
  await openView("题库管理");
  const bookFilter = document.querySelector("#question-book-filter");
  if (bookFilter && questionBookId && [...bookFilter.options].some((option) => option.value === questionBookId)) {
    bookFilter.value = questionBookId;
  }
  const statusFilter = document.querySelector("#question-status-filter");
  const search = document.querySelector("#question-family-search");
  if (statusFilter) statusFilter.value = target.membershipPending ? "pending" : "all";
  if (search) search.value = target.familyName;
  await loadQuestionFamilies();
  let family = state.questionFamilies.find((candidate) => candidate.id === target.familyId);
  if (!family && search?.value) {
    search.value = "";
    await loadQuestionFamilies();
    family = state.questionFamilies.find((candidate) => candidate.id === target.familyId);
  }
  if (!family) {
    setQuestionFamilyFeedback(`没有在当前教材目录找到题族“${target.familyName || target.familyId}”，请清除筛选后重试。`, "error");
    return;
  }
  state.expandedQuestionFamilyIds.add(family.id);
  renderQuestionFamilyTable();
  openQuestionFamilyReview(family.id);
  requestAnimationFrame(() => {
    document.querySelector(`#question-family-members [data-question-id="${CSS.escape(target.questionId)}"]`)?.scrollIntoView({ block: "center", behavior: "smooth" });
  });
}

// Confirm a pending formal membership without leaving the gold-review page.
// This is still a manual business-data action; it never changes the gold
// draft or accepts an AI prediction.  The mutation response carries the new
// formal hash, so the local catalog and sync status can update immediately.
async function confirmBlindGoldFormalFamilyMembership(button = null) {
  const batch = state.blindGoldReviewBatch;
  const item = selectedBlindGoldReviewItem();
  if (!batch || !item || blindGoldReviewItemIsReadOnly(item, batch) || state.blindGoldReviewSaving) return;
  const bookId = String(item.question?.bookId || "").trim();
  const sync = item.formalFamilySync || {};
  const familyId = String(button?.dataset?.familyId || "").trim();
  const questionId = String(button?.dataset?.questionId || item.questionId || "").trim();
  const membership = (sync.currentMemberships || []).find((entry) => String(entry.familyId || "") === familyId);
  if (!familyId || !questionId || !membership || membership.reviewStatus === "confirmed") return;
  const expectedRevision = Math.max(0, Number(button?.dataset?.membershipRevision || membership.membershipRevision || 0));
  const mutationToken = beginBlindGoldReviewMutation();
  state.blindGoldReviewSaving = true;
  let draftWasSynced = false;
  setBlindGoldReviewEditState();
  setBlindGoldReviewFeedback(`正在确认题目归属于正式题族“${membership.familyName || familyId}”…`, "loading");
  try {
    const response = await requestJson(`/api/admin/question-families/${encodeURIComponent(familyId)}/members/${encodeURIComponent(questionId)}/review`, {
      method: "PUT",
      body: JSON.stringify({
        status: "confirmed",
        expectedRevision,
        note: "金标审核前人工确认正式题族成员归属",
      }),
    });
    if (!blindGoldReviewMutationIsCurrent(mutationToken)) return;
    const familyCatalog = bookId ? state.blindGoldFamilyCatalogs.get(bookId) : null;
    if (Array.isArray(familyCatalog) && response.formalFactSha256) {
      state.blindGoldFamilyCatalogs.set(bookId, familyCatalog.map((family) => (
        String(family.id || "") === familyId
          ? { ...family, formalFactSha256: response.formalFactSha256 }
          : family
      )));
      invalidateBlindGoldReviewCatalogCaches(bookId);
    }
    const currentItem = selectedBlindGoldReviewItem();
    if (currentItem?.questionId === item.questionId) {
      // Keep unsaved gold fields and local contribution selections intact;
      // only update the server-derived sync status used by preflight.
      const currentSync = currentItem.formalFamilySync || {};
      const currentMemberships = (currentSync.currentMemberships || []).map((entry) => (
        String(entry.familyId || "") === familyId
          ? {
            ...entry,
            reviewStatus: "confirmed",
            membershipRevision: Math.max(
              Number(entry.membershipRevision) || 0,
              Number(response.membershipRevision) || 0,
            ),
          }
          : entry
      ));
      const issues = (currentSync.issues || []).filter((issue) => !(
        issue.code === "membership_pending" && String(issue.familyId || "") === familyId
      ));
      currentItem.formalFamilySync = {
        ...currentSync,
        currentMemberships,
        issues,
        status: issues.length ? "drift" : (currentSync.currentFamilyIds?.length ? "synced" : "not_available"),
      };
    }
    renderBlindGoldReviewDetail();
    const refreshedItem = selectedBlindGoldReviewItem();
    draftWasSynced = refreshedItem?.formalFamilySync?.status === "drift"
      && !blindGoldReviewItemIsReadOnly(refreshedItem, state.blindGoldReviewBatch)
      ? applyBlindGoldFormalFamilySyncToDraft()
      : false;
    setBlindGoldReviewFeedback(draftWasSynced
      ? `已确认题目归属于正式题族“${membership.familyName || familyId}”，并将当前正式题族关系临时填入待审草稿。请核对后保存；未改动你的金标答案、知识或贡献选择。`
      : `已确认题目归属于正式题族“${membership.familyName || familyId}”。现在可以重新保存题族裁决；未改动你的金标答案、知识或贡献选择。`, "success");
  } catch (error) {
    openBlindGoldReviewAlert(`确认正式题族成员失败：${friendlyError(error)}`);
  } finally {
    state.blindGoldReviewSaving = false;
    endBlindGoldReviewMutation(mutationToken);
    renderBlindGoldReview();
    // The final repaint rebuilds the selectors from the historical gold
    // snapshot.  Re-apply the live formal relation so a successful member
    // confirmation cannot be followed by a stale-primary save error.
    if (draftWasSynced) {
      const currentItem = selectedBlindGoldReviewItem();
      if (currentItem?.questionId === item.questionId
        && currentItem.formalFamilySync?.status === "drift"
        && !blindGoldReviewItemIsReadOnly(currentItem, state.blindGoldReviewBatch)) {
        applyBlindGoldFormalFamilySyncToDraft();
      }
    }
  }
}

// A review draft can retain historical related-family ids after the formal
// membership was changed.  The page normally aligns these selectors when the
// catalog is loaded, but a fast submit or a question switch can happen before
// that repaint.  Reconcile only ids that no longer exist in the live formal
// relation; keep a reviewer-selected current family intact.
function blindGoldFormalFamilyDraftNeedsLiveReconciliation(item = selectedBlindGoldReviewItem()) {
  const sync = item?.formalFamilySync;
  if (!sync || sync.status !== "drift") return false;
  const currentIds = new Set((sync.currentFamilyIds || []).map((id) => String(id || "").trim()).filter(Boolean));
  if (!currentIds.size) return false;
  const primaryId = String(document.querySelector("#blind-gold-existing-family")?.value || "").trim();
  const relatedIds = [...(document.querySelector("#blind-gold-related-families")?.selectedOptions || [])]
    .map((option) => String(option.value || "").trim()).filter(Boolean);
  return [primaryId, ...relatedIds].some((id) => id && !currentIds.has(id));
}

function blindGoldFormalFamilyPreflightIssues(item = selectedBlindGoldReviewItem(), familyGold = {}, result = "confirmed") {
  if (!item || result === "disputed") return [];
  const sync = item.formalFamilySync;
  if (!sync || sync.status === "not_available") return [];
  const currentIds = new Set((sync.currentFamilyIds || []).map((id) => String(id || "").trim()).filter(Boolean));
  const selectedIds = new Set([
    familyGold.primaryFamilyId,
    ...(Array.isArray(familyGold.relatedFamilyIds) ? familyGold.relatedFamilyIds : []),
  ].map((id) => String(id || "").trim()).filter(Boolean));
  const issues = [];
  const add = (code, message, details = {}) => issues.push({
    questionId: item.questionId,
    order: item.order,
    code,
    message,
    source: "formal_family_preflight",
    requiredStages: ["family"],
    ...details,
  });
  if (sync.currentPrimaryFamilyId && String(familyGold.primaryFamilyId || "") !== String(sync.currentPrimaryFamilyId)) {
    add("primary_family_changed", "当前正式主题族与本题提交的主题族不同。", {
      familyId: sync.currentPrimaryFamilyId,
      expected: sync.currentPrimaryFamilyId,
      actual: familyGold.primaryFamilyId || "",
    });
  }
  if (currentIds.size && (selectedIds.size !== currentIds.size || [...currentIds].some((id) => !selectedIds.has(id)))) {
    add("formal_family_membership_drift", "本题提交的题族关系没有覆盖当前正式题族关系；请先重新载入并按当前关系核对。", {
      expected: [...currentIds],
      actual: [...selectedIds],
    });
  }
  (sync.currentMemberships || [])
    .filter((membership) => membership.reviewStatus !== "confirmed" && selectedIds.has(String(membership.familyId || "")))
    .forEach((membership) => add("family_membership_not_confirmed", "当前题目与所选题族的归属关系仍待确认。", {
      familyId: membership.familyId,
      familyName: membership.familyName,
      expected: "confirmed",
      actual: membership.reviewStatus || "pending_fit",
    }));
  return issues;
}

function blindGoldReviewFamilyById(familyId, item = selectedBlindGoldReviewItem()) {
  const cache = blindGoldReviewCatalogCache(item);
  const itemCacheKey = `${item?.questionId || ""}:${Number(item?.revision || 0)}:${Number(item?.updatedAt || 0)}`;
  const familyMap = cache.familyMapsByQuestion.get(itemCacheKey);
  if (familyMap) return familyMap.get(familyId) || null;
  const catalogFamily = blindGoldReviewFamilies(item).find((family) => family.id === familyId);
  const inlineFamily = blindGoldReviewStoredFamilyGold(item).families?.find((family) => family.id === familyId);
  return catalogFamily || (inlineFamily ? blindGoldReviewCatalogFamily(inlineFamily, item) : null);
}

function blindGoldReviewFamilyName(familyId, item = selectedBlindGoldReviewItem()) {
  const family = blindGoldReviewFamilyById(familyId, item);
  return family?.name || familyId || "未识别题族";
}

function blindGoldReviewSemanticIssueText(issue = {}, item = selectedBlindGoldReviewItem()) {
  const familyName = issue.familyId ? `“${blindGoldReviewFamilyName(issue.familyId, item)}”` : "";
  if (issue.code === "family_status_not_confirmed" || issue.code === "family_status_missing") {
    return `题族${familyName}尚未确认，非争议金标只能使用已确认题族。`;
  }
  if (issue.code === "primary_family_role_inconsistent") {
    return issue.expected === true
      ? `题族${familyName}在正式关系中不是本题主题族，不能直接设为主题族。`
      : `题族${familyName}是本题正式主题族，不能作为关联题族提交。`;
  }
  if (issue.code === "family_membership_not_confirmed") {
    return `题目在${familyName || "所选题族"}中的成员归属仍是待审核，刷新不会自动确认；请先到题族成员管理确认或驳回本题。`;
  }
  if (issue.code === "family_membership_missing") {
    return `题目没有在${familyName || "所选题族"}中形成当前正式成员关系，请先调整题族归属后再保存金标。`;
  }
  if (issue.code === "formal_family_membership_drift") {
    return "本题提交的题族清单与当前正式关系不一致；请重新载入目录并按当前正式关系核对。";
  }
  if (["core_knowledge_mismatch", "candidate_core_knowledge_mismatch"].includes(issue.code)) {
    return `题目知识焦点“${blindGoldReviewNodeLabel(issue.expected || {})}”尚未包含在${familyName ? `题族${familyName}` : "候选主题族"}的本题贡献知识中；后台目录锚点无需与它相等。`;
  }
  if (["required_knowledge_mismatch", "candidate_required_knowledge_mismatch"].includes(issue.code)) {
    const expected = (Array.isArray(issue.expected) ? issue.expected : []).map(blindGoldReviewNodeLabel).join("、") || "未标注";
    const actual = (Array.isArray(issue.actual) ? issue.actual : []).map(blindGoldReviewNodeLabel).join("、") || "未标注";
    return `题目最小充分知识集“${expected}”尚未被主题族与作答必需关联族的本题贡献完整覆盖；当前联合贡献为“${actual}”。`;
  }
  if (issue.code === "required_family_no_knowledge_contribution") {
    const actual = issue.actual && typeof issue.actual === "object" ? issue.actual : {};
    const contribution = Array.isArray(actual)
      ? actual
      : (Array.isArray(actual.contributionKnowledge) ? actual.contributionKnowledge : []);
    const outsideQuestion = Array.isArray(actual.outsideQuestion) ? actual.outsideQuestion : [];
    const outsideFamily = Array.isArray(actual.outsideFamilyCoverage)
      ? actual.outsideFamilyCoverage
      : (Array.isArray(actual.outsideFamily) ? actual.outsideFamily : []);
    const target = familyName ? `题族${familyName}` : "主题族或作答必需关联族";
    if (!contribution.length) {
      return `${target}尚未填写本题贡献知识；请选择它在本题中实际承担的知识。`;
    }
    const invalid = blindGoldUniqueKnowledgeNodes([...outsideQuestion, ...outsideFamily]);
    if (invalid.length) {
      const labels = invalid.map(blindGoldReviewNodeLabel).join("、");
      const reasons = [];
      if (outsideQuestion.length) reasons.push("不在本题最小充分知识集内");
      if (outsideFamily.length) reasons.push("不在该题族覆盖范围内");
      return `${target}已填写本题贡献，但“${labels}”${reasons.join("且")}；请取消无效项或调整题族关系。手动勾选有效项即可提交，无需点击建议按钮。`;
    }
    return `${target}的本题贡献未通过范围校验；请确认贡献知识同时属于题目最小充分知识集和该题族覆盖范围。`;
  }
  if (issue.code === "reference_family_knowledge_contribution_forbidden") {
    return `普通关联题族${familyName}不参与作答联合覆盖，请清空本题贡献知识，或将其改为“作答必需”。`;
  }
  if (issue.code === "family_knowledge_protocol_missing") {
    return "本题仍是旧版题族知识口径，请重新确认各题族的本题贡献知识后保存。";
  }
  if (issue.code === "mature_hidden_question_not_independent") {
    return `成熟题族${familyName}中，本题不是独立主题成员，无法执行留一盲测。`;
  }
  if (issue.code === "mature_family_member_count_invalid") {
    return `成熟题族${familyName}不足 2 个独立成员，请改为单题题族或选择其他题族。`;
  }
  if (issue.code === "singleton_family_member_count_invalid") {
    return `单题题族${familyName}必须恰好只有本题 1 个独立成员。`;
  }
  const message = String(issue.message || "题族裁决存在未通过的一致性检查。")
    .replace(/主题题族/g, "主题族");
  return familyName && !message.includes(familyName) ? `${message}（题族${familyName}）` : message;
}

function blindGoldReviewSemanticIssues(error) {
  const candidates = [
    error?.details?.issues,
    error?.payload?.details?.issues,
    error?.payload?.issues,
  ];
  return candidates.find((issues) => Array.isArray(issues) && issues.length) || [];
}

function setBlindGoldReviewSemanticFeedback(error, item = selectedBlindGoldReviewItem()) {
  const issues = blindGoldReviewSemanticIssues(error);
  if (!issues.length) return false;
  const issueHtml = (issue) => `<li>${escapeHtml(blindGoldReviewSemanticIssueText(issue, item))}</li>`;
  const preview = issues.slice(0, 3);
  const pendingMembershipFamilyIds = new Set(issues
    .filter((issue) => issue.code === "family_membership_not_confirmed")
    .map((issue) => String(issue.familyId || "").trim())
    .filter(Boolean));
  const pendingMembershipActions = (item?.formalFamilySync?.currentMemberships || [])
    .filter((membership) => membership.reviewStatus !== "confirmed"
      && pendingMembershipFamilyIds.has(String(membership.familyId || "").trim()))
    .map((membership) => `<button type="button" class="secondary-action" data-confirm-blind-gold-formal-membership data-family-id="${escapeHtml(membership.familyId)}" data-question-id="${escapeHtml(item.questionId)}" data-membership-revision="${escapeHtml(String(membership.membershipRevision || 0))}">确认“${escapeHtml(membership.familyName || membership.familyId)}”归属并继续</button>`)
    .join("");
  const html = `<ol>${preview.map(issueHtml).join("")}</ol>
    ${issues.length > preview.length ? `<details><summary>展开全部 ${escapeHtml(issues.length)} 项</summary><ol>${issues.map(issueHtml).join("")}</ol></details>` : ""}
    ${pendingMembershipActions ? `<div class="blind-gold-review-feedback-actions">${pendingMembershipActions}</div>` : ""}
    <small>刷新只会重新读取题族目录，不会确认成员归属、改变主题族或修改题目知识。请先处理上面的正式关系，再回到本页保存；仍无法唯一判断时可标记为“存在争议”。</small>`;
  // 弹窗负责逐项说明；顶部横幅保留一句结果摘要，避免残留“正在保存…”的旧文案。
  setBlindGoldReviewFeedback("本题未保存：题族裁决未通过一致性检查，详情见弹窗提示。", "error");
  return openBlindGoldReviewAlert("", {
    title: `题族裁决暂不能保存，共有 ${issues.length} 项需要处理`,
    copy: "页面内容没有变化；请先处理下面的正式关系，再重新提交",
    html,
  });
}

function blindGoldFreezeIssueItem(issue = {}) {
  const questionId = String(issue.questionId || "").trim();
  if (!questionId) return null;
  return (state.blindGoldReviewBatch?.items || []).find((item) => String(item.questionId || "") === questionId) || null;
}

function focusBlindGoldFreezeIssue(questionId = "") {
  const id = String(questionId || "").trim();
  const item = blindGoldFreezeIssueItem({ questionId: id });
  if (!item || state.blindGoldReviewSaving) return false;
  // A blocker can belong to a question hidden by the current filter. Reset the
  // list filters before selecting it so every freeze issue is reachable.
  const search = document.querySelector("#blind-gold-review-search");
  const status = document.querySelector("#blind-gold-review-status");
  const mode = document.querySelector("#blind-gold-review-mode");
  if (search) search.value = "";
  if (status) status.value = "all";
  if (mode) mode.value = "all";
  state.blindGoldBusinessEditMode = false;
  state.blindGoldContentEditable = false;
  state.blindGoldReviewResult = "";
  state.selectedBlindGoldQuestionId = id;
  renderBlindGoldReview();
  requestAnimationFrame(() => document.querySelector(".blind-gold-question-head")?.scrollIntoView({ block: "start", behavior: "smooth" }));
  return true;
}

function setBlindGoldFreezeSemanticFeedback(error) {
  const issues = blindGoldReviewSemanticIssues(error);
  if (!issues.length) return false;
  const issueHtml = (issue) => {
    const item = blindGoldFreezeIssueItem(issue);
    const questionLabel = issue.order ? `第 ${issue.order} 题` : (issue.questionId || "未标明题目");
    const stem = String(item?.question?.stem || "题干暂缺").trim();
    const message = blindGoldReviewSemanticIssueText(issue, item || undefined);
    return `<li><button type="button" class="blind-gold-freeze-issue-button" data-blind-gold-freeze-question-id="${escapeHtml(issue.questionId || "")}">
      <span><strong>${escapeHtml(questionLabel)}</strong>${stem ? ` · ${escapeHtml(stem)}` : ""}</span>
      <small>${escapeHtml(message)}</small>
    </button></li>`;
  };
  const preview = issues.slice(0, 5);
  const html = `<ol class="blind-gold-freeze-issue-list">${preview.map(issueHtml).join("")}</ol>
    ${issues.length > preview.length ? `<details><summary>展开全部 ${escapeHtml(issues.length)} 项</summary><ol class="blind-gold-freeze-issue-list">${issues.map(issueHtml).join("")}</ol></details>` : ""}
    <small>点击任一条目可直接定位到对应题目；修正并保存题族裁决后，再重新生成冻结预览。当前没有写入快照。</small>`;
  setBlindGoldReviewFeedback("未生成冻结预览：题族裁决未通过一致性检查，详情见弹窗提示。", "error");
  return openBlindGoldReviewAlert("", {
    title: `生成冻结预览失败：题族裁决未通过一致性检查，共有 ${issues.length} 项需要处理`,
    copy: "当前没有写入快照；请先修正下面列出的题目",
    html,
  });
}

function setBlindGoldReviewFeedback(message = "", tone = "success") {
  const element = document.querySelector("#blind-gold-review-feedback");
  element.hidden = !message;
  element.className = `blind-gold-review-feedback ${tone}`.trim();
  element.textContent = message;
}

// Blocking validation errors are raised while the reviewer is scrolled down at
// the save buttons, where the inline banner at the top of the page is easy to
// miss. They are surfaced as a modal instead; the banner keeps async progress
// and outcome messages only.
// 支持两种内容：纯文本（message），或带清单与就地操作按钮的富内容（options.html，
// 由调用方负责转义）。题族裁决阻断这类需要逐项处理并当场操作的报错走富内容。
function openBlindGoldReviewAlert(message = "", options = {}) {
  const dialog = document.querySelector("#blind-gold-review-alert-dialog");
  if (!dialog || (!message && !options.html)) return false;
  const title = document.querySelector("#blind-gold-review-alert-title");
  const copy = document.querySelector("#blind-gold-review-alert-copy");
  const body = document.querySelector("#blind-gold-review-alert-message");
  const confirmButton = document.querySelector("#confirm-blind-gold-review-alert");
  if (title) title.textContent = options.title || "无法保存本题审核";
  if (copy) copy.textContent = options.copy || "页面内容没有变化；请先处理下面的问题，再重新提交";
  if (confirmButton) confirmButton.textContent = options.confirmLabel || "知道了";
  if (body) {
    body.classList.toggle("has-rich-content", Boolean(options.html));
    if (options.html) body.innerHTML = options.html;
    else body.textContent = message;
  }
  if (!dialog.open) dialog.showModal();
  return true;
}

function closeBlindGoldReviewAlert() {
  const dialog = document.querySelector("#blind-gold-review-alert-dialog");
  if (dialog?.open) dialog.close();
}

function blindGoldReviewFilteredItems() {
  const batch = state.blindGoldReviewBatch;
  if (!batch) return [];
  const query = document.querySelector("#blind-gold-review-search").value.trim().toLocaleLowerCase("zh-CN");
  const status = document.querySelector("#blind-gold-review-status").value;
  const mode = document.querySelector("#blind-gold-review-mode").value;
  return (batch.items || []).filter((item) => {
    const stage = blindGoldReviewItemStage(item);
    if (status === "needs_revision" && !["content_re_review", "family_re_review", "preflight_blocked"].includes(stage.key)) return false;
    if (status !== "all" && status !== "needs_revision" && blindGoldReviewItemResult(item) !== status) return false;
    if (mode !== "all" && blindGoldReviewReplayMode(item) !== mode) return false;
    if (!query) return true;
  const familyGold = blindGoldReviewStoredFamilyGold(item);
  const haystack = [
      item.questionId,
      item.question?.stem,
      item.answerKnowledge?.coreKnowledge?.path,
      ...(item.answerKnowledge?.requiredKnowledge || []).map(blindGoldReviewNodeLabel),
      ...(familyGold.families || []).map((family) => family.name),
      familyGold.candidateFamily?.name,
    ].join(" ").toLocaleLowerCase("zh-CN");
    return haystack.includes(query);
  });
}

function renderBlindGoldReviewSummary() {
  const batch = state.blindGoldReviewBatch;
  const summary = batch?.summary || {};
  const values = {
    "#blind-gold-total-count": summary.total || batch?.items?.length || 0,
    "#blind-gold-pending-count": summary.pending || 0,
    "#blind-gold-confirmed-count": summary.confirmed || 0,
    "#blind-gold-corrected-count": summary.corrected || 0,
    "#blind-gold-disputed-count": summary.disputed || 0,
    "#blind-gold-scored-count": summary.accuracyEligible || 0,
  };
  Object.entries(values).forEach(([selector, value]) => { document.querySelector(selector).textContent = String(value); });
  const revisionPending = (batch?.items || []).filter((item) => ["content_re_review", "family_re_review", "preflight_blocked"].includes(blindGoldReviewItemStage(item).key)).length;
  const preflightBlocked = blindGoldPreflightBlockedQuestionIds().length;
  document.querySelector("#blind-gold-review-progress").textContent = blindGoldReviewIsRevisionBatch(batch)
    ? `需重审 ${revisionPending}${preflightBlocked ? ` · 预检阻断 ${preflightBlocked}` : ""}`
    : `未审核 ${summary.pending || 0}${preflightBlocked ? ` · 预检阻断 ${preflightBlocked}` : ""}`;
  document.querySelector("#blind-gold-review-scope").textContent = batch
    ? `${batch.title || "盲测金标集"} · 金标集版本 ${batch.version || "V1"} · 两阶段人工审核，不会自动采纳 AI 预测`
    : "逐题确认答案、证据、知识与题族裁决；审核内容不会自动采纳本轮 AI 预测";
  const freezeButton = document.querySelector("#freeze-blind-gold-set");
  const verifyButton = document.querySelector("#verify-blind-gold-preflight");
  if (verifyButton) {
    verifyButton.hidden = !batch || batch.status === "frozen";
    verifyButton.disabled = !batch || batch.status === "frozen" || state.blindGoldReviewSaving;
    verifyButton.textContent = preflightBlocked ? `重新校验（阻断 ${preflightBlocked}）` : "重新校验";
  }
  const hasBusinessDrift = (batch?.items || []).some((item) => ["question_drift", "knowledge_drift"].includes(item.businessSync?.status));
  const frozen = batch?.status === "frozen";
  freezeButton.disabled = !summary.readyToFreeze || hasBusinessDrift;
  freezeButton.disabled = frozen
    ? !batch || state.blindGoldReviewSaving
    : freezeButton.disabled || !batch || state.blindGoldReviewSaving;
  freezeButton.textContent = frozen
    ? `创建 ${blindGoldRevisionNextVersion(batch.version)} 修订草稿`
    : `生成金标集版本 ${batch?.version || "V1"}`;
  freezeButton.title = frozen
    ? `${batch.version || "V1"} 保持不可变，只复制并重审风险项`
    : "完成全部人工审核后生成不可变金标快照";
}

function renderBlindGoldFreezeSummary() {
  const batch = state.blindGoldReviewBatch;
  const snapshot = batch?.snapshot;
  const section = document.querySelector("#blind-gold-freeze-summary");
  section.hidden = batch?.status !== "frozen" || !snapshot;
  if (section.hidden) return;
  document.querySelector("#blind-gold-freeze-title").textContent = `${batch.title || "20题盲测金标集"}${String(batch.title || "").endsWith(batch.version || "V1") ? "" : ` ${batch.version || "V1"}`}`;
  document.querySelector("#blind-gold-freeze-scored").textContent = `${snapshot.summary?.accuracyEligible || 0} 题`;
  document.querySelector("#blind-gold-freeze-needs-review").textContent = `${snapshot.summary?.goldNeedsReview || 0} 题`;
  document.querySelector("#blind-gold-freeze-reviewer").textContent = snapshot.frozenBy || batch.frozenBy || "-";
  document.querySelector("#blind-gold-freeze-time").textContent = formatTaskTime(snapshot.frozenAt || batch.frozenAt);
  document.querySelector("#blind-gold-freeze-version").textContent = snapshot.version || batch.version || "V1";
  document.querySelector("#blind-gold-freeze-hash").textContent = snapshot.fileSha256 || "-";
  document.querySelector("#blind-gold-freeze-path").textContent = `内容 SHA-256：${snapshot.contentSha256 || "-"}${snapshot.filePath ? ` · 快照：${snapshot.filePath}` : ""}。本页未启动新一轮盲测。`;
}

function renderBlindGoldRevisionLineage() {
  const batch = state.blindGoldReviewBatch;
  const source = batch?.source || {};
  const section = document.querySelector("#blind-gold-revision-lineage");
  section.hidden = !blindGoldReviewIsRevisionBatch(batch);
  if (section.hidden) return;
  document.querySelector("#blind-gold-revision-current-version").textContent = `${batch.version || "-"} · ${batch.status === "frozen" ? "已冻结" : "修订草稿"}`;
  document.querySelector("#blind-gold-revision-parent-version").textContent = source.parentVersion || batch.parentVersion || "-";
  document.querySelector("#blind-gold-revision-parent-file-hash").textContent = source.parentFileSha256 || batch.parentFileSha256 || "-";
  document.querySelector("#blind-gold-revision-parent-content-hash").textContent = source.parentContentSha256 || batch.parentContentSha256 || "-";
}

function renderBlindGoldReviewList() {
  const container = document.querySelector("#blind-gold-review-list");
  const items = blindGoldReviewFilteredItems();
  if (!state.blindGoldReviewBatch) {
    container.innerHTML = '<div class="blind-gold-review-empty">当前没有已导入的盲测金标审核批次</div>';
    return;
  }
  if (!items.length) {
    container.innerHTML = '<div class="blind-gold-review-empty">当前筛选下没有题目</div>';
    return;
  }
  container.innerHTML = items.map((item) => {
    const stage = blindGoldReviewItemStage(item);
    const risk = blindGoldReviewItemRisk(item);
    const mode = blindGoldReviewModeAuditLabel(item);
    return `<button class="${item.questionId === state.selectedBlindGoldQuestionId ? "is-active" : ""}" type="button" data-blind-gold-question-id="${escapeHtml(item.questionId)}">
      <span class="blind-gold-review-list-index">${escapeHtml(item.order)}</span>
      <span class="blind-gold-review-list-copy"><strong>${escapeHtml(item.question?.stem || "题干暂缺")}</strong><span class="blind-gold-review-list-mode">${escapeHtml(mode)}</span>${risk ? `<small><b>风险</b> ${escapeHtml(risk)}</small>` : ""}</span>
      <span class="blind-gold-review-list-state ${escapeHtml(stage.key)}">${escapeHtml(stage.label)}</span>
    </button>`;
  }).join("");
}

function updateBlindGoldReviewListSelection(questionId = "") {
  const container = document.querySelector("#blind-gold-review-list");
  if (!container) return;
  const buttons = [...container.querySelectorAll("[data-blind-gold-question-id]")];
  if (!buttons.length) {
    renderBlindGoldReviewList();
    return;
  }
  buttons.forEach((button) => {
    button.classList.toggle("is-active", button.dataset.blindGoldQuestionId === questionId);
  });
}

function blindGoldReviewKnowledgeTagsHtml(nodes = []) {
  const labels = nodes.map(blindGoldReviewNodeLabel).filter(Boolean);
  if (!labels.length) return '<span class="blind-gold-knowledge-tag is-empty">未标注</span>';
  return labels.map((label) => `<span class="blind-gold-knowledge-tag">${escapeHtml(label)}</span>`).join("");
}

const blindGoldOptionKnowledgeRelationLabels = {
  unreviewed: "未判断",
  question_only: "仅题目知识",
  option_specific: "另有选项知识",
  undetermined: "暂无法判断",
};
const blindGoldOptionKnowledgeProtocolVersion = "option-knowledge-v2";

function blindGoldReviewHumanAnswerKnowledge(item = {}) {
  const finalGold = item.finalGold?.answerKnowledge
    || item.finalGold?.answerAndEvidence
    || item.finalGold?.knowledgeGold;
  return item.humanGold?.answerKnowledge || finalGold || item.answerKnowledge || {};
}

const blindGoldCoreKnowledgeRoleLabels = {
  core: "作答核心",
  scope_anchor: "范围锚点",
};

function blindGoldCoreKnowledgeRole(answerKnowledge = {}) {
  return answerKnowledge?.coreKnowledgeRole === "scope_anchor" ? "scope_anchor" : "core";
}

function blindGoldSelectedCoreKnowledgeRole(item = selectedBlindGoldReviewItem()) {
  const selected = document.querySelector('input[name="blind-gold-core-knowledge-role"]:checked')?.value;
  return selected === "scope_anchor" || selected === "core"
    ? selected
    : blindGoldCoreKnowledgeRole(blindGoldReviewHumanAnswerKnowledge(item || {}));
}

function syncBlindGoldCoreKnowledgeRoleUi(item = selectedBlindGoldReviewItem()) {
  const role = blindGoldSelectedCoreKnowledgeRole(item);
  const field = document.querySelector(".blind-gold-core-knowledge-field");
  const coreHelp = document.querySelector("#blind-gold-core-knowledge-help");
  const requiredHelp = document.querySelector("#blind-gold-required-knowledge-help");
  if (field) field.dataset.coreKnowledgeRole = role;
  if (coreHelp) coreHelp.textContent = role === "scope_anchor"
    ? "范围锚点仅组织跨知识范围，不计入最小充分知识或题族联合覆盖。"
    : "作答核心会自动加入并锁定在最小充分知识集。";
  if (requiredHelp) requiredHelp.textContent = role === "scope_anchor"
    ? "范围锚点不自动包含；请选择实际作答必需知识。"
    : "作答核心自动包含；仅在修正正式题目时可修改。";
}

function blindGoldReviewCurrentAnswerKnowledge(item = selectedBlindGoldReviewItem()) {
  const stored = blindGoldReviewHumanAnswerKnowledge(item || {});
  const selectedItem = selectedBlindGoldReviewItem();
  const coreSelect = document.querySelector("#blind-gold-core-knowledge");
  const requiredSelect = document.querySelector("#blind-gold-required-knowledge");
  if (!item || selectedItem?.questionId !== item.questionId || !coreSelect?.options.length || !requiredSelect) {
    return stored;
  }
  return {
    ...stored,
    coreKnowledge: blindGoldReviewResolveNode(coreSelect.value, item),
    coreKnowledgeRole: blindGoldSelectedCoreKnowledgeRole(item),
    requiredKnowledge: blindGoldReviewSelectedNodes("#blind-gold-required-knowledge", item),
  };
}

function blindGoldReviewChoiceStructure(item = {}, answerKnowledge = blindGoldReviewHumanAnswerKnowledge(item)) {
  const value = answerKnowledge?.choiceStructure
    || item.finalGold?.choiceStructure
    || item.choiceStructure
    || item.question?.choiceStructure;
  return value === "composed_options" ? "composed_options" : "direct_options";
}

function blindGoldAtomicStatementKey(statement = {}, index = 0) {
  return String(statement.key || statement.statementKey || statement.id || statement.label || `S${index + 1}`).trim();
}

function blindGoldReviewAtomicStatements(item = {}, answerKnowledge = blindGoldReviewHumanAnswerKnowledge(item)) {
  const stored = Array.isArray(answerKnowledge?.atomicStatements) ? answerKnowledge.atomicStatements : [];
  const source = Array.isArray(item.question?.atomicStatements)
    ? item.question.atomicStatements
    : (Array.isArray(item.atomicStatements) ? item.atomicStatements : []);
  if (!source.length) return stored.map((statement, index) => ({
    ...statement,
    key: blindGoldAtomicStatementKey(statement, index),
  }));
  return source.map((statement, index) => {
    const key = blindGoldAtomicStatementKey(statement, index);
    const reviewed = stored.find((entry, storedIndex) => blindGoldAtomicStatementKey(entry, storedIndex) === key) || {};
    return { ...statement, ...reviewed, key, text: statement.text || reviewed.text || "" };
  });
}

function blindGoldCompositionRefs(value) {
  if (Array.isArray(value)) return [...new Set(value.map(String).map((entry) => entry.trim()).filter(Boolean))];
  const text = String(value || "").trim();
  if (!text) return [];
  const circled = text.match(/[\u2460-\u2473]/gu);
  return [...new Set(circled?.length ? circled : text.split(/[,，、+\s]+/u).filter(Boolean))];
}

function blindGoldReviewOptionComposition(item = {}, answerKnowledge = blindGoldReviewHumanAnswerKnowledge(item)) {
  const raw = answerKnowledge?.optionComposition
    || item.finalGold?.optionComposition
    || item.optionComposition
    || item.question?.optionComposition
    || [];
  const entries = Array.isArray(raw)
    ? raw.map((entry) => [entry?.optionKey || entry?.key, entry])
    : Object.entries(raw || {});
  return entries.map(([fallbackKey, entry = {}]) => {
    const value = entry && typeof entry === "object" && !Array.isArray(entry) ? entry : { atomicKeys: entry };
    return {
      ...value,
      optionKey: String(value.optionKey || value.key || fallbackKey || "").trim().toUpperCase(),
      atomicKeys: blindGoldCompositionRefs(value.atomicKeys || value.atomicStatementKeys
        || value.statementKeys || value.statementRefs || value.refs || value.atomicStatementIds),
    };
  }).filter((entry) => entry.optionKey);
}

function blindGoldOptionKnowledgeRelation(option = {}) {
  const relation = String(option.knowledgeRelation || "").trim();
  if (Object.hasOwn(blindGoldOptionKnowledgeRelationLabels, relation)) return relation;
  return "unreviewed";
}

function blindGoldOptionKnowledgeRelationSummaryHtml(relation, selectedCount = 0, selectedNodes = []) {
  const label = relation === "option_specific"
    ? (selectedCount ? `已标注 ${selectedCount} 项` : "需选择选项知识")
    : (blindGoldOptionKnowledgeRelationLabels[relation] || blindGoldOptionKnowledgeRelationLabels.unreviewed);
  const knowledge = relation === "option_specific" && selectedNodes.length
    ? blindGoldReviewKnowledgeTagsHtml(selectedNodes)
    : "";
  return `<span class="blind-gold-option-relation-badge ${escapeHtml(relation || "unreviewed")}">${escapeHtml(label)}</span>${knowledge}`;
}

function blindGoldKnowledgePickerSummary(nodes = [], emptyLabel = "请选择涉及知识") {
  const labels = nodes.map(blindGoldReviewNodeLabel).filter(Boolean);
  if (labels.length > 1) return `${labels[0]} · 另 ${labels.length - 1} 项`;
  return labels[0] || emptyLabel;
}

// 选项知识是否纳入"问题知识范围"：由主题范围锚点自动判定，不需要人工选择。
// 在锚点之下 → 纳入范围；跨主题 → 只记在该选项行（不参与覆盖、不影响题族归属与推送）。
function blindGoldOptionThemeScopeBadgeHtml(nodes, selectedNodes = [], anchorNodeId = "") {
  const anchor = String(anchorNodeId || "");
  if (!anchor) return "";
  const nodeMap = new Map((Array.isArray(nodes) ? nodes : []).map((node) => [String(node.id), node]));
  if (!nodeMap.has(anchor)) return "";
  const nodeIds = (Array.isArray(selectedNodes) ? selectedNodes : [])
    .map((node) => String(node?.id || node || "")).filter(Boolean);
  if (!nodeIds.length) return "";
  const { within, outside } = partitionKnowledgeNodesByThemeAnchor(nodeMap, nodeIds, anchor);
  const anchorLabel = nodeMap.get(anchor)?.path || nodeMap.get(anchor)?.title || anchor;
  const outsideLabels = outside.map((nodeId) => nodeMap.get(nodeId)?.path
    || nodeMap.get(nodeId)?.title || nodeId);
  if (!outside.length) {
    return `<span class="blind-gold-option-scope-badge is-in-scope" data-blind-gold-option-scope="within"`
      + ` title="在主题范围「${escapeHtml(anchorLabel)}」之下，已纳入问题知识范围">入范围</span>`;
  }
  const withinNote = within.length ? `另有 ${within.length} 项纳入范围；` : "";
  return `<span class="blind-gold-option-scope-badge is-cross-theme" data-blind-gold-option-scope="cross_theme"`
    + ` title="${escapeHtml(`超出主题范围「${anchorLabel}」：${outsideLabels.join("、")}。${withinNote}跨主题知识只记在该选项行，不进入问题知识范围。`)}"`
    + `>跨主题 · 仅记在选项</span>`;
}

function blindGoldKnowledgePickerHtml(nodes, selectedNodes, pickerId, optionKey, frozen, unitLabel = "选项", selectDataAttribute = "data-blind-gold-option-knowledge") {  const summary = blindGoldKnowledgePickerSummary(selectedNodes);
  const pickerLabel = [optionKey, unitLabel].filter(Boolean).join(" ");
  const hiddenSelectAttributes = selectDataAttribute === "data-blind-gold-option-knowledge"
    ? "data-blind-gold-option-knowledge multiple hidden"
    : `${selectDataAttribute} multiple hidden`;
  return `<div class="question-family-multiselect blind-gold-knowledge-picker" data-blind-gold-knowledge-picker data-blind-gold-knowledge-empty-label="请选择涉及知识" data-blind-gold-knowledge-label="${escapeHtml(pickerLabel)}涉及知识">
    <button class="question-family-multiselect-trigger" data-blind-gold-knowledge-trigger type="button" aria-haspopup="dialog" aria-expanded="false" aria-controls="${escapeHtml(pickerId)}-panel" aria-label="选择 ${escapeHtml(pickerLabel)}涉及知识" ${frozen ? "disabled" : ""}><span data-blind-gold-knowledge-summary title="${escapeHtml((selectedNodes || []).map(blindGoldReviewNodeLabel).filter(Boolean).join("\n"))}">${escapeHtml(summary)}</span><i aria-hidden="true"></i></button>
    <div class="question-family-multiselect-panel" id="${escapeHtml(pickerId)}-panel" data-blind-gold-knowledge-panel popover="auto" role="dialog" aria-label="选择 ${escapeHtml(pickerLabel)}涉及知识" hidden>
      <input class="question-family-multiselect-search" data-blind-gold-knowledge-search type="search" placeholder="搜索涉及知识" aria-label="搜索 ${escapeHtml(pickerLabel)}涉及知识" autocomplete="off" />
      <div class="question-family-multiselect-options" data-blind-gold-knowledge-options role="group" aria-label="${escapeHtml(`${pickerLabel || "涉及知识"}涉及知识`)}"></div>
    </div>
    <select data-blind-gold-knowledge-select ${hiddenSelectAttributes} aria-hidden="true" tabindex="-1" ${frozen ? "disabled" : ""}>${blindGoldReviewNodeOptions(nodes, selectedNodes)}</select>
  </div>`;
}

// 从审核条目里取本题的主题范围锚点（随 fingerprint 留痕）。
// 缺失时返回空字符串 —— 此时不显示范围徽标，避免用错误前提做判断。
function blindGoldReviewThemeAnchorNodeId(item = {}) {
  const provenance = item.humanGold?.answerKnowledgeProvenance
    || item.answerKnowledgeProvenance
    || item.finalGold?.answerKnowledgeProvenance
    || {};
  const fingerprint = provenance.fingerprint || {};
  return String(fingerprint.knowledgeThemeRangeAnchorNodeId
    || fingerprint.themeRangeAnchorNodeId
    || fingerprint.scopeAnchorNodeId
    || "");
}

function blindGoldReviewOptionKnowledgeHtml(item, nodes, frozen) {
  const answerKnowledge = blindGoldReviewHumanAnswerKnowledge(item);
  const choiceStructure = blindGoldReviewChoiceStructure(item, answerKnowledge);
  const composed = choiceStructure === "composed_options";
  const themeAnchorNodeId = blindGoldReviewThemeAnchorNodeId(item);
  const savedRows = answerKnowledge.optionKnowledge || [];
  const rows = composed
    ? blindGoldReviewAtomicStatements(item, answerKnowledge)
    : (item.question?.options || []).map((questionOption) => ({
      role: "unreviewed",
      knowledgeNodeIds: [],
      knowledgeLabels: [],
      ...savedRows.find((option) => option.key === questionOption.key),
      key: questionOption.key,
      text: questionOption.text,
    }));
  const knowledgeTable = rows.length ? `<div class="blind-gold-option-table ${composed ? "is-atomic" : ""}" role="table" aria-label="${composed ? "原子陈述" : "选项角色"}、知识关系与涉及知识">
    <div class="blind-gold-option-table-head" role="row"><span role="columnheader">${composed ? "原子陈述" : "选项"}</span><span role="columnheader">${composed ? "单元" : "角色"}</span><span role="columnheader">知识关系 / 涉及知识</span></div>
    ${rows.map((option, optionIndex) => {
      const selectedNodes = blindGoldReviewStoredKnowledgeNodes(option.knowledgeNodeIds, option.knowledgeLabels, nodes);
      const knowledgeRelation = blindGoldOptionKnowledgeRelation(option);
      const displayedNodes = knowledgeRelation === "option_specific" ? selectedNodes : [];
      const optionKey = blindGoldAtomicStatementKey(option, optionIndex);
      const optionText = option.text || item.question?.options?.find((entry) => entry.key === optionKey)?.text || "";
      const roleLabel = composed ? "原子陈述" : (option.role === "answer" ? "正确项" : (option.role === "distractor" ? "干扰项" : (option.role === "unreviewed" ? "待人工判断" : "中性")));
      const pickerId = `blind-gold-option-knowledge-${optionIndex}`;
      return `<details class="blind-gold-option-knowledge-row" data-blind-gold-option-row="${escapeHtml(optionKey)}" data-blind-gold-unit-kind="${composed ? "atomic" : "option"}">
        <summary class="blind-gold-option-row-summary" role="row">
          <span class="blind-gold-option-cell" role="cell"><strong>${escapeHtml(optionKey)}</strong><span>${escapeHtml(optionText)}</span></span>
          <span class="blind-gold-option-role-badge ${composed ? "statement" : escapeHtml(option.role || "neutral")}" data-blind-gold-option-role-summary role="cell">${escapeHtml(roleLabel)}</span>
          <span class="blind-gold-option-tags" data-blind-gold-option-tags role="cell">${blindGoldOptionKnowledgeRelationSummaryHtml(knowledgeRelation, displayedNodes.length, displayedNodes)}${displayedNodes.length ? blindGoldOptionThemeScopeBadgeHtml(nodes, displayedNodes, themeAnchorNodeId) : ""}</span>
        </summary>
        <div class="blind-gold-option-row-editor ${composed ? "is-atomic" : ""}">
          ${composed
    ? `<input type="hidden" data-blind-gold-option-role value="${escapeHtml(option.role || "statement")}" />`
    : `<label><span>角色</span><select data-blind-gold-option-role ${frozen ? "disabled" : ""}><option value="unreviewed" disabled ${option.role === "unreviewed" ? "selected" : ""}>待人工判断</option><option value="answer" ${option.role === "answer" ? "selected" : ""}>正确项</option><option value="distractor" ${option.role === "distractor" ? "selected" : ""}>干扰项</option><option value="neutral" ${option.role === "neutral" ? "selected" : ""}>中性</option></select></label>`}
          <label><span>知识关系</span><select data-blind-gold-option-knowledge-relation ${frozen ? "disabled" : ""}><option value="unreviewed" disabled ${knowledgeRelation === "unreviewed" ? "selected" : ""}>未判断</option><option value="question_only" ${knowledgeRelation === "question_only" ? "selected" : ""}>仅使用题目知识</option><option value="option_specific" ${knowledgeRelation === "option_specific" ? "selected" : ""}>另有选项知识</option><option value="undetermined" ${knowledgeRelation === "undetermined" ? "selected" : ""}>暂无法判断</option></select></label>
          ${composed ? `<label class="blind-gold-atomic-basis-field"><span>删除检验依据</span><textarea data-blind-gold-atomic-basis rows="2" placeholder="说明移除候选知识后，为何仍能或不能判断该陈述" ${frozen ? "readonly" : ""}>${escapeHtml(option.basis || "")}</textarea></label>` : ""}
          <div class="blind-gold-option-knowledge-field" data-blind-gold-option-knowledge-field ${knowledgeRelation === "option_specific" ? "" : "hidden"}><span>涉及知识</span>${blindGoldKnowledgePickerHtml(nodes, displayedNodes, pickerId, optionKey, frozen, composed ? "原子陈述" : "选项")}</div>
          <label class="blind-gold-option-uncertainty-field" data-blind-gold-option-uncertainty-field ${knowledgeRelation === "undetermined" ? "" : "hidden"}><span>不确定说明</span><textarea data-blind-gold-option-uncertainty-note rows="2" placeholder="记录当前无法判断的证据缺口" ${frozen ? "readonly" : ""}>${escapeHtml(option.uncertaintyNote || "")}</textarea></label>
          <small data-blind-gold-option-relation-help>${knowledgeRelation === "question_only" ? `本${composed ? "原子陈述" : "选项"}只使用题目层已有知识，不增加独立知识归属。` : (knowledgeRelation === "undetermined" ? "当前证据不足，请记录无法判断的原因。" : (knowledgeRelation === "option_specific" ? `请选择判断该${composed ? "原子陈述" : "选项"}时必须调用的独立知识。` : `请先判断本${composed ? "原子陈述" : "选项"}与知识的关系。`))}</small>
        </div>
      </details>`;
    }).join("")}
  </div>` : (composed ? '<div class="blind-gold-option-structure-warning">组合题尚未提供可审核的原子陈述。</div>' : "");
  if (composed) {
    const composition = blindGoldReviewOptionComposition(item, answerKnowledge);
    const compositionByKey = new Map(composition.map((entry) => [entry.optionKey, entry]));
    const storedCorrectAnswer = answerKnowledge.correctAnswer || item.question?.correctAnswer || [];
    const correctAnswers = new Set((Array.isArray(storedCorrectAnswer) ? storedCorrectAnswer : [storedCorrectAnswer])
      .map((key) => String(key).toUpperCase()));
    const optionRows = (item.question?.options || []).map((option) => {
      const key = String(option.key || "").toUpperCase();
      const mapping = compositionByKey.get(key);
      const role = correctAnswers.has(key) ? "answer" : "distractor";
      const refs = mapping?.atomicKeys || [];
      return `<div class="blind-gold-composition-row" role="row">
        <span class="blind-gold-option-cell" role="cell"><strong>${escapeHtml(key)}</strong><span>${escapeHtml(option.text || "")}</span></span>
        <span class="blind-gold-option-role-badge ${role}" role="cell">${role === "answer" ? "正确项" : "干扰项"}</span>
        <span class="blind-gold-composition-refs" role="cell">${refs.length ? refs.map((ref) => `<b>${escapeHtml(ref)}</b>`).join("") : "未提供原子映射"}</span>
      </div>`;
    }).join("");
    return `${knowledgeTable}<div class="blind-gold-composition-table" role="table" aria-label="组合选项映射与答案角色">
      <div class="blind-gold-composition-head" role="row"><span role="columnheader">答案选项</span><span role="columnheader">答案角色</span><span role="columnheader">原子映射</span></div>
      ${optionRows || '<div class="blind-gold-option-structure-warning">当前没有组合答案选项。</div>'}
    </div>`;
  }
  if (knowledgeTable) return knowledgeTable;
  const points = answerKnowledge.scoringPoints || [];
  if (points.length) return points.map((point, index) => blindGoldScoringPointRowHtml(point, index, nodes, frozen)).join("");
  return "<span>本题暂无选项知识或主观题得分点预填，请在审核说明中记录缺口。</span>";
}

function blindGoldScoringPointRowHtml(point = {}, index = 0, nodes = [], frozen = false) {
  const selectedNodes = blindGoldReviewStoredKnowledgeNodes(point.knowledgeNodeIds, point.knowledgeLabels, nodes);
  const pickerId = `blind-gold-scoring-knowledge-${index}`;
  return `<div class="blind-gold-scoring-point-row" data-blind-gold-scoring-point="${escapeHtml(index)}">
    <label><span>得分点 ${index + 1}</span><textarea data-blind-gold-scoring-description rows="2" ${frozen ? "readonly" : ""}>${escapeHtml(point.description || "")}</textarea></label>
    <label><span>分值</span><input data-blind-gold-scoring-score type="number" min="0" step="0.5" value="${escapeHtml(point.score ?? 0)}" ${frozen ? "readonly" : ""} /></label>
    <label><span>依赖知识</span>${blindGoldKnowledgePickerHtml(nodes, selectedNodes, pickerId, `得分点 ${index + 1}`, frozen, "", "data-blind-gold-scoring-knowledge")}</label>
    <button class="secondary-action blind-gold-remove-scoring-point" data-blind-gold-remove-scoring-point type="button" ${frozen ? "disabled" : ""}>删除</button>
  </div>`;
}

function blindGoldReviewOptionRelationSummary(item = selectedBlindGoldReviewItem(), relations = null) {
  const answerKnowledge = blindGoldReviewHumanAnswerKnowledge(item || {});
  const choiceStructure = blindGoldReviewChoiceStructure(item || {}, answerKnowledge);
  const applicable = Boolean((item?.question?.options || []).length || choiceStructure === "composed_options");
  const optionKnowledge = answerKnowledge.optionKnowledge || [];
  const questionOptions = item?.question?.options || [];
  const units = choiceStructure === "composed_options"
    ? blindGoldReviewAtomicStatements(item || {}, answerKnowledge)
    : questionOptions.map((option) => optionKnowledge.find((reviewed) => reviewed.key === option.key) || {});
  const values = Array.isArray(relations)
    ? relations
    : units.map((unit) => blindGoldOptionKnowledgeRelation(unit));
  const counts = { unreviewed: 0, question_only: 0, option_specific: 0, undetermined: 0 };
  values.forEach((value) => {
    const relation = Object.hasOwn(counts, value) ? value : "unreviewed";
    counts[relation] += 1;
  });
  let status = "不适用";
  if (applicable && !values.length) status = choiceStructure === "composed_options" ? "待判断：缺少原子陈述" : "待判断";
  else if (counts.unreviewed) status = `待判断 ${counts.unreviewed} 项`;
  else if (counts.undetermined) status = `已完成，${counts.undetermined} 项暂无法判断`;
  else if (values.length && counts.question_only === values.length) status = "全部仅使用题目知识";
  else if (values.length && counts.option_specific === values.length) status = "全部另有选项知识";
  else if (values.length) status = "混合";
  return { applicable, choiceStructure, total: values.length, counts, status };
}

function renderBlindGoldOptionRelationSummary(item = selectedBlindGoldReviewItem(), options = {}) {
  const overview = document.querySelector("#blind-gold-option-relation-overview");
  if (!overview || !item) return;
  const relations = options.fromDom
    ? [...document.querySelectorAll("#blind-gold-answer-knowledge [data-blind-gold-option-knowledge-relation]")].map((control) => control.value || "unreviewed")
    : null;
  const summary = blindGoldReviewOptionRelationSummary(item, relations);
  const labels = [
    ["unreviewed", "未判断"],
    ["question_only", "仅题目知识"],
    ["option_specific", "另有选项知识"],
    ["undetermined", "暂无法判断"],
  ];
  overview.dataset.choiceStructure = summary.choiceStructure;
  overview.classList.toggle("is-not-applicable", !summary.applicable);
  document.querySelector("#blind-gold-option-relation-counts").innerHTML = summary.applicable
    ? labels.map(([key, label]) => `<span class="${key}"><b>${summary.counts[key]}</b>${label}</span>`).join("")
    : '<span class="not_applicable"><b>-</b>非选择题</span>';
  const modeLabel = summary.choiceStructure === "composed_options" ? "组合选项·原子陈述" : "选项知识关系";
  document.querySelector("#blind-gold-option-relation-status").textContent = `${modeLabel}：${summary.status}`;
  document.querySelector("#set-all-blind-gold-question-only").hidden = !summary.applicable || !summary.total;
}

function syncBlindGoldOptionKnowledgeSummary(row) {
  if (!row) return;
  const atomic = row.dataset.blindGoldUnitKind === "atomic";
  const role = row.querySelector("[data-blind-gold-option-role]")?.value || (atomic ? "statement" : "neutral");
  const roleSummary = row.querySelector("[data-blind-gold-option-role-summary]");
  if (roleSummary) {
    roleSummary.className = `blind-gold-option-role-badge ${atomic ? "statement" : role}`;
    roleSummary.dataset.blindGoldOptionRoleSummary = "";
    roleSummary.setAttribute("role", "cell");
    roleSummary.textContent = atomic ? "原子陈述" : (role === "answer" ? "正确项" : (role === "distractor" ? "干扰项" : (role === "unreviewed" ? "待人工判断" : "中性")));
  }
  const tags = row.querySelector("[data-blind-gold-option-tags]");
  const relation = row.querySelector("[data-blind-gold-option-knowledge-relation]")?.value || "unreviewed";
  const selected = [...(row.querySelector("[data-blind-gold-option-knowledge]")?.selectedOptions || [])]
    .map((option) => blindGoldReviewResolveNode(option.value));
  if (tags) tags.innerHTML = blindGoldOptionKnowledgeRelationSummaryHtml(relation, selected.length, selected);
  renderBlindGoldOptionRelationSummary(selectedBlindGoldReviewItem(), { fromDom: true });
}

function syncBlindGoldOptionKnowledgeRelation(row, options = {}) {
  if (!row) return;
  const relation = row.querySelector("[data-blind-gold-option-knowledge-relation]")?.value || "unreviewed";
  const field = row.querySelector("[data-blind-gold-option-knowledge-field]");
  const picker = field?.querySelector("[data-blind-gold-knowledge-picker]");
  const select = picker && blindGoldKnowledgePickerSelect(picker);
  const uncertaintyField = row.querySelector("[data-blind-gold-option-uncertainty-field]");
  const uncertaintyNote = uncertaintyField?.querySelector("[data-blind-gold-option-uncertainty-note]");
  const optionSpecific = relation === "option_specific";
  const undetermined = relation === "undetermined";
  if (!optionSpecific && select && options.clear !== false) {
    [...select.options].forEach((option) => { option.selected = false; });
    setBlindGoldKnowledgePickerOpen(picker, false);
  }
  if (!undetermined && uncertaintyNote && options.clear !== false) uncertaintyNote.value = "";
  if (field) field.hidden = !optionSpecific;
  if (uncertaintyField) uncertaintyField.hidden = !undetermined;
  if (picker) renderBlindGoldKnowledgePicker(picker);
  const help = row.querySelector("[data-blind-gold-option-relation-help]");
  const unitLabel = row.dataset.blindGoldUnitKind === "atomic" ? "原子陈述" : "选项";
  if (help) help.textContent = relation === "question_only"
    ? `本${unitLabel}只使用题目层已有知识，不增加独立知识归属。`
    : (relation === "undetermined"
      ? "当前证据不足，请记录无法判断的原因。"
      : (relation === "option_specific" ? `请选择判断该${unitLabel}时必须调用的独立知识。` : `请先判断本${unitLabel}与知识的关系。`));
  syncBlindGoldOptionKnowledgeSummary(row);
}

function setAllBlindGoldOptionsQuestionOnly() {
  const item = selectedBlindGoldReviewItem();
  const contentComplete = blindGoldReviewStageIsComplete(item?.contentReview);
  if (!item || state.blindGoldReviewBatch?.status === "frozen" || blindGoldReviewItemIsReadOnly(item) || contentComplete
    || !state.blindGoldContentEditable || state.blindGoldBusinessEditMode || state.blindGoldReviewSaving) return;
  const rows = [...document.querySelectorAll("#blind-gold-answer-knowledge [data-blind-gold-option-row]")];
  if (!rows.length) return;
  const affected = rows.filter((row) => {
    const relation = row.querySelector("[data-blind-gold-option-knowledge-relation]")?.value || "unreviewed";
    const hasKnowledge = [...(row.querySelector("[data-blind-gold-option-knowledge]")?.selectedOptions || [])].length > 0;
    const hasUncertainty = Boolean(row.querySelector("[data-blind-gold-option-uncertainty-note]")?.value.trim());
    return relation !== "question_only" || hasKnowledge || hasUncertainty;
  });
  if (!affected.length) {
    setBlindGoldReviewFeedback("当前所有选项都已是“仅使用题目知识”。", "success");
    return;
  }
  const labels = affected.map((row) => row.dataset.blindGoldOptionRow).filter(Boolean);
  const confirmed = window.confirm(`确认将以下${blindGoldReviewChoiceStructure(item) === "composed_options" ? "原子陈述" : "选项"}设为“仅使用题目知识”吗？\n${labels.join("、")}\n\n已选知识节点与不确定说明将被清除。`);
  if (!confirmed) return;
  affected.forEach((row) => {
    const relation = row.querySelector("[data-blind-gold-option-knowledge-relation]");
    if (relation) relation.value = "question_only";
    const knowledge = row.querySelector("[data-blind-gold-option-knowledge]");
    if (knowledge) [...knowledge.options].forEach((option) => { option.selected = false; });
    const uncertainty = row.querySelector("[data-blind-gold-option-uncertainty-note]");
    if (uncertainty) uncertainty.value = "";
    syncBlindGoldOptionKnowledgeRelation(row, { clear: true });
  });
  markBlindGoldContentChanged();
  renderBlindGoldOptionRelationSummary(item, { fromDom: true });
  setBlindGoldReviewFeedback(`已将 ${labels.join("、")} 设为仅使用题目知识；未保存。`, "success");
}

function blindGoldKnowledgePickerRoots() {
  // 重构第 ① 步：除既有两处外，任何带通用标记 data-knowledge-picker-root 的容器内的选择器也纳入。
  // 这样题目编辑页的选项表格可以复用同一份实现，而不必再写第二个选择器。
  return [...document.querySelectorAll([
    "#blind-gold-review-form [data-blind-gold-knowledge-picker]",
    "#knowledge-inspection-dialog [data-blind-gold-knowledge-picker]",
    "[data-knowledge-picker-root] [data-blind-gold-knowledge-picker]",
  ].join(", "))];
}

function blindGoldKnowledgePickerSelect(root) {
  // 重构第 ② 步：编辑页的选项表格用 data-question-option-knowledge 承载选中值，
  // 这里一并接受，使同一份选择器实现可以直接服务两处。
  return root?.querySelector("[data-blind-gold-knowledge-select], [data-blind-gold-option-knowledge], [data-question-option-knowledge], [data-blind-gold-family-contribution-select], [data-knowledge-inspection-family-contribution-select]");
}

function blindGoldKnowledgePickerLockedValue(root) {
  const lockSelector = root?.dataset.blindGoldLockSelector || "";
  if (lockSelector) return document.querySelector(lockSelector)?.value || "";
  if (root?.dataset.blindGoldLockCore !== "true") return "";
  if (blindGoldSelectedCoreKnowledgeRole() !== "core") return "";
  return document.querySelector("#blind-gold-core-knowledge")?.value || "";
}

function syncBlindGoldRequiredKnowledgeCore({ removeScopeAnchor = false } = {}) {
  const coreRoot = document.querySelector("#blind-gold-core-knowledge-picker");
  const root = document.querySelector("#blind-gold-required-knowledge-picker");
  const select = blindGoldKnowledgePickerSelect(root);
  const selectedRole = blindGoldSelectedCoreKnowledgeRole();
  const focusValue = document.querySelector("#blind-gold-core-knowledge")?.value || "";
  const lockedValue = blindGoldKnowledgePickerLockedValue(root);
  if (select && focusValue) {
    const focusOption = [...select.options].find((option) => option.value === focusValue);
    if (focusOption && lockedValue) focusOption.selected = true;
    else if (focusOption && selectedRole === "scope_anchor" && removeScopeAnchor) focusOption.selected = false;
  }
  syncBlindGoldCoreKnowledgeRoleUi();
  renderBlindGoldKnowledgePicker(coreRoot);
  renderBlindGoldKnowledgePicker(root);
}

function syncBlindGoldNewFamilyRequiredKnowledgeCore() {
  const coreRoot = document.querySelector("#blind-gold-new-family-core-picker");
  const requiredRoot = document.querySelector("#blind-gold-new-family-required-picker");
  const anchorsRoot = document.querySelector("#blind-gold-new-family-anchors-picker");
  [coreRoot, requiredRoot, anchorsRoot].forEach(renderBlindGoldKnowledgePicker);
}

function syncBlindGoldKnowledgePickerSummary(root) {
  const select = blindGoldKnowledgePickerSelect(root);
  const summary = root?.querySelector("[data-blind-gold-knowledge-summary]");
  if (!select || !summary) return;
  const lockedValue = blindGoldKnowledgePickerLockedValue(root);
  const selected = [...select.options]
    .filter((option) => option.value && option.selected)
    .sort((left, right) => Number(right.value === lockedValue) - Number(left.value === lockedValue));
  summary.textContent = selected.length > 1
    ? `${selected[0].textContent} · 另 ${selected.length - 1} 项`
    : (selected[0]?.textContent || root.dataset.blindGoldKnowledgeEmptyLabel || "请选择涉及知识");
  summary.title = selected.map((option) => option.textContent).join("\n");
  const trigger = root.querySelector("[data-blind-gold-knowledge-trigger]");
  const label = root.dataset.blindGoldKnowledgeLabel || "涉及知识";
  trigger?.setAttribute("aria-label", `选择${label}，当前已选 ${selected.length} 项`);
}

function renderBlindGoldKnowledgePicker(root) {
  if (!root) return;
  const select = blindGoldKnowledgePickerSelect(root);
  const search = root.querySelector("[data-blind-gold-knowledge-search]");
  const optionsContainer = root.querySelector("[data-blind-gold-knowledge-options]");
  if (!select || !search || !optionsContainer) return;
  const isBlindGoldReviewPicker = Boolean(root.closest("#blind-gold-review-form"));
  const selectedItem = isBlindGoldReviewPicker ? selectedBlindGoldReviewItem() : null;
  const bookId = selectedItem?.question?.bookId || "";
  const catalogLoading = Boolean(bookId
    && !state.blindGoldKnowledgeStructures.has(bookId)
    && state.blindGoldCatalogRequests.has(bookId));
  const options = [...select.options].filter((option) => option.value);
  const single = root.dataset.blindGoldKnowledgeSingle === "true";
  const lockedValue = blindGoldKnowledgePickerLockedValue(root);
  if (lockedValue) {
    const lockedOption = options.find((option) => option.value === lockedValue);
    if (lockedOption) lockedOption.selected = true;
  }
  syncBlindGoldKnowledgePickerSummary(root);
  const query = search.value.trim().toLocaleLowerCase("zh-CN");
  const visible = options.filter((option) => option.selected
    || !query
    || option.textContent.toLocaleLowerCase("zh-CN").includes(query));
  visible.sort((left, right) => Number(right.selected) - Number(left.selected)
    || Number(right.value === lockedValue) - Number(left.value === lockedValue));
  optionsContainer.innerHTML = visible.length
    ? visible.map((option) => {
      const locked = Boolean(lockedValue && option.value === lockedValue);
      const disabled = select.disabled || locked;
      return `<label class="question-family-multiselect-option ${option.selected ? "is-selected" : ""} ${locked ? "is-locked" : ""}">
      <input data-blind-gold-knowledge-option type="${single ? "radio" : "checkbox"}" ${single ? `name="${escapeHtml(`${root.id || "blind-gold-knowledge"}-choice`)}"` : ""} value="${escapeHtml(option.value)}" aria-label="${escapeHtml(`${option.textContent}${locked ? "，题目知识焦点，已锁定" : ""}`)}" ${option.selected ? "checked" : ""} ${disabled ? "disabled" : ""} />
      <span>${escapeHtml(option.textContent)}</span>
      ${locked ? "<em>题目知识焦点</em>" : ""}
    </label>`;
    }).join("")
    : `<div class="question-family-multiselect-empty">${catalogLoading ? "正在载入教材知识点…" : "没有匹配的知识点"}</div>`;
}

// 选择器面板里点一个选项：同步 hidden <select>、刷新摘要，然后**广播统一事件**。
// 组件到此为止 —— 它不再写任何页面状态（金标审核条目 / 逐选项知识载荷 / 巡检草稿都由各页面自己监听）。
//
// 背景（2026-09-20 实测）：这三件事原先分别写在金标表单、巡检对话框、编辑页行绑定里各一份，
// 而且"打开面板"和"处理选项点击"都绑在 #blind-gold-review-form 上 —— 编辑页的选择器
// 面板根本打不开、点了也没反应（前驱的冒烟是直接改 select 再派发 change，绕过了真实点击）。
function applyKnowledgePickerOptionClick(root, pickerOption) {
  const select = blindGoldKnowledgePickerSelect(root);
  if (!root || !select || !pickerOption) return false;
  const option = [...select.options].find((entry) => entry.value === pickerOption.value);
  const locked = pickerOption.value === blindGoldKnowledgePickerLockedValue(root);
  const single = root.dataset.blindGoldKnowledgeSingle === "true";
  if (!option || select.disabled || locked) return false;
  if (single) [...select.options].forEach((entry) => { entry.selected = entry === option; });
  else option.selected = pickerOption.checked;
  select.dispatchEvent(new Event("change", { bubbles: true }));
  if (single) renderBlindGoldKnowledgePicker(root);
  else pickerOption.closest(".question-family-multiselect-option")?.classList.toggle("is-selected", pickerOption.checked);
  syncBlindGoldKnowledgePickerSummary(root);
  syncBlindGoldOptionKnowledgeSummary(root.closest("[data-blind-gold-option-row]"));
  // 统一事件：detail 里给出"哪个选择器 / 用户点的哪一个选项 / 是否单选"，
  // 页面只需据此写自己的状态，不必再各自解析 hidden select。
  root.dispatchEvent(new CustomEvent("knowledge-picker-change", {
    bubbles: true,
    detail: { root, option: pickerOption, single },
  }));
  return true;
}

// 打开/收起选择器面板：document 级代理，任何宿主都共用（原先只在金标表单里生效）。
document.addEventListener("click", (event) => {
  const trigger = event.target.closest("[data-blind-gold-knowledge-trigger]");
  if (!trigger) return;
  const root = trigger.closest("[data-blind-gold-knowledge-picker]");
  if (!root) return;
  const open = !questionFamilyMultiselectIsOpen(root);
  if (open) renderBlindGoldKnowledgePicker(root);   // 打开前先渲染，避免出现空面板
  setBlindGoldKnowledgePickerOpen(root, open);
  if (open && root.closest("#blind-gold-review-form")) {
    const item = selectedBlindGoldReviewItem();
    const bookId = item?.question?.bookId || "";
    if (bookId && !state.blindGoldKnowledgeStructures.has(bookId)
      && !state.blindGoldCatalogRequests.has(bookId)) {
      void ensureBlindGoldReviewCatalog(item, { quiet: true });
    }
  }
});

// 选项点击：同样 document 级代理 —— 三条宿主（金标 / 逐选项知识 / 巡检对话框）走同一条同步逻辑。
document.addEventListener("change", (event) => {
  const pickerOption = event.target.closest("[data-blind-gold-knowledge-option]");
  if (!pickerOption) return;
  applyKnowledgePickerOptionClick(pickerOption.closest("[data-blind-gold-knowledge-picker]"), pickerOption);
});

function initializeBlindGoldKnowledgePickers() {
  blindGoldKnowledgePickerRoots().forEach((root) => {
    renderBlindGoldKnowledgePicker(root);
    if (root.dataset.blindGoldKnowledgeInitialized === "true") return;
    root.dataset.blindGoldKnowledgeInitialized = "true";
    root.querySelector("[data-blind-gold-knowledge-panel]")?.addEventListener("toggle", (event) => syncBlindGoldKnowledgePickerOpenState(root, event.newState === "open"));
  });
}

function syncBlindGoldKnowledgePickerOpenState(root, open) {
  const panel = root?.querySelector("[data-blind-gold-knowledge-panel]");
  const trigger = root?.querySelector("[data-blind-gold-knowledge-trigger]");
  const search = root?.querySelector("[data-blind-gold-knowledge-search]");
  if (!root?.isConnected || !panel || !trigger || !search) return;
  panel.hidden = !open;
  root.classList.toggle("is-open", open);
  trigger.setAttribute("aria-expanded", String(open));
  if (open) {
    positionQuestionFamilyMultiselect(root);
    search.focus({ preventScroll: true });
  } else if (search.value) {
    search.value = "";
    renderBlindGoldKnowledgePicker(root);
  }
}

function setBlindGoldKnowledgePickerOpen(targetRoot = null, open = false) {
  if (open) setBlindGoldRelatedFamilyPickerOpen(false);
  blindGoldKnowledgePickerRoots().forEach((root) => {
    const shouldOpen = open && root === targetRoot && !root.querySelector("[data-blind-gold-knowledge-trigger]")?.disabled;
    const panel = root.querySelector("[data-blind-gold-knowledge-panel]");
    if (!panel) return;
    const wasOpen = questionFamilyMultiselectIsOpen(root);
    if (shouldOpen === wasOpen) {
      if (shouldOpen) syncBlindGoldKnowledgePickerOpenState(root, true);
      return;
    }
    if (shouldOpen) {
      renderBlindGoldKnowledgePicker(root);
      panel.hidden = false;
      if (typeof panel.showPopover === "function") {
        try {
          if (!panel.matches(":popover-open")) panel.showPopover();
        } catch {
          root.classList.add("is-open");
        }
      }
      syncBlindGoldKnowledgePickerOpenState(root, true);
      return;
    }
    if (typeof panel.hidePopover === "function") {
      try {
        if (panel.matches(":popover-open")) panel.hidePopover();
      } catch {
        root.classList.remove("is-open");
      }
    }
    syncBlindGoldKnowledgePickerOpenState(root, false);
    panel.hidden = true;
  });
}

function blindGoldRelatedFamilyPickerRoot() {
  return document.querySelector("[data-blind-gold-family-picker]");
}

const blindGoldRelatedFamilySelectionLimit = 30;

function blindGoldRelatedFamilyCoverageRole(value = {}, fallback = "required") {
  if (typeof value === "boolean") return value ? "required" : "reference";
  const source = value && typeof value === "object" ? value : { coverageRole: value };
  const rawRole = String(source.coverageRole || source.role || "").trim().toLocaleLowerCase("en-US");
  if (["reference", "ordinary", "normal", "related"].includes(rawRole)) return "reference";
  if (["required", "required_for_answer", "answer_required"].includes(rawRole)) return "required";
  if (typeof source.requiredForAnswer === "boolean") return source.requiredForAnswer ? "required" : "reference";
  return fallback === "reference" ? "reference" : "required";
}

function blindGoldRelatedFamilyRelation(familyId, value = {}, fallback = "required") {
  const coverageRole = blindGoldRelatedFamilyCoverageRole(value, fallback);
  return {
    familyId: String(familyId || "").trim(),
    coverageRole,
    requiredForAnswer: coverageRole === "required",
  };
}

function blindGoldReviewRelatedFamilyRelations(familyGold = {}) {
  const primaryFamilyId = String(familyGold.primaryFamilyId || "").trim();
  const relationMap = new Map();
  const hasExplicitRole = (value) => typeof value === "boolean" || typeof value === "string"
    || Boolean(value && typeof value === "object"
      && (value.coverageRole || value.role || typeof value.requiredForAnswer === "boolean"));
  const upsert = (familyId, value = {}, fallback = "required") => {
    const id = String(familyId || "").trim();
    if (!id || id === primaryFamilyId) return;
    const existing = relationMap.get(id);
    const effectiveFallback = existing?.coverageRole || fallback;
    const relation = blindGoldRelatedFamilyRelation(id, value, effectiveFallback);
    relationMap.set(id, hasExplicitRole(value) || !existing ? relation : existing);
  };
  (Array.isArray(familyGold.relatedFamilyIds) ? familyGold.relatedFamilyIds : []).forEach((familyId) => upsert(familyId));
  (Array.isArray(familyGold.relatedFamilies) ? familyGold.relatedFamilies : []).forEach((family) => {
    upsert(typeof family === "string" ? family : (family?.familyId || family?.id), family);
  });
  const relatedFamilyRoles = familyGold.relatedFamilyRoles;
  if (Array.isArray(relatedFamilyRoles)) {
    relatedFamilyRoles.forEach((relation) => upsert(relation?.familyId || relation?.id, relation));
  } else if (relatedFamilyRoles && typeof relatedFamilyRoles === "object") {
    Object.entries(relatedFamilyRoles).forEach(([familyId, role]) => upsert(familyId, role));
  }
  (Array.isArray(familyGold.families) ? familyGold.families : []).forEach((family) => {
    if (hasExplicitRole(family)) upsert(family?.familyId || family?.id, family);
  });
  (Array.isArray(familyGold.relatedFamilyRelations) ? familyGold.relatedFamilyRelations : []).forEach((relation) => {
    upsert(relation?.familyId || relation?.id, relation);
  });
  return [...relationMap.values()];
}

function blindGoldRelatedFamilyRelationsFromSelect(primaryFamilyId = "") {
  const select = document.querySelector("#blind-gold-related-families");
  return [...(select?.selectedOptions || [])]
    .filter((option) => option.value && option.value !== primaryFamilyId)
    .map((option) => blindGoldRelatedFamilyRelation(option.value, {
      coverageRole: option.dataset.coverageRole,
      requiredForAnswer: option.dataset.requiredForAnswer === "true",
    }));
}

function blindGoldRelatedFamilyRelationSignature(relations = []) {
  return relations
    .map((relation) => `${relation.familyId}:${blindGoldRelatedFamilyCoverageRole(relation)}`)
    .sort((left, right) => left.localeCompare(right, "zh-CN"))
    .join("|");
}

function blindGoldRelatedFamilyRelationCounts(relations = []) {
  return relations.reduce((counts, relation) => {
    const role = blindGoldRelatedFamilyCoverageRole(relation);
    counts[role] += 1;
    return counts;
  }, { required: 0, reference: 0 });
}

function blindGoldNormalizedKnowledgeText(value = "") {
  return String(value || "").trim().toLocaleLowerCase("zh-CN")
    .replace(/[（(]?[一二三四五六七八九十百]+[、.．)）\s]*/g, "")
    .replace(/[\s，。！？；：、“”‘’（）()【】\[\]《》<>·…—-]/g, "");
}

function blindGoldKnowledgeNodeIds(node = {}) {
  return [...new Set([
    node.id,
    node.nodeId,
    node.canonicalNodeId,
    ...(Array.isArray(node.aliasNodeIds) ? node.aliasNodeIds : []),
  ].map((value) => String(value || "").trim()).filter(Boolean))];
}

function blindGoldKnowledgeNodeExists(node = {}) {
  return Boolean(blindGoldKnowledgeNodeIds(node).length || node.path || node.knowledgePath || node.title || node.label);
}

function blindGoldKnowledgeNodesCompatible(leftValue = {}, rightValue = {}) {
  const leftIds = new Set(blindGoldKnowledgeNodeIds(leftValue));
  const rightIds = new Set(blindGoldKnowledgeNodeIds(rightValue));
  const leftPath = blindGoldNormalizedKnowledgeText(leftValue.path || leftValue.knowledgePath);
  const rightPath = blindGoldNormalizedKnowledgeText(rightValue.path || rightValue.knowledgePath);
  // Historical gold drafts and the live knowledge tree can use different
  // node IDs.  An exact textbook path is the stable identity in that case;
  // only fall back to labels when neither side has an ID or path.
  if (leftIds.size && rightIds.size && [...leftIds].some((nodeId) => rightIds.has(nodeId))) return true;
  if (leftPath && rightPath) return leftPath === rightPath;
  if (leftIds.size || rightIds.size) return false;
  const leftTitle = blindGoldNormalizedKnowledgeText(leftValue.title || leftValue.label);
  const rightTitle = blindGoldNormalizedKnowledgeText(rightValue.title || rightValue.label);
  return Boolean(leftTitle && rightTitle && leftTitle === rightTitle);
}

function blindGoldUniqueKnowledgeNodes(nodes = []) {
  return (Array.isArray(nodes) ? nodes : []).filter(blindGoldKnowledgeNodeExists).reduce((unique, node) => {
    if (!unique.some((candidate) => blindGoldKnowledgeNodesCompatible(candidate, node))) unique.push(node);
    return unique;
  }, []);
}

const blindGoldFamilyKnowledgeProtocolVersion = "family_knowledge_v3";

function blindGoldFamilyKnowledgeProtocolEnabled(item = selectedBlindGoldReviewItem()) {
  const familyGold = item?.humanGold?.familyGold || item?.finalGold?.familyGold || item?.familyGold || {};
  if (familyGold.familyKnowledgeProtocolVersion === blindGoldFamilyKnowledgeProtocolVersion) return true;
  const batch = state.blindGoldReviewBatch;
  if (!batch || batch.status === "frozen" || !blindGoldReviewIsRevisionBatch(batch)) return false;
  return blindGoldRevisionRequiredStages(item, batch).includes("family");
}

function blindGoldFamilyCoverageKnowledge(family = {}, item = selectedBlindGoldReviewItem()) {
  // Family snapshots often keep only node IDs. Resolve them against the live
  // textbook tree before comparing coverage, otherwise a valid child node can
  // look unrelated simply because its historical label/path was omitted.
  const normalized = blindGoldReviewCatalogFamily(family, item);
  return blindGoldUniqueKnowledgeNodes(normalized.coverageKnowledge || normalized.requiredKnowledge || []);
}

function blindGoldReviewKnowledgeDescendants(scopeNodes = [], nodes = []) {
  const scopes = blindGoldUniqueKnowledgeNodes(scopeNodes);
  const candidates = Array.isArray(nodes) ? nodes : [];
  if (!scopes.length || !candidates.length) return [];
  const byId = new Map();
  candidates.forEach((node) => blindGoldKnowledgeNodeIds(node).forEach((id) => {
    if (!byId.has(id)) byId.set(id, node);
  }));
  const isWithinByParent = (scope, candidate) => {
    const scopeIds = new Set(blindGoldKnowledgeNodeIds(scope));
    let current = candidate;
    const seen = new Set();
    while (current && !seen.has(current)) {
      seen.add(current);
      const currentIds = blindGoldKnowledgeNodeIds(current);
      if (currentIds.some((id) => scopeIds.has(id))) return true;
      const parentId = String(current.parentId || "").trim();
      if (!parentId) return false;
      current = byId.get(parentId) || null;
    }
    return false;
  };
  return candidates.filter((node) => scopes.some((scope) =>
    blindGoldKnowledgeNodeCovers(scope, node) || isWithinByParent(scope, node)));
}

function blindGoldReviewExplicitOptionKnowledge(item = selectedBlindGoldReviewItem()) {
  const answerKnowledge = blindGoldReviewCurrentAnswerKnowledge(item || {});
  const nodes = blindGoldReviewKnowledgeNodes(item);
  const collected = [];
  const add = (value = {}) => {
    const relation = String(value.knowledgeRelation || "").trim();
    if (relation && relation !== "option_specific") return;
    const ids = [
      ...(Array.isArray(value.knowledgeNodeIds) ? value.knowledgeNodeIds : []),
      ...(Array.isArray(value.legacyKnowledgeNodeIds) ? value.legacyKnowledgeNodeIds : []),
    ];
    const labels = [
      ...(Array.isArray(value.knowledgeLabels) ? value.knowledgeLabels : []),
      ...(Array.isArray(value.legacyKnowledgeHints) ? value.legacyKnowledgeHints : []),
    ];
    collected.push(...blindGoldReviewStoredKnowledgeNodes(ids, labels, nodes));
  };
  (answerKnowledge.optionKnowledge || []).forEach(add);
  (answerKnowledge.atomicStatements || []).forEach(add);
  (answerKnowledge.scoringPoints || []).forEach((point) => {
    const ids = Array.isArray(point.knowledgeNodeIds) ? point.knowledgeNodeIds : [];
    const labels = Array.isArray(point.knowledgeLabels) ? point.knowledgeLabels : [];
    collected.push(...blindGoldReviewStoredKnowledgeNodes(ids, labels, nodes));
  });
  return blindGoldUniqueKnowledgeNodes(collected);
}

function blindGoldFamilyContributionKey(item, familyKey) {
  return `${item?.questionId || ""}:${familyKey || ""}`;
}

const blindGoldFamilyContributionDraftStorageKey = "shukao.blindGoldFamilyContributionDrafts.v1";

function blindGoldFamilyContributionDraftStorageEntries() {
  try {
    const storage = globalThis.sessionStorage;
    const raw = storage?.getItem(blindGoldFamilyContributionDraftStorageKey);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed?.drafts)) return [];
    return parsed.drafts
      .filter((entry) => entry && typeof entry === "object"
        && String(entry.batchId || "").trim()
        && String(entry.questionId || "").trim()
        && String(entry.familyKey || "").trim()
        && Array.isArray(entry.nodeKeys))
      .map((entry) => ({
        batchId: String(entry.batchId).trim(),
        questionId: String(entry.questionId).trim(),
        familyKey: String(entry.familyKey).trim(),
        itemRevision: entry.itemRevision === undefined || entry.itemRevision === null
          ? ""
          : String(entry.itemRevision),
        nodeKeys: entry.nodeKeys.map((key) => String(key || "").trim()).filter(Boolean),
      }));
  } catch (_error) {
    return [];
  }
}

function persistBlindGoldFamilyContributionDrafts() {
  const batch = state.blindGoldReviewBatch;
  const batchId = String(batch?.id || "").trim();
  if (!batchId) return;
  try {
    const storage = globalThis.sessionStorage;
    if (!storage) return;
    const items = Array.isArray(batch.items) ? batch.items : [];
    const current = [];
    state.blindGoldFamilyContributionDrafts.forEach((nodeKeys, key) => {
      const item = items.find((entry) => key.startsWith(`${entry.questionId}:`));
      if (!item) return;
      const prefix = `${item.questionId}:`;
      const familyKey = key.slice(prefix.length).trim();
      if (!familyKey) return;
      current.push({
        batchId,
        questionId: String(item.questionId),
        familyKey,
        itemRevision: item.revision === undefined || item.revision === null ? "" : String(item.revision),
        // An empty list is intentional: it prevents a freshly-rendered
        // picker from falling back to a stale stored membership value.
        nodeKeys: (Array.isArray(nodeKeys) ? nodeKeys : []).map((value) => String(value || "").trim()).filter(Boolean),
      });
    });
    const retained = blindGoldFamilyContributionDraftStorageEntries()
      .filter((entry) => entry.batchId !== batchId);
    storage.setItem(blindGoldFamilyContributionDraftStorageKey, JSON.stringify({
      version: 1,
      drafts: [...retained, ...current],
      updatedAt: Date.now(),
    }));
  } catch (_error) {
    // Session storage can be unavailable in private/restricted contexts.
    // The in-memory map remains the source of truth for the current view.
  }
}

function restoreBlindGoldFamilyContributionDrafts(batch = state.blindGoldReviewBatch) {
  state.blindGoldFamilyContributionDrafts.clear();
  state.blindGoldFamilyContributionDirtyKeys.clear();
  const batchId = String(batch?.id || "").trim();
  if (!batchId) return;
  const items = Array.isArray(batch.items) ? batch.items : [];
  const itemById = new Map(items.map((item) => [String(item.questionId || ""), item]));
  blindGoldFamilyContributionDraftStorageEntries()
    .filter((entry) => entry.batchId === batchId)
    .forEach((entry) => {
      const item = itemById.get(entry.questionId);
      if (!item) return;
      const currentRevision = item.revision === undefined || item.revision === null ? "" : String(item.revision);
      // A changed item revision means the formal answer/knowledge baseline
      // changed; never reapply a contribution draft to that new baseline.
      if (entry.itemRevision && currentRevision && entry.itemRevision !== currentRevision) return;
      state.blindGoldFamilyContributionDrafts.set(
        blindGoldFamilyContributionKey(item, entry.familyKey),
        [...entry.nodeKeys],
      );
    });
}

function clearBlindGoldFamilyContributionDrafts(questionId = "", options = {}) {
  if (!questionId) {
    state.blindGoldFamilyContributionDrafts.clear();
    state.blindGoldFamilyContributionDirtyKeys.clear();
    if (options.persist !== false) persistBlindGoldFamilyContributionDrafts();
    return;
  }
  const prefix = `${questionId}:`;
  [...state.blindGoldFamilyContributionDrafts.keys()]
    .filter((key) => key.startsWith(prefix))
    .forEach((key) => state.blindGoldFamilyContributionDrafts.delete(key));
  [...state.blindGoldFamilyContributionDirtyKeys]
    .filter((key) => key.startsWith(prefix))
    .forEach((key) => state.blindGoldFamilyContributionDirtyKeys.delete(key));
  if (options.persist !== false) persistBlindGoldFamilyContributionDrafts();
}

function blindGoldFamilyStoredContribution(family = {}, item = selectedBlindGoldReviewItem()) {
  const membership = family.membership?.questionId === item?.questionId
    ? family.membership
    : (family.members || []).find((member) => member.questionId === item?.questionId);
  const ids = membership?.contributionKnowledgeNodeIds || [];
  const labels = membership?.contributionKnowledgeLabels || [];
  return blindGoldReviewStoredKnowledgeNodes(ids, labels, blindGoldReviewKnowledgeNodes(item));
}

function blindGoldFamilyContributionSelect(familyKey) {
  return [...document.querySelectorAll("[data-blind-gold-family-contribution-select]")]
    .find((select) => select.dataset.blindGoldFamilyContributionSelect === familyKey) || null;
}

function blindGoldFamilyContributionNodes(family = {}, role = "required", item = selectedBlindGoldReviewItem(), familyKey = family.id || "candidate") {
  if (role === "reference") return [];
  const select = blindGoldFamilyContributionSelect(familyKey);
  if (select) {
    const selected = [...select.selectedOptions].map((option) => option.value).filter(Boolean);
    if (selected.length) {
      const resolved = selected.map((key) => blindGoldReviewResolveNode(key, item))
        .filter(blindGoldKnowledgeNodeExists);
      if (resolved.length) return resolved;
    }
    // An empty select can be a freshly-rendered picker. Prefer an explicit
    // draft (including an intentional empty draft) before falling back to
    // the stored membership value.
    const draftKey = blindGoldFamilyContributionKey(item, familyKey);
    if (state.blindGoldFamilyContributionDrafts.has(draftKey)) {
      return (state.blindGoldFamilyContributionDrafts.get(draftKey) || [])
        .map((key) => blindGoldReviewResolveNode(key, item))
        .filter(blindGoldKnowledgeNodeExists);
    }
  }
  const draftKeys = state.blindGoldFamilyContributionDrafts.get(blindGoldFamilyContributionKey(item, familyKey));
  if (draftKeys !== undefined) {
    const draftNodes = draftKeys.map((key) => blindGoldReviewResolveNode(key, item)).filter(blindGoldKnowledgeNodeExists);
    if (draftNodes.length || !draftKeys.length) return draftNodes;
  }
  const stored = blindGoldFamilyStoredContribution(family, item);
  if (stored.length) return stored;
  return [];
}

function blindGoldFamilyContributionSuggestion(family = {}, role = "required", item = selectedBlindGoldReviewItem()) {
  if (role === "reference") return [];
  const required = blindGoldReviewCurrentAnswerKnowledge(item || {}).requiredKnowledge || [];
  const coverage = blindGoldFamilyCoverageKnowledge(family, item);
  return blindGoldUniqueKnowledgeNodes(required.filter((node) => coverage
    .some((coveredNode) => blindGoldKnowledgeNodeCovers(coveredNode, node))));
}

function rememberBlindGoldFamilyContribution(root, item = selectedBlindGoldReviewItem()) {
  const familyKey = root?.dataset.blindGoldFamilyContributionPicker || "";
  const select = blindGoldKnowledgePickerSelect(root);
  if (!familyKey || !select || !item) return;
  const draftKey = blindGoldFamilyContributionKey(item, familyKey);
  const existingDraft = state.blindGoldFamilyContributionDrafts.get(draftKey);
  const selected = [...select.selectedOptions].map((option) => option.value).filter(Boolean);
  // Rendering is asynchronous: the first pass can happen before the full
  // textbook catalog has arrived, so its select may temporarily contain no
  // selected values. Do not treat that system repaint as a reviewer clearing
  // an already-restored draft. Explicit picker changes set the dirty marker
  // below and are still allowed to persist an intentional empty selection.
  const userChanged = root.dataset.blindGoldFamilyContributionDirty === "true"
    || state.blindGoldFamilyContributionDirtyKeys.has(draftKey);
  const optionValues = new Set([...select.options].map((option) => option.value).filter(Boolean));
  const draftHasRenderableOption = Array.isArray(existingDraft)
    && existingDraft.some((key) => optionValues.has(String(key)));
  // A row can be rebuilt while the authoritative textbook catalog is still
  // hydrating, or while legacy node ids are being reconciled. If an existing
  // non-empty draft has no matching option yet, an empty select is a render
  // intermediate state, not a reviewer clearing the field. Keep the draft
  // until the options are available. An explicit clear remains valid because
  // the old selected option is still present in a hydrated picker.
  if (!selected.length && Array.isArray(existingDraft) && existingDraft.length
    && (!userChanged || !draftHasRenderableOption)) return;
  state.blindGoldFamilyContributionDrafts.set(
    draftKey,
    selected,
  );
  persistBlindGoldFamilyContributionDrafts();
}

function blindGoldFamilyContributionSignature(item = selectedBlindGoldReviewItem(), familyGold = null) {
  const value = familyGold || blindGoldReviewCollectFamilyGold(item);
  const families = Array.isArray(value?.families) ? value.families : [];
  const candidate = value?.candidateFamily ? [value.candidateFamily] : [];
  return [...families, ...candidate].map((family) => {
    const membership = family?.membership || {};
    return `${family.id || "candidate"}:${[...(membership.contributionKnowledgeNodeIds || [])].map(String).sort().join(",")}`;
  }).sort((left, right) => left.localeCompare(right, "zh-CN")).join("|");
}

function blindGoldFamilyContributionRowHtml({ family, familyKey, role, roleLabel }, index, item) {
  const questionRequired = blindGoldReviewCurrentAnswerKnowledge(item).requiredKnowledge || [];
  const coverage = blindGoldFamilyCoverageKnowledge(family, item);
  const selected = blindGoldFamilyContributionNodes(family, role, item, familyKey);
  const suggestion = blindGoldFamilyContributionSuggestion(family, role, item);
  const optionKnowledge = blindGoldReviewExplicitOptionKnowledge(item);
  const suggestionMatchesSelection = suggestion.length === selected.length
    && suggestion.every((suggestedNode) => selected.some((selectedNode) => blindGoldKnowledgeNodesCompatible(suggestedNode, selectedNode)));
  const suggestionLabel = selected.length
    ? (suggestion.length === 1
      ? `改用建议：${blindGoldReviewNodeShortLabel(suggestion[0])}`
      : `改用建议（${suggestion.length} 项）`)
    : (suggestion.length === 1
      ? `填入建议：${blindGoldReviewNodeShortLabel(suggestion[0])}`
      : `填入建议（${suggestion.length} 项）`);
  const sourceCandidates = blindGoldUniqueKnowledgeNodes([
    ...questionRequired,
    ...optionKnowledge,
    ...selected,
  ]);
  const catalogNodes = blindGoldReviewKnowledgeNodes(item);
  const coverageCandidates = blindGoldReviewKnowledgeDescendants(coverage, catalogNodes);
  const isValidContribution = (node) => questionRequired.some((expectedNode) => blindGoldKnowledgeNodeIsWithin(expectedNode, node))
    && coverage.some((coveredNode) => blindGoldKnowledgeNodeCovers(coveredNode, node));
  const matchedCandidates = blindGoldUniqueKnowledgeNodes([
    ...questionRequired.filter((node) => coverage.some((coveredNode) => blindGoldKnowledgeNodeCovers(coveredNode, node))),
    ...optionKnowledge.filter((node) => coverage.some((coveredNode) => blindGoldKnowledgeNodeCovers(coveredNode, node))),
  ]);
  const invalidSelected = selected.filter((node) => !isValidContribution(node));
  // New choices are limited to the valid intersection required by the
  // protocol. Keep already-selected invalid legacy values visible so the
  // reviewer can remove them after a family or knowledge correction.
  const validCatalogCandidates = blindGoldUniqueKnowledgeNodes([
    ...matchedCandidates.filter(isValidContribution),
    ...coverageCandidates.filter(isValidContribution),
  ]);
  const candidates = blindGoldUniqueKnowledgeNodes([
    ...validCatalogCandidates,
    ...invalidSelected,
    ...(validCatalogCandidates.length || catalogNodes.length ? [] : sourceCandidates),
  ]);
  const hasUnmatchedQuestionKnowledge = questionRequired.some((node) => !isValidContribution(node));
  const candidateHint = invalidSelected.length
    ? `<small class="blind-gold-family-contribution-hint">已选 ${escapeHtml(invalidSelected.length)} 项不属于“题目最小充分知识集 × 当前题族覆盖范围”的有效交集，请取消后再审核。</small>`
    : (hasUnmatchedQuestionKnowledge
      ? '<small class="blind-gold-family-contribution-hint">本题还有知识未被当前题族覆盖；这些知识不能作为本题贡献，请调整题族关系或覆盖范围。手动勾选有效项即可提交，无需点击建议按钮。</small>'
      : "");
  const pickerId = `blind-gold-family-contribution-${index + 1}`;
  const reference = role === "reference";
  return `<div class="blind-gold-family-contribution-row ${reference ? "is-reference" : ""}" data-blind-gold-family-contribution-row="${escapeHtml(familyKey)}">
    <div class="blind-gold-family-contribution-copy"><span>${escapeHtml(roleLabel)}</span><strong>${escapeHtml(family?.name || "候选新题族")}</strong><small>题族覆盖：${escapeHtml(coverage.map(blindGoldReviewNodeLabel).join(" · ") || "尚未填写")}</small></div>
    ${reference ? '<span class="blind-gold-family-contribution-reference">不参与联合覆盖</span>' : `<div class="blind-gold-family-contribution-controls"><div class="question-family-multiselect blind-gold-knowledge-picker blind-gold-family-contribution-picker" id="${pickerId}" data-blind-gold-knowledge-picker data-blind-gold-family-contribution-picker="${escapeHtml(familyKey)}" data-blind-gold-knowledge-empty-label="请选择本题贡献知识" data-blind-gold-knowledge-label="本题贡献知识">
        <button class="question-family-multiselect-trigger" data-blind-gold-knowledge-trigger type="button" aria-haspopup="dialog" aria-expanded="false" aria-controls="${pickerId}-panel" aria-label="选择本题贡献知识"><span data-blind-gold-knowledge-summary>请选择本题贡献知识</span><i aria-hidden="true"></i></button>
        <div class="question-family-multiselect-panel" id="${pickerId}-panel" data-blind-gold-knowledge-panel popover="auto" role="dialog" aria-label="选择本题贡献知识" hidden>
          <input class="question-family-multiselect-search" data-blind-gold-knowledge-search type="search" placeholder="搜索本题最小充分知识" aria-label="搜索本题贡献知识" autocomplete="off" />
          <div class="question-family-multiselect-options" data-blind-gold-knowledge-options role="group" aria-label="本题贡献知识选项"></div>
        </div>
        <select data-blind-gold-family-contribution-select="${escapeHtml(familyKey)}" multiple hidden aria-hidden="true" tabindex="-1">${blindGoldReviewNodeOptions(candidates, selected)}</select>
      </div>${suggestion.length && !suggestionMatchesSelection ? `<button class="primary-action family-contribution-suggestion" type="button" data-use-blind-gold-family-contribution-suggestion="${escapeHtml(familyKey)}" title="可选快捷操作：用系统计算的有效交集替换当前选择；手动勾选有效项后可直接审核">${escapeHtml(suggestionLabel)}</button>` : ""}${candidateHint}</div>`}
  </div>`;
}

function renderBlindGoldFamilyContributions(item = selectedBlindGoldReviewItem()) {
  const section = document.querySelector("#blind-gold-family-contributions");
  const list = document.querySelector("#blind-gold-family-contribution-list");
  if (!section || !list || !item || !blindGoldFamilyKnowledgeProtocolEnabled(item)) {
    if (section) section.hidden = true;
    return;
  }
  // Preserve selections before replacing the rows. Family/role changes
  // redraw the entire list, so relying on the DOM alone can lose unsaved
  // contribution choices before the review payload is collected.
  blindGoldKnowledgePickerRoots()
    .filter((root) => root.dataset.blindGoldFamilyContributionPicker)
    .forEach((root) => rememberBlindGoldFamilyContribution(root, item));
  const replayMode = blindGoldReviewSelectedReplayMode(item);
  const primaryFamilyId = replayMode === "unmatched" ? "" : (document.querySelector("#blind-gold-existing-family")?.value || "");
  const entries = [];
  if (replayMode === "unmatched") {
    entries.push({ family: blindGoldReviewCollectCandidateFamily(item, false), familyKey: "candidate", role: "primary", roleLabel: "候选主题族" });
  } else {
    const family = blindGoldReviewFamilyById(primaryFamilyId, item);
    if (family) entries.push({ family, familyKey: family.id, role: "primary", roleLabel: "主题族" });
  }
  blindGoldRelatedFamilyRelationsFromSelect(primaryFamilyId).forEach((relation) => {
    const family = blindGoldReviewFamilyById(relation.familyId, item);
    if (family) entries.push({
      family,
      familyKey: family.id,
      role: relation.coverageRole,
      roleLabel: relation.coverageRole === "required" ? "作答必需关联" : "普通关联",
    });
  });
  section.hidden = !entries.length;
  list.innerHTML = entries.length
    ? entries.map((entry, index) => blindGoldFamilyContributionRowHtml(entry, index, item)).join("")
    : '<div class="blind-gold-family-contribution-empty">请先选择主题族或填写候选新题族。</div>';
  initializeBlindGoldKnowledgePickers();
}

function blindGoldReviewFamilyCoverage(item = selectedBlindGoldReviewItem()) {
  const answerKnowledge = blindGoldReviewCurrentAnswerKnowledge(item || {});
  const expected = blindGoldUniqueKnowledgeNodes(answerKnowledge.requiredKnowledge || []);
  const useContributionProtocol = blindGoldFamilyKnowledgeProtocolEnabled(item);
  const replayMode = blindGoldReviewSelectedReplayMode(item);
  const isNew = replayMode === "unmatched";
  const primaryFamilyId = isNew ? "" : (document.querySelector("#blind-gold-existing-family")?.value || "");
  const primaryFamily = isNew
    ? blindGoldReviewCollectCandidateFamily(item, false)
    : blindGoldReviewFamilyById(primaryFamilyId, item);
  const relations = blindGoldRelatedFamilyRelationsFromSelect(primaryFamilyId);
  const requiredRelations = relations.filter((relation) => relation.coverageRole === "required");
  const requiredRelatedFamilies = requiredRelations
    .map((relation) => blindGoldReviewFamilyById(relation.familyId, item))
    .filter(Boolean);
  const contributors = [
    ...(primaryFamily ? [{ family: primaryFamily, familyKey: primaryFamily.id || "candidate", role: "primary" }] : []),
    ...requiredRelatedFamilies.map((family) => ({ family, familyKey: family.id, role: "required" })),
  ];
  const contributionAudits = contributors.map((entry) => {
    const knowledge = useContributionProtocol
      ? blindGoldFamilyContributionNodes(entry.family, entry.role, item, entry.familyKey)
      : blindGoldFamilyCoverageKnowledge(entry.family, item);
    const familyCoverage = blindGoldFamilyCoverageKnowledge(entry.family, item);
    const outsideQuestion = knowledge.filter((node) => !expected
      .some((expectedNode) => blindGoldKnowledgeNodeIsWithin(expectedNode, node)));
    const outsideFamily = useContributionProtocol ? knowledge.filter((node) => !familyCoverage
      .some((coveredNode) => blindGoldKnowledgeNodeCovers(coveredNode, node))) : [];
    return { ...entry, knowledge, familyCoverage, outsideQuestion, outsideFamily };
  });
  const actual = blindGoldUniqueKnowledgeNodes(contributionAudits.flatMap((entry) => entry.knowledge));
  const covered = expected.filter((expectedNode) => actual
    .some((actualNode) => blindGoldKnowledgeNodeCovers(actualNode, expectedNode)));
  const missing = expected.filter((expectedNode) => !actual
    .some((actualNode) => blindGoldKnowledgeNodeCovers(actualNode, expectedNode)));
  const extra = actual.filter((actualNode) => !expected
    .some((expectedNode) => blindGoldKnowledgeNodeCovers(actualNode, expectedNode)));
  const questionCore = answerKnowledge.coreKnowledge || {};
  const coreRole = blindGoldCoreKnowledgeRole(answerKnowledge);
  const familyCore = primaryFamily?.scopeAnchor || primaryFamily?.coreKnowledge || {};
  const questionCoreReady = blindGoldKnowledgeNodeExists(questionCore);
  const primaryContribution = contributionAudits.find((entry) => entry.role === "primary")?.knowledge || [];
  const invalidContributionCount = contributionAudits.reduce((total, entry) => total
    + entry.outsideQuestion.length + entry.outsideFamily.length, 0);
  return {
    expected,
    actual,
    covered,
    missing,
    extra,
    contributionAudits,
    invalidContributionCount,
    referenceCount: relations.filter((relation) => relation.coverageRole === "reference").length,
    missingRequiredFamilyCount: requiredRelations.length - requiredRelatedFamilies.length,
    primaryKind: isNew ? "候选题族" : "主题族",
    questionCore,
    coreRole,
    familyCore,
    coreStatus: !questionCoreReady ? "question_missing"
      : (coreRole === "scope_anchor" ? "scope_anchor"
        : (useContributionProtocol
        ? (primaryContribution.some((node) => blindGoldKnowledgeNodeCovers(node, questionCore)) ? "matched" : "not_contributed")
        : (!blindGoldKnowledgeNodeExists(familyCore) ? "family_missing"
          : (blindGoldKnowledgeNodeCovers(familyCore, questionCore) ? "matched" : "mismatched")))),
  };
}

function syncBlindGoldFamilyCoverageSummary(item = selectedBlindGoldReviewItem()) {
  const element = document.querySelector("#blind-gold-family-coverage-summary");
  if (!element || !item) return;
  const coverage = blindGoldReviewFamilyCoverage(item);
  const coreComplete = ["matched", "scope_anchor"].includes(coverage.coreStatus);
  const complete = coverage.expected.length > 0 && !coverage.missing.length && !coverage.extra.length
    && !coverage.invalidContributionCount && coreComplete;
  const parts = [`<strong>联合覆盖 ${escapeHtml(coverage.covered.length)}/${escapeHtml(coverage.expected.length)}</strong>`];
  if (coverage.coreStatus === "scope_anchor") {
    parts.push(`<span class="is-reference">后台目录锚点：${escapeHtml(blindGoldReviewNodeLabel(coverage.questionCore))}（不计入联合覆盖）</span>`);
  } else if (coverage.coreStatus !== "question_missing") {
    parts.push(`<span class="is-core">作答核心：${escapeHtml(blindGoldReviewNodeLabel(coverage.questionCore))}</span>`);
  }
  if (!coverage.expected.length) {
    parts.push('<span class="is-muted">题目最小充分知识集尚未确认</span>');
  } else if (complete) {
    parts.push('<span class="is-complete">最小充分知识已等价覆盖</span>');
  }
  if (coverage.missing.length) {
    parts.push('<span class="is-warning">未覆盖</span>', blindGoldReviewKnowledgeTagsHtml(coverage.missing));
  }
  if (coverage.extra.length) {
    parts.push('<span class="is-warning">超出范围</span>', blindGoldReviewKnowledgeTagsHtml(coverage.extra));
  }
  if (coverage.missingRequiredFamilyCount) {
    parts.push(`<span class="is-warning">${escapeHtml(coverage.missingRequiredFamilyCount)} 个作答必需关联题族缺少定义</span>`);
  }
  if (coverage.invalidContributionCount) {
    parts.push(`<span class="is-warning">${escapeHtml(coverage.invalidContributionCount)} 项贡献不属于题目最小充分知识或题族覆盖范围</span>`);
  }
  parts.push(`<span class="is-reference">普通关联 ${escapeHtml(coverage.referenceCount)} 个，不计入联合覆盖</span>`);
  if (coverage.coreStatus === "not_contributed") {
    parts.push(`<span class="is-core-mismatch">题目知识焦点“${escapeHtml(blindGoldReviewNodeLabel(coverage.questionCore))}”尚未由${escapeHtml(coverage.primaryKind)}承载</span>`);
  } else if (coverage.coreStatus === "mismatched") {
    parts.push(`<span class="is-core-mismatch">旧版核心口径不一致：题目“${escapeHtml(blindGoldReviewNodeLabel(coverage.questionCore))}” ≠ ${escapeHtml(coverage.primaryKind)}“${escapeHtml(blindGoldReviewNodeLabel(coverage.familyCore))}”</span>`);
  } else if (coverage.coreStatus === "family_missing") {
    parts.push(`<span class="is-muted">${escapeHtml(coverage.primaryKind)}后台目录锚点待选择</span>`);
  } else if (coverage.coreStatus === "question_missing") {
    parts.push(`<span class="is-muted">${coverage.coreRole === "scope_anchor" ? "范围锚点" : "作答核心"}尚未确认</span>`);
  }
  element.innerHTML = parts.join("");
  element.classList.toggle("is-complete", complete);
  element.classList.toggle("has-gap", Boolean(coverage.missing.length || coverage.extra.length
    || coverage.missingRequiredFamilyCount || coverage.invalidContributionCount));
  element.classList.toggle("has-core-mismatch", ["mismatched", "not_contributed"].includes(coverage.coreStatus));
}

function syncBlindGoldRelatedFamilyPickerSummary() {
  const root = blindGoldRelatedFamilyPickerRoot();
  const select = document.querySelector("#blind-gold-related-families");
  const summary = root?.querySelector("[data-blind-gold-family-summary]");
  if (!root || !select || !summary) return;
  const selected = [...select.options].filter((option) => option.value && option.selected);
  const relations = blindGoldRelatedFamilyRelationsFromSelect();
  const counts = blindGoldRelatedFamilyRelationCounts(relations);
  const roleLabel = (option) => blindGoldRelatedFamilyCoverageRole({ coverageRole: option.dataset.coverageRole }) === "required"
    ? "作答必需"
    : "普通关联";
  summary.textContent = selected.length > 1
    ? `已选 ${selected.length} 个 · 必需 ${counts.required} · 普通 ${counts.reference}`
    : (selected[0] ? `${selected[0].textContent} · ${roleLabel(selected[0])}` : (root.dataset.blindGoldFamilyEmptyLabel || "请选择关联题族"));
  summary.title = selected.map((option) => `${option.textContent} · ${roleLabel(option)}`).join("\n");
  const trigger = root.querySelector("[data-blind-gold-family-trigger]");
  trigger?.setAttribute("aria-label", `选择关联题族，当前已选 ${selected.length} 项，其中作答必需 ${counts.required} 项，普通关联 ${counts.reference} 项`);
}

function renderBlindGoldRelatedFamilyPicker() {
  const root = blindGoldRelatedFamilyPickerRoot();
  const select = document.querySelector("#blind-gold-related-families");
  const search = root?.querySelector("[data-blind-gold-family-search]");
  const optionsContainer = root?.querySelector("[data-blind-gold-family-options]");
  if (!root || !select || !search || !optionsContainer) return;
  syncBlindGoldRelatedFamilyPickerSummary();
  const query = search.value.trim().toLocaleLowerCase("zh-CN");
  const options = [...select.options].filter((option) => option.value);
  const selectedCount = options.filter((option) => option.selected && !option.disabled).length;
  const selectionLimitReached = selectedCount >= blindGoldRelatedFamilySelectionLimit;
  const visible = options.filter((option) => option.selected
    || !query
    || option.textContent.toLocaleLowerCase("zh-CN").includes(query));
  // Keep selected entries easy to find; the group renderer below always puts
  // the current formal catalog before historical snapshots.
  visible.sort((left, right) => Number(right.selected) - Number(left.selected)
    || Number(left.disabled) - Number(right.disabled));
  let optionIndex = 0;
  const renderOption = (option) => {
      const index = optionIndex;
      const blockedByLimit = selectionLimitReached && !option.selected && !option.disabled;
      const historicalSnapshot = option.dataset.familySource === "historical_snapshot";
      const pendingReview = option.dataset.familyStatus === "pending_review";
      const disabled = select.disabled || blockedByLimit || option.disabled;
      // Historical relations can be removed, but their role is part of the
      // frozen audit record and must not be edited in place.
      const roleDisabled = disabled || historicalSnapshot;
      const disabledLabel = historicalSnapshot ? "，历史快照，当前正式目录不存在"
        : (option.dataset.blindGoldDisabledReason === "primary" ? "，当前主题族，不可重复选择"
          : (pendingReview ? "，待审核，非争议审核不可选择" : ""));
      const badge = historicalSnapshot ? "历史快照 · 仅供追溯"
        : (option.dataset.blindGoldDisabledReason === "primary" ? "主题族"
          : (pendingReview ? "待审核" : ""));
      const coverageRole = blindGoldRelatedFamilyCoverageRole({
        coverageRole: option.dataset.coverageRole,
        requiredForAnswer: option.dataset.requiredForAnswer === "true",
      });
      const optionId = `blind-gold-related-family-option-${index}`;
      optionIndex += 1;
      return `<div class="question-family-multiselect-option blind-gold-related-family-option ${option.selected ? "is-selected" : ""} ${option.disabled || blockedByLimit ? "is-locked" : ""}" data-family-source="${escapeHtml(blindGoldFamilyPickerSource(option))}">
      <input id="${optionId}" data-blind-gold-family-option type="checkbox" value="${escapeHtml(option.value)}" aria-label="${escapeHtml(`${option.textContent}${disabledLabel || (blockedByLimit ? "，已达到 30 个关联题族上限" : "")}`)}" ${option.selected ? "checked" : ""} ${disabled ? "disabled" : ""} />
      <label for="${optionId}"><span>${escapeHtml(option.textContent)}</span></label>
      ${badge ? `<em>${escapeHtml(badge)}</em>` : ""}
      ${option.selected ? `<div class="blind-gold-family-coverage-role" role="group" aria-label="${escapeHtml(`${option.textContent}的关联用途`)}">
        <span>关联用途</span>
        <div>
          <button type="button" data-blind-gold-family-role="required" data-blind-gold-family-id="${escapeHtml(option.value)}" aria-pressed="${coverageRole === "required"}" ${roleDisabled ? "disabled" : ""}>作答必需</button>
          <button type="button" data-blind-gold-family-role="reference" data-blind-gold-family-id="${escapeHtml(option.value)}" aria-pressed="${coverageRole === "reference"}" ${roleDisabled ? "disabled" : ""}>普通关联</button>
        </div>
      </div>` : ""}
    </div>`;
    };
  const optionMarkup = blindGoldFamilyPickerGroups(visible).map((group) => `<section class="question-family-multiselect-group" data-family-group="${escapeHtml(group.source)}">
    <div class="question-family-multiselect-group-title">${escapeHtml(group.label)}</div>
    ${group.options.map(renderOption).join("")}
  </section>`).join("");
  optionsContainer.innerHTML = visible.length
    ? optionMarkup
    : '<div class="question-family-multiselect-empty">没有匹配的题族</div>';
}

function syncBlindGoldRelatedFamilyPickerOpenState(open) {
  const root = blindGoldRelatedFamilyPickerRoot();
  const panel = root?.querySelector("[data-blind-gold-family-panel]");
  const trigger = root?.querySelector("[data-blind-gold-family-trigger]");
  const search = root?.querySelector("[data-blind-gold-family-search]");
  if (!root?.isConnected || !panel || !trigger || !search) return;
  panel.hidden = !open;
  root.classList.toggle("is-open", open);
  trigger.setAttribute("aria-expanded", String(open));
  if (open) {
    positionQuestionFamilyMultiselect(root);
    search.focus({ preventScroll: true });
  } else if (search.value) {
    search.value = "";
    renderBlindGoldRelatedFamilyPicker();
  }
}

function setBlindGoldRelatedFamilyPickerOpen(open = false) {
  const root = blindGoldRelatedFamilyPickerRoot();
  const panel = root?.querySelector("[data-blind-gold-family-panel]");
  const trigger = root?.querySelector("[data-blind-gold-family-trigger]");
  if (!root || !panel || !trigger) return;
  const shouldOpen = Boolean(open && !trigger.disabled);
  if (shouldOpen) setBlindGoldKnowledgePickerOpen(null, false);
  const wasOpen = questionFamilyMultiselectIsOpen(root);
  if (shouldOpen === wasOpen) {
    if (shouldOpen) syncBlindGoldRelatedFamilyPickerOpenState(true);
    return;
  }
  if (shouldOpen) {
    renderBlindGoldRelatedFamilyPicker();
    panel.hidden = false;
    if (typeof panel.showPopover === "function") {
      try {
        if (!panel.matches(":popover-open")) panel.showPopover();
      } catch {
        root.classList.add("is-open");
      }
    }
    syncBlindGoldRelatedFamilyPickerOpenState(true);
    return;
  }
  if (typeof panel.hidePopover === "function") {
    try {
      if (panel.matches(":popover-open")) panel.hidePopover();
    } catch {
      root.classList.remove("is-open");
    }
  }
  syncBlindGoldRelatedFamilyPickerOpenState(false);
  panel.hidden = true;
}

function initializeBlindGoldRelatedFamilyPicker() {
  const root = blindGoldRelatedFamilyPickerRoot();
  if (!root) return;
  renderBlindGoldRelatedFamilyPicker();
  if (root.dataset.blindGoldFamilyInitialized === "true") return;
  root.dataset.blindGoldFamilyInitialized = "true";
  root.querySelector("[data-blind-gold-family-panel]")?.addEventListener("toggle", (event) => syncBlindGoldRelatedFamilyPickerOpenState(event.newState === "open"));
}

function blindGoldReviewKnowledgeSummary(value = {}) {
  const role = blindGoldCoreKnowledgeRole(value);
  const roleLabel = blindGoldCoreKnowledgeRoleLabels[role];
  const core = blindGoldReviewNodeLabel(value.coreKnowledge || {});
  const required = (value.requiredKnowledge || []).map(blindGoldReviewNodeLabel).filter(Boolean);
  const evidenceCount = value.textbookEvidence?.length || 0;
  const optionCount = value.optionKnowledge?.length || value.scoringPoints?.length || 0;
  const roleNote = role === "scope_anchor" ? "（不计入联合覆盖）" : "";
  return `${roleLabel}：${core || "未标注"}${roleNote}\n最小充分知识：${required.join(" · ") || "未标注"}\n教材证据：${evidenceCount} 条 · 选项知识/得分点：${optionCount} 项`;
}

function blindGoldReviewFamilySummary(value = {}) {
  const decision = value.decision === "create_new" ? "新建题族" : "加入现有题族";
  const primary = value.decision === "create_new"
    ? value.candidateFamily?.name
    : value.families?.find((family) => family.id === value.primaryFamilyId)?.name;
  const relations = blindGoldReviewRelatedFamilyRelations(value);
  const counts = blindGoldRelatedFamilyRelationCounts(relations);
  return `${decision}：${primary || value.primaryFamilyId || "未选择"}\n关联题族：${relations.length} 个（作答必需 ${counts.required} · 普通关联 ${counts.reference}）`;
}

function renderBlindGoldAiComparisons(item = selectedBlindGoldReviewItem()) {
  const comparison = item?.aiComparison || {};
  const validityCopy = comparison.validity === "stale" ? "AI 候选已失效，仅供追溯" : "AI 候选仅供提交后对照";
  const renderStage = (stageName, humanValue, formatter) => {
    const stage = comparison[stageName] || {};
    const panel = document.querySelector(`#blind-gold-${stageName}-ai-comparison`);
    const body = document.querySelector(`#blind-gold-${stageName}-ai-comparison-body`);
    const revealed = stage.available === true && stage.revealed === true && stage.candidate;
    panel.hidden = !revealed;
    panel.open = Boolean(revealed);
    if (!revealed) {
      body.innerHTML = "";
      return;
    }
    body.innerHTML = `<div class="blind-gold-ai-comparison-grid">
      <section><h4>人工金标</h4><p>${escapeHtml(formatter(humanValue || {}))}</p><small>先于 AI 候选独立提交</small></section>
      <section><h4>AI 候选</h4><p>${escapeHtml(formatter(stage.candidate || {}))}</p>${stage.candidate?.reason || stage.candidate?.similarityReason ? `<small>${escapeHtml(stage.candidate.reason || stage.candidate.similarityReason)}</small>` : ""}<small class="${comparison.validity === "stale" ? "is-stale" : ""}">${escapeHtml(validityCopy)}</small></section>
    </div>`;
  };
  const human = item?.humanGold || {};
  renderStage("content", human.answerKnowledge || item?.answerKnowledge, blindGoldReviewKnowledgeSummary);
  renderStage("family", human.familyGold || item?.familyGold, blindGoldReviewFamilySummary);
}

// 证据卡片显示知识树里"现在"的教材位置（服务端按 chunkId 现算 currentCatalogPath）。
// 只有"这条证据指向的那个节点本身变了名"时才补一行小字留痕——比较用的是路径末段，
// 并忽略"第X章/节""一、""（一）"这类编号，避免同一位置因写法差异被误判成变更。
function blindGoldEvidencePathKey(value) {
  return String(value || "").normalize("NFKC").toLocaleLowerCase("zh-CN")
    .replace(/第[一二三四五六七八九十百零〇两0-9]+[章节篇编]/g, "")
    .replace(/[（(]\s*[一二三四五六七八九十百零〇两0-9]+\s*[）)]/g, "")
    .replace(/(?:^|[\s>])[一二三四五六七八九十百零〇两0-9]+[、.．]/g, "")
    .replace(/[\s，。！？；：、“”‘’（）()【】\[\]《》<>·…—\-_/\\>]/g, "");
}

function blindGoldEvidencePathTail(value) {
  const segments = String(value || "").split(/\s*>\s*/).filter(Boolean);
  return blindGoldEvidencePathKey(segments[segments.length - 1] || "");
}

function blindGoldEvidenceRowHtml(evidence = {}, index = 0, frozen = false) {
  const checked = evidence.humanSelection?.status === "selected";
  const recordedPath = String(evidence.catalogPath || "");
  const currentPath = String(evidence.currentCatalogPath || "");
  const shownPath = currentPath || recordedPath;
  const pathChanged = Boolean(currentPath && recordedPath
    && blindGoldEvidencePathTail(currentPath) !== blindGoldEvidencePathTail(recordedPath));
  const recordedNote = pathChanged ? `<small class="blind-gold-evidence-recorded">审核时：${escapeHtml(recordedPath)}</small>` : "";
  return `<div class="blind-gold-evidence-row" data-blind-gold-evidence-row data-blind-gold-evidence-index="${escapeHtml(index)}">
    <label class="blind-gold-evidence-choice"><input type="checkbox" data-blind-gold-evidence-retained ${checked ? "checked" : ""} ${frozen ? "disabled" : ""} /><span class="blind-gold-evidence-view"><strong>${escapeHtml(shownPath || `教材证据 ${index + 1}`)}</strong>${evidence.printedPageStart || evidence.pdfPageStart ? ` · 教材 ${escapeHtml(evidence.printedPageStart || "-")} 页 / PDF ${escapeHtml(evidence.pdfPageStart || "-")} 页` : ""}<br>${escapeHtml(evidence.excerpt || "未保存教材原文")}${recordedNote}</span></label>
    <div class="blind-gold-evidence-editor">
      <label class="wide"><span>教材位置</span><input data-blind-gold-evidence-path type="text" value="${escapeHtml(recordedPath)}" /></label>
      <label><span>教材页</span><input data-blind-gold-evidence-printed-page type="number" min="0" value="${escapeHtml(evidence.printedPageStart || "")}" /></label>
      <label><span>PDF 页</span><input data-blind-gold-evidence-pdf-page type="number" min="0" value="${escapeHtml(evidence.pdfPageStart || "")}" /></label>
      <label class="wide"><span>教材原文</span><textarea data-blind-gold-evidence-excerpt rows="3">${escapeHtml(evidence.excerpt || "")}</textarea></label>
      <input data-blind-gold-evidence-chunk-id type="hidden" value="${escapeHtml(evidence.chunkId || "")}" />
      <input data-blind-gold-evidence-book-id type="hidden" value="${escapeHtml(evidence.bookId || "")}" />
    </div>
  </div>`;
}

function blindGoldEvidenceListHtml(evidence = [], frozen = false) {
  if (!evidence.length) return '<div class="blind-gold-evidence-empty"><span>当前没有教材证据预填；证据不足时应标记“存在争议”。</span></div>';
  return evidence.map((entry, index) => blindGoldEvidenceRowHtml(entry, index, frozen)).join("");
}

function blindGoldReviewDisplayedEvidence(item = selectedBlindGoldReviewItem()) {
  const sourceEvidence = item?.sourceMaterials?.textbookEvidence || [];
  const humanEvidence = item?.humanGold?.answerKnowledge?.textbookEvidence || item?.answerKnowledge?.textbookEvidence || [];
  const humanByChunkId = new Map(humanEvidence
    .filter((evidence) => evidence.chunkId)
    .map((evidence) => [evidence.chunkId, evidence]));
  const sourceChunkIds = new Set(sourceEvidence.map((evidence) => evidence.chunkId).filter(Boolean));
  const fullSourcePool = sourceEvidence.map((evidence) => {
    const humanSelection = evidence.chunkId ? humanByChunkId.get(evidence.chunkId) : null;
    return humanSelection ? { ...evidence, ...humanSelection } : { ...evidence, humanSelection: null };
  });
  const humanOnlyEvidence = humanEvidence.filter((evidence) => !evidence.chunkId || !sourceChunkIds.has(evidence.chunkId));
  return [...fullSourcePool, ...humanOnlyEvidence];
}

function renderBlindGoldFamilyDefinition(family) {
  const required = (family?.coverageKnowledge || family?.requiredKnowledge || []).map(blindGoldReviewNodeLabel).filter(Boolean);
  const anchors = (family?.textbookAnchors || []).map(blindGoldReviewNodeLabel).filter(Boolean);
  const values = {
    name: family?.name || "-",
    focusKey: family?.focusKey || "-",
    coreKnowledge: family ? blindGoldReviewNodeLabel(family.scopeAnchor || family.coreKnowledge || {}) : "-",
    requiredKnowledge: required.join(" · ") || "-",
    textbookAnchors: anchors.join(" · ") || "-",
    assessmentAction: family?.assessmentAction || "-",
    boundaries: family ? `纳入：${family.inclusionBoundary || "未填写"}\n排除：${family.exclusionBoundary || "未填写"}` : "-",
  };
  Object.entries(values).forEach(([field, value]) => {
    const element = document.querySelector(`[data-blind-gold-family-field="${field}"]`);
    if (element) element.textContent = value;
  });
}

function blindGoldReviewPrefillCandidateFromKnowledge(item = selectedBlindGoldReviewItem()) {
  if (!item) return false;
  const answerKnowledge = blindGoldReviewHumanAnswerKnowledge(item);
  const coreKnowledge = answerKnowledge.coreKnowledge || {};
  const coreKey = blindGoldReviewNodeKey(coreKnowledge);
  const requiredKeys = new Set((answerKnowledge.requiredKnowledge || []).map(blindGoldReviewNodeKey).filter(Boolean));
  const coreSelect = document.querySelector("#blind-gold-new-family-core");
  const requiredSelect = document.querySelector("#blind-gold-new-family-required");
  const anchorSelect = document.querySelector("#blind-gold-new-family-anchors");
  let prefilled = false;
  if (coreKey && coreSelect && !coreSelect.value && [...coreSelect.options].some((option) => option.value === coreKey)) {
    coreSelect.value = coreKey;
    prefilled = true;
  }
  if (requiredSelect && ![...requiredSelect.options].some((option) => option.selected) && requiredKeys.size) {
    [...requiredSelect.options].forEach((option) => { option.selected = requiredKeys.has(option.value); });
    prefilled = [...requiredSelect.options].some((option) => option.selected) || prefilled;
  }
  if (coreKey && anchorSelect && ![...anchorSelect.options].some((option) => option.selected)) {
    const coreAnchor = [...anchorSelect.options].find((option) => option.value === coreKey);
    if (coreAnchor) {
      coreAnchor.selected = true;
      prefilled = true;
    }
  }
  if (prefilled) {
    syncBlindGoldNewFamilyRequiredKnowledgeCore();
    initializeBlindGoldKnowledgePickers();
  }
  return prefilled;
}

function syncBlindGoldFamilyOptionEligibility(primaryFamilyId = "") {
  const allowUnconfirmed = blindGoldReviewApiResult(state.blindGoldReviewResult) === "disputed";
  const liveOverride = blindGoldFormalFamilyDraftOverride();
  const liveOverrideIds = new Set((liveOverride?.familyIds || []).map((id) => String(id || "").trim()).filter(Boolean));
  const primarySelect = document.querySelector("#blind-gold-existing-family");
  const relatedSelect = document.querySelector("#blind-gold-related-families");
  [...(primarySelect?.options || [])].forEach((option) => {
    if (!option.value) return;
    const historicalSnapshot = option.dataset.familySource === "historical_snapshot";
    const pendingReview = option.dataset.familyStatus === "pending_review";
    // A historical primary remains visible for auditability, but unlike a
    // related checkbox it has no separate remove action. It must therefore be
    // read-only and can only be replaced by selecting a current family.
    if (historicalSnapshot) option.disabled = true;
    else option.disabled = pendingReview && !allowUnconfirmed;
    option.dataset.blindGoldDisabledReason = historicalSnapshot
      ? "historical_snapshot"
      : (option.disabled ? "pending_review" : "");
    // A temporary live alignment may intentionally carry a pending member
    // relation so the reviewer can see and submit a disputed verdict. Keep it
    // selected (still disabled for manual changes); the server remains the
    // final non-disputed membership gate.
    if (option.disabled && option.selected && !historicalSnapshot && !liveOverrideIds.has(option.value)) option.selected = false;
  });
  [...(relatedSelect?.options || [])].forEach((option) => {
    const isPrimary = Boolean(primaryFamilyId) && option.value === primaryFamilyId;
    const historicalSnapshot = option.dataset.familySource === "historical_snapshot";
    const pendingReview = option.dataset.familyStatus === "pending_review";
    // Selected historical relations are removable; unselected historical
    // snapshots remain read-only and cannot be re-added.
    option.disabled = (historicalSnapshot && !option.selected) || isPrimary || (pendingReview && !allowUnconfirmed);
    option.dataset.blindGoldDisabledReason = historicalSnapshot
      ? "historical_snapshot"
      : (isPrimary ? "primary" : (option.disabled ? "pending_review" : ""));
    if (option.disabled && option.selected && !historicalSnapshot && !liveOverrideIds.has(option.value)) option.selected = false;
  });
}

function syncBlindGoldFamilyDecision() {
  const item = selectedBlindGoldReviewItem();
  if (!item) return;
  const replayMode = blindGoldReviewSelectedReplayMode(item);
  const decision = replayMode === "unmatched" ? "create_new" : "join_existing";
  document.querySelectorAll('input[name="blind-gold-family-decision"]').forEach((radio) => { radio.checked = radio.value === decision; });
  const isNew = decision === "create_new";
  const prefilled = isNew && blindGoldReviewPrefillCandidateFromKnowledge(item);
  const newFamilyFields = document.querySelector("#blind-gold-new-family-fields");
  if (prefilled) newFamilyFields.dataset.knowledgePrefilled = "true";
  newFamilyFields.hidden = !isNew;
  document.querySelector("#blind-gold-existing-family-field").hidden = isNew;
  document.querySelector("#blind-gold-related-family-field").hidden = false;
  document.querySelector("#blind-gold-family-definition").hidden = isNew;
  const primaryFamilyId = isNew ? "" : document.querySelector("#blind-gold-existing-family").value;
  syncBlindGoldFamilyOptionEligibility(primaryFamilyId);
  renderQuestionFamilyMultiselect("blind-gold-primary");
  renderBlindGoldRelatedFamilyPicker();
  document.querySelector("#blind-gold-new-family-requirement").textContent = isNew && newFamilyFields.dataset.knowledgePrefilled === "true"
    ? "已按人工确认的题目知识焦点与最小充分知识集预填覆盖范围；题族判别焦点、后台目录锚点、考查动作和边界仍需逐项核对。"
    : "名称、题族判别焦点、后台目录锚点、覆盖知识、教材锚点和考查动作必须齐全；纳入与排除边界可后补。";
  renderBlindGoldFamilyDefinition(isNew ? null : blindGoldReviewFamilyById(document.querySelector("#blind-gold-existing-family").value, item));
  renderBlindGoldFamilyContributions(item);
  syncBlindGoldReviewStages(item);
}

function syncBlindGoldReplayMode() {
  const item = selectedBlindGoldReviewItem();
  if (!item) return;
  const replayMode = blindGoldReviewSelectedReplayMode(item);
  syncBlindGoldFamilyDecision();
  const question = item.question || {};
  document.querySelector("#blind-gold-question-meta").textContent = `${questionBookName(question.bookId || "")} · ${question.typeLabel || question.type || "题型未标明"} · 正式题目版本 v${question.version || 0} · ${blindGoldReviewModeAuditLabel(item, replayMode)}`;
}

function blindGoldReviewNextPendingItem(currentItem = selectedBlindGoldReviewItem()) {
  const items = [...(state.blindGoldReviewBatch?.items || [])]
    .filter((item) => item.questionId !== currentItem?.questionId && blindGoldReviewItemResult(item) === "pending_review")
    .sort((left, right) => Number(left.order || 0) - Number(right.order || 0));
  return items.find((item) => Number(item.order || 0) > Number(currentItem?.order || 0)) || items[0] || null;
}

function syncBlindGoldReviewStages(item = selectedBlindGoldReviewItem()) {
  if (!item) return;
  syncBlindGoldFamilyCoverageSummary(item);
  const answerKnowledge = blindGoldReviewCurrentAnswerKnowledge(item);
  const contentComplete = blindGoldReviewStageIsComplete(item.contentReview);
  const familyComplete = blindGoldReviewStageIsComplete(item.familyReview)
    && item.familyReview.basedOnKnowledgeDigest === item.knowledgeDigest;
  const contentStage = document.querySelector("#blind-gold-content-stage");
  const familyStage = document.querySelector("#blind-gold-family-stage");
  const answer = (answerKnowledge.correctAnswer || []).join("、") || "待确认";
  const coreRole = blindGoldCoreKnowledgeRole(answerKnowledge);
  const coreRoleLabel = blindGoldCoreKnowledgeRoleLabels[coreRole];
  const core = blindGoldReviewNodeLabel(answerKnowledge.coreKnowledge || {});
  const requiredCount = answerKnowledge.requiredKnowledge?.length || 0;
  const relationSummary = blindGoldReviewOptionRelationSummary(item);
  const relationCopy = relationSummary.applicable ? ` · ${relationSummary.status}` : "";
  document.querySelector("#blind-gold-content-stage-summary").textContent = contentComplete
    ? `答案 ${answer} · ${coreRoleLabel}：${core || "未标注"} · 最小充分知识 ${requiredCount} 项${relationCopy}`
    : `待确认答案 ${answer}、教材证据与最小充分知识集`;
  const storedFamilyGold = item.humanGold?.familyGold || item.finalGold?.familyGold || item.familyGold || {};
  const replayMode = blindGoldReviewSelectedReplayMode(item);
  const decision = replayMode === "unmatched" ? "create_new" : "join_existing";
  const selectedFamilyControl = document.querySelector("#blind-gold-existing-family");
  const candidateNameControl = document.querySelector("#blind-gold-new-family-name");
  const candidateFocusControl = document.querySelector("#blind-gold-new-family-focus-key");
  const selectedFamilyId = selectedFamilyControl ? selectedFamilyControl.value : storedFamilyGold.primaryFamilyId;
  const candidateName = candidateNameControl ? candidateNameControl.value.trim() : storedFamilyGold.candidateFamily?.name;
  const candidateFocusKey = candidateFocusControl ? candidateFocusControl.value.trim() : storedFamilyGold.candidateFamily?.focusKey;
  const family = decision === "create_new"
    ? { name: candidateName || "待填写题族名称" }
    : blindGoldReviewFamilyById(selectedFamilyId, item);
  const currentRelatedRelations = blindGoldRelatedFamilyRelationsFromSelect(selectedFamilyId || "");
  const storedRelatedRelations = blindGoldReviewRelatedFamilyRelations(storedFamilyGold);
  const relatedCounts = blindGoldRelatedFamilyRelationCounts(currentRelatedRelations);
  const relatedSummary = currentRelatedRelations.length
    ? ` · 关联 ${currentRelatedRelations.length} 个（必需 ${relatedCounts.required} · 普通 ${relatedCounts.reference}）`
    : " · 无关联题族";
  const decisionLabel = decision === "create_new" ? "新建题族" : "加入现有题族";
  const storedReplayMode = blindGoldReviewReplayMode(item);
  const storedDecision = storedFamilyGold.decision || (storedReplayMode === "unmatched" ? "create_new" : "join_existing");
  const currentFamilyGold = blindGoldReviewCollectFamilyGold(item);
  const familySelectionChanged = replayMode !== storedReplayMode
    || decision !== storedDecision
    || (decision === "join_existing" && selectedFamilyId !== (storedFamilyGold.primaryFamilyId || ""))
    || (decision === "create_new" && candidateName !== (storedFamilyGold.candidateFamily?.name || ""))
    || (decision === "create_new" && candidateFocusKey !== (storedFamilyGold.candidateFamily?.focusKey || ""))
    || blindGoldRelatedFamilyRelationSignature(currentRelatedRelations) !== blindGoldRelatedFamilyRelationSignature(storedRelatedRelations)
    || blindGoldFamilyContributionSignature(item, currentFamilyGold) !== blindGoldFamilyContributionSignature(item, storedFamilyGold);
  const familyStageStatus = familyComplete && !familySelectionChanged ? "已完成" : (familySelectionChanged ? "待保存" : "待确认");
  document.querySelector("#blind-gold-family-stage-summary").textContent = contentComplete
    ? `${decisionLabel} · ${family?.name || "待选择题族"}${relatedSummary} · ${familyStageStatus}`
    : "完成阶段 1 后核对题族六维定义";
  familyStage.classList.toggle("is-locked", !contentComplete);
  familyStage.dataset.locked = String(!contentComplete);
  familyStage.querySelector("summary")?.setAttribute("aria-disabled", String(!contentComplete));
  if (state.blindGoldBusinessEditMode || state.blindGoldContentEditable || !contentComplete) {
    contentStage.open = true;
    familyStage.open = false;
  } else {
    contentStage.open = false;
    familyStage.open = true;
  }
  contentStage.classList.toggle("is-complete", contentComplete);
  familyStage.classList.toggle("is-complete", familyComplete);
}

function setBlindGoldReviewEditState() {
  const item = selectedBlindGoldReviewItem();
  if (!item) return;
  const frozen = state.blindGoldReviewBatch?.status === "frozen";
  const revisionLocked = blindGoldRevisionItemIsInherited(item);
  const readOnly = frozen || revisionLocked;
  const contentComplete = blindGoldReviewStageIsComplete(item.contentReview);
  const familyComplete = blindGoldReviewStageIsComplete(item.familyReview)
    && item.familyReview.basedOnKnowledgeDigest === item.knowledgeDigest;
  const bookId = item.question?.bookId || "";
  const catalogReady = state.blindGoldKnowledgeStructures.has(bookId) && state.blindGoldFamilyCatalogs.has(bookId);
  const businessSync = item.businessSync || {};
  const hasBusinessDrift = ["question_drift", "knowledge_drift"].includes(businessSync.status);
  const businessEditable = !readOnly && !hasBusinessDrift && catalogReady && state.blindGoldBusinessEditMode && !state.blindGoldReviewSaving;
  const goldContentEditable = !readOnly && !hasBusinessDrift && catalogReady && state.blindGoldContentEditable
    && !state.blindGoldBusinessEditMode && !state.blindGoldReviewSaving;
  const reviewingContent = !contentComplete || state.blindGoldContentEditable;
  const revisingCompletedContent = contentComplete && state.blindGoldContentEditable;
  // Stage 2 is an editable draft as soon as stage 1 is complete. The verdict
  // controls still decide whether the draft may be submitted, but choosing
  // “人工修正” should not be a prerequisite for inspecting or correcting the
  // family relation itself.
  const familyEditable = !readOnly && !hasBusinessDrift && catalogReady && contentComplete && !state.blindGoldContentEditable && !state.blindGoldBusinessEditMode
    && !state.blindGoldReviewSaving;
  if (!(goldContentEditable || businessEditable)) setBlindGoldKnowledgePickerOpen(null, false);
  if (!familyEditable) setBlindGoldRelatedFamilyPickerOpen(false);
  const form = document.querySelector("#blind-gold-review-form");
  form.classList.toggle("is-business-editing", businessEditable);
  form.classList.toggle("is-gold-content-editing", goldContentEditable);
  form.classList.toggle("is-revision-inherited", revisionLocked);
  ["#blind-gold-correct-answer", "#blind-gold-source-answer"].forEach((selector) => {
    document.querySelector(selector).readOnly = !businessEditable;
  });
  document.querySelector("#blind-gold-answer-source").disabled = !businessEditable;
  document.querySelector("#blind-gold-evidence-note").readOnly = !(goldContentEditable || businessEditable);
  document.querySelectorAll("#blind-gold-textbook-evidence [data-blind-gold-evidence-retained]")
    .forEach((control) => { control.disabled = !(goldContentEditable || businessEditable); });
  document.querySelectorAll("#blind-gold-textbook-evidence .blind-gold-evidence-editor input, #blind-gold-textbook-evidence .blind-gold-evidence-editor textarea, #blind-gold-core-knowledge, #blind-gold-required-knowledge")
    .forEach((control) => { control.disabled = !businessEditable; });
  document.querySelectorAll('input[name="blind-gold-core-knowledge-role"]')
    .forEach((control) => { control.disabled = !businessEditable; });
  document.querySelectorAll("#blind-gold-answer-knowledge input, #blind-gold-answer-knowledge select, #blind-gold-answer-knowledge textarea, #blind-gold-answer-knowledge button")
    .forEach((control) => { control.disabled = !(goldContentEditable || businessEditable); });
  document.querySelectorAll("#blind-gold-answer-knowledge input, #blind-gold-answer-knowledge textarea")
    .forEach((control) => { control.readOnly = !(goldContentEditable || businessEditable); });
  document.querySelectorAll("#blind-gold-replay-mode input, #blind-gold-existing-family, #blind-gold-related-families, #blind-gold-new-family-fields input, #blind-gold-new-family-fields select, #blind-gold-new-family-fields textarea, #blind-gold-family-contributions select")
    .forEach((control) => { control.disabled = !familyEditable; });
  document.querySelectorAll("#blind-gold-family-decision input").forEach((control) => { control.disabled = true; });
  document.querySelector('[data-question-family-multiselect="blind-gold-primary"] .question-family-multiselect-trigger').disabled = !familyEditable;
  document.querySelector("[data-blind-gold-family-trigger]").disabled = !familyEditable;
  document.querySelectorAll("#blind-gold-new-family-fields [data-blind-gold-knowledge-trigger]")
    .forEach((control) => { control.disabled = !familyEditable; });
  document.querySelectorAll("#blind-gold-family-contributions [data-blind-gold-knowledge-trigger], #blind-gold-family-contributions [data-use-blind-gold-family-contribution-suggestion]")
    .forEach((control) => { control.disabled = !familyEditable; });
  const formalFamilySyncButton = document.querySelector("#sync-blind-gold-formal-family-draft");
  if (formalFamilySyncButton) formalFamilySyncButton.disabled = !familyEditable || state.blindGoldReviewSaving;
  const selectedReplayMode = blindGoldReviewSelectedReplayMode(item);
  const selectedPrimaryFamilyId = selectedReplayMode === "unmatched" ? "" : document.querySelector("#blind-gold-existing-family").value;
  syncBlindGoldFamilyOptionEligibility(selectedPrimaryFamilyId);
  renderQuestionFamilyMultiselect("blind-gold-primary");
  syncBlindGoldNewFamilyRequiredKnowledgeCore();
  renderBlindGoldRelatedFamilyPicker();
  document.querySelector("#blind-gold-review-note").disabled = readOnly || state.blindGoldReviewSaving;
  const businessButton = document.querySelector("#edit-blind-gold-business-data");
  businessButton.disabled = readOnly || hasBusinessDrift || !catalogReady || state.blindGoldReviewSaving || state.blindGoldBusinessEditMode;
  businessButton.textContent = `修正正式题目，生成题目版本 v${(Number(item.question?.version) || 0) + 1}`;
  document.querySelector("#blind-gold-business-change-note").hidden = !state.blindGoldBusinessEditMode;
  document.querySelector("#blind-gold-business-sync-actions").hidden = !state.blindGoldBusinessEditMode;
  document.querySelector("#add-blind-gold-evidence").hidden = !businessEditable;
  const isSubjective = blindGoldReviewChoiceStructure(item) !== "composed_options" && !(item.question?.options || []).length;
  const setAllQuestionOnlyButton = document.querySelector("#set-all-blind-gold-question-only");
  setAllQuestionOnlyButton.disabled = frozen || contentComplete || !goldContentEditable || state.blindGoldReviewSaving;
  setAllQuestionOnlyButton.disabled = setAllQuestionOnlyButton.disabled || revisionLocked;
  setAllQuestionOnlyButton.title = contentComplete
    ? "首次答案与知识判断已提交，不能再批量覆盖"
    : (readOnly ? (revisionLocked ? "本题继承父版本，不在本次重审范围" : "金标集已冻结") : "");
  const addScoringPointButton = document.querySelector("#add-blind-gold-scoring-point");
  addScoringPointButton.hidden = !isSubjective || !(goldContentEditable || businessEditable);
  addScoringPointButton.disabled = state.blindGoldReviewSaving;
  const editGoldContentButton = document.querySelector("#edit-blind-gold-content-review");
  editGoldContentButton.hidden = readOnly || !contentComplete || state.blindGoldBusinessEditMode;
  editGoldContentButton.disabled = hasBusinessDrift || !catalogReady || state.blindGoldReviewSaving || state.blindGoldContentEditable;
  editGoldContentButton.textContent = state.blindGoldContentEditable ? "正在修订阶段 1" : "对照 AI 后修订阶段 1";
  document.querySelector("#blind-gold-content-edit-help").textContent = businessEditable
    ? "当前正在升版正式题目，可修改答案、知识焦点角色、题目知识焦点与最小充分知识。"
    : "证据取舍、选项知识和得分点只写入人工金标；答案、知识焦点角色、题目知识焦点或最小充分知识变更需使用顶部的正式题目升版按钮。";
  document.querySelector("#sync-blind-gold-business-data").textContent = state.blindGoldReviewSaving
    ? "正在同步正式题目"
    : `同步并创建正式题目版本 v${(Number(item.question?.version) || 0) + 1}`;
  const businessSyncPanel = document.querySelector("#blind-gold-business-sync");
  businessSyncPanel.classList.toggle("has-drift", hasBusinessDrift);
  const formalVersion = Number(businessSync.formalQuestionVersion) || Number(item.question?.version) || 0;
  const auditVersion = Number(businessSync.auditQuestionVersion) || Number(item.question?.version) || 0;
  document.querySelector("#blind-gold-business-sync-status").textContent = hasBusinessDrift
    ? (businessSync.status === "question_drift"
      ? `版本漂移：金标草稿依据正式题目版本 v${auditVersion}，当前正式题目版本为 v${formalVersion}`
      : `知识漂移：正式题目的知识归属已不同于金标草稿（正式题目版本 v${formalVersion}）`)
    : (state.blindGoldBusinessEditMode
    ? `正在修正正式题目版本 v${item.question?.version || 0}；提交成功后生成题目版本 v${(Number(item.question?.version) || 0) + 1}`
    : (catalogReady ? `已保存审核基线与正式题目版本 v${formalVersion} 一致` : "正在读取本教材的完整知识树与正式题族目录"));
  document.querySelector("#blind-gold-business-sync-help").textContent = hasBusinessDrift
    ? "当前审核依据已过期。重新载入会以正式题目、正式知识归属和正式题族关系覆盖本题草稿，并把两阶段审核重置为待审核。"
    : "这里校验的是已保存基线；人工修正不会只写入金标草稿，正式字段变更会生成新题目版本并清空旧题族审核。";
  const reloadBusinessButton = document.querySelector("#reload-blind-gold-business-data");
  reloadBusinessButton.hidden = readOnly || !hasBusinessDrift;
  reloadBusinessButton.disabled = state.blindGoldReviewSaving;
  // Keep the catalog recovery action visible for every editable question.
  // A formal-family drift can be discovered only when the reviewer submits;
  // hiding the action until then leaves a plain page refresh as the only
  // apparent recovery path.
  const familyCatalogAvailable = !readOnly && Boolean(item?.question?.bookId);
  const reloadFamilyButton = document.querySelector("#reload-blind-gold-family-catalog");
  if (reloadFamilyButton) {
    reloadFamilyButton.hidden = !familyCatalogAvailable;
    reloadFamilyButton.disabled = state.blindGoldReviewSaving;
  }
  const contentState = document.querySelector("#blind-gold-content-stage-state");
  contentState.textContent = contentComplete
    ? `已${blindGoldReviewResultLabels[blindGoldReviewUiResult(item.contentReview.result)] || "审核"}`
    : "待审核";
  contentState.className = `blind-gold-stage-state ${contentComplete ? item.contentReview.result : "pending_review"}`;
  const familyState = document.querySelector("#blind-gold-family-stage-state");
  familyState.textContent = familyComplete
    ? `已${blindGoldReviewResultLabels[blindGoldReviewUiResult(item.familyReview.result)] || "审核"}`
    : (contentComplete ? (item.contentReview.result === "corrected" ? "待重新审核" : "待审核") : "等待答案与知识");
  familyState.className = `blind-gold-stage-state ${familyComplete ? item.familyReview.result : "pending_review"}`;
  document.querySelectorAll("[data-blind-gold-review-result]").forEach((button) => {
    button.disabled = readOnly || hasBusinessDrift || !catalogReady || state.blindGoldReviewSaving || state.blindGoldBusinessEditMode
      || (revisingCompletedContent && button.dataset.blindGoldReviewResult !== "corrected");
    button.classList.toggle("is-selected", button.dataset.blindGoldReviewResult === state.blindGoldReviewResult);
  });
  const saveButton = document.querySelector("#save-blind-gold-review");
  const saveDisabled = readOnly || hasBusinessDrift || !catalogReady || state.blindGoldReviewSaving || state.blindGoldBusinessEditMode || !state.blindGoldReviewResult;
  saveButton.disabled = saveDisabled;
  const saveAndNextButton = document.querySelector("#save-and-next-blind-gold-review");
  const nextPending = !reviewingContent ? blindGoldReviewNextPendingItem(item) : null;
  saveAndNextButton.hidden = reviewingContent || !nextPending;
  saveAndNextButton.disabled = saveDisabled || !nextPending;
  document.querySelector("#blind-gold-review-stage-label").textContent = reviewingContent
    ? (revisingCompletedContent ? "重新审核答案、证据与知识" : "答案、教材证据与知识审核结果")
    : contentComplete
    ? (familyComplete ? "重新审核题族裁决" : "题族审核结果")
    : "答案、教材证据与知识审核结果";
  saveButton.textContent = state.blindGoldReviewSaving
    ? "正在保存审核"
    : (reviewingContent ? (revisingCompletedContent ? "保存人工金标修订" : "保存答案与知识审核") : "仅保存本题");
  syncBlindGoldRequiredKnowledgeCore();
  syncBlindGoldReviewStages(item);
}

function renderBlindGoldReviewDetail(options = {}) {
  const item = selectedBlindGoldReviewItem();
  const form = document.querySelector("#blind-gold-review-form");
  const empty = document.querySelector("#blind-gold-review-detail-empty");
  const preserveTransient = options.preserveTransient === true;
  const transientReviewResult = state.blindGoldReviewResult;
  const transientBusinessEdit = state.blindGoldBusinessEditMode;
  const transientContentEdit = state.blindGoldContentEditable;
  setBlindGoldKnowledgePickerOpen(null, false);
  setBlindGoldRelatedFamilyPickerOpen(false);
  if (!item) {
    state.blindGoldBusinessEditMode = false;
    state.blindGoldContentEditable = false;
    renderBlindGoldFormalFamilySync(null);
    form.hidden = true;
    empty.hidden = false;
    empty.textContent = state.blindGoldReviewBatch ? "从左侧选择一道题开始审核" : "当前没有可审核的金标批次";
    return;
  }
  form.hidden = false;
  empty.hidden = true;
  const question = item.question || {};
  const answerKnowledge = blindGoldReviewHumanAnswerKnowledge(item);
  const familyGold = blindGoldEffectiveFamilyGoldForRender(item);
  const sourceAnswer = item.sourceMaterials?.sourceAnswer || {};
  const frozen = state.blindGoldReviewBatch?.status === "frozen";
  const readOnly = frozen || blindGoldRevisionItemIsInherited(item);
  const nodes = blindGoldReviewKnowledgeNodes(item);
  const contentComplete = blindGoldReviewStageIsComplete(item.contentReview);
  if (!contentComplete && !readOnly && !state.blindGoldBusinessEditMode) state.blindGoldContentEditable = true;
  if (readOnly) state.blindGoldContentEditable = false;
  if (!preserveTransient || !transientReviewResult) {
    state.blindGoldReviewResult = contentComplete && state.blindGoldContentEditable
      ? "corrected"
      : blindGoldReviewPreferredResult(item);
  }
  if (preserveTransient) {
    state.blindGoldBusinessEditMode = transientBusinessEdit;
    state.blindGoldContentEditable = transientContentEdit;
  }
  document.querySelector("#blind-gold-review-result").value = state.blindGoldReviewResult;
  document.querySelector("#blind-gold-question-title").textContent = `第 ${item.order} 题`;
  document.querySelector("#blind-gold-question-meta").textContent = `${questionBookName(question.bookId || "")} · ${question.typeLabel || question.type || "题型未标明"} · 正式题目版本 v${question.version || 0} · ${blindGoldReviewModeAuditLabel(item)}`;
  const coreKnowledgeRole = blindGoldCoreKnowledgeRole(answerKnowledge);
  document.querySelectorAll('input[name="blind-gold-core-knowledge-role"]').forEach((radio) => {
    radio.checked = radio.value === coreKnowledgeRole;
  });
  const coreKnowledgePath = blindGoldReviewNodeLabel(answerKnowledge.coreKnowledge || item.answerKnowledge?.coreKnowledge || {});
  document.querySelector("#blind-gold-question-knowledge-path").textContent = `${blindGoldCoreKnowledgeRoleLabels[coreKnowledgeRole]} · ${coreKnowledgePath || "暂未标注"}`;
  document.querySelector("#blind-gold-question-sticky-summary").innerHTML = `<strong>${escapeHtml(question.stem || "题干暂缺")}</strong>${questionOptionListHtml(question?.options || [], "compact")}`;
  document.querySelector("#blind-gold-question-content").innerHTML = `${question.material ? `<div><strong>材料</strong><p>${escapeHtml(question.material)}</p></div>` : ""}<div><strong>题干</strong><p>${escapeHtml(question.stem || "")}</p></div>${questionOptionListHtml(question.options, "")}${question.sourceLabel || question.sourcePage ? `<small>来源：${escapeHtml(question.sourceLabel || "未标明")}${question.sourcePage ? ` · ${escapeHtml(question.sourcePage)}` : ""}</small>` : ""}`;
  document.querySelector("#blind-gold-answer-source").value = answerKnowledge.answerSource || sourceAnswer.answerSource || question.answerSource || "";
  const correctAnswer = answerKnowledge.correctAnswer ?? sourceAnswer.correctAnswer ?? [];
  document.querySelector("#blind-gold-correct-answer").value = (Array.isArray(correctAnswer) ? correctAnswer : [correctAnswer]).filter(Boolean).join("、");
  document.querySelector("#blind-gold-source-answer").value = answerKnowledge.referenceAnswer || sourceAnswer.referenceAnswer || question.referenceAnswer || "";
  const answerKnowledgeProvenance = item.humanGold?.answerKnowledgeProvenance || item.answerKnowledgeProvenance;
  const familyGoldProvenance = item.humanGold?.familyGoldProvenance || item.familyGoldProvenance;
  document.querySelector("#blind-gold-answer-provenance").textContent = blindGoldProvenanceSummary(answerKnowledgeProvenance, [
    ["答案", "answer"],
    ["教材证据", "textbookEvidence"],
  ]);
  document.querySelector("#blind-gold-knowledge-provenance").textContent = blindGoldProvenanceSummary(answerKnowledgeProvenance, [
    ["焦点角色", "coreKnowledgeRole"],
    ["知识焦点", "coreKnowledge"],
    ["最小充分集", "requiredKnowledge"],
    ["选项知识", "optionKnowledge"],
    ["主观题得分点", "scoringPoints"],
  ]);
  document.querySelector("#blind-gold-family-provenance").textContent = blindGoldProvenanceSummary(familyGoldProvenance, [
    ["裁决", "decision"],
    ["现有题族", "families"],
    ["新题族草稿", "candidateFamily"],
  ]);
  document.querySelector("#blind-gold-evidence-note").value = answerKnowledgeProvenance?.reviewEvidenceNote || "";
  const textbookEvidence = blindGoldReviewDisplayedEvidence(item);
  document.querySelector("#blind-gold-textbook-evidence").innerHTML = blindGoldEvidenceListHtml(textbookEvidence, readOnly);
  document.querySelector("#blind-gold-core-knowledge").innerHTML = blindGoldReviewNodeOptions(nodes, [answerKnowledge.coreKnowledge], true);
  const requiredKnowledgeSelect = document.querySelector("#blind-gold-required-knowledge");
  const requiredKnowledgeKeys = new Set((answerKnowledge.requiredKnowledge || []).map(blindGoldReviewNodeKey).filter(Boolean));
  requiredKnowledgeSelect.innerHTML = blindGoldReviewNodeOptions(nodes, answerKnowledge.requiredKnowledge || []);
  [...requiredKnowledgeSelect.options].forEach((option) => { option.selected = requiredKnowledgeKeys.has(option.value); });
  document.querySelector("#blind-gold-answer-knowledge").innerHTML = blindGoldReviewOptionKnowledgeHtml(item, nodes, readOnly);
  renderBlindGoldOptionRelationSummary(item);
  syncBlindGoldRequiredKnowledgeCore();
  const families = blindGoldReviewFormalFamilies(item);
  renderBlindGoldFormalFamilySync(item);
  const replayMode = blindGoldReviewReplayMode(item);
  document.querySelectorAll('input[name="blind-gold-replay-mode"]').forEach((radio) => { radio.checked = radio.value === replayMode; });
  document.querySelector("#blind-gold-existing-family").innerHTML = `<option value="">请选择题族</option>${families.map((family) => {
    const status = blindGoldReviewFamilyStatusLabel(family);
    const statusLabel = status ? ` · ${status}` : "";
    const familyLabel = `${family.name || family.id}${family.knowledgePath ? ` · ${family.knowledgePath}` : ""}${statusLabel}`;
    const selected = family.id === familyGold.primaryFamilyId;
    const historical = blindGoldReviewFamilyIsHistorical(family);
    const source = historical ? "historical_snapshot" : "current_catalog";
    return `<option value="${escapeHtml(family.id)}" data-family-status="${escapeHtml(family.status || "unknown")}" data-family-source="${source}" data-family-group="${source}" ${historical ? "disabled" : ""} ${selected ? "selected" : ""}>${escapeHtml(familyLabel)}</option>`;
  }).join("")}`;
  renderQuestionFamilyMultiselect("blind-gold-primary");
  const relatedFamilyRelations = blindGoldReviewRelatedFamilyRelations(familyGold);
  const relatedFamilyRelationMap = new Map(relatedFamilyRelations.map((relation) => [relation.familyId, relation]));
  document.querySelector("#blind-gold-related-families").innerHTML = families.map((family) => {
    const status = blindGoldReviewFamilyStatusLabel(family);
    const statusLabel = status ? ` · ${status}` : "";
    const relation = relatedFamilyRelationMap.get(family.id) || blindGoldRelatedFamilyRelation(family.id);
    const selected = relatedFamilyRelationMap.has(family.id);
    const historical = blindGoldReviewFamilyIsHistorical(family);
    const source = historical ? "historical_snapshot" : "current_catalog";
    return `<option value="${escapeHtml(family.id)}" data-family-status="${escapeHtml(family.status || "unknown")}" data-family-source="${source}" data-family-group="${source}" data-coverage-role="${escapeHtml(relation.coverageRole)}" data-required-for-answer="${relation.requiredForAnswer}" ${historical ? "disabled" : ""} ${selected ? "selected" : ""}>${escapeHtml(`${family.name || family.id}${family.knowledgePath ? ` · ${family.knowledgePath}` : ""}${statusLabel}`)}</option>`;
  }).join("");
  initializeBlindGoldRelatedFamilyPicker();
  document.querySelectorAll('input[name="blind-gold-family-decision"]').forEach((radio) => { radio.checked = radio.value === familyGold.decision; });
  const candidate = familyGold.candidateFamily || {};
  document.querySelector("#blind-gold-new-family-name").value = candidate.name || "";
  document.querySelector("#blind-gold-new-family-focus-key").value = candidate.focusKey || "";
  document.querySelector("#blind-gold-new-family-core").innerHTML = blindGoldReviewNodeOptions(nodes, [candidate.scopeAnchor || candidate.coreKnowledge], true);
  document.querySelector("#blind-gold-new-family-required").innerHTML = blindGoldReviewNodeOptions(nodes, candidate.coverageKnowledge || candidate.requiredKnowledge || []);
  document.querySelector("#blind-gold-new-family-anchors").innerHTML = blindGoldReviewNodeOptions(nodes, candidate.textbookAnchors || []);
  syncBlindGoldNewFamilyRequiredKnowledgeCore();
  initializeBlindGoldKnowledgePickers();
  document.querySelector("#blind-gold-new-family-action").value = candidate.assessmentAction || "";
  document.querySelector("#blind-gold-new-family-inclusion").value = candidate.inclusionBoundary || "";
  document.querySelector("#blind-gold-new-family-exclusion").value = candidate.exclusionBoundary || "";
  const familyReviewCurrent = blindGoldReviewStageIsComplete(item.familyReview)
    && item.familyReview.basedOnKnowledgeDigest === item.knowledgeDigest;
  const reviewNote = familyReviewCurrent ? (item.familyReview?.note || "")
    : (blindGoldReviewStageIsComplete(item.contentReview) ? "" : (item.contentReview?.note || ""));
  document.querySelector("#blind-gold-review-note").value = reviewNote;
  if (!state.blindGoldBusinessEditMode) document.querySelector("#blind-gold-business-note").value = "";
  syncBlindGoldFamilyDecision();
  setBlindGoldReviewEditState();
  renderBlindGoldAiComparisons(item);
  const bookId = item.question?.bookId || "";
  if (bookId && (!state.blindGoldKnowledgeStructures.has(bookId) || !state.blindGoldFamilyCatalogs.has(bookId))
    && !state.blindGoldCatalogRequests.has(bookId)) {
    void ensureBlindGoldReviewCatalog(item, { quiet: true });
  }
}

function renderBlindGoldReview(options = {}) {
  renderBlindGoldReviewSummary();
  renderBlindGoldFreezeSummary();
  renderBlindGoldRevisionLineage();
  renderBlindGoldReviewList();
  renderBlindGoldReviewDetail(options);
}

function invalidateBlindGoldReviewLoads() {
  state.blindGoldReviewLoadSequence = Number(state.blindGoldReviewLoadSequence || 0) + 1;
}

function beginBlindGoldReviewMutation() {
  state.blindGoldReviewMutationSequence = Number(state.blindGoldReviewMutationSequence || 0) + 1;
  invalidateBlindGoldReviewLoads();
  return state.blindGoldReviewMutationSequence;
}

function endBlindGoldReviewMutation(token) {
  if (token !== Number(state.blindGoldReviewMutationSequence || 0)) return;
  state.blindGoldReviewMutationSequence += 1;
  invalidateBlindGoldReviewLoads();
}

function blindGoldReviewMutationIsCurrent(token) {
  return token === Number(state.blindGoldReviewMutationSequence || 0);
}

function blindGoldRevisionNumber(value) {
  const revision = Number(value);
  return Number.isFinite(revision) ? revision : 0;
}

function mergeBlindGoldReviewBatchMeta(batch, incomingMeta = null) {
  if (!batch || !incomingMeta || typeof incomingMeta !== "object") return false;
  if (incomingMeta.id && batch.id && String(incomingMeta.id) !== String(batch.id)) return false;
  const currentRevision = blindGoldRevisionNumber(batch.revision);
  const incomingRevision = blindGoldRevisionNumber(incomingMeta.revision);
  const currentUpdatedAt = Number(batch.updatedAt) || 0;
  const incomingUpdatedAt = Number(incomingMeta.updatedAt) || 0;
  if (incomingRevision < currentRevision
    || (incomingRevision === currentRevision && incomingUpdatedAt > 0 && currentUpdatedAt > 0
      && incomingUpdatedAt < currentUpdatedAt)) return false;
  if (incomingRevision > 0) batch.revision = incomingRevision;
  if (incomingUpdatedAt > 0) batch.updatedAt = Math.max(currentUpdatedAt, incomingUpdatedAt);
  return true;
}

function mergeBlindGoldReviewBatchSnapshot(currentBatch, incomingBatch) {
  if (!incomingBatch?.id) return currentBatch;
  if (!currentBatch || currentBatch.id !== incomingBatch.id) return incomingBatch;
  const currentRevision = blindGoldRevisionNumber(currentBatch.revision);
  const incomingRevision = blindGoldRevisionNumber(incomingBatch.revision);
  if (incomingRevision < currentRevision) return currentBatch;
  const currentItems = new Map((currentBatch.items || []).map((item) => [item.questionId, item]));
  const seen = new Set();
  const items = (incomingBatch.items || []).map((incomingItem) => {
    seen.add(incomingItem.questionId);
    const currentItem = currentItems.get(incomingItem.questionId);
    if (!currentItem) return incomingItem;
    const currentItemRevision = blindGoldRevisionNumber(currentItem.revision);
    const incomingItemRevision = blindGoldRevisionNumber(incomingItem.revision);
    if (currentItemRevision > incomingItemRevision) return currentItem;
    if (currentItemRevision === incomingItemRevision
      && Number(currentItem.updatedAt || 0) > Number(incomingItem.updatedAt || 0)) return currentItem;
    return incomingItem;
  });
  (currentBatch.items || []).forEach((item) => {
    if (!seen.has(item.questionId)) items.push(item);
  });
  items.sort((left, right) => Number(left.order || 0) - Number(right.order || 0));
  return { ...incomingBatch, items };
}

function blindGoldReviewSelectedNodes(selector, item = selectedBlindGoldReviewItem()) {
  const select = document.querySelector(selector);
  return [...(select?.selectedOptions || [])].map((option) => blindGoldReviewResolveNode(option.value, item))
    .filter((node) => node.id || node.path || node.title);
}

function blindGoldReviewCollectCandidateFamily(item = selectedBlindGoldReviewItem(), includeIdentity = true) {
  if (!item) return null;
  const familyGold = item.humanGold?.familyGold || item.finalGold?.familyGold || item.familyGold || {};
  const original = familyGold.candidateFamily || {};
  const coreKnowledge = blindGoldReviewResolveNode(document.querySelector("#blind-gold-new-family-core")?.value || "", item);
  const requiredKnowledge = blindGoldReviewSelectedNodes("#blind-gold-new-family-required", item);
  const textbookAnchors = blindGoldReviewSelectedNodes("#blind-gold-new-family-anchors", item);
  const candidate = {
    ...(includeIdentity && original.id ? { id: original.id } : {}),
    name: document.querySelector("#blind-gold-new-family-name")?.value.trim() || "",
    focusKey: document.querySelector("#blind-gold-new-family-focus-key")?.value.trim() || "",
    bookId: item.question?.bookId || original.bookId || "",
    scopeAnchor: coreKnowledge,
    scopeAnchorNodeId: coreKnowledge.id,
    coreKnowledge,
    coreKnowledgeNodeId: coreKnowledge.id,
    coverageKnowledge: requiredKnowledge,
    coverageKnowledgeNodeIds: requiredKnowledge.map((node) => node.id).filter(Boolean),
    requiredKnowledge,
    requiredKnowledgeNodeIds: requiredKnowledge.map((node) => node.id).filter(Boolean),
    textbookAnchors,
    textbookAnchorNodeIds: textbookAnchors.map((node) => node.id).filter(Boolean),
    assessmentAction: document.querySelector("#blind-gold-new-family-action")?.value.trim() || "",
    inclusionBoundary: document.querySelector("#blind-gold-new-family-inclusion")?.value.trim() || "",
    exclusionBoundary: document.querySelector("#blind-gold-new-family-exclusion")?.value.trim() || "",
    independentMemberCount: Number(original.independentMemberCount || 0),
    memberQuestionIds: original.memberQuestionIds || [],
    independentMemberQuestionIds: original.independentMemberQuestionIds || [],
    retainedIndependentMemberQuestionIds: original.retainedIndependentMemberQuestionIds || [],
    provenance: original.provenance || "human_gold_review",
  };
  const contributionKnowledge = blindGoldFamilyContributionNodes(candidate, "primary", item, "candidate");
  return {
    ...candidate,
    membership: {
      ...(original.membership || {}),
      questionId: item.questionId,
      isPrimary: true,
      contributionKnowledgeNodeIds: contributionKnowledge.map((node) => node.id).filter(Boolean),
      contributionKnowledgeLabels: contributionKnowledge.map(blindGoldReviewNodeLabel).filter(Boolean),
    },
  };
}

function blindGoldReviewCollectAnswerKnowledge(item) {
  const displayedEvidence = blindGoldReviewDisplayedEvidence(item);
  const currentAnswerKnowledge = blindGoldReviewHumanAnswerKnowledge(item);
  const choiceStructure = blindGoldReviewChoiceStructure(item, currentAnswerKnowledge);
  const correctAnswer = document.querySelector("#blind-gold-correct-answer").value
    .split(/[,，、;；\s]+/).map((value) => value.trim()).filter(Boolean);
  const textbookEvidence = [...document.querySelectorAll("[data-blind-gold-evidence-row]")]
    .filter((row) => row.querySelector("[data-blind-gold-evidence-retained]")?.checked)
    .map((row) => {
      const selectedChunkId = row.querySelector("[data-blind-gold-evidence-chunk-id]")?.value.trim() || "";
      const original = displayedEvidence.find((evidence) => selectedChunkId && evidence.chunkId === selectedChunkId) || {};
      const printedPageStart = Number(row.querySelector("[data-blind-gold-evidence-printed-page]")?.value) || 0;
      const pdfPageStart = Number(row.querySelector("[data-blind-gold-evidence-pdf-page]")?.value) || 0;
      return {
        ...original,
        chunkId: row.querySelector("[data-blind-gold-evidence-chunk-id]")?.value.trim() || original.chunkId || "",
        bookId: row.querySelector("[data-blind-gold-evidence-book-id]")?.value.trim() || original.bookId || item.question?.bookId || "",
        catalogPath: row.querySelector("[data-blind-gold-evidence-path]")?.value.trim() || "",
        printedPageStart,
        printedPageEnd: printedPageStart,
        pdfPageStart,
        pdfPageEnd: pdfPageStart,
        excerpt: row.querySelector("[data-blind-gold-evidence-excerpt]")?.value.trim() || "",
        provenance: state.blindGoldBusinessEditMode ? "human_business_correction"
          : (state.blindGoldContentEditable ? "human_gold_review" : (original.provenance || "review_prefill")),
        candidateOnly: false,
      };
    });
  const coreKnowledge = blindGoldReviewResolveNode(document.querySelector("#blind-gold-core-knowledge").value, item);
  const coreKnowledgeRole = blindGoldSelectedCoreKnowledgeRole(item);
  const requiredKnowledge = blindGoldReviewSelectedNodes("#blind-gold-required-knowledge", item);
  const collectedKnowledgeUnits = [...document.querySelectorAll("[data-blind-gold-option-row]")].map((row, index) => {
    const knowledgeRelation = row.querySelector("[data-blind-gold-option-knowledge-relation]")?.value || "unreviewed";
    const selected = knowledgeRelation === "option_specific" ? [...(row.querySelector("[data-blind-gold-option-knowledge]")?.selectedOptions || [])]
      .map((option) => blindGoldReviewResolveNode(option.value, item))
      : [];
    const key = row.dataset.blindGoldOptionRow;
    const atomic = row.dataset.blindGoldUnitKind === "atomic";
    const original = atomic
      ? blindGoldReviewAtomicStatements(item, currentAnswerKnowledge).find((statement, statementIndex) => blindGoldAtomicStatementKey(statement, statementIndex) === key) || {}
      : currentAnswerKnowledge.optionKnowledge?.find((option) => option.key === key) || {};
    return {
      ...original,
      key,
      text: original.text || item.question?.options?.find((option) => option.key === key)?.text || "",
      role: row.querySelector("[data-blind-gold-option-role]")?.value || original.role || (atomic ? "statement" : "neutral"),
      basis: atomic ? row.querySelector("[data-blind-gold-atomic-basis]")?.value.trim() || "" : (original.basis || ""),
      knowledgeRelation,
      knowledgeNodeIds: selected.map((node) => node.id).filter(Boolean),
      knowledgeLabels: selected.map(blindGoldReviewNodeLabel),
      uncertaintyNote: knowledgeRelation === "undetermined"
        ? row.querySelector("[data-blind-gold-option-uncertainty-note]")?.value.trim() || ""
        : "",
      provenance: state.blindGoldBusinessEditMode ? "human_business_correction"
        : (state.blindGoldContentEditable ? "human_gold_review" : (original.provenance || "review_prefill")),
    };
  });
  const optionKnowledge = choiceStructure === "composed_options" ? [] : collectedKnowledgeUnits;
  const atomicStatements = choiceStructure === "composed_options" ? collectedKnowledgeUnits : [];
  const optionComposition = choiceStructure === "composed_options"
    ? blindGoldReviewOptionComposition(item, currentAnswerKnowledge)
    : [];
  const scoringPoints = [...document.querySelectorAll("[data-blind-gold-scoring-point]")].map((row, index) => {
    const original = currentAnswerKnowledge.scoringPoints?.[Number(row.dataset.blindGoldScoringPoint)] || {};
    const selected = [...(row.querySelector("[data-blind-gold-scoring-knowledge]")?.selectedOptions || [])]
      .map((option) => blindGoldReviewResolveNode(option.value, item));
    return {
      ...original,
      id: original.id || `point-${index + 1}`,
      description: row.querySelector("[data-blind-gold-scoring-description]")?.value.trim() || "",
      score: Number(row.querySelector("[data-blind-gold-scoring-score]")?.value) || 0,
      knowledgeNodeIds: selected.map((node) => node.id).filter(Boolean),
      knowledgeLabels: selected.map(blindGoldReviewNodeLabel),
      provenance: state.blindGoldBusinessEditMode ? "human_business_correction"
        : (state.blindGoldContentEditable ? "human_gold_review" : (original.provenance || "review_prefill")),
    };
  }).filter((point) => point.description);
  return {
    ...currentAnswerKnowledge,
    optionKnowledgeProtocolVersion: blindGoldOptionKnowledgeProtocolVersion,
    choiceStructure,
    correctAnswer,
    referenceAnswer: document.querySelector("#blind-gold-source-answer").value.trim(),
    answerSource: document.querySelector("#blind-gold-answer-source").value.trim(),
    answerReviewStatus: currentAnswerKnowledge.answerReviewStatus || item.question?.answerReviewStatus || "",
    textbookEvidence,
    coreKnowledge,
    coreKnowledgeRole,
    requiredKnowledge,
    optionKnowledge,
    atomicStatements,
    optionComposition,
    scoringPoints,
  };
}

function blindGoldReviewCollectFamilyGold(item) {
  // Commit the live picker state before assembling the payload. This is
  // important when the user edited a contribution and then changed a family
  // relation without triggering another picker render.
  blindGoldKnowledgePickerRoots()
    .filter((root) => root.dataset.blindGoldFamilyContributionPicker)
    .forEach((root) => rememberBlindGoldFamilyContribution(root, item));
  const replayMode = blindGoldReviewSelectedReplayMode(item);
  const decision = replayMode === "unmatched" ? "create_new" : "join_existing";
  const primaryFamilyId = decision === "join_existing" ? document.querySelector("#blind-gold-existing-family").value : "";
  const selectedFamily = primaryFamilyId ? blindGoldReviewFamilyById(primaryFamilyId, item) : null;
  const relatedFamilyRelations = blindGoldRelatedFamilyRelationsFromSelect(primaryFamilyId);
  const relatedFamilyIds = relatedFamilyRelations.map((relation) => relation.familyId);
  const relatedFamilyRelationMap = new Map(relatedFamilyRelations.map((relation) => [relation.familyId, relation]));
  const familyMap = new Map();
  const familyWithContribution = (family, role) => {
    const contributionKnowledge = blindGoldFamilyContributionNodes(family, role, item, family.id);
    return {
      ...family,
      membership: {
        ...(family.membership || {}),
        questionId: item.questionId,
        isPrimary: role === "primary",
        contributionKnowledgeNodeIds: contributionKnowledge.map((node) => node.id).filter(Boolean),
        contributionKnowledgeLabels: contributionKnowledge.map(blindGoldReviewNodeLabel).filter(Boolean),
      },
    };
  };
  if (decision === "join_existing" && selectedFamily) {
    familyMap.set(selectedFamily.id, familyWithContribution(selectedFamily, "primary"));
  }
  relatedFamilyIds.forEach((familyId) => {
    const family = blindGoldReviewFamilyById(familyId, item);
    const relation = relatedFamilyRelationMap.get(familyId);
    if (family && relation) familyMap.set(family.id, {
      ...familyWithContribution(family, relation.coverageRole),
      coverageRole: relation.coverageRole,
      requiredForAnswer: relation.requiredForAnswer,
    });
  });
  return {
    familyKnowledgeProtocolVersion: blindGoldFamilyKnowledgeProtocolVersion,
    replayMode,
    decision,
    primaryFamilyId,
    relatedFamilyIds,
    relatedFamilyRelations,
    families: [...familyMap.values()],
    candidateFamily: decision === "create_new" ? blindGoldReviewCollectCandidateFamily(item) : null,
    reason: blindGoldReviewStoredFamilyGold(item).reason || "",
  };
}

function blindGoldReviewSelectedHistoricalFamilyIds(item = selectedBlindGoldReviewItem()) {
  if (!item) return [];
  const historicalIds = new Set(
    blindGoldReviewFamilies(item)
      .filter(blindGoldReviewFamilyIsHistorical)
      .map((family) => String(family.id || "").trim())
      .filter(Boolean),
  );
  const selectedIds = [
    ...(document.querySelector("#blind-gold-existing-family")?.selectedOptions || []),
    ...(document.querySelector("#blind-gold-related-families")?.selectedOptions || []),
  ].filter((option) => option.selected && option.value && option.dataset.familySource === "historical_snapshot")
    .map((option) => String(option.value).trim())
    .filter(Boolean);
  return [...new Set(selectedIds.filter((id) => historicalIds.has(id)))];
}

async function reloadBlindGoldBusinessData() {
  const batch = state.blindGoldReviewBatch;
  const item = selectedBlindGoldReviewItem();
  const hasDrift = ["question_drift", "knowledge_drift"].includes(item?.businessSync?.status);
  if (!batch || !item || !hasDrift || blindGoldReviewItemIsReadOnly(item, batch) || state.blindGoldReviewSaving) return;
  if (!window.confirm("确认从正式题库重新载入这道题吗？\n\n当前金标草稿中的答案、知识和题族裁决将被正式数据覆盖，本题两阶段审核会重置为待审核。不会启动盲测。")) return;
  const mutationToken = beginBlindGoldReviewMutation();
  state.blindGoldReviewSaving = true;
  state.blindGoldBusinessEditMode = false;
  state.blindGoldContentEditable = false;
  setBlindGoldReviewEditState();
  renderBlindGoldReviewSummary();
  setBlindGoldReviewFeedback("正在重新载入正式题目、知识归属和题族关系；两阶段审核将重置。", "loading");
  try {
    const response = await requestJson(`/api/admin/knowledge-classification/gold-review/sets/${encodeURIComponent(batch.id)}/items/${encodeURIComponent(item.questionId)}/reload`, {
      method: "POST",
      body: JSON.stringify({ expectedRevision: item.revision }),
    });
    if (!blindGoldReviewMutationIsCurrent(mutationToken)) return;
      updateBlindGoldReviewItem(response.item, response.summary, response.batch || response.set, response.batchMeta, { authoritative: true });
    state.blindGoldReviewResult = "";
    setBlindGoldReviewFeedback(`已重新载入正式题目 v${response.question?.version || response.item?.question?.version || 0}、知识归属与题族关系；答案/知识和题族均已重置为待审核。未采纳 AI 预测，也未启动盲测。`, "success");
  } catch (error) {
    openBlindGoldReviewAlert(`重新载入失败：${friendlyError(error)}`);
  } finally {
    state.blindGoldReviewSaving = false;
    endBlindGoldReviewMutation(mutationToken);
    renderBlindGoldReview();
  }
}

async function reloadBlindGoldFamilyCatalog() {
  const batch = state.blindGoldReviewBatch;
  const item = selectedBlindGoldReviewItem();
  const readOnly = blindGoldReviewItemIsReadOnly(item, batch);
  if (!batch || !item || readOnly || state.blindGoldReviewSaving) return;
  const bookId = String(item.question?.bookId || "");
  if (!bookId) {
    openBlindGoldReviewAlert("当前题目没有教材信息，无法重新载入题族目录。");
    return;
  }
  const mutationToken = beginBlindGoldReviewMutation();
  state.blindGoldReviewSaving = true;
  setBlindGoldReviewEditState();
  renderBlindGoldReviewSummary();
  setBlindGoldReviewFeedback("正在重新载入当前教材的正式题族目录；不会修改答案、知识或冻结快照。", "loading");
  let draftWasSynced = false;
  try {
    state.blindGoldKnowledgeStructures.delete(bookId);
    state.blindGoldFamilyCatalogs.delete(bookId);
    state.blindGoldCatalogRequests.delete(bookId);
    invalidateBlindGoldReviewCatalogCaches(bookId);
    const catalogLoaded = await ensureBlindGoldReviewCatalog(item, { quiet: true, force: true });
    if (!catalogLoaded || !blindGoldReviewMutationIsCurrent(mutationToken)) return;
    const detail = await requestJson(`/api/admin/knowledge-classification/gold-review/sets/${encodeURIComponent(batch.id)}`);
    if (!blindGoldReviewMutationIsCurrent(mutationToken)) return;
    const incomingBatch = detail.set || detail.batch;
    if (incomingBatch?.id === batch.id
      && blindGoldRevisionNumber(incomingBatch.revision) >= blindGoldRevisionNumber(batch.revision)) {
      state.blindGoldReviewBatch = incomingBatch;
      state.blindGoldReviewBatch.summary = blindGoldReviewSummaryFromItems(
        state.blindGoldReviewBatch.items,
        state.blindGoldReviewBatch.summary,
      );
    }
    state.selectedBlindGoldQuestionId = item.questionId;
    state.blindGoldFamilyCatalogReloadRequired = false;
    state.blindGoldReviewResult = "";
    renderBlindGoldReview();
    const refreshedItem = selectedBlindGoldReviewItem();
    draftWasSynced = refreshedItem
      && refreshedItem.formalFamilySync?.status === "drift"
      && !blindGoldReviewItemIsReadOnly(refreshedItem, state.blindGoldReviewBatch)
      ? applyBlindGoldFormalFamilySyncToDraft()
      : false;
    setBlindGoldReviewFeedback(draftWasSynced
      ? "已重新载入当前教材的正式题族目录，并将当前正式关系临时填入本题待审草稿；未自动保存或确认。请核对成员归属与贡献知识后提交。"
      : "已重新载入当前教材的正式题族目录，并重新读取本题状态。答案与知识审核保持不变；请重新核对题族裁决后保存。", "success");
  } catch (error) {
    state.blindGoldFamilyCatalogReloadRequired = true;
    openBlindGoldReviewAlert(`重新载入题族目录失败：${friendlyError(error)}`);
  } finally {
    state.blindGoldReviewSaving = false;
    endBlindGoldReviewMutation(mutationToken);
    renderBlindGoldReview();
    // The final repaint rebuilds selectors from the historical audit draft.
    // Re-apply the temporary live relation after that repaint so a successful
    // catalog reload cannot appear to succeed while the next submission still
    // carries stale family IDs. This remains a local form change; it does not
    // save or confirm the family review.
    if (draftWasSynced) {
      const currentItem = selectedBlindGoldReviewItem();
      if (currentItem?.questionId === item.questionId
        && currentItem.formalFamilySync?.status === "drift"
        && !blindGoldReviewItemIsReadOnly(currentItem, state.blindGoldReviewBatch)) {
        applyBlindGoldFormalFamilySyncToDraft();
      }
    }
  }
}

function beginBlindGoldBusinessEdit() {
  const item = selectedBlindGoldReviewItem();
  if (!item || blindGoldReviewItemIsReadOnly(item) || state.blindGoldReviewSaving) return;
  if (["question_drift", "knowledge_drift"].includes(item.businessSync?.status)) {
    openBlindGoldReviewAlert("当前金标草稿已落后于正式数据，请先重新载入正式数据。");
    return;
  }
  state.blindGoldContentEditable = false;
  state.blindGoldBusinessEditMode = true;
  state.blindGoldReviewResult = "";
  document.querySelector("#blind-gold-review-result").value = "";
  document.querySelector("#blind-gold-business-note").value = "";
  setBlindGoldReviewFeedback(`正在修正正式题目 v${item.question?.version || 0}。只有点击“同步并创建新版本”才会写入；不会只修改金标草稿。`, "loading");
  setBlindGoldReviewEditState();
  document.querySelector("#blind-gold-correct-answer").focus();
}

function beginBlindGoldContentEdit() {
  const item = selectedBlindGoldReviewItem();
  if (!item || !blindGoldReviewStageIsComplete(item.contentReview) || blindGoldReviewItemIsReadOnly(item)
    || state.blindGoldReviewSaving || state.blindGoldBusinessEditMode) return;
  if (["question_drift", "knowledge_drift"].includes(item.businessSync?.status)) {
    openBlindGoldReviewAlert("当前金标草稿已落后于正式数据，请先重新载入正式数据。");
    return;
  }
  state.blindGoldContentEditable = true;
  state.blindGoldReviewResult = "corrected";
  document.querySelector("#blind-gold-review-result").value = "corrected";
  document.querySelector("#blind-gold-review-note").value = "";
  document.querySelector("#blind-gold-review-note").placeholder = "说明本次人工金标修订了哪些证据、选项知识或得分点";
  setBlindGoldReviewFeedback("正在对照 AI 结果修订阶段 1。结果固定为“人工修正”，请填写本次修订理由；保存后题族阶段将重新进入待审核。", "loading");
  setBlindGoldReviewEditState();
}

function cancelBlindGoldBusinessEdit() {
  if (!state.blindGoldBusinessEditMode || state.blindGoldReviewSaving) return;
  state.blindGoldBusinessEditMode = false;
  state.blindGoldContentEditable = false;
  state.blindGoldReviewResult = blindGoldReviewPreferredResult(selectedBlindGoldReviewItem());
  setBlindGoldReviewFeedback("已取消业务修正，正式题目与金标审核草稿均未改变。", "success");
  renderBlindGoldReviewDetail();
}

function addBlindGoldEvidenceRow() {
  if (!state.blindGoldBusinessEditMode || state.blindGoldReviewSaving) return;
  const container = document.querySelector("#blind-gold-textbook-evidence");
  const rows = container.querySelectorAll("[data-blind-gold-evidence-row]");
  if (rows.length >= 12) {
    openBlindGoldReviewAlert("单题最多保留 12 条教材证据。");
    return;
  }
  if (!rows.length) container.innerHTML = "";
  const index = Math.max(-1, ...[...rows].map((row) => Number(row.dataset.blindGoldEvidenceIndex) || 0)) + 1;
  container.insertAdjacentHTML("beforeend", blindGoldEvidenceRowHtml({
    bookId: selectedBlindGoldReviewItem()?.question?.bookId || "",
    chunkId: `human-evidence-${Date.now()}-${index}`,
    provenance: "human_business_correction",
    humanSelection: { status: "selected" },
  }, index));
  setBlindGoldReviewEditState();
  container.querySelector(`[data-blind-gold-evidence-index="${index}"] [data-blind-gold-evidence-path]`)?.focus();
}

function addBlindGoldScoringPoint() {
  const item = selectedBlindGoldReviewItem();
  if (!item || (item.question?.options || []).length || state.blindGoldReviewSaving
    || (!state.blindGoldContentEditable && !state.blindGoldBusinessEditMode)) return;
  const container = document.querySelector("#blind-gold-answer-knowledge");
  const rows = [...container.querySelectorAll("[data-blind-gold-scoring-point]")];
  if (rows.length >= 100) {
    openBlindGoldReviewAlert("单题最多保留 100 个得分点。");
    return;
  }
  if (!rows.length) container.innerHTML = "";
  const index = Math.max(-1, ...rows.map((row) => Number(row.dataset.blindGoldScoringPoint) || 0)) + 1;
  container.insertAdjacentHTML("beforeend", blindGoldScoringPointRowHtml({}, index, blindGoldReviewKnowledgeNodes(item)));
  initializeBlindGoldKnowledgePickers();
  if (state.blindGoldContentEditable) markBlindGoldContentChanged();
  else setBlindGoldReviewEditState();
  container.querySelector(`[data-blind-gold-scoring-point="${index}"] [data-blind-gold-scoring-description]`)?.focus();
}

function removeBlindGoldScoringPoint(button) {
  if ((!state.blindGoldContentEditable && !state.blindGoldBusinessEditMode) || state.blindGoldReviewSaving) return;
  button.closest("[data-blind-gold-scoring-point]")?.remove();
  markBlindGoldContentChanged();
}

function markBlindGoldContentChanged() {
  const item = selectedBlindGoldReviewItem();
  if (!item || !state.blindGoldContentEditable || state.blindGoldBusinessEditMode) return;
  const revisingCompletedContent = blindGoldReviewStageIsComplete(item.contentReview);
  if (revisingCompletedContent) {
    state.blindGoldReviewResult = "corrected";
    document.querySelector("#blind-gold-review-result").value = "corrected";
  }
  document.querySelector("#blind-gold-review-note").placeholder = revisingCompletedContent
    ? "说明本次人工金标修订了哪些证据、选项知识或得分点"
    : "可记录人工选择或调整证据、选项知识、得分点的依据";
  setBlindGoldReviewEditState();
}

async function syncBlindGoldBusinessContent() {
  const batch = state.blindGoldReviewBatch;
  const item = selectedBlindGoldReviewItem();
  if (!batch || !item || !state.blindGoldBusinessEditMode || state.blindGoldReviewSaving || blindGoldReviewItemIsReadOnly(item, batch)) return;
  const note = document.querySelector("#blind-gold-business-note").value.trim();
  if (!note) {
    openBlindGoldReviewAlert("同步正式题目前，请填写业务修正说明。");
    document.querySelector("#blind-gold-business-note").focus();
    return;
  }
  const answerKnowledge = blindGoldReviewCollectAnswerKnowledge(item);
  if (!answerKnowledge.referenceAnswer && !answerKnowledge.correctAnswer.length) {
    openBlindGoldReviewAlert("请先填写正确答案或来源答案。");
    return;
  }
  if (!answerKnowledge.textbookEvidence.length) {
    openBlindGoldReviewAlert("同步业务修正前，请至少保留或补充一份教材证据。");
    return;
  }
  if (!answerKnowledge.coreKnowledge.id || !answerKnowledge.requiredKnowledge.length
    || answerKnowledge.requiredKnowledge.some((node) => !node.id)) {
    openBlindGoldReviewAlert(friendlyError("classification_gold_review_knowledge_assignment_invalid"));
    return;
  }
  const previousVersion = Number(item.question?.version) || 0;
  const selectedEvidenceChunkIds = answerKnowledge.textbookEvidence.map((evidence) => evidence.chunkId).filter(Boolean);
  const mutationToken = beginBlindGoldReviewMutation();
  state.blindGoldReviewSaving = true;
  setBlindGoldReviewEditState();
  renderBlindGoldReviewSummary();
  setBlindGoldReviewFeedback(`正在把答案、教材证据与知识同步到正式题目 v${previousVersion + 1}；题族审核将在成功后清空。`, "loading");
  try {
    const response = await requestJson(`/api/admin/knowledge-classification/gold-review/sets/${encodeURIComponent(batch.id)}/items/${encodeURIComponent(item.questionId)}/business-content`, {
      method: "PUT",
      body: JSON.stringify({
        expectedRevision: item.revision,
        expectedQuestionVersion: previousVersion,
        result: "corrected",
        note,
        answerKnowledge,
        selectedEvidenceChunkIds,
        questionPatch: {
          correctAnswer: answerKnowledge.correctAnswer,
          referenceAnswer: answerKnowledge.referenceAnswer,
          scoringPoints: answerKnowledge.scoringPoints,
          answerSource: answerKnowledge.answerSource,
          answerReviewStatus: answerKnowledge.answerReviewStatus || "verified",
          answerVerified: (answerKnowledge.answerReviewStatus || "verified") === "verified",
        },
        knowledgeAssignment: {
          primaryNodeId: answerKnowledge.coreKnowledge.id,
          primaryNodeRole: answerKnowledge.coreKnowledgeRole,
          requiredNodeIds: answerKnowledge.requiredKnowledge.map((node) => node.id),
          focus: answerKnowledge.coreKnowledge.title || answerKnowledge.coreKnowledge.path || "",
          evidenceChunkIds: selectedEvidenceChunkIds,
        },
        answerKnowledgeProvenance: {
          ...(item.answerKnowledgeProvenance || {}),
          reviewEvidenceNote: document.querySelector("#blind-gold-evidence-note").value.trim(),
          reviewedIn: "blind_gold_business_sync_ui",
        },
      }),
    });
    if (!blindGoldReviewMutationIsCurrent(mutationToken)) return;
    updateBlindGoldReviewItem(response.item, response.summary, response.batch || response.set, response.batchMeta, { authoritative: true });
    state.blindGoldBusinessEditMode = false;
    state.blindGoldContentEditable = false;
    state.blindGoldReviewResult = "";
    renderBlindGoldReview();
    const nextVersion = Number(response.question?.version || response.item?.question?.version) || previousVersion + 1;
    setBlindGoldReviewFeedback(`正式题目已由 v${previousVersion} 更新为 v${nextVersion}，答案、证据与知识已同步；旧题族审核已失效，请现在独立审核题族裁决。未采纳 AI 预测，也未启动盲测。`, "success");
  } catch (error) {
    openBlindGoldReviewAlert(`正式题目同步失败：${friendlyError(error)}。本次没有写入半套数据，请刷新后核对。`);
  } finally {
    state.blindGoldReviewSaving = false;
    endBlindGoldReviewMutation(mutationToken);
    renderBlindGoldReview();
  }
}

function setBlindGoldReviewResult(result) {
  if (!Object.prototype.hasOwnProperty.call(blindGoldReviewResultLabels, result) || result === "pending_review") return;
  const item = selectedBlindGoldReviewItem();
  if (!item || blindGoldReviewItemIsReadOnly(item)) return;
  if (blindGoldReviewStageIsComplete(item?.contentReview) && state.blindGoldContentEditable) result = "corrected";
  state.blindGoldReviewResult = result;
  document.querySelector("#blind-gold-review-result").value = result;
  if (result === "corrected" && !document.querySelector("#blind-gold-review-note").value.trim()) {
    document.querySelector("#blind-gold-review-note").placeholder = "说明修正了什么，以及依据是什么";
  } else if (result === "disputed") {
    document.querySelector("#blind-gold-review-note").placeholder = "说明争议点与仍需补充的教材依据";
  }
  setBlindGoldReviewEditState();
}

function updateBlindGoldReviewItem(item, summary, batchSnapshot = null, batchMetaSnapshot = null, options = {}) {
  const batch = state.blindGoldReviewBatch;
  if (!batch || !item) return false;
  // A successful mutation makes the server response authoritative; discard
  // the unsaved live-family alignment before replacing the item snapshot.
  clearBlindGoldFormalFamilyDraftOverride(item);
  const index = batch.items.findIndex((entry) => entry.questionId === item.questionId);
  const existing = index >= 0 ? batch.items[index] : null;
  // A mutation response is authoritative for the item just saved.  The
  // revision/updatedAt guards are still needed for background GET snapshots,
  // but applying them to a successful PUT/POST response can leave the form
  // displaying the pre-save object until the user refreshes the page.
  const authoritative = options?.authoritative === true;
  const incomingItemRevision = blindGoldRevisionNumber(item.revision);
  const existingItemRevision = blindGoldRevisionNumber(existing?.revision);
  if (!authoritative) {
    if (existing && incomingItemRevision < existingItemRevision) return false;
    if (existing && incomingItemRevision === existingItemRevision
      && Number(item.updatedAt || 0) > 0 && Number(existing.updatedAt || 0) > 0
      && Number(item.updatedAt) < Number(existing.updatedAt)) return false;
  }
  clearBlindGoldFamilyContributionDrafts(item.questionId);
  if (index >= 0) batch.items.splice(index, 1, item);
  else batch.items.push(item);
  invalidateBlindGoldReviewCatalogCaches(item.question?.bookId || "");
  const effectiveBatchMeta = batchMetaSnapshot
    || (batchSnapshot?.id && !Array.isArray(batchSnapshot.items) ? batchSnapshot : null);
  mergeBlindGoldReviewBatchMeta(batch, effectiveBatchMeta);
  batch.summary = blindGoldReviewSummaryFromItems(batch.items, summary || batch.summary || {});
  const setIndex = state.blindGoldReviewSets.findIndex((entry) => entry.id === batch.id);
  if (setIndex >= 0) {
    const currentSet = state.blindGoldReviewSets[setIndex];
    const snapshotRevision = batchSnapshot?.id === batch.id
      ? blindGoldRevisionNumber(batchSnapshot.revision)
      : blindGoldRevisionNumber(currentSet.revision);
    if (batchSnapshot?.id === batch.id && snapshotRevision >= blindGoldRevisionNumber(batch.revision)) {
      // 只合并批次元数据；批次快照中的 items 可能来自保存前的 GET，不能覆盖刚更新的单题。
      Object.assign(batch, { ...batchSnapshot, items: batch.items });
      // The snapshot may carry a summary calculated before the mutation.
      // Recompute it after the merge so the list never rolls back to "待审核".
      batch.summary = blindGoldReviewSummaryFromItems(batch.items, batch.summary || {});
    }
    state.blindGoldReviewSets.splice(setIndex, 1, {
      ...currentSet,
      ...(batchSnapshot?.id === batch.id && snapshotRevision >= blindGoldRevisionNumber(currentSet.revision)
        ? { revision: snapshotRevision, updatedAt: batchSnapshot.updatedAt }
        : {}),
      ...(effectiveBatchMeta?.id === batch.id
        && blindGoldRevisionNumber(effectiveBatchMeta.revision) >= blindGoldRevisionNumber(currentSet.revision)
        ? {
          revision: blindGoldRevisionNumber(effectiveBatchMeta.revision),
          updatedAt: Math.max(Number(currentSet.updatedAt) || 0, Number(effectiveBatchMeta.updatedAt) || 0),
        }
        : {}),
      summary: batch.summary,
      updatedAt: Math.max(
        Number(currentSet.updatedAt) || 0,
        Number(item.updatedAt) || 0,
        Number(effectiveBatchMeta?.updatedAt) || 0,
      ),
    });
  }
  return true;
}

function renderBlindGoldReviewEmpty(message) {
  state.blindGoldReviewBatch = null;
  state.selectedBlindGoldQuestionId = "";
  clearBlindGoldFormalFamilyDraftOverride();
  invalidateBlindGoldReviewCatalogCaches();
  clearBlindGoldFamilyContributionDrafts();
  state.blindGoldBusinessEditMode = false;
  state.blindGoldContentEditable = false;
  renderBlindGoldReview();
  document.querySelector("#blind-gold-review-list").innerHTML = `<div class="blind-gold-review-empty">${escapeHtml(message)}</div>`;
}

async function ensureBlindGoldReviewCatalog(item = selectedBlindGoldReviewItem(), options = {}) {
  const bookId = item?.question?.bookId || "";
  if (!bookId) return false;
  const force = options.force === true;
  if (force) {
    // Do not expose the previous book catalog while the authoritative
    // directory is being re-read after a formal-family change.
    state.blindGoldKnowledgeStructures.delete(bookId);
    state.blindGoldFamilyCatalogs.delete(bookId);
    invalidateBlindGoldReviewCatalogCaches(bookId);
  }
  if (!force && state.blindGoldKnowledgeStructures.has(bookId) && state.blindGoldFamilyCatalogs.has(bookId)) return true;
  let request = state.blindGoldCatalogRequests.get(bookId);
  if (!request || force) {
    request = Promise.all([
      requestJson(`/api/admin/knowledge-structure?bookId=${encodeURIComponent(bookId)}&generate=true`),
      requestJson(`/api/admin/question-family-options?bookId=${encodeURIComponent(bookId)}`),
    ]).then(([structurePayload, familyPayload]) => {
      // A forced refresh may supersede an older request.  Do not let the
      // older response put stale catalog data back into the shared cache.
      if (state.blindGoldCatalogRequests.get(bookId) !== request) return false;
      state.blindGoldKnowledgeStructures.set(bookId, structurePayload.structure);
      state.blindGoldFamilyCatalogs.set(bookId, familyPayload.families || []);
      invalidateBlindGoldReviewCatalogCaches(bookId);
      return true;
    }).finally(() => {
      if (state.blindGoldCatalogRequests.get(bookId) === request) {
        state.blindGoldCatalogRequests.delete(bookId);
      }
    });
    state.blindGoldCatalogRequests.set(bookId, request);
  }
  if (!options.quiet) setBlindGoldReviewFeedback(`正在读取《${questionBookName(bookId)}》的完整知识树与正式题族目录…`, "loading");
  try {
    const catalogLoaded = await request;
    // A forced refresh can supersede an older request.  The superseded
    // request returns false and must not repaint the current review with a
    // stale/partial catalog or announce a misleading success message.
    if (!catalogLoaded) return false;
    if (selectedBlindGoldReviewItem()?.question?.bookId === bookId) {
      renderBlindGoldReviewDetail();
      initializeBlindGoldKnowledgePickers();
    }
    if (!options.quiet) setBlindGoldReviewFeedback(`已载入《${questionBookName(bookId)}》完整知识树与正式题族目录，可改判到本批 20 题之外的节点和题族。`, "success");
    return true;
  } catch (error) {
    openBlindGoldReviewAlert(`完整教材目录读取失败：${friendlyError(error)}。当前仅展示本批预填项，请勿在目录不完整时提交人工修正。`);
    return false;
  }
}

// 「重新校验」：跑一次覆盖门禁预检，并把未通过的题目重新开放题族审核。
// 该动作只会增加人工复核，不确认任何结论、不采纳 AI 预测、不改写金标事实。
async function verifyBlindGoldPreflight() {
  const batch = state.blindGoldReviewBatch;
  if (!batch || batch.status === "frozen" || state.blindGoldReviewSaving) return;
  state.blindGoldReviewSaving = true;
  renderBlindGoldReviewSummary();
  setBlindGoldReviewFeedback("正在按覆盖门禁重新校验整批金标；不会确认或采纳任何结论。", "loading");
  try {
    await refreshBlindGoldPreflight({ quiet: true });
    const blocked = blindGoldPreflightBlockedQuestionIds();
    if (!blocked.length) {
      renderBlindGoldReview();
      setBlindGoldReviewFeedback(`已重新校验：整批 ${(batch.items || []).length} 题通过覆盖门禁预检。`, "success");
      return;
    }
    const response = await requestJson(
      `/api/admin/knowledge-classification/gold-review/sets/${encodeURIComponent(batch.id)}/family-reviews/sync-preflight`,
      {
        method: "POST",
        body: JSON.stringify({
          questionIds: blocked,
          reason: "覆盖门禁预检未通过，重新开放本题题族审核。",
        }),
      },
    );
    state.blindGoldReviewBatch = response.batch || batch;
    state.blindGoldReviewBatch.summary = response.summary || state.blindGoldReviewBatch.summary;
    await refreshBlindGoldPreflight({ quiet: true });
    renderBlindGoldReview();
    setBlindGoldReviewFeedback(
      `已重新校验：${blocked.length} 题未通过覆盖门禁，已重新开放题族审核。请逐题修正题族覆盖知识或本题最小充分知识集；本轮没有确认任何结论，也没有采纳 AI 预测。`,
      "error",
    );
  } catch (error) {
    openBlindGoldReviewAlert(`重新校验失败：${friendlyError(error)}`);
  } finally {
    state.blindGoldReviewSaving = false;
    renderBlindGoldReviewSummary();
  }
}

async function loadBlindGoldReviewSets(options = {}) {
  const loadSequence = Number(state.blindGoldReviewLoadSequence || 0) + 1;
  state.blindGoldReviewLoadSequence = loadSequence;
  const mutationSequence = Number(state.blindGoldReviewMutationSequence || 0);
  const isCurrentLoad = () => loadSequence === Number(state.blindGoldReviewLoadSequence || 0)
    && mutationSequence === Number(state.blindGoldReviewMutationSequence || 0)
    && !state.blindGoldReviewSaving;
  if (!options.quiet) {
    state.blindGoldBusinessEditMode = false;
    state.blindGoldContentEditable = false;
  }
  // A batch reload rehydrates the persisted audit draft. Any live-family
  // alignment from the previous view must be discarded and rebuilt explicitly
  // after the fresh catalog has loaded.
  clearBlindGoldFormalFamilyDraftOverride();
  if (!options.quiet) setBlindGoldReviewFeedback("正在读取盲测金标审核批次…", "loading");
  try {
    // Rebuild the in-memory map from the persisted session draft after the
    // authoritative batch snapshot arrives; do not erase it on page refresh.
    clearBlindGoldFamilyContributionDrafts("", { persist: false });
    const payload = await requestJson("/api/admin/knowledge-classification/gold-review/sets");
    if (!isCurrentLoad()) return false;
    const incomingSets = payload.sets || payload.items || [];
    const currentSetById = new Map((state.blindGoldReviewSets || []).map((entry) => [entry.id, entry]));
    state.blindGoldReviewSets = incomingSets.map((entry) => {
      const current = currentSetById.get(entry.id);
      return current && (blindGoldRevisionNumber(current.revision) > blindGoldRevisionNumber(entry.revision)
        || (blindGoldRevisionNumber(current.revision) === blindGoldRevisionNumber(entry.revision)
          && Number(current.updatedAt || 0) > Number(entry.updatedAt || 0)))
        ? current
        : entry;
    });
    if (!state.blindGoldReviewSets.length) {
      renderBlindGoldReviewEmpty("本批 20 道题尚未导入金标审核区");
      openBlindGoldReviewAlert("本批 20 道题尚未导入，当前没有启动或采纳任何盲测结果。");
      return false;
    }
    const preferred = state.blindGoldReviewSets.find((set) => set.id === state.blindGoldReviewBatchId)
      || state.blindGoldReviewSets.find((set) => set.status !== "frozen")
      || state.blindGoldReviewSets[0];
    state.blindGoldReviewBatchId = preferred.id;
    const detail = await requestJson(`/api/admin/knowledge-classification/gold-review/sets/${encodeURIComponent(preferred.id)}`);
    if (!isCurrentLoad()) return false;
    const incomingBatch = detail.set || detail.batch;
    const currentBatch = state.blindGoldReviewBatch;
    if (currentBatch && incomingBatch?.id === currentBatch.id
      && blindGoldRevisionNumber(incomingBatch.revision) < blindGoldRevisionNumber(currentBatch.revision)) return false;
    state.blindGoldReviewBatch = mergeBlindGoldReviewBatchSnapshot(currentBatch, incomingBatch);
    restoreBlindGoldFamilyContributionDrafts(state.blindGoldReviewBatch);
    invalidateBlindGoldReviewCatalogCaches();
    if (state.blindGoldReviewBatch) {
      state.blindGoldReviewBatch.summary = blindGoldReviewSummaryFromItems(
        state.blindGoldReviewBatch.items,
        state.blindGoldReviewBatch.summary,
      );
    }
    const items = state.blindGoldReviewBatch?.items || [];
    if (!items.some((item) => item.questionId === state.selectedBlindGoldQuestionId)) {
      state.selectedBlindGoldQuestionId = items[0]?.questionId || "";
    }
    // 批次状态就绪后立即跑一次覆盖门禁预检：阻断必须在刷新时就可见，
    // 而不是等 20 题全部审完、点冻结时才第一次出现。
    await refreshBlindGoldPreflight({ quiet: true });
    if (!isCurrentLoad()) return false;
    renderBlindGoldReview();
    // renderBlindGoldReviewDetail starts the catalog request when this is a
    // fresh page load. Reuse that in-flight request instead of forcing a
    // second full textbook/family scan. When a catalog is already cached,
    // force a fresh read so an in-session batch switch cannot reuse stale
    // formal-family facts.
    const catalogItem = selectedBlindGoldReviewItem();
    const catalogBookId = String(catalogItem?.question?.bookId || "");
    const catalogAlreadyCached = Boolean(catalogBookId
      && state.blindGoldKnowledgeStructures.has(catalogBookId)
      && state.blindGoldFamilyCatalogs.has(catalogBookId));
    const catalogReady = await ensureBlindGoldReviewCatalog(catalogItem, {
      quiet: true,
      force: catalogAlreadyCached && !state.blindGoldCatalogRequests.has(catalogBookId),
    });
    if (!isCurrentLoad()) return false;
    // A normal page refresh rehydrates the historical draft before the live
    // family catalog arrives.  When the formal relation has changed, keep the
    // audit snapshot intact but temporarily align the editable selectors with
    // the current formal relation so the next save does not resubmit stale ids.
    // This is intentionally a local form update; no review decision is saved
    // and no formal family membership is changed here.
    let draftWasSynced = false;
    const refreshedItem = selectedBlindGoldReviewItem();
    if (catalogReady && refreshedItem
      && refreshedItem.formalFamilySync?.status === "drift"
      && !blindGoldReviewItemIsReadOnly(refreshedItem, state.blindGoldReviewBatch)) {
      draftWasSynced = applyBlindGoldFormalFamilySyncToDraft();
    }
    if (!options.quiet) {
      if (!catalogReady && state.blindGoldReviewBatch.status !== "frozen") return true;
      setBlindGoldReviewFeedback(state.blindGoldReviewBatch.status === "frozen"
        ? "不可变金标快照已生成；下方仅展示审核汇总与哈希，本页没有启动盲测。"
        : (draftWasSynced
          ? `已载入 ${items.length} 道题，并将当前正式题族关系临时填入本题待审草稿；未自动保存或确认，请核对后提交。`
          : `已载入 ${items.length} 道题，请先审核答案与知识，再审核题族裁决。`), "success");
    }
    return true;
  } catch (error) {
    if (!isCurrentLoad()) return false;
    renderBlindGoldReviewEmpty(`读取失败：${friendlyError(error)}`);
    openBlindGoldReviewAlert(`读取失败：${friendlyError(error)}`);
    return false;
  }
}

// 盲测层级类错误的服务端 details 里有「原层级 → 本次提交层级」和可读标签，
// 之前只显示英文错误码，审核员看不出是哪一项不一致。
const blindGoldReplayModeErrorCodes = new Set([
  "classification_gold_review_replay_mode_invalid",
  "classification_gold_review_replay_mode_conflict",
  "classification_gold_review_replay_mode_locked",
  "classification_gold_review_replay_mode_correction_required",
  "classification_gold_review_replay_mode_change_reason_required",
]);

function blindGoldReplayModeErrorText(error) {
  const code = String(error?.message || error?.payload?.error || "");
  if (!blindGoldReplayModeErrorCodes.has(code)) return "";
  const details = error?.details || error?.payload?.details || {};
  const label = String(details.label || "").trim();
  const labelOf = (mode) => blindGoldReviewModeLabels[mode] || "";
  const previous = labelOf(details.previousReplayMode);
  const requested = labelOf(details.requestedReplayMode);
  let text = label || "盲测层级修改失败";
  if (previous && requested && previous !== requested) {
    text += `。本题原层级为“${previous}”，本次提交为“${requested}”`;
  } else if (requested) {
    text += `。本次提交层级为“${requested}”`;
  }
  if (details.sourceModeLabel) text += `（父快照层级：${details.sourceModeLabel}）`;
  return `${text}。`;
}

function blindGoldSaveFailureMessage(error, fallbackMessage) {
  const replayModeText = blindGoldReplayModeErrorText(error);
  if (replayModeText) {
    return `${replayModeText}请把审核结果改为“人工修正”并填写改判依据后重新提交；若认为层级不应变化，请把“最终盲测层级”恢复为原层级。`;
  }
  return fallbackMessage;
}

async function saveBlindGoldReview(event) {
  event.preventDefault();
  const advanceAfterSave = event.submitter?.id === "save-and-next-blind-gold-review";
  const batch = state.blindGoldReviewBatch;
  const item = selectedBlindGoldReviewItem();
  if (!batch || !item || blindGoldReviewItemIsReadOnly(item, batch) || state.blindGoldReviewSaving) return;
  if (state.blindGoldBusinessEditMode) {
    openBlindGoldReviewAlert("请先同步正式题目并形成新版本，或取消本次业务修正。", {
      copy: "业务修正尚未写入正式题目，本题还不能提交审核",
    });
    return;
  }
  const contentComplete = blindGoldReviewStageIsComplete(item.contentReview);
  const revisingCompletedContent = contentComplete && state.blindGoldContentEditable;
  const reviewingContent = !contentComplete || state.blindGoldContentEditable;
  const uiResult = revisingCompletedContent ? "corrected" : state.blindGoldReviewResult;
  const result = blindGoldReviewApiResult(uiResult);
  const note = document.querySelector("#blind-gold-review-note").value.trim();
  if (!uiResult) {
    openBlindGoldReviewAlert("请先选择本题的审核结果。", {
      copy: "阶段裁决还没有选择“确认现有值 / 人工修正 / 存在争议”",
    });
    return;
  }
  if (["corrected", "disputed"].includes(result) && !note) {
    openBlindGoldReviewAlert(friendlyError("classification_gold_review_note_required"), {
      copy: "本题裁决为“人工修正”或“存在争议”，需要留下人工判断依据",
    });
    return;
  }
  let familyGold = null;
  if (!reviewingContent) {
    // Do one last local reconciliation before serializing the family payload.
    // This covers a submit that races the catalog-refresh repaint and keeps
    // removed historical relations from reaching the formal-fact guard.
    if (blindGoldFormalFamilyDraftNeedsLiveReconciliation(item)) {
      applyBlindGoldFormalFamilySyncToDraft();
    }
    familyGold = blindGoldReviewCollectFamilyGold(item);
    const historicalFamilyIds = blindGoldReviewSelectedHistoricalFamilyIds(item);
    if (historicalFamilyIds.length && result !== "disputed") {
      const historicalNames = historicalFamilyIds.map((id) => blindGoldReviewFamilyName(id, item)).join("、");
      openBlindGoldReviewAlert(`当前裁决仍引用历史题族“${historicalNames}”。该题族已不在正式目录，不能作为非争议金标提交；请选择当前正式题族，或标记“存在争议”。`, {
        copy: "正式题族目录已变化，请先重新载入题族目录再裁决",
      });
      return;
    }
    if (familyGold.decision === "join_existing" && !familyGold.primaryFamilyId) {
      openBlindGoldReviewAlert(friendlyError("classification_gold_review_primary_family_required"));
      return;
    }
    if (familyGold.decision === "create_new") {
      const candidate = familyGold.candidateFamily || {};
      const missing = [
        !candidate.name && "名称",
        !candidate.focusKey && "题族判别焦点",
        !(candidate.scopeAnchor?.id || candidate.coreKnowledge?.id || candidate.coreKnowledge?.path) && "后台目录锚点",
        !(candidate.coverageKnowledge || candidate.requiredKnowledge || []).length && "覆盖知识",
        !(candidate.textbookAnchors || []).length && "教材锚点",
        !candidate.assessmentAction && "考查动作",
      ].filter(Boolean);
      if (missing.length) {
        openBlindGoldReviewAlert(`${friendlyError("classification_gold_review_candidate_family_fields_required")}。当前缺少：${missing.join("、")}；请选择“人工修正”补齐。`, {
          copy: "新题族草稿尚未达到可提交的完整度，缺少项已在下面列出",
        });
        return;
      }
    }
    const formalPreflightIssues = blindGoldFormalFamilyPreflightIssues(item, familyGold, result);
    if (formalPreflightIssues.length) {
      setBlindGoldReviewSemanticFeedback({ details: { issues: formalPreflightIssues } }, item);
      return;
    }
  }
  const mutationToken = beginBlindGoldReviewMutation();
  state.blindGoldReviewSaving = true;
  let saveFailed = false;
  setBlindGoldReviewEditState();
  renderBlindGoldReviewSummary();
  try {
    if (reviewingContent) {
      const answerKnowledge = blindGoldReviewCollectAnswerKnowledge(item);
      if (result !== "disputed" && !answerKnowledge.textbookEvidence.length) {
        throw new Error("classification_gold_review_human_evidence_required");
      }
      if (result !== "disputed" && answerKnowledge.textbookEvidence.some((evidence) => !evidence.chunkId)) {
        throw new Error("classification_gold_review_human_evidence_selection_invalid");
      }
      if (result !== "disputed" && (!answerKnowledge.coreKnowledge.id || !answerKnowledge.requiredKnowledge.length
        || answerKnowledge.requiredKnowledge.some((node) => !node.id))) {
        throw new Error("classification_gold_review_human_knowledge_required");
      }
      if (result !== "disputed") {
        const resolvedRelations = new Set(["question_only", "option_specific", "undetermined"]);
        const choiceStructure = answerKnowledge.choiceStructure || "direct_options";
        if (choiceStructure === "composed_options") {
          const atomicStatements = Array.isArray(answerKnowledge.atomicStatements) ? answerKnowledge.atomicStatements : [];
          const incompleteAtomicStatement = !atomicStatements.length || atomicStatements.some((reviewed) => {
            const relation = reviewed?.knowledgeRelation;
            return !reviewed?.key || !reviewed?.text || !String(reviewed.basis || "").trim() || !resolvedRelations.has(relation)
              || (relation === "option_specific"
                && !(reviewed.knowledgeNodeIds || []).length && !(reviewed.knowledgeLabels || []).length)
              || (relation === "undetermined" && !String(reviewed.uncertaintyNote || "").trim());
          });
          if (incompleteAtomicStatement) {
            throw new Error("classification_gold_review_human_atomic_statements_required");
          }
          const atomicKeys = new Set(atomicStatements.map((statement) => String(statement.key || "").trim()).filter(Boolean));
          const optionComposition = Array.isArray(answerKnowledge.optionComposition) ? answerKnowledge.optionComposition : [];
          const optionCompositionByKey = new Map(optionComposition.map((entry) => [String(entry.optionKey || "").toUpperCase(), entry]));
          const questionOptions = item.question?.options || [];
          const invalidComposition = atomicKeys.size !== atomicStatements.length || !questionOptions.length
            || questionOptions.some((option) => {
              const mapping = optionCompositionByKey.get(String(option.key || "").toUpperCase());
              const refs = mapping?.atomicKeys || [];
              return !mapping || !refs.length || refs.some((ref) => !atomicKeys.has(String(ref).trim()));
            });
          if (invalidComposition) {
            throw new Error("classification_gold_review_human_option_composition_required");
          }
        } else if ((item.question?.options || []).length) {
          const optionKnowledgeByKey = new Map(answerKnowledge.optionKnowledge.map((option) => [option.key, option]));
          const incompleteOption = item.question.options.some((option) => {
            const reviewed = optionKnowledgeByKey.get(option.key);
            const relation = reviewed?.knowledgeRelation;
            return !reviewed || reviewed.role === "unreviewed" || !resolvedRelations.has(relation)
              || (relation === "option_specific"
                && !(reviewed.knowledgeNodeIds || []).length && !(reviewed.knowledgeLabels || []).length)
              || (relation === "undetermined" && !String(reviewed.uncertaintyNote || "").trim());
          });
          if (incompleteOption) throw new Error("classification_gold_review_human_option_knowledge_required");
        } else if (blindGoldQuestionRequiresScoringPoints(item.question)
          && !answerKnowledge.scoringPoints.some((point) => point.description && Number(point.score) > 0)) {
          throw new Error("classification_gold_review_human_scoring_points_required");
        }
      }
      const selectedEvidenceChunkIds = answerKnowledge.textbookEvidence.map((evidence) => evidence.chunkId).filter(Boolean);
      setBlindGoldReviewFeedback("正在保存第 1 阶段：答案、教材证据与知识。完成后仍需单独审核题族。", "loading");
      const contentResponse = await requestJson(`/api/admin/knowledge-classification/gold-review/sets/${encodeURIComponent(batch.id)}/items/${encodeURIComponent(item.questionId)}/content`, {
        method: "PUT",
        body: JSON.stringify({
          expectedRevision: item.revision,
          result,
          note,
          answerKnowledge,
          selectedEvidenceChunkIds,
          answerKnowledgeProvenance: {
            ...(item.answerKnowledgeProvenance || {}),
            reviewEvidenceNote: document.querySelector("#blind-gold-evidence-note").value.trim(),
            reviewedIn: "blind_gold_review_ui",
          },
        }),
      });
      if (!blindGoldReviewMutationIsCurrent(mutationToken)) return;
      updateBlindGoldReviewItem(contentResponse.item, contentResponse.summary, contentResponse.batch || contentResponse.set, contentResponse.batchMeta, { authoritative: true });
      state.blindGoldContentEditable = false;
      state.blindGoldReviewResult = "";
      setBlindGoldReviewFeedback(`第 1 阶段已保存为“${blindGoldReviewResultLabels[uiResult]}”。题族仍是待审核状态，请核对题族六维定义后再单独提交；没有启动盲测。`, "success");
      return;
    }
    setBlindGoldReviewFeedback("正在保存第 2 阶段：题族裁决。答案、证据与知识不会被重复写入。", "loading");
    const familyResponse = await requestJson(`/api/admin/knowledge-classification/gold-review/sets/${encodeURIComponent(batch.id)}/items/${encodeURIComponent(item.questionId)}/family`, {
      method: "PUT",
      body: JSON.stringify({
        expectedRevision: item.revision,
        result,
        note,
        familyGold,
        familyGoldProvenance: {
          ...(item.familyGoldProvenance || {}),
          reviewedIn: "blind_gold_review_ui",
        },
      }),
    });
    if (!blindGoldReviewMutationIsCurrent(mutationToken)) return;
    updateBlindGoldReviewItem(familyResponse.item, familyResponse.summary, familyResponse.batch || familyResponse.set, familyResponse.batchMeta, { authoritative: true });
    const nextPending = advanceAfterSave ? blindGoldReviewNextPendingItem(item) : null;
    if (nextPending) {
      state.blindGoldBusinessEditMode = false;
      state.blindGoldContentEditable = false;
      state.selectedBlindGoldQuestionId = nextPending.questionId;
    }
    state.blindGoldReviewResult = "";
    setBlindGoldReviewFeedback(nextPending
      ? `本题两阶段审核已完成并保存为“${blindGoldReviewResultLabels[uiResult]}”，已进入第 ${nextPending.order} 题；没有采纳 AI 预测，也没有启动盲测。`
      : `题族审核已独立保存为“${blindGoldReviewResultLabels[uiResult]}”，本题两阶段审核完成；没有采纳 AI 预测，也没有启动盲测。`, "success");
  } catch (error) {
    saveFailed = true;
    const errorCode = String(error?.message || error?.payload?.error || "");
    if (errorCode === "classification_gold_review_family_semantic_invalid"
      && setBlindGoldReviewSemanticFeedback(error, item)) return;
    const message = error.message === "classification_gold_review_evidence_required"
      ? "确认答案与知识前，请至少保留一份教材证据；证据不足时请选择“存在争议”。"
      : friendlyError(error);
    if (errorCode === "classification_gold_review_formal_family_drift") {
      state.blindGoldFamilyCatalogReloadRequired = true;
      openBlindGoldReviewAlert(blindGoldSaveFailureMessage(error, `保存失败：${message}。请点击顶部“重新载入题族目录”，再复核并保存本题；答案与知识阶段不会被自动改写。`));
    } else {
      openBlindGoldReviewAlert(blindGoldSaveFailureMessage(error, `保存失败：${message}`));
    }
  } finally {
    state.blindGoldReviewSaving = false;
    endBlindGoldReviewMutation(mutationToken);
    // Keep the selected result and unsaved controls visible after a rejected
    // family payload so the reviewer can correct it without starting over.
    renderBlindGoldReview(saveFailed ? { preserveTransient: true } : {});
    if (advanceAfterSave && state.selectedBlindGoldQuestionId !== item?.questionId) {
      requestAnimationFrame(() => document.querySelector(".blind-gold-question-head")?.scrollIntoView({ block: "start", behavior: "smooth" }));
    }
  }
}

function renderBlindGoldFreezePreview(preparation = state.blindGoldFreezePreparation) {
  const batch = state.blindGoldReviewBatch;
  if (!batch || !preparation) return;
  const snapshotSummary = preparation.summary || {};
  const batchSummary = batch.summary || {};
  const modeLabels = { mature: "成熟题族", singleton: "单题题族", unmatched: "无匹配题" };
  const modeText = Object.entries(snapshotSummary.modes || {})
    .map(([mode, count]) => `${modeLabels[mode] || mode} ${count}`)
    .join(" · ") || "-";
  const bookText = Object.entries(snapshotSummary.books || {})
    .map(([bookId, count]) => `${questionBookName(bookId)} ${count}`)
    .join(" · ") || "-";
  const versionCounts = (batch.items || []).reduce((counts, item) => {
    const version = `v${Number(item.question?.version) || 0}`;
    counts[version] = (counts[version] || 0) + 1;
    return counts;
  }, {});
  const versionText = Object.entries(versionCounts).map(([version, count]) => `${version} ${count}题`).join(" · ") || "-";
  const driftCount = (batch.items || []).filter((item) => ["question_drift", "knowledge_drift"].includes(item.businessSync?.status)).length;
  document.querySelector("#blind-gold-freeze-preview-subtitle").textContent = `${batch.title} · 金标集版本 ${preparation.version || batch.version || "V1"}`;
  document.querySelector("#blind-gold-freeze-preview-completed").textContent = `${batchSummary.completed || 0} / ${batchSummary.total || snapshotSummary.total || 0}`;
  document.querySelector("#blind-gold-freeze-preview-eligible").textContent = `${snapshotSummary.accuracyEligible || 0} 题`;
  document.querySelector("#blind-gold-freeze-preview-disputed").textContent = `${snapshotSummary.goldNeedsReview || 0} 题`;
  document.querySelector("#blind-gold-freeze-preview-drift").textContent = `${driftCount} 题`;
  document.querySelector("#blind-gold-freeze-preview-version").textContent = preparation.version || batch.version || "V1";
  document.querySelector("#blind-gold-freeze-preview-reviewer").textContent = "超级管理员";
  document.querySelector("#blind-gold-freeze-preview-modes").textContent = modeText;
  document.querySelector("#blind-gold-freeze-preview-books").textContent = bookText;
  document.querySelector("#blind-gold-freeze-preview-question-versions").textContent = versionText;
  document.querySelector("#blind-gold-freeze-preview-expiry").textContent = formatTaskTime(preparation.expiresAt);
  document.querySelector("#blind-gold-freeze-preview-content-hash").textContent = preparation.contentSha256 || "-";
  document.querySelector("#blind-gold-freeze-preview-file-hash").textContent = preparation.fileSha256 || "-";
}

function setBlindGoldRevisionStatus(message = "", tone = "") {
  setSmallDialogStatus("#blind-gold-revision-status", message, tone);
}

function openBlindGoldRevisionDialog() {
  const batch = state.blindGoldReviewBatch;
  if (!batch || batch.status !== "frozen" || state.blindGoldReviewSaving) return;
  const risks = blindGoldRevisionRisks(batch);
  if (!risks.length) {
    openBlindGoldReviewAlert(friendlyError("classification_gold_review_revision_risks_required"));
    return;
  }
  const version = blindGoldRevisionNextVersion(batch.version);
  const title = blindGoldRevisionTitle(batch, version);
  const contentRiskCount = risks.filter((risk) => risk.requiredStages.includes("content")).length;
  const familyRiskCount = risks.filter((risk) => risk.requiredStages.includes("family")).length;
  state.blindGoldRevisionDraft = {
    sourceBatchId: batch.id,
    version,
    title,
    risks,
    reason: `${batch.version || "V1"} 冻结批次修订审计识别 ${risks.length} 道风险题（内容阶段 ${contentRiskCount} 道、题族阶段 ${familyRiskCount} 道）。保留冻结父版本，仅重审风险阶段。`,
  };
  document.querySelector("#blind-gold-revision-subtitle").textContent = `${batch.title || "冻结金标集"} 保持不可变；${version} 只重新开放风险阶段`;
  document.querySelector("#blind-gold-revision-dialog-parent-version").textContent = batch.snapshot?.version || batch.version || "-";
  document.querySelector("#blind-gold-revision-dialog-target-version").textContent = `${version} · 修订草稿`;
  document.querySelector("#blind-gold-revision-dialog-file-hash").textContent = batch.snapshot?.fileSha256 || "-";
  document.querySelector("#blind-gold-revision-dialog-content-hash").textContent = batch.snapshot?.contentSha256 || "-";
  document.querySelector("#blind-gold-revision-risk-count").textContent = `${risks.length} 题`;
  document.querySelector("#blind-gold-revision-risk-list").innerHTML = risks.map((risk) => {
    const stageLabel = risk.requiredStages.includes("content") ? "内容待重审" : "题族待重审";
    return `<article>
      <span>${escapeHtml(risk.order || "-")}</span>
      <div><strong>${escapeHtml(risk.stem)}</strong><small>${escapeHtml(risk.reason)}</small></div>
      <b class="${risk.requiredStages.includes("content") ? "content_re_review" : "family_re_review"}">${stageLabel}</b>
    </article>`;
  }).join("");
  document.querySelector("#confirm-blind-gold-revision").textContent = `创建 ${version} 修订草稿`;
  setBlindGoldRevisionStatus();
  document.querySelector("#blind-gold-revision-dialog").showModal();
}

function closeBlindGoldRevisionDialog() {
  if (state.blindGoldReviewSaving) return;
  document.querySelector("#blind-gold-revision-dialog").close();
  state.blindGoldRevisionDraft = null;
  setBlindGoldRevisionStatus();
}

async function createBlindGoldRevisionDraft() {
  const draft = state.blindGoldRevisionDraft;
  const batch = state.blindGoldReviewBatch;
  if (!draft || !batch || batch.id !== draft.sourceBatchId || batch.status !== "frozen" || state.blindGoldReviewSaving) return;
  state.blindGoldReviewSaving = true;
  document.querySelector("#confirm-blind-gold-revision").disabled = true;
  setBlindGoldRevisionStatus(`正在从 ${batch.version || "V1"} 创建 ${draft.version} 修订草稿`, "loading");
  try {
    const response = await requestJson(`/api/admin/knowledge-classification/gold-review/sets/${encodeURIComponent(draft.sourceBatchId)}/revisions`, {
      method: "POST",
      body: JSON.stringify({
        version: draft.version,
        title: draft.title,
        riskQuestionIds: draft.risks.map((risk) => risk.questionId),
        reason: draft.reason,
      }),
    });
    const revisionBatch = response.batch || response.set;
    if (!revisionBatch?.id) throw new Error("classification_gold_review_batch_not_found");
    if (response.revisionReview && !revisionBatch.revisionReview) revisionBatch.revisionReview = response.revisionReview;
    const existingIndex = state.blindGoldReviewSets.findIndex((entry) => entry.id === revisionBatch.id);
    if (existingIndex >= 0) state.blindGoldReviewSets.splice(existingIndex, 1, revisionBatch);
    else state.blindGoldReviewSets.unshift(revisionBatch);
    state.blindGoldReviewBatch = revisionBatch;
    invalidateBlindGoldReviewCatalogCaches();
    state.blindGoldReviewBatchId = revisionBatch.id;
    state.blindGoldBusinessEditMode = false;
    state.blindGoldContentEditable = false;
    state.blindGoldReviewResult = "";
    document.querySelector("#blind-gold-review-status").value = "needs_revision";
    const firstRisk = (revisionBatch.items || []).find((item) => blindGoldRevisionRequiredStages(item, revisionBatch).length)
      || (revisionBatch.items || []).find((item) => draft.risks.some((risk) => risk.questionId === item.questionId));
    state.selectedBlindGoldQuestionId = firstRisk?.questionId || revisionBatch.items?.[0]?.questionId || "";
    document.querySelector("#blind-gold-revision-dialog").close();
    state.blindGoldRevisionDraft = null;
    renderBlindGoldReview();
    await ensureBlindGoldReviewCatalog(selectedBlindGoldReviewItem(), { quiet: true, force: true });
    setBlindGoldReviewFeedback(`${revisionBatch.version || draft.version} 修订草稿已创建。未列入风险的题目已继承完成，仅风险题进入重审；没有启动盲测、采纳 AI 预测或运行经验沉淀。`, "success");
  } catch (error) {
    setBlindGoldRevisionStatus(`创建失败：${friendlyError(error)}`, "error");
  } finally {
    state.blindGoldReviewSaving = false;
    document.querySelector("#confirm-blind-gold-revision").disabled = false;
    renderBlindGoldReviewSummary();
  }
}

function closeBlindGoldFreezePreview() {
  document.querySelector("#blind-gold-freeze-preview-dialog").close();
  state.blindGoldFreezePreparation = null;
}

async function reopenBlindGoldFormalFamilyDrift(error) {
  const batch = state.blindGoldReviewBatch;
  const questionId = String(error?.details?.questionId || "");
  const issues = Array.isArray(error?.details?.issues) ? error.details.issues : [];
  if (!batch || !blindGoldReviewIsRevisionBatch(batch) || !questionId || !issues.length) return false;
  const item = (batch.items || []).find((entry) => entry.questionId === questionId);
  if (!item) return false;
  const qualificationIssues = issues.map((issue) => ({
    ...issue,
    questionId,
    source: "formal_family_live_drift_preflight",
    requiredStages: ["family"],
    message: `正式题族已变化，需要重新审核题族裁决（${issue.code || "family_drift"}）。`,
  }));
  const preflightReportHash = await sha256Hex({
    batchId: batch.id,
    questionId,
    qualificationIssues,
  });
  const response = await requestJson(`/api/admin/knowledge-classification/gold-review/sets/${encodeURIComponent(batch.id)}/family-reviews/reopen`, {
    method: "POST",
    body: JSON.stringify({
      questionIds: [questionId],
      reason: "冻结预检发现正式题族在修订草稿创建后发生变化，重新开放本题的题族审核。",
      preflightReportHash,
      qualificationIssues,
    }),
  });
  state.blindGoldReviewBatch = response.batch || batch;
  state.blindGoldReviewBatch.summary = response.summary || state.blindGoldReviewBatch.summary;
  state.selectedBlindGoldQuestionId = questionId;
  state.blindGoldReviewResult = "";
  state.blindGoldContentEditable = false;
  state.blindGoldBusinessEditMode = false;
  const bookId = item.question?.bookId || "";
  if (bookId) {
    state.blindGoldFamilyCatalogs.delete(bookId);
    state.blindGoldCatalogRequests.delete(bookId);
    await ensureBlindGoldReviewCatalog(selectedBlindGoldReviewItem(), { quiet: true });
  }
  renderBlindGoldReview();
  openBlindGoldReviewAlert(`正式题族已变化，第 ${item.order} 题已自动重新开放“题族裁决”，并刷新正式题族目录；答案与知识审核保持不变。`);
  return true;
}

async function freezeBlindGoldReviewSet() {
  const batch = state.blindGoldReviewBatch;
  if (!batch || state.blindGoldReviewSaving) return;
  if (batch.status === "frozen") {
    openBlindGoldRevisionDialog();
    return;
  }
  if ((batch.items || []).some((item) => ["question_drift", "knowledge_drift"].includes(item.businessSync?.status))) {
    openBlindGoldReviewAlert("仍有题目的正式数据已更新，请先逐题重新载入并完成两阶段审核。");
    return;
  }
  if (!batch.summary?.readyToFreeze) {
    openBlindGoldReviewAlert(friendlyError("classification_gold_review_incomplete"));
    return;
  }
  state.blindGoldReviewSaving = true;
  renderBlindGoldReviewSummary();
  setBlindGoldReviewFeedback("正在生成冻结预览与真实哈希；当前不会写入快照。", "loading");
  try {
    const response = await requestJson(`/api/admin/knowledge-classification/gold-review/sets/${encodeURIComponent(batch.id)}/freeze/prepare`, {
      method: "POST",
      body: "{}",
    });
    state.blindGoldReviewBatch = response.batch || state.blindGoldReviewBatch;
    state.blindGoldReviewBatch.summary = response.summary || state.blindGoldReviewBatch.summary;
    state.blindGoldFreezePreparation = response.preparation || null;
    renderBlindGoldReview();
    renderBlindGoldFreezePreview();
    document.querySelector("#blind-gold-freeze-preview-dialog").showModal();
    setBlindGoldReviewFeedback("冻结预览已生成，请核对汇总与哈希后确认；尚未写入快照。", "success");
  } catch (error) {
    state.blindGoldFreezePreparation = null;
    const reopened = error.message === "classification_gold_review_formal_family_drift"
      ? await reopenBlindGoldFormalFamilyDrift(error)
      : false;
    if (!reopened && !setBlindGoldFreezeSemanticFeedback(error)) {
      openBlindGoldReviewAlert(`生成冻结预览失败：${friendlyError(error)}`);
    }
  } finally {
    state.blindGoldReviewSaving = false;
    renderBlindGoldReview();
  }
}

async function commitBlindGoldReviewSet() {
  const batch = state.blindGoldReviewBatch;
  const preparation = state.blindGoldFreezePreparation;
  if (!batch || !preparation?.token || state.blindGoldReviewSaving) return;
  state.blindGoldReviewSaving = true;
  document.querySelector("#commit-blind-gold-freeze").disabled = true;
  setBlindGoldReviewFeedback("正在按预览内容冻结金标集；不会启动盲测。", "loading");
  try {
    const response = await requestJson(`/api/admin/knowledge-classification/gold-review/sets/${encodeURIComponent(batch.id)}/freeze/commit`, {
      method: "POST",
      body: JSON.stringify({ token: preparation.token }),
    });
    state.blindGoldReviewBatch = response.batch;
    state.blindGoldReviewBatch.summary = response.summary || state.blindGoldReviewBatch.summary;
    state.blindGoldReviewBatch.snapshot = response.snapshot || state.blindGoldReviewBatch.snapshot;
    state.blindGoldFreezePreparation = null;
    document.querySelector("#blind-gold-freeze-preview-dialog").close();
    renderBlindGoldReview();
    setBlindGoldReviewFeedback(`金标快照已冻结：${response.summary?.accuracyEligible || 0} 题可计准确率，${response.snapshot?.summary?.goldNeedsReview || 0} 题保持 gold_needs_review。预览哈希与落盘哈希一致；未启动新一轮盲测。`, "success");
  } catch (error) {
    const familyDrift = error.message === "classification_gold_review_formal_family_drift";
    if (familyDrift) {
      document.querySelector("#blind-gold-freeze-preview-dialog").close();
      state.blindGoldFreezePreparation = null;
    }
    const reopened = familyDrift ? await reopenBlindGoldFormalFamilyDrift(error) : false;
    if (!reopened) openBlindGoldReviewAlert(`冻结失败：${friendlyError(error)}`);
  } finally {
    state.blindGoldReviewSaving = false;
    document.querySelector("#commit-blind-gold-freeze").disabled = false;
    renderBlindGoldReview();
  }
}

// DEC-092：盲测金标已从「AI 巡检」子标签提升为题库管理的**平级子标签**，
// 因此原来的子标签机制整块删除 —— 页面显隐的唯一来源就是 state.questionLibraryTab，
// 不再保留第二套"子标签状态"（否则又会出现同一事实两处可改）。
function knowledgeInspectionQuery() {
  return new URLSearchParams({
    bookId: document.querySelector("#question-book-filter").value,
    status: document.querySelector("#knowledge-inspection-status").value,
    risk: document.querySelector("#knowledge-inspection-risk").value,
    issue: document.querySelector("#knowledge-inspection-issue").value,
    family: document.querySelector("#knowledge-inspection-family").value,
    query: document.querySelector("#knowledge-inspection-search").value.trim(),
    includeHistory: document.querySelector("#knowledge-inspection-show-history").checked,
    page: state.knowledgeInspectionPage,
  });
}

function stopKnowledgeInspectionPolling() {
  if (knowledgeInspectionRefreshTimer) clearTimeout(knowledgeInspectionRefreshTimer);
  knowledgeInspectionRefreshTimer = null;
}

function scheduleKnowledgeInspectionPolling() {
  stopKnowledgeInspectionPolling();
  const job = state.knowledgeInspectionJob;
  if (!job || !["queued", "running", "agent1_running", "agent2_running"].includes(String(job.status)) || state.questionLibraryTab !== "inspections") return;
  knowledgeInspectionRefreshTimer = setTimeout(pollKnowledgeInspectionJob, 2200);
}

async function pollKnowledgeInspectionJob() {
  const job = state.knowledgeInspectionJob;
  if (!job?.id || state.questionLibraryTab !== "inspections") return;
  try {
    const payload = await requestJson(`/api/admin/knowledge-classification/jobs/${encodeURIComponent(job.id)}`);
    state.knowledgeInspectionJob = payload.job || payload;
    renderKnowledgeInspectionJob();
    await loadKnowledgeInspections();
  } catch (error) {
    stopKnowledgeInspectionPolling();
    setKnowledgeInspectionFeedback(`任务状态读取失败：${friendlyError(error)}`, "error");
  }
}

async function loadKnowledgeInspections() {
  try {
    const payload = await requestJson(`/api/admin/knowledge-classification/results?${knowledgeInspectionQuery()}`);
    state.knowledgeInspectionResults = payload.results || payload.items || [];
    state.knowledgeInspectionSummary = payload.summary || {};
    // 体检项词表由后端原样下发（code → { title, source, severity, suggestion }）——只有摘要卡按 code 计数时
    // 需要它来显示中文标题；详情/列表一律直接用每行自带的 title。AGENTS §5：不在前端再维护第二份 map。
    if (payload.issueLabels && typeof payload.issueLabels === "object") state.knowledgeInspectionIssueLabels = payload.issueLabels;
    syncKnowledgeInspectionIssueOptions();
    state.knowledgeInspectionTotal = Number(payload.total ?? state.knowledgeInspectionResults.length);
    state.knowledgeInspectionPage = Number(payload.page) || 1;
    state.knowledgeInspectionPageCount = Number(payload.pageCount) || Math.max(1, Math.ceil(state.knowledgeInspectionTotal / (Number(payload.pageSize) || 50)));
    if (payload.job) state.knowledgeInspectionJob = payload.job;
    else if (Array.isArray(payload.jobs)) state.knowledgeInspectionJob = payload.jobs.find((job) => ["queued", "running", "agent1_running", "agent2_running"].includes(String(job.status))) || state.knowledgeInspectionJob;
    renderKnowledgeInspectionSummary();
    renderKnowledgeInspectionJob();
    renderKnowledgeInspectionTable();
    const historyCount = Number(state.knowledgeInspectionSummary.history || 0);
    document.querySelector("#knowledge-inspection-history-count").textContent = historyCount ? `(${historyCount})` : "";
    document.querySelector("#knowledge-inspection-page-copy").textContent = `第 ${state.knowledgeInspectionPage} / ${state.knowledgeInspectionPageCount} 页 · 共 ${state.knowledgeInspectionTotal} 条建议`;
    document.querySelector("#knowledge-inspection-prev").disabled = state.knowledgeInspectionPage <= 1;
    document.querySelector("#knowledge-inspection-next").disabled = state.knowledgeInspectionPage >= state.knowledgeInspectionPageCount;
    scheduleKnowledgeInspectionPolling();
    return true;
  } catch (error) {
    document.querySelector("#knowledge-inspection-table-body").innerHTML = `<tr><td colspan="5" class="question-table-empty">读取失败：${escapeHtml(friendlyError(error))}</td></tr>`;
    return false;
  }
}

async function refreshKnowledgeInspections() {
  const button = document.querySelector("#refresh-knowledge-inspections");
  button.disabled = true;
  setKnowledgeInspectionFeedback("正在刷新 AI 巡检建议…", "loading");
  const loaded = await loadKnowledgeInspections();
  setKnowledgeInspectionFeedback(loaded ? `已刷新，共 ${state.knowledgeInspectionTotal} 条待人工查看的巡检记录。` : "刷新失败，请稍后重试。", loaded ? "success" : "error");
  button.disabled = false;
}

async function runKnowledgeInspections(questionIds = null, options = {}) {
  const bookId = options.bookId || document.querySelector("#question-book-filter").value;
  if (!bookId || bookId === "all") {
    setKnowledgeInspectionFeedback("请先选择一本教材，再启动 AI 巡检。", "error");
    return;
  }
  const button = document.querySelector("#run-knowledge-inspections");
  button.disabled = true;
  setKnowledgeInspectionFeedback("正在创建四 Agent 协作巡检任务；任务只会生成建议，不会自动修改题库。", "loading");
  try {
    const selected = Array.isArray(questionIds) ? questionIds : state.questionSelectedIds;
    const payload = await requestJson("/api/admin/knowledge-classification/jobs", {
      method: "POST",
      body: JSON.stringify({ bookId, questionIds: selected, limit: options.limit || 50 }),
    });
    state.knowledgeInspectionJob = payload.job || payload;
    renderKnowledgeInspectionJob();
    scheduleKnowledgeInspectionPolling();
    setKnowledgeInspectionFeedback(`巡检已开始${selected.length ? `，将分析所选 ${selected.length} 道题` : "，将从当前教材中选取待复核题目"}。完成后仍需人工确认。`, "success");
  } catch (error) {
    setKnowledgeInspectionFeedback(`启动失败：${friendlyError(error)}`, "error");
  } finally {
    button.disabled = false;
  }
}

function knowledgeInspectionTraceHtml(agent = {}) {
  const rawTrace = knowledgeInspectionArray(agent.trace || agent.steps || agent.pathTrace || agent.reasoningTrace);
  const trace = rawTrace.flatMap((item) => Array.isArray(item?.steps) ? item.steps : [item]);
  if (!trace.length) {
    const diagnostics = knowledgeInspectionArray(agent.diagnostics);
    if (diagnostics.length) {
      const last = diagnostics.at(-1);
      return `<div class="knowledge-inspection-empty">${escapeHtml(friendlyError(agent.error || last.errorCode || "knowledge_classification_agent2_contract_failed"))}<br><small>已保存 ${diagnostics.length} 次合同校验记录，可在盲测原始结果中回看。</small></div>`;
    }
    return '<div class="knowledge-inspection-empty">Agent 2 尚未返回逐层归类轨迹</div>';
  }
  const traceHtml = trace.map((step, index) => {
    const selected = knowledgeInspectionArray(step?.selectedNodes || step?.selectedNodeIds);
    const title = typeof step === "string" ? `第 ${index + 1} 步` : (step.label || step.level || step.title || `第 ${index + 1} 层 · ${step.decision || "选择"}`);
    const path = typeof step === "string" ? step : knowledgeInspectionPath(step.path || step.candidate || step.selection || step.node || selected);
    const reason = typeof step === "string" ? "" : (step.reason || step.explanation || step.evidence || "");
    const confidence = typeof step === "object" && step.confidence != null ? ` · ${Math.round(Number(step.confidence) * 100)}%` : "";
    const gap = step?.auxiliaryGap;
    const gapLabels = knowledgeInspectionArray(gap?.dependencies).map((dependency) => dependency.label).filter(Boolean).join("、");
    const gapHtml = gap ? `<small>辅助知识缺口：${escapeHtml(gapLabels || gap.dependencyStepRefs?.join("、") || "待 Agent 3 核验")} · ${escapeHtml(gap.reason || "已继续核心路径")}</small>` : "";
    return `<div class="knowledge-inspection-trace-step"><span>${index + 1}</span><div><strong>${escapeHtml(title)}${escapeHtml(confidence)}</strong><p>${escapeHtml(path || reason || "未给出具体候选")}</p>${path && reason ? `<small>${escapeHtml(reason)}</small>` : ""}${gapHtml}</div></div>`;
  }).join("");
  const retryCount = knowledgeInspectionArray(agent.diagnostics).filter((item) => Number(item.contractAttempt) > 1).length;
  return `${retryCount ? `<div class="knowledge-inspection-verdict"><strong>约束纠正</strong><p>Agent 2 有 ${retryCount} 层在首次输出违约后完成了一次约束重试。</p></div>` : ""}${traceHtml}`;
}

function knowledgeInspectionFeatureHtml(agent = {}) {
  const features = agent.features || agent;
  if (!features || (!features.stemKeywords?.length && !features.optionFeatures?.length)) {
    return '<div class="knowledge-inspection-empty">Agent 1 尚未形成结构化题目特征</div>';
  }
  const modeLabels = { stem_direct: "题干直问", option_judgement: "选项判断", material_analysis: "材料分析", composite: "综合调用" };
  const optionHtml = knowledgeInspectionArray(features.optionFeatures).map((option) => `<article class="knowledge-inspection-option-feature">
    <div><strong>${escapeHtml(option.key || "选项")}. ${escapeHtml(option.text || "")}</strong><span>${option.isCorrect ? "答案" : "干扰项"} · 权重 ${Math.round(Number(option.weight || 0) * 100)}%</span></div>
    <p>${escapeHtml((option.knowledgeHints || []).join(" · ") || "暂未匹配具体知识点")}</p>
    ${(option.keywords || []).length ? `<small>关键词：${escapeHtml(option.keywords.join("、"))}</small>` : ""}
  </article>`).join("");
  const dependencies = knowledgeInspectionArray(features.dependencySteps).map((step) => `<li><b>${escapeHtml(step.order)}</b><span>${escapeHtml(step.label || (step.nodeIds || []).join("、"))}</span></li>`).join("");
  return `<dl class="knowledge-inspection-feature-summary">
    <div><dt>题目模式</dt><dd>${escapeHtml(modeLabels[features.questionMode] || features.questionMode || "待判断")}</dd></div>
    <div><dt>题干关键词</dt><dd>${escapeHtml((features.stemKeywords || []).join("、") || "未提取")}</dd></div>
    <div><dt>题目知识焦点候选</dt><dd>${escapeHtml((features.primaryKnowledgeHints || []).join(" · ") || "待归类")}</dd></div>
    <div><dt>跨题族概率</dt><dd>${Math.round(Number(features.crossFamilyProbability || 0) * 100)}% · 调用深度 ${escapeHtml(features.callDepth || 1)}</dd></div>
  </dl>${features.primaryBasis ? `<div class="knowledge-inspection-verdict"><strong>焦点与依赖判断</strong><p>${escapeHtml(features.primaryBasis)}</p></div>` : ""}<div class="knowledge-inspection-option-features">${optionHtml}</div>${dependencies ? `<ol class="knowledge-inspection-dependencies">${dependencies}</ol>` : ""}`;
}

function knowledgeInspectionEvidenceHtml(agent = {}) {
  const evidence = knowledgeInspectionArray(agent.evidence || agent.textbookEvidence || agent.sources || agent.citations);
  const verdict = agent.verdict || agent.reason || agent.explanation || [
    agent.primaryNode?.path,
    agent.focusLabel,
    agent.action,
  ].filter(Boolean).join(" · ");
  const primaryPath = knowledgeInspectionPath(agent.primaryNode);
  const requiredPaths = knowledgeInspectionArray(agent.requiredNodes).map((node) => knowledgeInspectionPath(node)).filter(Boolean);
  const evidenceChunkIds = knowledgeInspectionArray(agent.evidenceChunkIds).map(String).filter(Boolean);
  const recoveryLabels = { unable: "Agent 2 无法确定", none_of_candidates: "Agent 2 候选均不合适", previous_level_wrong: "Agent 2 判断上一层可能选错" };
  const recoveryNotice = agent.recoveredFrom
    ? `<div class="knowledge-inspection-verdict"><strong>整树重新定位</strong><p>${escapeHtml(recoveryLabels[agent.recoveredFrom] || agent.recoveredFrom)}，Agent 3 已脱离原候选路径检索完整知识树。</p></div>`
    : "";
  const contractNotice = agent.agent3ContractStatus === "failed"
    ? '<div class="knowledge-inspection-verdict uncertain"><strong>需要重点人工确认</strong><p>Agent 3 唯一一次约束纠正后仍未完全满足输出合同。系统只保留了内部一致的知识判断，并已将题族裁决降为待定。</p></div>'
    : "";
  const verification = primaryPath || requiredPaths.length || agent.focusLabel || agent.action || agent.uncertainty
    ? `<dl class="knowledge-inspection-verification">
      <div><dt>题目知识焦点</dt><dd>${escapeHtml(primaryPath || "未形成明确结论")}</dd></div>
      <div><dt>最小充分知识集</dt><dd>${escapeHtml(requiredPaths.join(" · ") || primaryPath || "未形成明确结论")}</dd></div>
      <div><dt>考查焦点</dt><dd>${escapeHtml(agent.focusLabel || "未标注")}</dd></div>
      <div><dt>作答动作</dt><dd>${escapeHtml(agent.action || "未标注")}</dd></div>
      ${agent.uncertainty ? `<div class="uncertain"><dt>不确定项</dt><dd>${escapeHtml(agent.uncertainty)}</dd></div>` : ""}
    </dl>`
    : "";
  const items = evidence.map((item, index) => {
    const path = typeof item === "string" ? "" : (item.catalogPath || item.path || item.source || "");
    const page = typeof item === "string" ? "" : (item.printedPage || item.page || "");
    const excerpt = typeof item === "string" ? item : (item.excerpt || item.text || item.quote || item.content || "");
    return `<details ${index === 0 ? "open" : ""}><summary>教材证据 ${index + 1}${path ? ` · ${escapeHtml(path)}` : ""}${page ? ` · ${escapeHtml(page)} 页` : ""}</summary><p>${escapeHtml(excerpt || "未提供正文摘录")}</p></details>`;
  }).join("");
  const chunkRefs = evidenceChunkIds.length
    ? `<div class="knowledge-inspection-chunk-refs"><strong>教材证据片段</strong><span>${evidenceChunkIds.map((id) => `<code>${escapeHtml(id)}</code>`).join("")}</span><small>当前接口仅返回证据片段编号，可在教材正文库中进一步核对。</small></div>`
    : "";
  const familyNameMap = new Map((agent.candidateFamilies || []).map((family) => [family.id, family.name]));
  const familyNames = (ids) => (ids || []).map((id) => familyNameMap.get(id) || id).join("、");
  const familyDecisionLabels = { join_existing: "加入现有题族", create_new: "现有题族均不合适", needs_merge: "存在重复题族，需先人工判断", unresolved: "暂不能确定题族" };
  const familyReview = (agent.matchedFamilyIds || []).length || (agent.duplicateFamilyIds || []).length || agent.familySimilarityReason || agent.familyDecision
    ? `<div class="knowledge-inspection-family-review"><strong>题族核验 · ${escapeHtml(familyDecisionLabels[agent.familyDecision] || "待人工裁决")}</strong><span>相近题族：${escapeHtml(familyNames(agent.matchedFamilyIds) || "无")}</span><span>疑似重复：${escapeHtml(familyNames(agent.duplicateFamilyIds) || "无")}</span>${agent.familySimilarityReason ? `<p>${escapeHtml(agent.familySimilarityReason)}</p>` : ""}</div>` : "";
  return `${contractNotice}${recoveryNotice}${verification}${verdict ? `<div class="knowledge-inspection-verdict"><strong>核验理由</strong><p>${escapeHtml(verdict)}</p></div>` : ""}${familyReview}${items}${chunkRefs || (!items ? '<div class="knowledge-inspection-empty">Agent 3 未提供可追溯的教材证据片段</div>' : "")}`;
}

function knowledgeInspectionSuggestedFamilyMemberships(result = state.currentKnowledgeInspection || {}) {
  const agent = knowledgeInspectionAgent(result, 3);
  const candidateIds = new Set((agent.candidateFamilies || []).map((family) => family.id));
  const relationMap = new Map(knowledgeInspectionArray(agent.relatedFamilyRelations)
    .map((relation) => [String(relation?.familyId || ""), relation])
    .filter(([familyId]) => familyId));
  const suggestedMembershipMap = new Map(knowledgeInspectionArray(agent.familyMemberships)
    .map((membership) => [String(membership?.familyId || ""), membership])
    .filter(([familyId]) => familyId));
  let primaryFamilyId = candidateIds.has(String(agent.primaryFamilyId || "")) ? String(agent.primaryFamilyId) : "";
  let relatedFamilyIds = knowledgeInspectionArray(agent.relatedFamilyIds).map(String).filter((id) => candidateIds.has(id) && id !== primaryFamilyId);
  if (!primaryFamilyId && (!agent.familyDecision || agent.familyDecision === "join_existing")) {
    primaryFamilyId = knowledgeInspectionArray(agent.matchedFamilyIds).map(String).find((id) => candidateIds.has(id)) || "";
    relatedFamilyIds = relatedFamilyIds.filter((id) => id !== primaryFamilyId);
  }
  const membershipFor = (familyId, isPrimary) => {
    const family = (agent.candidateFamilies || []).find((item) => String(item.id || "") === familyId) || {};
    const source = suggestedMembershipMap.get(familyId) || relationMap.get(familyId) || family.membership || {};
    const rawRole = String(source.coverageRole || source.role || "").trim().toLocaleLowerCase("en-US");
    const coverageRole = isPrimary ? "required"
      : (["required", "required_for_answer", "answer_required"].includes(rawRole) ? "required"
        : (["reference", "ordinary", "normal", "related"].includes(rawRole) ? "reference"
          : (typeof source.requiredForAnswer === "boolean" ? (source.requiredForAnswer ? "required" : "reference") : "")));
    let contributionKnowledgeNodeIds = [...new Set(knowledgeInspectionArray(
      source.contributionKnowledgeNodeIds || source.membership?.contributionKnowledgeNodeIds,
    ).map(String).filter(Boolean))];
    return { familyId, isPrimary, coverageRole, contributionKnowledgeNodeIds };
  };
  return [
    ...(primaryFamilyId ? [membershipFor(primaryFamilyId, true)] : []),
    ...[...new Set(relatedFamilyIds)].map((familyId) => membershipFor(familyId, false)),
  ];
}

function knowledgeInspectionCandidateFamilyById(familyId, result = state.currentKnowledgeInspection || {}) {
  return (knowledgeInspectionAgent(result, 3).candidateFamilies || [])
    .find((family) => String(family.id || "") === String(familyId || "")) || null;
}

function knowledgeInspectionResolveKnowledgeNode(value, result = state.currentKnowledgeInspection || {}) {
  const supplied = value && typeof value === "object" ? value : null;
  const id = String(supplied?.id || supplied?.nodeId || supplied?.canonicalNodeId || value || "");
  if (!id) return {};
  const resolved = (state.knowledgeStructure?.nodes || []).find((node) => blindGoldKnowledgeNodeIds(node).includes(id))
    || knowledgeInspectionRequiredNodes(result).find((node) => blindGoldKnowledgeNodeIds(node).includes(id))
    || null;
  return supplied ? { ...(resolved || {}), ...supplied } : (resolved || { id, path: id });
}

function knowledgeInspectionKnowledgeNodesCompatible(left, right, result = state.currentKnowledgeInspection || {}) {
  return blindGoldKnowledgeNodesCompatible(
    knowledgeInspectionResolveKnowledgeNode(left, result),
    knowledgeInspectionResolveKnowledgeNode(right, result),
  );
}

function knowledgeInspectionUniqueKnowledgeNodeIds(values = [], result = state.currentKnowledgeInspection || {}) {
  return knowledgeInspectionArray(values).map((value) => String(value?.id || value?.nodeId || value || "")).filter(Boolean)
    .reduce((unique, nodeId) => {
      if (!unique.some((candidateId) => knowledgeInspectionKnowledgeNodesCompatible(candidateId, nodeId, result))) unique.push(nodeId);
      return unique;
    }, []);
}

function knowledgeInspectionFamilyCoverageNodes(family = {}, result = state.currentKnowledgeInspection || {}) {
  if (!family || typeof family !== "object") return [];
  const declaredNodes = [
    ...knowledgeInspectionArray(family.coverageKnowledge || family.requiredKnowledge),
    ...knowledgeInspectionArray(family.coverageKnowledgeNodes || family.requiredKnowledgeNodes),
  ].map((node) => knowledgeInspectionResolveKnowledgeNode(node, result));
  const idNodes = [
    ...knowledgeInspectionArray(family.coverageKnowledgeNodeIds || family.requiredKnowledgeNodeIds),
  ].map((nodeId) => knowledgeInspectionResolveKnowledgeNode(nodeId, result));
  return blindGoldUniqueKnowledgeNodes([...declaredNodes, ...idNodes]);
}

function knowledgeInspectionFamilyCoverageNodeIds(family = {}, result = state.currentKnowledgeInspection || {}) {
  return knowledgeInspectionFamilyCoverageNodes(family, result)
    .map((node) => String(node.id || node.nodeId || node.canonicalNodeId || "")).filter(Boolean);
}

function knowledgeInspectionSelectedQuestionNodes(result = state.currentKnowledgeInspection || {}) {
  const selectedIds = [...document.querySelectorAll("#knowledge-inspection-choices [data-knowledge-node-choice]:checked")]
    .map((input) => input.value).filter(Boolean);
  const nodeMap = new Map((state.knowledgeStructure?.nodes || []).map((node) => [String(node.id), node]));
  const fallbackMap = new Map(knowledgeInspectionRequiredNodes(result).map((node) => [String(node.id), node]));
  return [...new Set(selectedIds)].map((id) => {
    const node = nodeMap.get(String(id)) || fallbackMap.get(String(id)) || {};
    return { ...node, id: String(node.id || id), path: knowledgeInspectionPath(node) || String(id) };
  });
}

function knowledgeInspectionFamilyContributionDraftKey(familyKey, result = state.currentKnowledgeInspection || {}) {
  return `${knowledgeInspectionResultId(result)}:${String(familyKey || "")}`;
}

function clearKnowledgeInspectionFamilyContributionDrafts() {
  state.knowledgeInspectionFamilyContributionDrafts.clear();
}

function knowledgeInspectionRememberFamilyContribution(familyKey, nodeIds, result = state.currentKnowledgeInspection || {}) {
  state.knowledgeInspectionFamilyContributionDrafts.set(
    knowledgeInspectionFamilyContributionDraftKey(familyKey, result),
    [...new Set(knowledgeInspectionArray(nodeIds).map(String).filter(Boolean))],
  );
}

function knowledgeInspectionStoredFamilyContribution(familyKey, fallbackIds = [], result = state.currentKnowledgeInspection || {}) {
  const key = knowledgeInspectionFamilyContributionDraftKey(familyKey, result);
  return state.knowledgeInspectionFamilyContributionDrafts.has(key)
    ? state.knowledgeInspectionFamilyContributionDrafts.get(key)
    : [...new Set(knowledgeInspectionArray(fallbackIds).map(String).filter(Boolean))];
}

function knowledgeInspectionContributionCandidates(family = {}, selectedIds = [], result = state.currentKnowledgeInspection || {}) {
  const questionNodes = knowledgeInspectionSelectedQuestionNodes(result);
  const coverageNodes = knowledgeInspectionFamilyCoverageNodes(family, result);
  const selectedNodes = knowledgeInspectionArray(selectedIds).map((nodeId) => knowledgeInspectionResolveKnowledgeNode(nodeId, result));
  const matchedQuestionNodes = questionNodes.filter((node) => coverageNodes
    .some((coveredNode) => blindGoldKnowledgeNodeCovers(coveredNode, node)));
  // Keep the complete reviewed knowledge set available even when a formal or
  // historical family still points at an older directory node. The final
  // coverage audit remains responsible for rejecting an invalid contribution.
  return blindGoldUniqueKnowledgeNodes([
    ...matchedQuestionNodes,
    ...questionNodes,
    ...selectedNodes,
  ]);
}

function knowledgeInspectionContributionSuggestionNodeIds(family = {}, membership = {}, result = state.currentKnowledgeInspection || {}) {
  const role = membership.isPrimary ? "required" : String(membership.coverageRole || "");
  if (role !== "required") return [];
  const coverageNodes = knowledgeInspectionFamilyCoverageNodes(family, result);
  return knowledgeInspectionSelectedQuestionNodes(result)
    .filter((node) => coverageNodes.some((coveredNode) => blindGoldKnowledgeNodeCovers(coveredNode, node)))
    .map((node) => node.id).filter(Boolean);
}

function knowledgeInspectionFamilyContributionPickerHtml({ familyKey, family, selectedIds = [], enabled = true, pickerId }) {
  const candidates = knowledgeInspectionContributionCandidates(family, selectedIds);
  const selected = new Set(knowledgeInspectionArray(selectedIds).map(String));
  const suggestionIds = knowledgeInspectionContributionSuggestionNodeIds(family, { coverageRole: "required" });
  const emptyLabel = candidates.length ? "请选择本题贡献知识" : "题族覆盖与本题知识无交集";
  return `<div class="question-family-multiselect blind-gold-knowledge-picker knowledge-inspection-family-contribution-picker" id="${escapeHtml(pickerId)}" data-blind-gold-knowledge-picker data-knowledge-inspection-family-contribution-picker="${escapeHtml(familyKey)}" data-blind-gold-knowledge-empty-label="${escapeHtml(emptyLabel)}" data-blind-gold-knowledge-label="本题贡献知识">
    <button class="question-family-multiselect-trigger" data-blind-gold-knowledge-trigger type="button" aria-haspopup="dialog" aria-expanded="false" aria-controls="${escapeHtml(pickerId)}-panel" aria-label="选择本题贡献知识" ${enabled && candidates.length ? "" : "disabled"}><span data-blind-gold-knowledge-summary>${escapeHtml(emptyLabel)}</span><i aria-hidden="true"></i></button>
    <div class="question-family-multiselect-panel" id="${escapeHtml(pickerId)}-panel" data-blind-gold-knowledge-panel popover="auto" role="dialog" aria-label="选择本题贡献知识" hidden>
      <input class="question-family-multiselect-search" data-blind-gold-knowledge-search type="search" placeholder="搜索本题最小充分知识" aria-label="搜索本题贡献知识" autocomplete="off" />
      <div class="question-family-multiselect-options" data-blind-gold-knowledge-options role="group" aria-label="本题贡献知识选项"></div>
    </div>
    <select data-knowledge-inspection-family-contribution-select="${escapeHtml(familyKey)}" multiple hidden aria-hidden="true" tabindex="-1" ${enabled ? "" : "disabled"}>${candidates.map((node) => `<option value="${escapeHtml(node.id)}" ${selected.has(String(node.id)) ? "selected" : ""}>${escapeHtml(node.path || node.id)}</option>`).join("")}</select>
    ${enabled && !selected.size && suggestionIds.length ? `<button class="secondary-action family-contribution-suggestion" type="button" data-use-knowledge-inspection-contribution-suggestion="${escapeHtml(familyKey)}">采用建议（${escapeHtml(suggestionIds.length)} 项）</button>` : ""}
  </div>`;
}

function knowledgeInspectionSelectedFamilyMemberships() {
  const checked = [...document.querySelectorAll("#knowledge-inspection-family-choices [data-knowledge-family-choice]:checked")];
  const primaryFamilyId = document.querySelector("#knowledge-inspection-family-choices [data-knowledge-primary-family]:checked")?.value || "";
  const createCandidateFamily = document.querySelector("#knowledge-inspection-create-candidate-family")?.checked === true;
  return checked.map((input) => {
    const row = input.closest("[data-knowledge-family-row]");
    const isPrimary = !createCandidateFamily && input.value === primaryFamilyId;
    const coverageRole = isPrimary ? "required" : String(row?.dataset.knowledgeFamilyCoverageRole || "");
    const select = row?.querySelector("[data-knowledge-inspection-family-contribution-select]");
    const contributionKnowledgeNodeIds = coverageRole === "reference" ? []
      : [...(select?.selectedOptions || [])].map((option) => option.value).filter(Boolean);
    return { familyId: input.value, isPrimary, coverageRole, contributionKnowledgeNodeIds };
  });
}

function knowledgeInspectionCandidateFamilyDraft(result = state.currentKnowledgeInspection || {}) {
  const draft = knowledgeInspectionAgent(result, 3).candidateFamilyDraft;
  return draft && typeof draft === "object" && !Array.isArray(draft) ? draft : null;
}

function knowledgeInspectionSelectedCandidateFamilyDraft() {
  const selectedValues = (selector) => [...document.querySelector(selector)?.selectedOptions || []].map((option) => option.value).filter(Boolean);
  const checkedEvidence = [...document.querySelectorAll("#knowledge-inspection-family-draft-evidence-chunks [data-candidate-family-evidence]:checked")]
    .map((input) => input.value).filter(Boolean);
  const scopeAnchorNodeId = document.querySelector("#knowledge-inspection-family-draft-core")?.value || "";
  const coverageKnowledgeNodeIds = selectedValues("#knowledge-inspection-family-draft-required");
  const contributionKnowledgeNodeIds = [...document.querySelectorAll("#knowledge-inspection-candidate-contribution [data-knowledge-inspection-family-contribution-select] option:checked")]
    .map((option) => option.value).filter(Boolean);
  return {
    familyKnowledgeProtocolVersion: blindGoldFamilyKnowledgeProtocolVersion,
    name: document.querySelector("#knowledge-inspection-family-draft-name")?.value.trim() || "",
    focusKey: document.querySelector("#knowledge-inspection-family-draft-focus-key")?.value.trim() || "",
    scopeAnchorNodeId,
    coreKnowledgeNodeId: scopeAnchorNodeId,
    coverageKnowledgeNodeIds,
    requiredKnowledgeNodeIds: coverageKnowledgeNodeIds,
    textbookAnchorNodeIds: selectedValues("#knowledge-inspection-family-draft-anchors"),
    assessmentAction: document.querySelector("#knowledge-inspection-family-draft-action")?.value.trim() || "",
    inclusionBoundary: document.querySelector("#knowledge-inspection-family-draft-inclusion")?.value.trim() || "",
    exclusionBoundary: document.querySelector("#knowledge-inspection-family-draft-exclusion")?.value.trim() || "",
    textbookEvidence: {
      chunkIds: checkedEvidence,
      summary: document.querySelector("#knowledge-inspection-family-draft-evidence-summary")?.value.trim() || "",
    },
    reason: document.querySelector("#knowledge-inspection-family-draft-reason")?.value.trim() || "",
    membership: {
      coverageRole: "required",
      contributionKnowledgeNodeIds,
    },
  };
}

function knowledgeInspectionCandidateFamilyDraftKey(draft = {}) {
  const scopeAnchorNodeId = String(draft.scopeAnchorNodeId || draft.coreKnowledgeNodeId || "");
  const coverageKnowledgeNodeIds = [...new Set(knowledgeInspectionArray(draft.coverageKnowledgeNodeIds || draft.requiredKnowledgeNodeIds).map(String).filter(Boolean))].sort();
  const hasContribution = Object.prototype.hasOwnProperty.call(draft.membership || {}, "contributionKnowledgeNodeIds")
    || Object.prototype.hasOwnProperty.call(draft, "contributionKnowledgeNodeIds");
  const contributionKnowledgeNodeIds = hasContribution
    ? knowledgeInspectionArray(draft.membership?.contributionKnowledgeNodeIds || draft.contributionKnowledgeNodeIds)
    : [];
  return JSON.stringify({
    name: String(draft.name || "").trim(),
    focusKey: String(draft.focusKey || "").trim(),
    scopeAnchorNodeId,
    coverageKnowledgeNodeIds,
    textbookAnchorNodeIds: [...new Set(knowledgeInspectionArray(draft.textbookAnchorNodeIds).map(String).filter(Boolean))].sort(),
    assessmentAction: String(draft.assessmentAction || draft.action || "").trim(),
    inclusionBoundary: String(draft.inclusionBoundary || "").trim(),
    exclusionBoundary: String(draft.exclusionBoundary || "").trim(),
    textbookEvidence: {
      chunkIds: [...new Set(knowledgeInspectionArray(draft.textbookEvidence?.chunkIds || draft.evidenceChunkIds).map(String).filter(Boolean))].sort(),
      summary: String(draft.textbookEvidence?.summary || draft.evidenceSummary || "").trim(),
    },
    reason: String(draft.reason || "").trim(),
    membership: {
      coverageRole: "required",
      contributionKnowledgeNodeIds: [...new Set(contributionKnowledgeNodeIds.map(String).filter(Boolean))].sort(),
    },
  });
}

function knowledgeInspectionCandidateFamilyDraftError(draft = knowledgeInspectionSelectedCandidateFamilyDraft()) {
  if (!draft.name) return "请填写候选题族名称";
  if (!draft.focusKey) return "请填写候选题族判别焦点";
  if (!(draft.scopeAnchorNodeId || draft.coreKnowledgeNodeId)) return "请选择候选题族的后台目录锚点";
  if (!(draft.coverageKnowledgeNodeIds || draft.requiredKnowledgeNodeIds || []).length) return "请至少选择一项候选题族覆盖知识";
  if (!draft.textbookAnchorNodeIds.length) return "请至少选择一个教材位置";
  if (!draft.assessmentAction) return "请填写考查动作";
  if (!draft.textbookEvidence.chunkIds.length) return "请至少保留一条教材证据";
  return "";
}

function knowledgeInspectionNodeLabelById(nodeId, result = state.currentKnowledgeInspection || {}) {
  const id = String(nodeId || "");
  return knowledgeInspectionPath(knowledgeInspectionResolveKnowledgeNode(id, result)) || id;
}

function knowledgeInspectionDefaultContributionNodeIds(family, membership = {}, result = state.currentKnowledgeInspection || {}) {
  return knowledgeInspectionStoredFamilyContribution(
    family?.id || "candidate",
    membership.contributionKnowledgeNodeIds || membership.membership?.contributionKnowledgeNodeIds,
    result,
  );
}

function knowledgeInspectionFamilyCoverageAudit(options = {}) {
  const result = options.result || state.currentKnowledgeInspection || {};
  const expectedIds = knowledgeInspectionUniqueKnowledgeNodeIds(knowledgeInspectionArray(options.selectedNodeIds)
    .concat(options.selectedNodeIds ? [] : knowledgeInspectionSelectedQuestionNodes(result).map((node) => node.id))
    .map(String).filter(Boolean), result);
  const expectedNodes = expectedIds.map((nodeId) => knowledgeInspectionResolveKnowledgeNode(nodeId, result));
  const primaryNodeId = String(options.primaryNodeId ?? document.querySelector("#knowledge-inspection-choices [data-knowledge-primary-choice]:checked")?.value ?? "");
  const primaryNodeRole = normalizeQuestionFingerprintPrimaryNodeRole(options.primaryNodeRole
    ?? document.querySelector('input[name="knowledge-inspection-primary-node-role"]:checked')?.value
    ?? knowledgeInspectionPrimaryNodeRole(result));
  const createCandidateFamily = options.createCandidateFamily ?? (document.querySelector("#knowledge-inspection-create-candidate-family")?.checked === true);
  const familyDeferred = options.familyDeferred ?? (document.querySelector("#knowledge-inspection-family-deferred")?.checked === true);
  const familyMemberships = options.familyMemberships || knowledgeInspectionSelectedFamilyMemberships();
  const candidateFamilyDraft = options.candidateFamilyDraft || (createCandidateFamily ? knowledgeInspectionSelectedCandidateFamilyDraft() : null);
  if (familyDeferred && !familyMemberships.length && !createCandidateFamily) {
    return { valid: true, deferred: true, expectedIds, actualIds: [], missingIds: expectedIds, extraIds: [] };
  }
  const invalidRoleFamilyIds = [];
  const missingContributionFamilyIds = [];
  const referenceContributionFamilyIds = [];
  const invalidContributionFamilyIds = [];
  const missingFamilyDefinitionIds = [];
  const contributors = [];
  let themeContributionIds = [];
  let themeFound = false;
  const auditMembership = (membership, family, label) => {
    const isPrimary = membership.isPrimary === true;
    const role = isPrimary ? "required" : String(membership.coverageRole || "");
    const contributionIds = [...new Set(knowledgeInspectionArray(membership.contributionKnowledgeNodeIds).map(String).filter(Boolean))];
    if (isPrimary) themeFound = true;
    if (!isPrimary && !["required", "reference"].includes(role)) invalidRoleFamilyIds.push(label);
    if (role === "reference") {
      if (contributionIds.length) referenceContributionFamilyIds.push(label);
      return;
    }
    if (role !== "required") return;
    if (!contributionIds.length) missingContributionFamilyIds.push(label);
    const coverageNodes = knowledgeInspectionFamilyCoverageNodes(family, result);
    if (!family || !coverageNodes.length) missingFamilyDefinitionIds.push(label);
    if (contributionIds.some((nodeId) => {
      const contributionNode = knowledgeInspectionResolveKnowledgeNode(nodeId, result);
      return !expectedNodes.some((expectedNode) => blindGoldKnowledgeNodeIsWithin(expectedNode, contributionNode))
        || !coverageNodes.some((coveredNode) => blindGoldKnowledgeNodeCovers(coveredNode, contributionNode));
    })) {
      invalidContributionFamilyIds.push(label);
    }
    contributors.push(...contributionIds);
    if (isPrimary) themeContributionIds = contributionIds;
  };
  familyMemberships.forEach((membership) => {
    const family = knowledgeInspectionCandidateFamilyById(membership.familyId, result);
    auditMembership(membership, family, family?.name || membership.familyId);
  });
  if (createCandidateFamily && candidateFamilyDraft) {
    const membership = {
      isPrimary: true,
      coverageRole: "required",
      contributionKnowledgeNodeIds: candidateFamilyDraft.membership?.contributionKnowledgeNodeIds || [],
    };
    auditMembership(membership, candidateFamilyDraft, candidateFamilyDraft.name || "候选新题族");
  }
  const actualIds = knowledgeInspectionUniqueKnowledgeNodeIds(contributors, result);
  const actualNodes = actualIds.map((nodeId) => knowledgeInspectionResolveKnowledgeNode(nodeId, result));
  const missingIds = expectedIds.filter((nodeId) => !actualNodes.some((actualNode) => blindGoldKnowledgeNodeCovers(actualNode, knowledgeInspectionResolveKnowledgeNode(nodeId, result))));
  const extraIds = actualIds.filter((nodeId) => !expectedNodes.some((expectedNode) => blindGoldKnowledgeNodeCovers(knowledgeInspectionResolveKnowledgeNode(nodeId, result), expectedNode)));
  const primaryMissingFocus = Boolean(primaryNodeRole === "core" && primaryNodeId && themeFound && !themeContributionIds
    .some((nodeId) => blindGoldKnowledgeNodeCovers(
      knowledgeInspectionResolveKnowledgeNode(nodeId, result),
      knowledgeInspectionResolveKnowledgeNode(primaryNodeId, result),
    )));
  const missingTheme = !themeFound;
  return {
    valid: Boolean(expectedIds.length && !missingTheme && !invalidRoleFamilyIds.length
      && !missingContributionFamilyIds.length && !referenceContributionFamilyIds.length
      && !invalidContributionFamilyIds.length && !missingFamilyDefinitionIds.length
      && !missingIds.length && !extraIds.length && !primaryMissingFocus),
    deferred: false,
    expectedIds,
    actualIds,
    missingIds,
    extraIds,
    invalidRoleFamilyIds,
    missingContributionFamilyIds,
    referenceContributionFamilyIds,
    invalidContributionFamilyIds,
    missingFamilyDefinitionIds,
    primaryMissingFocus,
    missingTheme,
    primaryNodeId,
    primaryNodeRole,
    referenceCount: familyMemberships.filter((membership) => membership.coverageRole === "reference").length,
  };
}

function knowledgeInspectionFamilyCoverageError(audit = knowledgeInspectionFamilyCoverageAudit()) {
  if (audit.deferred) return "";
  if (audit.missingTheme) return "请选择一个主题族";
  if (audit.invalidRoleFamilyIds?.length) return `请为关联题族“${audit.invalidRoleFamilyIds.join("、")}”选择作答必需或普通关联`;
  if (audit.missingContributionFamilyIds?.length) return `请填写“${audit.missingContributionFamilyIds.join("、")}”的本题贡献知识`;
  if (audit.referenceContributionFamilyIds?.length) return `普通关联题族“${audit.referenceContributionFamilyIds.join("、")}”不能填写贡献知识`;
  if (audit.missingFamilyDefinitionIds?.length) return `题族“${audit.missingFamilyDefinitionIds.join("、")}”尚未定义覆盖知识`;
  if (audit.invalidContributionFamilyIds?.length) return `题族“${audit.invalidContributionFamilyIds.join("、")}”的贡献超出本题知识或题族覆盖范围`;
  if (audit.primaryMissingFocus) return `主题族必须承载题目知识焦点“${knowledgeInspectionNodeLabelById(audit.primaryNodeId)}”`;
  if (audit.missingIds?.length) return `题族贡献尚未覆盖：${audit.missingIds.map((id) => knowledgeInspectionNodeLabelById(id)).join("、")}`;
  if (audit.extraIds?.length) return `题族贡献超出最小充分知识集：${audit.extraIds.map((id) => knowledgeInspectionNodeLabelById(id)).join("、")}`;
  return "";
}

function syncKnowledgeInspectionFamilyCoverageSummary() {
  const element = document.querySelector("#knowledge-inspection-family-coverage-summary");
  if (!element) return;
  const audit = knowledgeInspectionFamilyCoverageAudit();
  if (audit.deferred) {
    element.innerHTML = '<strong>待归组</strong><span class="is-muted">仅保存知识判断，本次不执行题族联合覆盖</span>';
    element.classList.remove("is-complete", "has-gap", "has-core-mismatch");
    return;
  }
  const coveredCount = audit.expectedIds.length - audit.missingIds.length;
  const tags = (ids) => ids.map((id) => `<span class="blind-gold-knowledge-tag">${escapeHtml(knowledgeInspectionNodeLabelById(id))}</span>`).join("");
  const parts = [`<strong>联合覆盖 ${escapeHtml(coveredCount)}/${escapeHtml(audit.expectedIds.length)}</strong>`];
  if (audit.valid) parts.push('<span class="is-complete">最小充分知识已等价覆盖</span>');
  if (audit.missingIds.length) parts.push('<span class="is-warning">未覆盖</span>', tags(audit.missingIds));
  if (audit.extraIds.length) parts.push('<span class="is-warning">超出范围</span>', tags(audit.extraIds));
  if (audit.invalidRoleFamilyIds.length) parts.push(`<span class="is-warning">${escapeHtml(audit.invalidRoleFamilyIds.length)} 个关联题族未选择用途</span>`);
  if (audit.missingContributionFamilyIds.length) parts.push(`<span class="is-warning">${escapeHtml(audit.missingContributionFamilyIds.length)} 个作答必需题族未填贡献</span>`);
  if (audit.invalidContributionFamilyIds.length || audit.missingFamilyDefinitionIds.length) parts.push('<span class="is-warning">存在不合法的成员贡献</span>');
  if (audit.primaryMissingFocus) parts.push(`<span class="is-core-mismatch">主题族未承载题目知识焦点“${escapeHtml(knowledgeInspectionNodeLabelById(audit.primaryNodeId))}”</span>`);
  parts.push(`<span class="is-reference">普通关联 ${escapeHtml(audit.referenceCount || 0)} 个，不计入联合覆盖</span>`);
  element.innerHTML = parts.join("");
  element.classList.toggle("is-complete", audit.valid);
  element.classList.toggle("has-gap", !audit.valid);
  element.classList.toggle("has-core-mismatch", audit.primaryMissingFocus);
}

function setKnowledgeInspectionCandidateFamilyDraftEnabled(enabled) {
  document.querySelectorAll("#knowledge-inspection-family-draft-form input, #knowledge-inspection-family-draft-form textarea, #knowledge-inspection-family-draft-form select")
    .forEach((control) => { control.disabled = !enabled; });
}

function knowledgeInspectionFamilySelectionKey(memberships = []) {
  return memberships.map((membership) => `${membership.familyId}:${membership.isPrimary ? "1" : "0"}:${membership.coverageRole || ""}:${[...new Set(membership.contributionKnowledgeNodeIds || [])].map(String).sort().join(",")}`).sort().join("\u0000");
}

function createKnowledgeInspectionCommitId() {
  const cryptoApi = globalThis.crypto;
  if (typeof cryptoApi?.randomUUID === "function") return cryptoApi.randomUUID();
  const bytes = new Uint8Array(16);
  if (typeof cryptoApi?.getRandomValues === "function") cryptoApi.getRandomValues(bytes);
  else bytes.forEach((_, index) => { bytes[index] = Math.floor(Math.random() * 256); });
  bytes[6] = (bytes[6] & 0x0f) | 0x40;
  bytes[8] = (bytes[8] & 0x3f) | 0x80;
  const hex = [...bytes].map((byte) => byte.toString(16).padStart(2, "0"));
  return `${hex.slice(0, 4).join("")}-${hex.slice(4, 6).join("")}-${hex.slice(6, 8).join("")}-${hex.slice(8, 10).join("")}-${hex.slice(10).join("")}`;
}

function clearKnowledgeInspectionCommit() {
  state.knowledgeInspectionCommit = null;
}

function setKnowledgeInspectionApplyLocked(locked) {
  const dialog = document.querySelector("#knowledge-inspection-dialog");
  if (!dialog) return;
  if (locked) {
    dialog.setAttribute("aria-busy", "true");
    dialog.inert = true;
    knowledgeInspectionApplyControlLock.lock(dialog.querySelectorAll("button, input, textarea, select"));
    return;
  }
  knowledgeInspectionApplyControlLock.unlock();
  dialog.inert = false;
  dialog.removeAttribute("aria-busy");
}

function getKnowledgeInspectionCommitId(content) {
  const key = JSON.stringify({
    resultId: String(content.resultId || ""),
    selectedNodeIds: [...content.selectedNodeIds].map(String).sort(),
    selectedPrimary: String(content.selectedPrimary || ""),
    primaryNodeRole: normalizeQuestionFingerprintPrimaryNodeRole(content.primaryNodeRole),
    familyMemberships: [...content.familyMemberships]
      .map((membership) => ({
        familyId: String(membership.familyId),
        isPrimary: Boolean(membership.isPrimary),
        coverageRole: String(membership.coverageRole || ""),
        contributionKnowledgeNodeIds: [...new Set(membership.contributionKnowledgeNodeIds || [])].map(String).sort(),
      }))
      .sort((left, right) => left.familyId.localeCompare(right.familyId) || Number(right.isPrimary) - Number(left.isPrimary)),
    familyDeferred: Boolean(content.familyDeferred),
    createCandidateFamily: Boolean(content.createCandidateFamily),
    candidateFamilyDraft: content.createCandidateFamily ? knowledgeInspectionCandidateFamilyDraftKey(content.candidateFamilyDraft) : "",
    adjustmentReason: String(content.adjustmentReason || ""),
  });
  if (state.knowledgeInspectionCommit?.key !== key) {
    state.knowledgeInspectionCommit = { key, commitId: createKnowledgeInspectionCommitId() };
  }
  return state.knowledgeInspectionCommit.commitId;
}

function knowledgeInspectionSelectionAdjusted() {
  const suggested = knowledgeInspectionAgent(state.currentKnowledgeInspection || {}, 3);
  const selectedNodeIds = [...document.querySelectorAll("#knowledge-inspection-choices [data-knowledge-node-choice]:checked")].map((input) => input.value).sort();
  const suggestedNodeIds = [...new Set(knowledgeInspectionArray(suggested.requiredNodeIds).map(String).filter(Boolean))].sort();
  const selectedPrimary = document.querySelector("#knowledge-inspection-choices [data-knowledge-primary-choice]:checked")?.value || "";
  const selectedPrimaryNodeRole = normalizeQuestionFingerprintPrimaryNodeRole(document.querySelector('input[name="knowledge-inspection-primary-node-role"]:checked')?.value);
  const knowledgeAdjusted = selectedPrimary !== String(suggested.primaryNodeId || suggested.primaryNode?.id || "")
    || selectedPrimaryNodeRole !== knowledgeInspectionPrimaryNodeRole(state.currentKnowledgeInspection || {})
    || selectedNodeIds.join("\u0000") !== suggestedNodeIds.join("\u0000");
  const selectedFamilyKey = knowledgeInspectionFamilySelectionKey(knowledgeInspectionSelectedFamilyMemberships());
  const suggestedFamilyKey = knowledgeInspectionFamilySelectionKey(knowledgeInspectionSuggestedFamilyMemberships());
  const offeredDraft = knowledgeInspectionCandidateFamilyDraft();
  const createCandidateFamily = document.querySelector("#knowledge-inspection-create-candidate-family")?.checked === true;
  const familyAdjusted = offeredDraft
    ? (!createCandidateFamily
      || selectedFamilyKey !== suggestedFamilyKey
      || knowledgeInspectionCandidateFamilyDraftKey(knowledgeInspectionSelectedCandidateFamilyDraft()) !== knowledgeInspectionCandidateFamilyDraftKey(offeredDraft))
    : selectedFamilyKey !== suggestedFamilyKey;
  return knowledgeAdjusted || familyAdjusted;
}

function syncKnowledgeInspectionAdjustmentReason() {
  // DEC-100：只读弹窗里已没有「调整依据」输入框（勾选与提交都在「完善题目」里做）；
  // 这里补空值兜底，避免旧写路径在元素缺失时抛错。
  const element = document.querySelector("#knowledge-inspection-adjustment-reason");
  if (!element) return;
  element.hidden = !knowledgeInspectionSelectionAdjusted();
}

function knowledgeInspectionRefreshFamilyContributionRow(row, options = {}) {
  if (!row) return;
  const familyId = row.dataset.knowledgeFamilyRow || "";
  const family = knowledgeInspectionCandidateFamilyById(familyId) || {};
  const selected = row.querySelector("[data-knowledge-family-choice]")?.checked === true;
  const primary = selected
    && document.querySelector("#knowledge-inspection-create-candidate-family")?.checked !== true
    && row.querySelector("[data-knowledge-primary-family]")?.checked === true;
  const role = primary ? "required" : String(row.dataset.knowledgeFamilyCoverageRole || "");
  const existingSelect = row.querySelector("[data-knowledge-inspection-family-contribution-select]");
  const existingIds = existingSelect
    ? [...existingSelect.selectedOptions].map((option) => option.value).filter(Boolean)
    : knowledgeInspectionStoredFamilyContribution(familyId);
  const eligibleIds = knowledgeInspectionContributionCandidates(family).map((node) => node.id);
  let contributionIds = existingIds.filter((nodeId) => eligibleIds.includes(nodeId));
  if (role === "reference") contributionIds = [];
  knowledgeInspectionRememberFamilyContribution(familyId, contributionIds);
  const roleControls = row.querySelector("[data-knowledge-family-role-controls]");
  const primaryRole = row.querySelector("[data-knowledge-family-primary-role]");
  if (roleControls) roleControls.hidden = !selected || primary;
  if (primaryRole) primaryRole.hidden = !primary;
  row.querySelectorAll("[data-knowledge-family-role]").forEach((button) => {
    button.disabled = !selected || primary || row.classList.contains("unavailable");
    button.setAttribute("aria-pressed", String(!primary && row.dataset.knowledgeFamilyCoverageRole === button.dataset.knowledgeFamilyRole));
  });
  const contribution = row.querySelector("[data-knowledge-family-contribution]");
  const host = row.querySelector("[data-knowledge-family-contribution-host]");
  if (contribution) contribution.hidden = !selected || role !== "required";
  if (host) host.innerHTML = knowledgeInspectionFamilyContributionPickerHtml({
    familyKey: familyId,
    family,
    selectedIds: contributionIds,
    enabled: selected && role === "required" && !row.classList.contains("unavailable"),
    pickerId: `knowledge-inspection-family-contribution-${familyId.replace(/[^a-zA-Z0-9_-]/g, "-")}`,
  });
}

function renderKnowledgeInspectionCandidateContribution(options = {}) {
  const host = document.querySelector("#knowledge-inspection-candidate-contribution");
  if (!host) return;
  const create = document.querySelector("#knowledge-inspection-create-candidate-family")?.checked === true;
  const canApply = knowledgeInspectionCanApply(state.currentKnowledgeInspection || {});
  const draft = knowledgeInspectionCandidateFamilyDraft() || {};
  const family = {
    id: "candidate",
    name: document.querySelector("#knowledge-inspection-family-draft-name")?.value.trim() || draft.name || "候选新题族",
    coverageKnowledgeNodeIds: [...document.querySelector("#knowledge-inspection-family-draft-required")?.selectedOptions || []]
      .map((option) => option.value).filter(Boolean),
  };
  const existingSelect = host.querySelector("[data-knowledge-inspection-family-contribution-select]");
  const fallbackIds = existingSelect
    ? [...existingSelect.selectedOptions].map((option) => option.value).filter(Boolean)
    : knowledgeInspectionArray(draft.membership?.contributionKnowledgeNodeIds || draft.contributionKnowledgeNodeIds);
  const eligibleIds = knowledgeInspectionContributionCandidates(family).map((node) => node.id);
  let contributionIds = knowledgeInspectionStoredFamilyContribution("candidate", fallbackIds)
    .filter((nodeId) => eligibleIds.includes(nodeId));
  knowledgeInspectionRememberFamilyContribution("candidate", contributionIds);
  host.innerHTML = `<div class="knowledge-inspection-family-contribution-copy"><span>候选主题族 · 作答必需</span><small>标注新题族在本题中实际承载的最小充分知识；必须包含题目知识焦点</small></div>${knowledgeInspectionFamilyContributionPickerHtml({
    familyKey: "candidate",
    family,
    selectedIds: contributionIds,
    enabled: create && canApply,
    pickerId: "knowledge-inspection-candidate-contribution-picker",
  })}`;
  host.hidden = !create;
  initializeBlindGoldKnowledgePickers();
}

function syncKnowledgeInspectionFamilyRows(options = {}) {
  document.querySelectorAll("#knowledge-inspection-family-choices [data-knowledge-family-row]")
    .forEach((row) => knowledgeInspectionRefreshFamilyContributionRow(row, options));
  renderKnowledgeInspectionCandidateContribution(options);
  initializeBlindGoldKnowledgePickers();
  syncKnowledgeInspectionFamilyCoverageSummary();
}

function handleKnowledgeInspectionContributionOptionChange(root) {
  const select = blindGoldKnowledgePickerSelect(root);
  if (!root || !select) return;
  const familyKey = root.dataset.knowledgeInspectionFamilyContributionPicker || "";
  knowledgeInspectionRememberFamilyContribution(
    familyKey,
    [...select.selectedOptions].map((entry) => entry.value).filter(Boolean),
  );
  clearKnowledgeInspectionCommit();
  syncKnowledgeInspectionFamilyCoverageSummary();
  updateKnowledgeInspectionApplyButton();
  syncKnowledgeInspectionAdjustmentReason();
}

function handleKnowledgeInspectionDialogClick(event) {
  const contributionSuggestion = event.target.closest("[data-use-knowledge-inspection-contribution-suggestion]");
  if (contributionSuggestion) {
    const familyKey = contributionSuggestion.dataset.useKnowledgeInspectionContributionSuggestion;
    const family = familyKey === "candidate"
      ? knowledgeInspectionSelectedCandidateFamilyDraft()
      : knowledgeInspectionCandidateFamilyById(familyKey);
    const contributionIds = knowledgeInspectionContributionSuggestionNodeIds(family || {}, { coverageRole: "required" });
    knowledgeInspectionRememberFamilyContribution(familyKey, contributionIds);
    clearKnowledgeInspectionCommit();
    syncKnowledgeInspectionFamilyRows();
    updateKnowledgeInspectionApplyButton();
    syncKnowledgeInspectionAdjustmentReason();
    return;
  }
  const roleButton = event.target.closest("[data-knowledge-family-role]");
  if (roleButton) {
    const row = roleButton.closest("[data-knowledge-family-row]");
    if (!row || roleButton.disabled) return;
    row.dataset.knowledgeFamilyCoverageRole = roleButton.dataset.knowledgeFamilyRole;
    if (roleButton.dataset.knowledgeFamilyRole === "reference") knowledgeInspectionRememberFamilyContribution(row.dataset.knowledgeFamilyRow, []);
    clearKnowledgeInspectionCommit();
    knowledgeInspectionRefreshFamilyContributionRow(row);
    initializeBlindGoldKnowledgePickers();
    syncKnowledgeInspectionFamilyCoverageSummary();
    updateKnowledgeInspectionApplyButton();
    syncKnowledgeInspectionAdjustmentReason();
    return;
  }
  const trigger = event.target.closest("[data-blind-gold-knowledge-trigger]");
  if (trigger && trigger.closest("#knowledge-inspection-dialog")) {
    const root = trigger.closest("[data-blind-gold-knowledge-picker]");
    setBlindGoldKnowledgePickerOpen(root, !questionFamilyMultiselectIsOpen(root));
  }
}

function handleKnowledgeInspectionDialogInput(event) {
  const search = event.target.closest("[data-blind-gold-knowledge-search]");
  if (search) renderBlindGoldKnowledgePicker(search.closest("[data-blind-gold-knowledge-picker]"));
}

function updateKnowledgeInspectionApplyButton() {
  // DEC-100（产品手册 §4.6.12）：巡检弹窗已改成只读，不再有「采纳所选」按钮，
  // 这个函数保留（write path 与静态契约仍在），但页面上再无任何入口能调用它。
  const button = document.querySelector("#apply-knowledge-inspection");
  if (!button) return;
  const count = document.querySelectorAll("#knowledge-inspection-choices [data-knowledge-node-choice]:checked").length;
  const hasPrimary = Boolean(document.querySelector("#knowledge-inspection-choices [data-knowledge-primary-choice]:checked"));
  const familyMemberships = knowledgeInspectionSelectedFamilyMemberships();
  const hasPrimaryFamily = familyMemberships.some((membership) => membership.isPrimary);
  const deferred = document.querySelector("#knowledge-inspection-family-deferred")?.checked === true;
  const createCandidateFamily = document.querySelector("#knowledge-inspection-create-candidate-family")?.checked === true;
  const candidateDraftError = createCandidateFamily ? knowledgeInspectionCandidateFamilyDraftError() : "";
  const familyCoverageError = knowledgeInspectionFamilyCoverageError();
  const familyChoiceValid = (createCandidateFamily ? !candidateDraftError : (familyMemberships.length ? hasPrimaryFamily : deferred)) && !familyCoverageError;
  const result = state.currentKnowledgeInspection || {};
  const blockReason = knowledgeInspectionApplyBlockReason(result);
  if (knowledgeInspectionApplyGuard.currentRequest()) {
    button.disabled = true;
    button.textContent = "正在保存";
    return;
  }
  button.disabled = !count || !hasPrimary || !familyChoiceValid || Boolean(blockReason);
  button.textContent = result.answerConflict
    ? "请先修正答案"
    : (blockReason ? "无可采纳建议" : (!count ? "请确认知识依据" : (!familyChoiceValid ? (candidateDraftError || (familyCoverageError ? "请完善题族贡献" : "请选择主题族或待归组")) : (createCandidateFamily ? "创建题族并确认归类" : "确认知识与题族归类"))));
}

function handleKnowledgeInspectionChoiceChange(event) {
  if (knowledgeInspectionApplyGuard.currentRequest()) return;
  clearKnowledgeInspectionCommit();
  const container = document.querySelector("#knowledge-inspection-choices");
  const nodeChoices = [...container.querySelectorAll("[data-knowledge-node-choice]")];
  const primaryChoices = [...container.querySelectorAll("[data-knowledge-primary-choice]")];
  const primaryNodeRole = normalizeQuestionFingerprintPrimaryNodeRole(document.querySelector('input[name="knowledge-inspection-primary-node-role"]:checked')?.value);
  if (event.target.matches("[data-knowledge-primary-choice]")) {
    const nodeChoice = nodeChoices.find((input) => input.value === event.target.value);
    if (nodeChoice && primaryNodeRole === "core") nodeChoice.checked = true;
  }
  if (event.target.matches("[data-knowledge-node-choice]")) {
    const primaryChoice = primaryChoices.find((input) => input.value === event.target.value);
    if (!event.target.checked && primaryChoice?.checked && primaryNodeRole === "core") primaryChoice.checked = false;
  }
  const selectedPrimaryChoice = primaryChoices.find((input) => input.checked);
  nodeChoices.forEach((input) => {
    const isPrimary = input.value === selectedPrimaryChoice?.value;
    if (isPrimary && primaryNodeRole === "core") input.checked = true;
    if (isPrimary && primaryNodeRole === "scope_anchor") input.checked = false;
    input.disabled = isPrimary && primaryNodeRole === "core";
  });
  const checkedNodes = nodeChoices.filter((input) => input.checked);
  const selectedPrimary = primaryChoices.find((input) => input.checked);
  if (!selectedPrimary && checkedNodes.length) {
    const fallback = primaryChoices.find((input) => input.value === checkedNodes[0].value);
    if (fallback) fallback.checked = true;
  }
  syncKnowledgeInspectionFamilyRows();
  updateKnowledgeInspectionApplyButton();
  syncKnowledgeInspectionAdjustmentReason();
}

function handleKnowledgeInspectionFamilyChoiceChange(event) {
  if (knowledgeInspectionApplyGuard.currentRequest()) return;
  if (event.target.matches("[data-blind-gold-knowledge-option], [data-knowledge-inspection-family-contribution-select]")) return;
  clearKnowledgeInspectionCommit();
  const container = document.querySelector("#knowledge-inspection-family-choices");
  const familyChoices = [...container.querySelectorAll("[data-knowledge-family-choice]")];
  const primaryChoices = [...container.querySelectorAll("[data-knowledge-primary-family]")];
  const deferred = document.querySelector("#knowledge-inspection-family-deferred");
  const createCandidateFamily = document.querySelector("#knowledge-inspection-create-candidate-family")?.checked === true;
  if (event.target === deferred && deferred.checked) {
    familyChoices.forEach((input) => { input.checked = false; });
    primaryChoices.forEach((input) => { input.checked = false; });
  }
  if (event.target.matches("[data-knowledge-primary-family]")) {
    const familyChoice = familyChoices.find((input) => input.value === event.target.value);
    if (familyChoice) familyChoice.checked = true;
    deferred.checked = false;
  }
  if (event.target.matches("[data-knowledge-family-choice]")) {
    const primaryChoice = primaryChoices.find((input) => input.value === event.target.value);
    if (!event.target.checked && primaryChoice?.checked) primaryChoice.checked = false;
    if (event.target.checked) deferred.checked = false;
  }
  const checkedFamilies = familyChoices.filter((input) => input.checked);
  const selectedPrimary = primaryChoices.find((input) => input.checked && checkedFamilies.some((family) => family.value === input.value));
  if (!createCandidateFamily && !selectedPrimary && checkedFamilies.length) {
    const fallback = primaryChoices.find((input) => input.value === checkedFamilies[0].value);
    if (fallback) fallback.checked = true;
  }
  if (!createCandidateFamily && !checkedFamilies.length) deferred.checked = true;
  syncKnowledgeInspectionFamilyRows();
  updateKnowledgeInspectionApplyButton();
  syncKnowledgeInspectionAdjustmentReason();
}

function syncKnowledgeInspectionCandidateFamilyMode() {
  const create = document.querySelector("#knowledge-inspection-create-candidate-family")?.checked === true;
  const canApply = knowledgeInspectionCanApply(state.currentKnowledgeInspection || {});
  const familyChoices = [...document.querySelectorAll("#knowledge-inspection-family-choices [data-knowledge-family-choice]")];
  const primaryChoices = [...document.querySelectorAll("#knowledge-inspection-family-choices [data-knowledge-primary-family]")];
  const deferred = document.querySelector("#knowledge-inspection-family-deferred");
  setKnowledgeInspectionCandidateFamilyDraftEnabled(create && canApply);
  primaryChoices.forEach((input) => {
    if (create) input.checked = false;
    input.disabled = !canApply || create || input.closest(".knowledge-inspection-family-choice")?.classList.contains("unavailable");
  });
  if (create) {
    deferred.checked = false;
    deferred.disabled = true;
  } else {
    deferred.disabled = !canApply;
    const checkedFamilies = familyChoices.filter((input) => input.checked && !input.disabled);
    if (checkedFamilies.length) {
      const currentPrimary = primaryChoices.find((input) => input.checked && checkedFamilies.some((family) => family.value === input.value));
      if (!currentPrimary) {
        const fallback = primaryChoices.find((input) => !input.disabled && input.value === checkedFamilies[0].value);
        if (fallback) fallback.checked = true;
      }
      deferred.checked = false;
    } else {
      deferred.checked = true;
    }
  }
  syncKnowledgeInspectionFamilyRows();
  updateKnowledgeInspectionApplyButton();
  syncKnowledgeInspectionAdjustmentReason();
}

function handleKnowledgeInspectionCandidateFamilyDecision() {
  if (knowledgeInspectionApplyGuard.currentRequest()) return;
  clearKnowledgeInspectionCommit();
  syncKnowledgeInspectionCandidateFamilyMode();
}

function handleKnowledgeInspectionCandidateFamilyDraftInput(event) {
  if (knowledgeInspectionApplyGuard.currentRequest()) return;
  if (event.target.matches("[data-blind-gold-knowledge-search], [data-blind-gold-knowledge-option], [data-knowledge-inspection-family-contribution-select]")) return;
  clearKnowledgeInspectionCommit();
  if (event.target.matches("#knowledge-inspection-family-draft-required")) renderKnowledgeInspectionCandidateContribution();
  syncKnowledgeInspectionFamilyCoverageSummary();
  updateKnowledgeInspectionApplyButton();
  syncKnowledgeInspectionAdjustmentReason();
}

// ── DEC-100（产品手册 §4.6.12）：巡检弹窗的只读渲染 ────────────────────────────────
// 巡检只诊断、不改库：知识依据与题族归属都只展示 AI 结论与证据。
// 原来这里的 checkbox／radio／select／textarea／角色按钮全部不再渲染；改库一律在「完善题目」里做。
function renderKnowledgeInspectionReadonlyKnowledge(result, offeredKnowledgeNodes, requiredNodes, suggestedPrimaryNodeId, primaryNodeRole) {
  const roleElement = document.querySelector("#knowledge-inspection-primary-node-role");
  if (roleElement) {
    roleElement.innerHTML = `<span>题目知识焦点角色（只读展示）：</span><span class="knowledge-inspection-readonly-mark">${escapeHtml(primaryNodeRole === "scope_anchor" ? "范围锚点（不计入最小充分知识集）" : "作答核心（计入最小充分知识集）")}</span><span>最小充分知识集（${escapeHtml(requiredNodes.length)}）</span>`;
  }
  const container = document.querySelector("#knowledge-inspection-choices");
  if (!container) return;
  container.innerHTML = offeredKnowledgeNodes.map((node) => {
    const suggestedPrimary = node.id === suggestedPrimaryNodeId;
    const isRequired = requiredNodes.some((requiredNode) => requiredNode.id === node.id);
    const marks = [isRequired ? "最小充分知识集" : "", suggestedPrimary ? "题目知识焦点" : ""].filter(Boolean);
    return `<div class="knowledge-inspection-node-readonly ${suggestedPrimary ? "is-primary" : ""}" data-inspection-node-row="${escapeHtml(node.id)}">
      <div><strong>${escapeHtml(node.path || node.id)}</strong><small>${escapeHtml(suggestedPrimary ? (primaryNodeRole === "scope_anchor" ? "Agent 3 建议作为范围锚点，不计入最小充分知识" : "Agent 3 建议作为作答核心，已计入最小充分知识") : "Agent 3 判断为作答必需知识")}</small><em>${escapeHtml(marks.join(" · ") || "仅作参考")}</em></div>
      <span class="knowledge-inspection-readonly-mark">只读展示</span>
    </div>`;
  }).join("") || '<div class="knowledge-inspection-empty">本次巡检没有形成可选知识点</div>';
}

function renderKnowledgeInspectionReadonlyFamilies(result) {
  const suggestedFamilyMemberships = knowledgeInspectionSuggestedFamilyMemberships(result);
  const suggestedFamilyMap = new Map(suggestedFamilyMemberships.map((membership) => [membership.familyId, membership]));
  const familyStatusLabels = { confirmed: "已确认", pending_review: "待审核", rejected: "已驳回" };
  const familyRoleLabels = { primary: "Agent 3 建议主题族", related: "Agent 3 建议关联题族", matched: "相近候选", duplicate: "疑似重复", candidate: "同知识候选" };
  const candidateFamilies = knowledgeInspectionAgent(result, 3).candidateFamilies || [];
  const container = document.querySelector("#knowledge-inspection-family-choices");
  if (container) {
    container.innerHTML = candidateFamilies.length ? candidateFamilies.map((family) => {
      const suggestedMembership = suggestedFamilyMap.get(family.id);
      const currentLabel = family.isCurrent ? (family.isCurrentPrimary ? "当前主题族" : "当前关联题族") : "";
      const suggestedRoleLabel = suggestedMembership
        ? (suggestedMembership.isPrimary ? "建议主题族（作答必需）" : (String(suggestedMembership.coverageRole || "") === "reference" ? "建议关联题族（普通关联）" : "建议关联题族（作答必需）"))
        : "未建议归属";
      const coverageLabel = knowledgeInspectionFamilyCoverageNodeIds(family)
        .map((nodeId) => knowledgeInspectionNodeLabelById(nodeId, result)).join(" · ") || "尚未定义";
      return `<div class="knowledge-inspection-family-readonly ${suggestedMembership?.isPrimary ? "is-primary" : ""} ${family.suggestedRole === "duplicate" ? "is-duplicate" : ""}" data-inspection-family-row="${escapeHtml(family.id)}">
        <div class="knowledge-inspection-family-readonly-head"><strong>${escapeHtml(family.name)}</strong><span class="knowledge-inspection-readonly-mark">只读展示</span></div>
        <small>${escapeHtml(family.knowledgePath || "未标注知识位置")} · ${escapeHtml(family.memberCount || 0)} 道题${family.relatedFamilyAssessment ? ` · 删除检验：${escapeHtml(family.relatedFamilyAssessment.deletionTest || family.relatedFamilyAssessment.reason || "未提供依据")}` : ""}</small>
        <em>${escapeHtml([familyRoleLabels[family.suggestedRole], currentLabel, familyStatusLabels[family.status], suggestedRoleLabel].filter(Boolean).join(" · "))}</em>
        <small>题族覆盖知识（只读）：${escapeHtml(coverageLabel)}</small>
      </div>`;
    }).join("") : '<div class="knowledge-inspection-empty">当前最小充分知识集下没有可复用的题族，本题应先进入待归组。</div>';
  }
  // 「暂无准确题族，进入待归组」在只读态下只切换显隐，内容由 index.html 固化（不再有勾选项）。
  const deferred = document.querySelector("#knowledge-inspection-family-deferred");
  if (deferred) deferred.hidden = Boolean(suggestedFamilyMemberships.length);
  renderKnowledgeInspectionCandidateFamilyDraft(result);
  renderKnowledgeInspectionReadonlyFamilyCoverage(result);
}

// 只读联合覆盖提示：原来这里展示的是"勾选后的校验结果"，现在只说明 AI 建议了什么、以及普通关联不计入覆盖。
function renderKnowledgeInspectionReadonlyFamilyCoverage(result) {
  const element = document.querySelector("#knowledge-inspection-family-coverage-summary");
  if (!element) return;
  const memberships = knowledgeInspectionSuggestedFamilyMemberships(result);
  const primaryMembership = memberships.find((membership) => membership.isPrimary);
  const relatedCount = memberships.filter((membership) => !membership.isPrimary).length;
  const primaryFamily = primaryMembership ? knowledgeInspectionCandidateFamilyById(primaryMembership.familyId, result) : null;
  element.classList.remove("is-complete", "has-gap", "has-core-mismatch");
  element.innerHTML = [
    `<strong>AI 建议题族归属：${escapeHtml(memberships.length ? `${memberships.length} 个（主题族 ${primaryMembership ? 1 : 0} 个）` : "暂无可用题族")}</strong>`,
    primaryMembership ? `<span class="is-complete">主题族：${escapeHtml(primaryFamily?.name || primaryMembership.familyId)}</span>` : '<span class="is-muted">未建议主题族</span>',
    `<span class="is-reference">普通关联 ${escapeHtml(relatedCount)} 个，不计入联合覆盖</span>`,
    '<span class="is-muted">只读展示：勾选与提交在「完善题目」里完成</span>',
  ].join("");
}

// DEC-100：Agent 3 的候选题族草案同样改成只读展示 ——
// 原来这里回填可编辑表单（名称／判别焦点／覆盖知识／证据等），现在只把草案渲染成只读信息；
// 新建候选题族必须在「完善题目」里人工确认后创建，巡检本身不写库。
function renderKnowledgeInspectionCandidateFamilyDraft(result) {
  const container = document.querySelector("#knowledge-inspection-family-draft");
  if (!container) return;
  const draft = knowledgeInspectionCandidateFamilyDraft(result);
  container.hidden = !draft;
  if (!draft) {
    container.innerHTML = "";
    return;
  }
  const nodeMap = new Map((state.knowledgeStructure?.nodes || []).map((node) => [String(node.id), node]));
  const offeredNodes = knowledgeInspectionRequiredNodes(result);
  const knowledgeNodes = [...nodeMap.values()].filter((node) => node.id && node.path && node.kind === "knowledge");
  const selectableNodes = knowledgeNodes.length ? knowledgeNodes : offeredNodes;
  const labelOf = (nodeId) => {
    const key = String(nodeId || "");
    if (!key) return "";
    const node = nodeMap.get(key) || selectableNodes.find((entry) => String(entry.id) === key) || offeredNodes.find((entry) => String(entry.id) === key);
    return node?.path || node?.displayTitle || node?.title || key;
  };
  const listOf = (nodeIds) => knowledgeInspectionArray(nodeIds).map(labelOf).filter(Boolean).join(" · ");
  const scopeAnchorNodeId = String(draft.scopeAnchorNodeId || draft.coreKnowledgeNodeId || "");
  const coverageNodeIds = knowledgeInspectionArray(draft.coverageKnowledgeNodeIds || draft.requiredKnowledgeNodeIds);
  const anchorNodeIds = knowledgeInspectionArray(draft.textbookAnchorNodeIds || draft.knowledgeNodeId);
  const evidenceIds = [...new Set([
    ...knowledgeInspectionArray(draft.textbookEvidence?.chunkIds || draft.evidenceChunkIds),
    ...knowledgeInspectionArray(knowledgeInspectionAgent(result, 3).evidenceChunkIds),
  ].map(String).filter(Boolean))];
  container.innerHTML = `<h4>Agent 3 建议新建的候选题族（只读展示，不能在这里创建）</h4>
    <dl>
      <div><dt>候选题族名称</dt><dd>${escapeHtml(draft.name || "未命名")}</dd></div>
      <div><dt>题族判别焦点</dt><dd>${escapeHtml(draft.focusKey || "未提供")}</dd></div>
      <div><dt>后台目录锚点</dt><dd>${escapeHtml(labelOf(scopeAnchorNodeId) || "未提供")}</dd></div>
      <div><dt>考查动作</dt><dd>${escapeHtml(draft.assessmentAction || draft.action || "未提供")}</dd></div>
      <div><dt>题族覆盖知识</dt><dd>${escapeHtml(listOf(coverageNodeIds) || "未提供")}</dd></div>
      <div><dt>教材位置（教材锚点）</dt><dd>${escapeHtml(listOf(anchorNodeIds) || "未提供")}</dd></div>
      <div><dt>纳入边界</dt><dd>${escapeHtml(draft.inclusionBoundary || "未提供")}</dd></div>
      <div><dt>排除边界</dt><dd>${escapeHtml(draft.exclusionBoundary || "未提供")}</dd></div>
      <div><dt>教材证据</dt><dd>${escapeHtml(evidenceIds.join(" · ") || "本次没有可追溯的教材证据")}</dd></div>
      <div><dt>证据摘要</dt><dd>${escapeHtml(draft.textbookEvidence?.summary || draft.evidenceSummary || "未提供")}</dd></div>
      <div><dt>新建理由</dt><dd>${escapeHtml(draft.reason || "未提供")}</dd></div>
    </dl>
    <p class="knowledge-inspection-family-draft-note">后台目录锚点用于组织和检索，不会自动写入题目知识；题族覆盖知识＝这个题族稳定判别任务能够覆盖的知识。只读展示：新建候选题族要在「完善题目」里人工确认后创建。</p>`;
}

// 弹窗里的「体检项（确定性规则）」只读清单：与 Agent 的 AI 结论分开列，逐条标来源（规则／AI），
// 通过（后端体检跑过但没命中任何规则项）也显示成「已留档 · 无问题」，不是"没问题就不显示"。
// 只有字段整个缺失（后端这一版还没上线）才整节隐藏，不留空壳、也不报错。
function renderKnowledgeInspectionRuleFindings(result = {}) {
  const section = document.querySelector("#knowledge-inspection-rule-findings-section");
  const list = document.querySelector("#knowledge-inspection-rule-findings");
  if (!section || !list) return;
  const hasField = Array.isArray(result.ruleFindings);
  const capability = knowledgeInspectionRuleAuditCapability();
  const findings = knowledgeInspectionRuleFindings(result);
  // 整份响应都没有体检能力（后端还没上这一版）→ 整节隐藏，不留空壳；有能力的响应里字段缺失 = 未体检。
  section.hidden = !hasField && !capability;
  if (!hasField) {
    list.innerHTML = capability ? knowledgeInspectionRuleNoticeRow("not_audited") : "";
    return;
  }
  const rows = findings.map((finding) => {
    const source = knowledgeInspectionRuleFindingSource(finding);
    const isPass = knowledgeInspectionRuleFindingIsPass(finding);
    const severity = String(finding.severity || (isPass ? "none" : "medium"));
    const detail = knowledgeInspectionRuleFindingDetailText(finding);
    const evidence = knowledgeInspectionRuleFindingEvidence(finding);
    const suggestion = knowledgeInspectionRuleFindingSuggestion(finding);
    return `<div class="knowledge-inspection-rule-finding is-${escapeHtml(isPass ? "pass" : severity)} is-${escapeHtml(source)}" data-rule-code="${escapeHtml(finding.code || "")}" data-rule-source="${escapeHtml(source)}">
      <div class="knowledge-inspection-rule-finding-head">
        <span class="knowledge-inspection-rule-source is-${escapeHtml(source)}">${escapeHtml(knowledgeInspectionRuleSourceLabels[source])}</span>
        <strong>${escapeHtml(knowledgeInspectionRuleFindingTitle(finding) || finding.code || "未命名的体检项")}</strong>
        ${isPass ? `<span class="knowledge-inspection-rule-pass">${escapeHtml(KNOWLEDGE_INSPECTION_RULE_PASS_TITLE)}</span>` : `<span class="knowledge-inspection-rule-severity is-${escapeHtml(severity)}">严重度：${escapeHtml(knowledgeInspectionRuleSeverityLabels[severity] || severity)}</span>`}
        <span class="knowledge-inspection-readonly-mark">只读展示</span>
      </div>
      ${detail ? `<p class="knowledge-inspection-rule-finding-detail">说明：${escapeHtml(detail)}</p>` : ""}
      ${evidence ? `<p class="knowledge-inspection-rule-finding-evidence">证据：${escapeHtml(evidence)}</p>` : ""}
      ${suggestion ? `<p class="knowledge-inspection-rule-finding-suggestion">建议：${escapeHtml(suggestion)}</p>` : ""}
    </div>`;
  });
  if (!rows.length) {
    // 体检跑过、没有命中任何规则项：这就是「通过」，也要留档显示。
    list.innerHTML = knowledgeInspectionRuleNoticeRow("pass");
    return;
  }
  list.innerHTML = rows.join("");
}

// 记录状态动作（DEC-100 四态）：只写"人工处理进度"，不改题库内容。
function renderKnowledgeInspectionAuditState(result) {
  const audit = knowledgeInspectionAuditReview(result || {});
  const stateElement = document.querySelector("#knowledge-inspection-review-state");
  if (stateElement) {
    stateElement.textContent = knowledgeInspectionAuditStateLabels[audit.state];
    stateElement.className = `knowledge-inspection-review-state state-${audit.state}`;
  }
  const noteElement = document.querySelector("#knowledge-inspection-review-record-note");
  if (noteElement) {
    noteElement.textContent = audit.note
      ? `最近一次记录备注：${audit.note}`
      : "还没有人工处理备注；四个状态按钮只记录人工处理进度，不会修改题库内容。";
  }
  const auditElement = document.querySelector("#knowledge-inspection-review-audit");
  if (auditElement) {
    const parts = [];
    if (audit.at) parts.push(`<span>处理人：${escapeHtml(knowledgeInspectionAuditActorLabel(audit) || "未知")}</span>`, `<span>时间：${escapeHtml(formatTaskTime(audit.at))}</span>`);
    if (audit.recordedState && audit.recordedState !== audit.state) {
      parts.push(`<span>题目变更前记录的状态：${escapeHtml(knowledgeInspectionAuditStateLabels[audit.recordedState] || audit.recordedState)}</span>`);
    }
    auditElement.innerHTML = parts.join("");
    auditElement.hidden = !parts.length;
  }
  const invalidatedElement = document.querySelector("#knowledge-inspection-review-invalidated");
  if (invalidatedElement) {
    // 后端在题目被改动时派生 auditReview.invalidated／invalidatedReason；界面必须显式提示旧结论已作废。
    invalidatedElement.hidden = !audit.invalidated;
    invalidatedElement.innerHTML = audit.invalidated
      ? `<strong>题目已变更，旧结论作废，需重新巡检</strong><span>${escapeHtml(knowledgeInspectionInvalidatedReasonLabels[audit.invalidatedReason] || "题目在巡检后被改动过")}；这条记录已回到「待复核」${audit.recordedState ? `（旧结论当时的记录状态：${escapeHtml(knowledgeInspectionAuditStateLabels[audit.recordedState] || audit.recordedState)}）` : ""}。</span>`
      : "";
  }
  document.querySelectorAll("[data-knowledge-inspection-audit-state]").forEach((button) => {
    button.disabled = button.dataset.knowledgeInspectionAuditState === audit.state;
  });
  const sendButton = document.querySelector("#send-knowledge-inspection-to-enrichment");
  if (sendButton) sendButton.disabled = !knowledgeInspectionResultId(result || {});
}

async function setKnowledgeInspectionAuditState(nextState) {
  const result = state.currentKnowledgeInspection;
  const resultId = knowledgeInspectionResultId(result || {});
  const label = knowledgeInspectionAuditStateLabels[nextState];
  if (!result || !resultId || !label) return;
  const request = knowledgeInspectionApplyGuard.begin(state.knowledgeInspectionDialogSession, { resultId });
  if (!request) {
    setSmallDialogStatus("#knowledge-inspection-dialog-status", "正在保存当前操作，完成前不能重复提交", "loading");
    return;
  }
  setSmallDialogStatus("#knowledge-inspection-dialog-status", `正在把这条巡检记录标为「${label}」`, "loading");
  setKnowledgeInspectionApplyLocked(true);
  try {
    const payload = await requestJson(`/api/admin/knowledge-classification/results/${encodeURIComponent(resultId)}/audit-review`, {
      method: "POST",
      body: JSON.stringify({ state: nextState }),
    });
    if (!knowledgeInspectionApplyGuard.isCurrent(request)) return;
    await loadKnowledgeInspections();
    const updated = state.knowledgeInspectionResults.find((item) => knowledgeInspectionResultId(item) === resultId);
    if (knowledgeInspectionResultId(state.currentKnowledgeInspection || {}) === resultId) {
      if (updated) state.currentKnowledgeInspection = updated;
      renderKnowledgeInspectionAuditState(updated || { ...result, auditReview: payload?.result?.auditReview || { ...knowledgeInspectionAuditReview(result), state: nextState } });
    }
    setSmallDialogStatus("#knowledge-inspection-dialog-status", `已把这条巡检记录标为「${label}」；记录状态只记录人工处理进度，题库内容没有改变。`, "success");
    setKnowledgeInspectionFeedback(`巡检记录已标为「${label}」。`, "success");
  } catch (error) {
    if (!knowledgeInspectionApplyGuard.isCurrent(request)) return;
    setSmallDialogStatus("#knowledge-inspection-dialog-status", `记录状态保存失败：${friendlyError(error)}`, "error");
  } finally {
    if (knowledgeInspectionApplyGuard.finish(request)) setKnowledgeInspectionApplyLocked(false);
  }
}

// 「送去完善题目」＝把这条体检结论送到「完善题目」生成／刷新建议稿；**不写库、不自动勾选、不自动采纳**。
async function sendKnowledgeInspectionToEnrichment() {
  const result = state.currentKnowledgeInspection;
  const resultId = knowledgeInspectionResultId(result || {});
  if (!result || !resultId) return;
  const request = knowledgeInspectionApplyGuard.begin(state.knowledgeInspectionDialogSession, { resultId });
  if (!request) {
    setSmallDialogStatus("#knowledge-inspection-dialog-status", "正在保存当前操作，完成前不能重复提交", "loading");
    return;
  }
  setSmallDialogStatus("#knowledge-inspection-dialog-status", "正在把这条体检结论送去「完善题目」", "loading");
  setKnowledgeInspectionApplyLocked(true);
  try {
    const payload = await requestJson(`/api/admin/knowledge-classification/results/${encodeURIComponent(resultId)}/send-to-enrichment`, {
      method: "POST",
      body: "{}",
    });
    if (!knowledgeInspectionApplyGuard.isCurrent(request)) return;
    await loadKnowledgeInspections();
    const question = payload?.questionId || knowledgeInspectionQuestion(result).id || result.questionId || "该题";
    setSmallDialogStatus("#knowledge-inspection-dialog-status", `已送去「完善题目」（题目 ${question}${payload?.jobId ? ` · 任务 ${payload.jobId}` : ""}）：巡检不改库，知识依据与题族归属请在「完善题目」里逐项确认。`, "success");
    setKnowledgeInspectionFeedback("已把这条体检结论送去「完善题目」生成／刷新建议稿；AI 巡检本身没有改库。", "success");
  } catch (error) {
    if (!knowledgeInspectionApplyGuard.isCurrent(request)) return;
    setSmallDialogStatus("#knowledge-inspection-dialog-status", `送去完善题目失败：${friendlyError(error)}`, "error");
  } finally {
    if (knowledgeInspectionApplyGuard.finish(request)) setKnowledgeInspectionApplyLocked(false);
  }
}

function openKnowledgeInspection(resultId, questionId) {
  const result = state.knowledgeInspectionResults.find((item) => String(item.id || item.resultId) === String(resultId))
    || state.knowledgeInspectionResults.find((item) => String(knowledgeInspectionQuestion(item).id || item.questionId) === String(questionId));
  if (!result) return;
  if (knowledgeInspectionApplyGuard.currentRequest()) {
    setSmallDialogStatus("#knowledge-inspection-dialog-status", "正在保存当前审核，完成前不能切换题目", "loading");
    return;
  }
  const dialogSession = knowledgeInspectionApplyGuard.open(knowledgeInspectionResultId(result));
  if (!dialogSession) return;
  clearKnowledgeInspectionCommit();
  state.knowledgeInspectionDialogSession = dialogSession;
  state.currentKnowledgeInspection = result;
  clearKnowledgeInspectionFamilyContributionDrafts();
  state.knowledgeInspectionExperience = {
    messages: [],
    rules: result.experience?.rules || [],
    cases: result.experience?.cases || [],
  };
  state.knowledgeInspectionAgent = "agent1";
  const question = knowledgeInspectionQuestion(result);
  const agent1 = knowledgeInspectionAgent(result, 1);
  const agent2 = knowledgeInspectionAgent(result, 2);
  const agent3 = knowledgeInspectionAgent(result, 3);
  const requiredNodes = knowledgeInspectionRequiredNodes(result);
  const suggestedPrimaryNodeId = knowledgeInspectionResolvedNodeId(result);
  const primaryNodeRole = knowledgeInspectionPrimaryNodeRole(result);
  const nodeMap = new Map((state.knowledgeStructure?.nodes || []).map((node) => [String(node.id), node]));
  const primaryNode = suggestedPrimaryNodeId ? {
    ...(nodeMap.get(suggestedPrimaryNodeId) || {}),
    id: suggestedPrimaryNodeId,
    path: knowledgeInspectionPath(nodeMap.get(suggestedPrimaryNodeId)) || knowledgeInspectionSuggestedPath(result) || suggestedPrimaryNodeId,
  } : null;
  const offeredKnowledgeNodes = [...requiredNodes];
  if (primaryNode && !offeredKnowledgeNodes.some((node) => node.id === primaryNode.id)) offeredKnowledgeNodes.unshift(primaryNode);
  document.querySelector("#knowledge-inspection-dialog-title").textContent = `查看巡检结论 · ${question.id || result.questionId || "题目"}`;
  document.querySelector("#knowledge-inspection-dialog-copy").textContent = result.answerConflict ? "高风险 · 答案冲突：请编辑题目后重新巡检（巡检不改库）" : `${knowledgeInspectionRiskLabels[result.risk || result.riskLevel] || "待评风险"} · 只诊断不改库：改库请用「送去完善题目」`;
  const answerConflict = result.answerConflict
    ? `<div class="knowledge-inspection-answer-conflict"><strong>${result.answerConflict.authority === "verified_official" ? "结构化答案与已核验答案冲突" : "答案与参考解析冲突"}</strong><span>结构化答案：${escapeHtml(result.answerConflict.structuredAnswer.join("、"))} · ${result.answerConflict.authority === "verified_official" ? "已核验答案" : "参考解析答案"}：${escapeHtml(result.answerConflict.referenceAnswer.join("、"))}</span><small>${result.answerConflict.authority === "verified_official" ? `答案来源：${escapeHtml(result.answerConflict.answerSource || "已核验来源")}；AI 答案不得覆盖已核验答案。` : "请核对正确答案和解析。"} 请编辑题目后重新巡检。</small></div>`
    : "";
  document.querySelector("#knowledge-inspection-question").innerHTML = `<strong>${escapeHtml(question.stem || "题目内容暂不可用")}</strong>${questionOptionListHtml(question.options)}${answerConflict}<span>当前知识落点：${escapeHtml(knowledgeInspectionCurrentPath(result) || "未归属")}</span><span>建议题目知识焦点：${escapeHtml(knowledgeInspectionSuggestedPath(result) || "未形成明确建议")}</span>${requiredNodes.length > 1 ? `<span class="knowledge-inspection-required-summary">最小充分知识集（${requiredNodes.length}）：${escapeHtml(requiredNodes.map((node) => node.path).join(" · "))}</span>` : ""}`;
  document.querySelector("#knowledge-inspection-agent1").innerHTML = knowledgeInspectionFeatureHtml(agent1);
  document.querySelector("#knowledge-inspection-agent2").innerHTML = knowledgeInspectionTraceHtml(agent2);
  document.querySelector("#knowledge-inspection-agent3").innerHTML = knowledgeInspectionEvidenceHtml(agent3);
  const disagreements = knowledgeInspectionArray(result.disagreements || result.conflicts || agent3.disagreements || agent3.conflicts);
  document.querySelector("#knowledge-inspection-disagreements").innerHTML = disagreements.length
    ? `<ul>${disagreements.map((item) => `<li>${escapeHtml(typeof item === "string" ? item : (item.reason || item.description || item.message || JSON.stringify(item)))}</li>`).join("")}</ul>`
    : '<p class="knowledge-inspection-empty">未发现明确分歧；仍请人工核对最终知识路径。</p>';
  // DEC-100（产品手册 §4.6.12）：巡检弹窗是**只读体检清单** —— 知识依据只展示 AI 结论与证据，
  // 这里不再渲染任何 checkbox／radio／select／textarea，也没有提交入口；改库在「完善题目」里做。
  renderKnowledgeInspectionReadonlyKnowledge(result, offeredKnowledgeNodes, requiredNodes, suggestedPrimaryNodeId, primaryNodeRole);
  // DEC-100：题族归属同样只做只读展示（含"待归组"与候选题族草案），勾选／创建／提交都在「完善题目」里做。
  renderKnowledgeInspectionReadonlyFamilies(result);
  renderKnowledgeInspectionRuleFindings(result);
  document.querySelector("#rerun-knowledge-inspection").disabled = false;
  document.querySelector("#rerun-knowledge-inspection").textContent = result.hasNewerResult ? "打开最新建议" : "重新巡检本题";
  document.querySelector("#knowledge-inspection-feedback-message").value = "";
  document.querySelector("#knowledge-inspection-create-rule").checked = true;
  // 只读弹窗的按钮只有四个记录状态动作 ＋「送去完善题目」，状态由 auditReview 驱动。
  renderKnowledgeInspectionAuditState(result);
  renderKnowledgeInspectionExperience();
  setKnowledgeInspectionAgent("agent1");
  setKnowledgeInspectionConversationStatus("正在读取本题的教研对话与经验记录…", "loading");
  setSmallDialogStatus("#knowledge-inspection-dialog-status");
  document.querySelector("#knowledge-inspection-dialog").showModal();
  loadKnowledgeInspectionExperience(knowledgeInspectionResultId(result)).then((loaded) => {
    if (loaded && knowledgeInspectionResultId() === knowledgeInspectionResultId(result)) setKnowledgeInspectionConversationStatus();
  });
}

function closeKnowledgeInspectionDialog(options = {}) {
  const expectedSession = options?.expectedSession || state.knowledgeInspectionDialogSession;
  if (!knowledgeInspectionApplyGuard.close(expectedSession)) {
    if (knowledgeInspectionApplyGuard.currentRequest()) {
      setSmallDialogStatus("#knowledge-inspection-dialog-status", "正在保存当前审核，完成前不能关闭或切换", "loading");
    }
    return false;
  }
  const dialog = document.querySelector("#knowledge-inspection-dialog");
  if (dialog.open) dialog.close();
  clearKnowledgeInspectionCommit();
  clearKnowledgeInspectionFamilyContributionDrafts();
  state.knowledgeInspectionDialogSession = null;
  state.currentKnowledgeInspection = null;
  state.knowledgeInspectionExperience = { messages: [], rules: [], cases: [] };
  setSmallDialogStatus("#knowledge-inspection-dialog-status");
  setKnowledgeInspectionConversationStatus();
  return true;
}

// ⚠️ DEC-100（产品手册 §4.6.12）：AI 巡检只诊断、不改库 —— 本函数已从巡检路径摘除，
// 页面上没有「采纳所选」按钮，也没有任何事件绑定会调用它（唯一写库入口是「完善题目」）。
// 它现在只是一个**三行转发壳**：不再读巡检弹窗 DOM、不再构造载荷，也不再有第二套提交判据
// （载荷构造的唯一实现是 knowledge-inspection-apply-guard.js 的 buildApplyRequest）。
async function applyKnowledgeInspection() {
  return openEnrichmentClassification(String(state.currentKnowledgeInspection?.questionId || ""));
}

// ⚠️ DEC-100（产品手册 §4.6.12）：「已拒绝」已从巡检记录状态机中废止（改为四态 待复核／已复核／已修复／已忽略），
// 本函数不再绑定到任何按钮，保留仅为兼容旧写路径与静态契约。
async function rejectKnowledgeInspection() {
  const result = state.currentKnowledgeInspection;
  const question = knowledgeInspectionQuestion(result || {});
  const resultId = String(result?.id || result?.resultId || "");
  if (!result || !question.id || !resultId) return;
  // DEC-100（产品手册 §4.6.12）：巡检记录状态里已没有「已拒绝」，页面上也没有「拒绝建议」按钮，
  // 本函数保留仅为兼容旧的写路径；它不再被任何事件绑定调用，缺失按钮时直接退出。
  const button = document.querySelector("#reject-knowledge-inspection");
  if (button) button.disabled = true;
  setSmallDialogStatus("#knowledge-inspection-dialog-status", "正在记录人工拒绝结果", "loading");
  try {
    await requestJson(`/api/admin/knowledge-classification/results/${encodeURIComponent(question.id)}/reject`, { method: "POST", body: JSON.stringify({ resultId }) });
    closeKnowledgeInspectionDialog();
    await loadKnowledgeInspections();
    setKnowledgeInspectionFeedback("已拒绝这条 AI 建议，题库内容未发生改变。", "success");
  } catch (error) {
    setSmallDialogStatus("#knowledge-inspection-dialog-status", `拒绝失败：${friendlyError(error)}`, "error");
  } finally {
    if (button) button.disabled = false;
  }
}

async function rerunKnowledgeInspection() {
  const result = state.currentKnowledgeInspection;
  const question = knowledgeInspectionQuestion(result || {});
  if (!question.id) return;
  if (result.latestResultId && result.latestResultId !== knowledgeInspectionResultId(result)) {
    const latestResultId = result.latestResultId;
    const cached = state.knowledgeInspectionResults.find((item) => knowledgeInspectionResultId(item) === latestResultId);
    closeKnowledgeInspectionDialog();
    if (cached) {
      openKnowledgeInspection(latestResultId, question.id);
      return;
    }
    try {
      const query = new URLSearchParams({ bookId: question.bookId || result.bookId, query: question.id, pageSize: "100" });
      const payload = await requestJson(`/api/admin/knowledge-classification/results?${query}`);
      const latest = (payload.items || payload.results || []).find((item) => knowledgeInspectionResultId(item) === latestResultId);
      if (latest) {
        state.knowledgeInspectionResults.push(latest);
        openKnowledgeInspection(latestResultId, question.id);
        return;
      }
      setKnowledgeInspectionFeedback("没有找到这道题的最新巡检建议，请刷新后重试。", "error");
    } catch (error) {
      setKnowledgeInspectionFeedback(`读取最新建议失败：${friendlyError(error)}`, "error");
    }
    return;
  }
  closeKnowledgeInspectionDialog();
  await runKnowledgeInspections([question.id], { bookId: question.bookId || result.bookId, limit: 1 });
}

async function editKnowledgeInspectionQuestion() {
  const result = state.currentKnowledgeInspection;
  const question = knowledgeInspectionQuestion(result || {});
  if (!question.id) return;
  if (!state.questions.some((item) => item.id === question.id)
    && !state.questionPool.some((item) => item.id === question.id)) {
    state.questionPool.push(question);
  }
  closeKnowledgeInspectionDialog();
  await openQuestionEditor(question.id);
}

// 默认值只对"不传参"生效：显式传 null 表示**这道题没有巡检结论**，
// 此时绝不能回落到 state.currentKnowledgeInspection（那会把别的题的结论当成本题的）——所以用 ?. 兜空。
function knowledgeInspectionResultId(result = state.currentKnowledgeInspection || {}) {
  return String(result?.id || result?.resultId || "");
}

function teachingRuleStatusClass(status) {
  return ["draft", "active", "inactive"].includes(status) ? status : "draft";
}

function renderKnowledgeInspectionExperience() {
  const experience = state.knowledgeInspectionExperience || {};
  const resultExperience = state.currentKnowledgeInspection?.experience || {};
  const agent1RuleIds = new Set(resultExperience.agent1RuleIds || []);
  const agent2RuleIds = new Set(resultExperience.agent2RuleIds || []);
  const agent1CaseIds = new Set(resultExperience.agent1CaseIds || []);
  const agent2CaseIds = new Set(resultExperience.agent2CaseIds || []);
  const rules = knowledgeInspectionArray(experience.rules);
  const cases = knowledgeInspectionArray(experience.cases);
  const ruleHtml = rules.map((rule) => {
    const agents = [agent1RuleIds.has(rule.id) && "Agent 2", agent2RuleIds.has(rule.id) && "Agent 3"].filter(Boolean);
    const isDraft = rule.status === "draft";
    return `<article class="knowledge-inspection-experience-item">
      <div><strong>${escapeHtml(rule.title || "未命名规则")}</strong><span class="${escapeHtml(teachingRuleStatusClass(rule.status))}">${escapeHtml(teachingRuleStatusLabels[rule.status] || rule.status || "规则")}</span></div>
      <p>${escapeHtml(rule.statement || "暂无规则内容")}</p>
      <small>${escapeHtml(agents.length ? `${agents.join("、")} 本次已读取` : (isDraft ? "对话形成的草案，尚未参与巡检" : "相关规则"))}</small>
      ${isDraft ? `<button class="secondary-action" data-experience-rule-id="${escapeHtml(rule.id)}" type="button">审核规则</button>` : ""}
    </article>`;
  }).join("");
  const caseHtml = cases.map((item) => {
    const agents = [agent1CaseIds.has(item.id) && "Agent 2", agent2CaseIds.has(item.id) && "Agent 3"].filter(Boolean);
    return `<article class="knowledge-inspection-experience-item case">
      <div><strong>确认案例 · ${escapeHtml(item.questionId || "题目")}</strong><span>案例</span></div>
      <p>${escapeHtml(item.knowledgePath || item.focusLabel || item.stem || "人工确认案例")}</p>
      <small>${escapeHtml(agents.length ? `${agents.join("、")} 本次已读取` : "与本题相关的人工确认案例")}</small>
    </article>`;
  }).join("");
  document.querySelector("#knowledge-inspection-experience").innerHTML = ruleHtml || caseHtml
    ? `${ruleHtml}${caseHtml}`
    : '<p class="knowledge-inspection-empty">本次没有读取已批准规则或确认案例。可以在下方复盘并形成规则草案。</p>';
}

function setKnowledgeInspectionConversationStatus(message = "", tone = "") {
  const element = document.querySelector("#knowledge-inspection-conversation-status");
  element.textContent = message;
  element.hidden = !message;
  element.className = `knowledge-inspection-conversation-status${tone ? ` ${tone}` : ""}`;
}

function setKnowledgeInspectionAgent(agent) {
  state.knowledgeInspectionAgent = ["agent1", "agent2", "agent3", "agent4"].includes(agent) ? agent : "agent1";
  document.querySelectorAll("[data-knowledge-inspection-agent]").forEach((button) => {
    const active = button.dataset.knowledgeInspectionAgent === state.knowledgeInspectionAgent;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-selected", String(active));
  });
  document.querySelector("#knowledge-inspection-feedback-label").textContent = `反馈给 Agent ${state.knowledgeInspectionAgent.slice(-1)}`;
  renderKnowledgeInspectionMessages();
}

function renderKnowledgeInspectionMessages() {
  const messages = knowledgeInspectionArray(state.knowledgeInspectionExperience?.messages)
    .filter((message) => message.agent === state.knowledgeInspectionAgent);
  const container = document.querySelector("#knowledge-inspection-messages");
  container.innerHTML = messages.length ? messages.map((message) => `
    <article class="knowledge-inspection-message ${message.role === "reviewer" ? "reviewer" : "agent"}">
      <div><strong>${message.role === "reviewer" ? "审核员" : `Agent ${String(message.agent || "agent2").slice(-1)}`}</strong><time>${escapeHtml(formatTaskTime(message.createdAt))}</time></div>
      <p>${escapeHtml(message.message)}</p>
      ${message.ruleDraftId ? `<button class="secondary-action" data-experience-rule-id="${escapeHtml(message.ruleDraftId)}" type="button">查看规则草案</button>` : ""}
    </article>`).join("") : `<p class="knowledge-inspection-empty">还没有与 Agent ${state.knowledgeInspectionAgent.slice(-1)} 的复盘记录。</p>`;
  container.scrollTop = container.scrollHeight;
}

async function loadKnowledgeInspectionExperience(resultId = knowledgeInspectionResultId()) {
  if (!resultId) return false;
  try {
    const payload = await requestJson(`/api/admin/knowledge-classification/results/${encodeURIComponent(resultId)}/experience`);
    if (resultId !== knowledgeInspectionResultId()) return;
    state.knowledgeInspectionExperience = {
      messages: payload.messages || [],
      rules: payload.rules || [],
      cases: payload.cases || [],
    };
    renderKnowledgeInspectionExperience();
    renderKnowledgeInspectionMessages();
    return true;
  } catch (error) {
    if (resultId === knowledgeInspectionResultId()) setKnowledgeInspectionConversationStatus(`经验记录读取失败：${friendlyError(error)}`, "error");
    return false;
  }
}

async function submitKnowledgeInspectionFeedback(event) {
  event.preventDefault();
  const resultId = knowledgeInspectionResultId();
  const input = document.querySelector("#knowledge-inspection-feedback-message");
  const message = input.value.trim();
  if (!resultId || !message) {
    setKnowledgeInspectionConversationStatus("请先填写需要反馈的内容。", "error");
    return;
  }
  const button = document.querySelector("#send-knowledge-inspection-feedback");
  button.disabled = true;
  setKnowledgeInspectionConversationStatus(`正在请 Agent ${state.knowledgeInspectionAgent.slice(-1)} 结合教材和已有经验复盘…`, "loading");
  try {
    const payload = await requestJson(`/api/admin/knowledge-classification/results/${encodeURIComponent(resultId)}/feedback`, {
      method: "POST",
      body: JSON.stringify({
        agent: state.knowledgeInspectionAgent,
        message,
        createRuleDraft: document.querySelector("#knowledge-inspection-create-rule").checked,
      }),
    });
    input.value = "";
    await loadKnowledgeInspectionExperience(resultId);
    const current = state.knowledgeInspectionResults.find((item) => knowledgeInspectionResultId(item) === resultId);
    if (current?.experience) current.experience.messageCount = Number(current.experience.messageCount || 0) + 2;
    setKnowledgeInspectionConversationStatus(payload.modelError
      ? "反馈已保存；本次模型复盘未完成，规则草案已保留供人工审核。"
      : (payload.rule
        ? (payload.ruleAction === "updated" ? `Agent 已回复，并补充到原规则草案 v${payload.rule.version}，没有重复新建。` : "Agent 已回复，并形成一条待人工审核的规则草案。")
        : "Agent 已回复，本次未形成规则草案。"), payload.modelError ? "warning" : "success");
  } catch (error) {
    setKnowledgeInspectionConversationStatus(`反馈失败：${friendlyError(error)}`, "error");
  } finally {
    button.disabled = false;
  }
}

function setTeachingRuleFeedback(message = "", tone = "") {
  const element = document.querySelector("#teaching-rule-feedback");
  element.textContent = message;
  element.hidden = !message;
  element.className = `teaching-rule-feedback${tone ? ` ${tone}` : ""}`;
}

function renderTeachingRuleSummary() {
  const summary = state.teachingRuleSummary || {};
  const metrics = [
    ["规则总数", summary.rules || 0],
    ["待审核", summary.draft || 0],
    ["已启用", summary.active || 0],
    ["已停用", summary.inactive || 0],
    ["确认案例", summary.cases || 0],
  ];
  document.querySelector("#teaching-rule-summary").innerHTML = metrics.map(([label, count]) => `<div class="teaching-rule-metric"><strong>${escapeHtml(count)}</strong><span>${escapeHtml(label)}</span></div>`).join("");
}

function renderTeachingRuleTable() {
  const body = document.querySelector("#teaching-rule-table-body");
  if (!state.teachingRules.length) {
    body.innerHTML = '<tr><td colspan="5" class="question-table-empty">当前筛选下没有教研规则。请先在巡检详情中与 Agent 复盘并形成规则草案。</td></tr>';
    return;
  }
  body.innerHTML = state.teachingRules.map((rule) => `
    <tr>
      <td><div class="teaching-rule-main"><strong>${escapeHtml(rule.title)}</strong><p>${escapeHtml(rule.statement)}</p><small>${escapeHtml((rule.triggerTerms || []).length ? `触发词：${rule.triggerTerms.join("、")}` : "未设置触发词")}</small></div></td>
      <td><div class="teaching-rule-scope"><strong>${escapeHtml(rule.scopePath || "未限定知识节点")}</strong><span>${escapeHtml((rule.questionTypes || []).length ? `题型：${rule.questionTypes.join("、")}` : "适用全部题型")}</span><small>优先级：${escapeHtml(teachingRulePriorityLabels[rule.priority] || "中")}</small></div></td>
      <td><div class="teaching-rule-source-cell"><strong>${escapeHtml(`Agent ${String(rule.sourceAgent || "agent2").slice(-1)}`)}</strong><span>${escapeHtml(rule.sourceQuestionId || "人工规则")}</span><small>${escapeHtml(rule.sourceResultId ? "来自巡检复盘" : "直接创建")}</small></div></td>
      <td><div class="teaching-rule-state"><span class="${escapeHtml(teachingRuleStatusClass(rule.status))}">${escapeHtml(teachingRuleStatusLabels[rule.status] || rule.status)}</span><strong>v${escapeHtml(rule.version || 1)}</strong><small>${escapeHtml(formatTaskTime(rule.updatedAt))}</small></div></td>
      <td><button class="secondary-action" data-teaching-rule-id="${escapeHtml(rule.id)}" type="button">${rule.status === "draft" ? "审核" : "查看编辑"}</button></td>
    </tr>`).join("");
}

async function loadTeachingRules() {
  assessmentModeUi().syncManagerLayout();
  const bookId = document.querySelector("#question-book-filter").value || "all";
  const status = document.querySelector("#teaching-rule-status").value;
  const query = document.querySelector("#teaching-rule-search").value.trim();
  try {
    const payload = await requestJson(`/api/admin/knowledge-classification/rules?${new URLSearchParams({ bookId, status, query })}`);
    state.teachingRules = payload.items || [];
    state.teachingRuleSummary = payload.summary || {};
    renderTeachingRuleSummary();
    renderTeachingRuleTable();
    return true;
  } catch (error) {
    document.querySelector("#teaching-rule-table-body").innerHTML = `<tr><td colspan="5" class="question-table-empty">读取失败：${escapeHtml(friendlyError(error))}</td></tr>`;
    return false;
  }
}

function teachingRuleDelimitedValues(value) {
  return [...new Set(String(value || "").split(/[，,\n]/).map((item) => item.trim()).filter(Boolean))];
}

function teachingRuleLineValues(value) {
  return [...new Set(String(value || "").split(/\r?\n/).map((item) => item.trim()).filter(Boolean))];
}

function closeTeachingRuleDialog() {
  const dialog = document.querySelector("#teaching-rule-dialog");
  if (dialog.open) dialog.close();
  state.currentTeachingRule = null;
  setSmallDialogStatus("#teaching-rule-dialog-status");
}

function openTeachingRuleDialog(ruleId) {
  const rule = state.teachingRules.find((item) => item.id === ruleId)
    || state.knowledgeInspectionExperience?.rules?.find((item) => item.id === ruleId);
  if (!rule) return;
  state.currentTeachingRule = rule;
  document.querySelector("#teaching-rule-id").value = rule.id;
  document.querySelector("#teaching-rule-title").value = rule.title || "";
  document.querySelector("#teaching-rule-statement").value = rule.statement || "";
  document.querySelector("#teaching-rule-question-types").value = (rule.questionTypes || []).join("、");
  document.querySelector("#teaching-rule-priority").value = rule.priority || "medium";
  document.querySelector("#teaching-rule-trigger-terms").value = (rule.triggerTerms || []).join("、");
  document.querySelector("#teaching-rule-positive-examples").value = (rule.positiveExamples || []).join("\n");
  document.querySelector("#teaching-rule-negative-examples").value = (rule.negativeExamples || []).join("\n");
  const selected = new Set(rule.scopeNodeIds || []);
  const nodes = state.knowledgeStructure?.nodes || [];
  const knownIds = new Set(nodes.map((node) => node.id));
  document.querySelector("#teaching-rule-scope-nodes").innerHTML = [
    ...nodes.map((node) => `<option value="${escapeHtml(node.id)}" ${selected.has(node.id) ? "selected" : ""}>${escapeHtml(node.path || node.displayTitle || node.title)}</option>`),
    ...[...selected].filter((id) => !knownIds.has(id)).map((id) => `<option value="${escapeHtml(id)}" selected>范围节点 · ${escapeHtml(id)}</option>`),
  ].join("");
  document.querySelector("#teaching-rule-dialog-title").textContent = `${rule.status === "draft" ? "审核" : "编辑"}教研规则`;
  document.querySelector("#teaching-rule-dialog-copy").textContent = `${teachingRuleStatusLabels[rule.status] || "规则"} · v${rule.version || 1} · 只有已启用规则会进入后续巡检`;
  document.querySelector("#teaching-rule-source").innerHTML = `<strong>来源记录</strong><span>${escapeHtml(rule.sourceQuestionId ? `题目 ${rule.sourceQuestionId} · Agent ${String(rule.sourceAgent || "agent2").slice(-1)} 复盘` : "人工规则")}</span><small>${escapeHtml(rule.scopePath || "尚未形成范围说明")} · 共 ${escapeHtml((rule.history || []).length)} 个历史版本</small>`;
  document.querySelector("#deactivate-teaching-rule").hidden = rule.status !== "active";
  document.querySelector("#delete-teaching-rule").hidden = false;
  document.querySelector("#delete-teaching-rule").textContent = "删除规则";
  document.querySelector("#activate-teaching-rule").textContent = rule.status === "active" ? "保存并继续启用" : "批准并启用";
  setSmallDialogStatus("#teaching-rule-dialog-status");
  document.querySelector("#teaching-rule-dialog").showModal();
}

function teachingRuleFormPayload(status) {
  const selectedNodes = [...document.querySelector("#teaching-rule-scope-nodes").selectedOptions].map((option) => option.value);
  const nodeMap = new Map((state.knowledgeStructure?.nodes || []).map((node) => [node.id, node]));
  const resolvedScopePath = selectedNodes.map((id) => nodeMap.get(id)?.path).filter(Boolean).join("；");
  return {
    title: document.querySelector("#teaching-rule-title").value.trim(),
    statement: document.querySelector("#teaching-rule-statement").value.trim(),
    scopeNodeIds: selectedNodes,
    scopePath: selectedNodes.length ? (resolvedScopePath || state.currentTeachingRule?.scopePath || "") : "",
    questionTypes: teachingRuleDelimitedValues(document.querySelector("#teaching-rule-question-types").value),
    triggerTerms: teachingRuleDelimitedValues(document.querySelector("#teaching-rule-trigger-terms").value),
    positiveExamples: teachingRuleLineValues(document.querySelector("#teaching-rule-positive-examples").value),
    negativeExamples: teachingRuleLineValues(document.querySelector("#teaching-rule-negative-examples").value),
    priority: document.querySelector("#teaching-rule-priority").value,
    status,
  };
}

async function updateTeachingRule(requestedStatus) {
  const rule = state.currentTeachingRule;
  if (!rule) return;
  const status = requestedStatus || rule.status;
  const payload = teachingRuleFormPayload(status);
  if (!payload.title || !payload.statement) {
    setSmallDialogStatus("#teaching-rule-dialog-status", "请填写规则名称和执行规则。", "error");
    return;
  }
  if (status === "active" && !payload.scopeNodeIds.length && !payload.triggerTerms.length) {
    setSmallDialogStatus("#teaching-rule-dialog-status", errorLabels.knowledge_classification_rule_scope_required, "error");
    return;
  }
  const buttons = ["#save-teaching-rule", "#activate-teaching-rule", "#deactivate-teaching-rule", "#delete-teaching-rule"].map((selector) => document.querySelector(selector));
  buttons.forEach((button) => { button.disabled = true; });
  setSmallDialogStatus("#teaching-rule-dialog-status", status === "active" ? "正在保存并启用规则" : (status === "inactive" ? "正在停用规则" : "正在保存规则草案"), "loading");
  try {
    await requestJson(`/api/admin/knowledge-classification/rules/${encodeURIComponent(rule.id)}`, { method: "PATCH", body: JSON.stringify(payload) });
    closeTeachingRuleDialog();
    await loadTeachingRules();
    setTeachingRuleFeedback(status === "active" ? "规则已人工批准，将从下一次匹配的巡检开始生效。" : (status === "inactive" ? "规则已停用，后续巡检不会再读取它。" : "规则修改已保存，仍处于待审核状态。"), "success");
  } catch (error) {
    setSmallDialogStatus("#teaching-rule-dialog-status", `保存失败：${friendlyError(error)}`, "error");
  } finally {
    buttons.forEach((button) => { button.disabled = false; });
  }
}

async function deleteTeachingRule() {
  const rule = state.currentTeachingRule;
  if (!rule) return;
  const statusLabel = teachingRuleStatusLabels[rule.status] || rule.status || "当前";
  const activeImpact = rule.status === "active" ? "该规则目前正在使用，删除后后续巡检将立即停止读取它。\n\n" : "";
  if (!window.confirm(`确定删除${statusLabel}规则“${rule.title}”吗？\n\n${activeImpact}删除时的规则快照和本次操作会保留在审计记录中，但规则本身无法继续编辑或启用。`)) return;
  const button = document.querySelector("#delete-teaching-rule");
  button.disabled = true;
  setSmallDialogStatus("#teaching-rule-dialog-status", "正在删除规则", "loading");
  try {
    await requestJson(`/api/admin/knowledge-classification/rules/${encodeURIComponent(rule.id)}`, {
      method: "DELETE",
      body: JSON.stringify({ reason: "管理员在规则详情中二次确认删除" }),
    });
    closeTeachingRuleDialog();
    await loadTeachingRules();
    setTeachingRuleFeedback(`“${rule.title}”已删除，审计记录已保留。`, "success");
  } catch (error) {
    setSmallDialogStatus("#teaching-rule-dialog-status", `删除失败：${friendlyError(error)}`, "error");
  } finally {
    button.disabled = false;
  }
}

async function reviewExperienceRule(ruleId) {
  closeKnowledgeInspectionDialog();
  setQuestionLibraryTab("rules");
  await loadTeachingRules();
  openTeachingRuleDialog(ruleId);
}

function questionFamilyCounts(family, field, values) {
  return Object.fromEntries(values.map((value) => [value, family.members.filter((member) => member[field] === value).length]));
}

function questionFamilyMemberReviewStatus(member = {}, family = {}) {
  const status = String(member.reviewStatus || "");
  if (Object.prototype.hasOwnProperty.call(questionFamilyMemberReviewStatusLabels, status)) return status;
  return family.status === "pending_review" ? "pending_fit" : "confirmed";
}

function questionFamilyMemberReviewCounts(family = {}) {
  const counts = { confirmed: 0, pending_fit: 0, inactive: 0 };
  (family.members || []).forEach((member) => {
    const status = questionFamilyMemberReviewStatus(member, family);
    counts[status] = (counts[status] || 0) + 1;
  });
  return counts;
}

function questionFamilyMatchesMemberReviewFilter(family = {}, filter = "all") {
  if (filter === "all") return true;
  return (family.members || []).some((member) => questionFamilyMemberReviewStatus(member, family) === filter);
}

function questionFamilyMemberReviewActionsHtml(member = {}, family = {}) {
  if (questionFamilyMemberReviewStatus(member, family) !== "pending_fit") return "";
  return `<div class="question-family-member-review-actions">
    <button class="secondary-action" data-question-family-member-review="confirmed" data-family-id="${escapeHtml(family.id)}" data-question-id="${escapeHtml(member.questionId)}" type="button">确认归属</button>
    <button class="question-delete-action" data-question-family-member-review="rejected" data-family-id="${escapeHtml(family.id)}" data-question-id="${escapeHtml(member.questionId)}" type="button">驳回归属</button>
  </div>`;
}

function questionFamilyMembershipsHtml(question, currentFamilyId = "") {
  const memberships = Array.isArray(question.familyMemberships) ? question.familyMemberships : [];
  if (!memberships.length) return '<div class="question-family-preview-memberships is-empty"><b>题族归属</b><span>未归档</span></div>';
  const visible = memberships.slice(0, 4);
  return `<div class="question-family-preview-memberships"><b>题族归属</b>${visible.map((membership) => {
    const reviewStatus = questionFamilyMemberReviewStatus(membership, { status: membership.familyStatus || membership.status });
    const reviewLabel = reviewStatus === "confirmed" ? "" : ` · ${questionFamilyMemberReviewStatusLabels[reviewStatus]}`;
    return `<span class="${membership.familyId === currentFamilyId ? "is-current" : ""} ${membership.isPrimary ? "is-primary" : ""} is-member-${escapeHtml(reviewStatus)}" title="${escapeHtml(`${membership.knowledgePath || membership.familyName || ""}${reviewLabel}`)}">${escapeHtml(`${membership.isPrimary ? "主 · " : ""}${membership.familyName || membership.familyId}${reviewLabel}`)}</span>`;
  }).join("")}${memberships.length > visible.length ? `<em>另有 ${memberships.length - visible.length} 个</em>` : ""}</div>`;
}

function questionFamilyVisibleQuestions() {
  const byId = new Map();
  (state.ungroupedQuestions || []).forEach((question) => byId.set(question.id, question));
  (state.questionFamilies || []).forEach((family) => {
    (family.members || []).forEach((member) => {
      if (Array.isArray(family.workspaceMemberIds) && !family.workspaceMemberIds.includes(member.questionId)) return;
      if (member.question?.id) byId.set(member.question.id, member.question);
    });
  });
  return [...byId.values()];
}

function clearQuestionFamilyManagementSelection() {
  state.questionSelectedIds = [];
  state.questionFamilySelectionSources = {};
}

function selectedQuestionFamilySourceIds() {
  return [...new Set(state.questionSelectedIds
    .map((questionId) => state.questionFamilySelectionSources[questionId])
    .filter(Boolean))];
}

function movableQuestionFamilySourceId() {
  const sourceIds = selectedQuestionFamilySourceIds();
  if (sourceIds.length !== 1 || sourceIds[0] === "__ungrouped__") return "";
  if (state.questionSelectedIds.some((questionId) => state.questionFamilySelectionSources[questionId] !== sourceIds[0])) return "";
  return sourceIds[0];
}

function renderQuestionFamilyManagement() {
  const button = document.querySelector("#toggle-question-family-management");
  const toolbar = document.querySelector("#question-family-batch-toolbar");
  const panel = document.querySelector("#question-family-panel");
  if (!button || !toolbar || !panel) return;
  const active = state.questionFamilyManagementMode && !button.hidden;
  button.classList.toggle("is-active", active);
  button.textContent = active ? "完成" : "管理";
  button.setAttribute("aria-pressed", String(active));
  panel.classList.toggle("is-managing", active);
  toolbar.hidden = !active;
  if (!active) return;
  const selectedCount = state.questionSelectedIds.length;
  document.querySelector("#question-family-selected-count").textContent = `已选 ${selectedCount} 道题`;
  document.querySelector("#group-selected-questions").disabled = selectedCount === 0;
  const moveButton = document.querySelector("#move-selected-questions");
  const sourceFamilyId = movableQuestionFamilySourceId();
  const sourceFamily = state.questionFamilies.find((family) => family.id === sourceFamilyId);
  moveButton.disabled = !sourceFamilyId;
  moveButton.title = sourceFamilyId ? `从“${sourceFamily?.name || "当前题族"}”移动所选题目` : "移动仅支持同一题族内勾选的题目";
  const selectionCopy = document.querySelector("#question-family-selection-copy");
  if (!selectedCount) selectionCopy.textContent = "勾选属于同一题族的题目，再一次完成归组";
  else if (sourceFamilyId) selectionCopy.textContent = `可保留原关系归入其他题族，或从“${sourceFamily?.name || "当前题族"}”整体移动`;
  else selectionCopy.textContent = "跨题族或未成族混选时只能归入；移动需在同一题族内勾选";
  document.querySelectorAll("#question-family-table-body [data-question-family-select]").forEach((checkbox) => {
    const selected = state.questionSelectedIds.includes(checkbox.dataset.questionFamilySelect);
    checkbox.checked = selected;
    checkbox.closest(".question-family-preview")?.classList.toggle("is-selected", selected);
  });
}

function setQuestionFamilyManagementMode(active) {
  state.questionFamilyManagementMode = Boolean(active);
  clearQuestionFamilyManagementSelection();
  if (state.questionFamilyManagementMode) state.expandedQuestionFamilyIds.add("__ungrouped__");
  renderQuestionFamilyTable();
}

function setQuestionFamilyQuestionSelected(questionId, selected, sourceFamilyId = "") {
  const ids = new Set(state.questionSelectedIds);
  const sources = { ...state.questionFamilySelectionSources };
  if (selected) {
    ids.add(questionId);
    sources[questionId] = String(sourceFamilyId || "");
  } else {
    ids.delete(questionId);
    delete sources[questionId];
  }
  state.questionSelectedIds = [...ids];
  state.questionFamilySelectionSources = sources;
  renderQuestionFamilyManagement();
}

function questionFamilyPreviewHtml(question, options = {}) {
  const member = options.member || {};
  const family = options.family || {};
  const memberReviewStatus = options.ungrouped ? "" : questionFamilyMemberReviewStatus(member, family);
  const roleLabel = options.ungrouped ? "未成族" : (questionFamilyRoleLabels[member.role] || member.role || "题族成员");
  const levelLabel = options.ungrouped ? "待归组" : (trainingLevelLabels[member.trainingLevel] || member.trainingLevel || "未定层级");
  const selectable = state.questionFamilyManagementMode;
  const selected = state.questionSelectedIds.includes(question.id);
  const sourceFamilyId = options.ungrouped ? "__ungrouped__" : String(options.currentFamilyId || "");
  const selector = selectable ? `<label class="question-family-preview-selector" title="选择这道题"><input type="checkbox" data-question-family-select="${escapeHtml(question.id)}" data-question-family-source="${escapeHtml(sourceFamilyId)}" aria-label="选择题目：${escapeHtml(question.stem || question.id)}" ${selected ? "checked" : ""} /></label>` : "";
  const memberReviewBadge = memberReviewStatus
    ? `<span class="question-family-member-status is-${escapeHtml(memberReviewStatus)}">${escapeHtml(questionFamilyMemberReviewStatusLabels[memberReviewStatus])}</span>`
    : "";
  const memberReviewActions = options.ungrouped ? "" : questionFamilyMemberReviewActionsHtml(member, family);
  return `<article class="question-family-preview ${selectable ? "is-selectable" : ""} ${selected ? "is-selected" : ""} ${options.matched ? "is-search-match" : ""} ${memberReviewStatus ? `is-member-${escapeHtml(memberReviewStatus)}` : ""}" data-question-preview-id="${escapeHtml(question.id)}">
    ${selector}
    <div class="question-family-preview-index">${options.index + 1}</div>
    <div class="question-family-preview-main" data-question-open="${escapeHtml(question.id)}" data-question-family-source="${escapeHtml(sourceFamilyId)}" role="button" tabindex="0" title="${selectable ? "选择题目" : "查看并编辑题目"}">
      <div class="question-family-preview-meta"><span>${escapeHtml(roleLabel)}</span><span>${escapeHtml(levelLabel)}</span>${memberReviewBadge}<span class="question-status-badge ${escapeHtml(question.status || "pending_review")}">${escapeHtml(questionStatusLabels[question.status] || question.status || "待复核")}</span><small>${escapeHtml(question.id)}</small></div>
      <strong>${escapeHtml(question.stem || "题目已不存在")}</strong>
      ${questionFamilyMatchedOptionsHtml(question.options)}
      <small>${escapeHtml(question.typeLabel || question.type || "未知题型")} · ${escapeHtml(question.maxScore || 0)} 分 · ${"★".repeat(Number(question.difficultyStars) || 1)} · v${escapeHtml(question.version || 1)} · ${escapeHtml(formatTaskTime(question.updatedAt))}</small>
      ${questionFamilyMembershipsHtml(question, options.currentFamilyId)}
    </div>
    <div class="question-family-preview-actions">${memberReviewActions}${questionActionButtons(question)}</div>
  </article>`;
}

function ungroupedQuestionFamilyHtml() {
  const questions = state.ungroupedQuestions || [];
  if (!questions.length) return "";
  const key = "__ungrouped__";
  const searching = Boolean(normalizeQuestionFamilyWorkspaceQuery(document.querySelector("#question-family-search").value));
  const expanded = searching
    ? state.questionFamilySearchExpandedIds.has(key)
    : state.expandedQuestionFamilyIds.has(key);
  return `<section class="question-family-row question-family-ungrouped ${expanded ? "is-expanded" : ""}" data-question-family-id="${key}">
    <div class="question-family-row-main">
      <button class="question-family-expand" data-question-family-action="toggle" data-id="${key}" type="button" aria-expanded="${expanded}" title="${expanded ? "收起题目" : "展开题目"}"><span>›</span></button>
      <div class="question-family-title"><div class="question-family-title-line"><strong>未归档题目</strong>${searching ? `<span class="question-family-search-match">成员题命中 ${questions.length} 道</span>` : ""}</div><span>尚未建立题族归属关系</span><small>可直接查看和编辑题目，或预览缺失的指纹与题族后人工确认。</small></div>
      <div class="question-family-structure"><strong>${questions.length} 道</strong><span>不复制题目，仅展示未建立题族关系的真实题目</span></div>
      <div class="question-family-state"><strong class="medium">待处理</strong><span class="pending_review">未归档</span></div>
      <button class="secondary-action question-family-review" data-question-family-action="generate" type="button">重新归组</button>
    </div>
    <div class="question-family-preview-list" ${expanded ? "" : "hidden"}>
      <div class="question-family-preview-head"><span>${searching ? `搜索命中 ${questions.length} 道题` : `未归档题目 ${questions.length} 道`}</span><small>编辑后仍保留同一题目 ID 与版本链</small></div>
      ${questions.map((question, index) => questionFamilyPreviewHtml(question, { index, ungrouped: true, currentFamilyId: "__ungrouped__", matched: searching })).join("")}
    </div>
  </section>`;
}

function renderQuestionFamilySummary() {
  const summary = state.questionFamilySummary || {};
  const pendingMemberCount = summary.pendingMemberCount ?? state.questionFamilies.reduce((total, family) => total + questionFamilyMemberReviewCounts(family).pending_fit, 0);
  const metrics = [
    ["题族集", summary.familySetCount ?? state.questionFamilySets.length],
    ["候选题族", summary.total || 0],
    ["待审核", summary.pending || 0],
    ["已确认", summary.confirmed || 0],
    ["成员归属待审", pendingMemberCount],
    ["已归组题目", summary.confirmedTopicQuestionCount ?? summary.questionCount ?? 0],
    ["待归组题目", summary.pendingGroupingQuestionCount || 0],
    ["未归档", summary.unresolvedQuestionCount || 0],
  ];
  document.querySelector("#question-family-summary").innerHTML = metrics.map(([label, value]) => `
    <div class="question-family-metric"><strong>${escapeHtml(value)}</strong><span>${escapeHtml(label)}</span></div>
  `).join("");
  document.querySelector("#question-family-summary").title = "所选科目、教材范围统计；当前五项筛选命中数量见列表上方。未归档指没有任何题族关系。";
  renderQuestionFamilyScopeSummary();
}

function renderQuestionFamilyScopeSummary() {
  const element = document.querySelector("#question-family-scope-summary");
  if (!element) return;
  const treeSummary = state.questionFamilyCatalogTreeSummary || {};
  const formalCount = state.selectedKnowledgeNodeId
    ? Number(treeSummary.nodeQuestionCounts?.[state.selectedKnowledgeNodeId] || 0)
    : Number(treeSummary.questionCount || 0);
  const currentQuestionCount = new Set(state.questionFamilies.flatMap((family) => (family.members || [])
    .map((member) => member.questionId).filter(Boolean))).size;
  const ungroupedCount = (state.ungroupedQuestions || []).length;
  const ungroupedLabel = state.selectedKnowledgeNodeId
    ? `本目录（含下级）未成族 ${ungroupedCount} 道 · `
    : "";
  const matchedCount = new Set(state.questionFamilies.flatMap(family => family.workspaceMemberIds || family.members.map(member => member.questionId))).size;
  element.textContent = `当前筛选：${state.questionFamilies.length} 个题族 · ${matchedCount} 道成员题 · ${ungroupedCount} 道未归档`;
  element.title = `${ungroupedLabel}左侧目录 ${formalCount} 道正式投影（已确认定义和归属、含下级、去重）；这些题族完整成员共 ${currentQuestionCount} 道。`;
}

function questionFamilySetItems(set, type) {
  return (Array.isArray(set?.items) ? set.items : [])
    .filter((item) => item?.type === type && item.id)
    .sort((left, right) => Number(left.orderIndex || 0) - Number(right.orderIndex || 0));
}

function questionFamilySetMaps() {
  const setById = new Map(state.questionFamilySets.map((set) => [set.id, set]));
  const familyParent = new Map();
  const setParent = new Map();
  state.questionFamilySets.forEach((set) => {
    if (set.parentSetId) setParent.set(set.id, set.parentSetId);
    questionFamilySetItems(set, "family").forEach((item) => familyParent.set(item.id, set.id));
    questionFamilySetItems(set, "set").forEach((item) => setParent.set(item.id, set.id));
  });
  return { setById, familyParent, setParent };
}

function questionFamilySetScopeNodeIds() {
  if (!state.selectedKnowledgeNodeId) return null;
  const childrenByParent = new Map();
  (state.knowledgeStructure?.nodes || []).forEach((node) => {
    const parentId = String(node.parentId || "");
    if (!childrenByParent.has(parentId)) childrenByParent.set(parentId, []);
    childrenByParent.get(parentId).push(node.id);
  });
  const result = new Set([state.selectedKnowledgeNodeId]);
  const pending = [state.selectedKnowledgeNodeId];
  while (pending.length) {
    (childrenByParent.get(pending.shift()) || []).forEach((id) => {
      if (result.has(id)) return;
      result.add(id);
      pending.push(id);
    });
  }
  return result;
}

function normalizeQuestionFamilyWorkspaceQuery(query = "") {
  return String(query || "").trim().toLocaleLowerCase("zh-CN");
}

function syncQuestionFamilySearchView(query = "") {
  const normalized = normalizeQuestionFamilyWorkspaceQuery(query);
  if (state.questionFamilySearchQuery === normalized) return normalized;
  state.questionFamilySearchQuery = normalized;
  state.questionFamilySearchExpandedIds.clear();
  state.questionFamilySearchShowAllIds.clear();
  return normalized;
}

function questionMatchesFamilyWorkspaceQuery(question, query) {
  if (!query || !question) return false;
  return [
    question.id,
    question.stem,
    ...(question.options || []).map((option) => option.text),
  ].filter(Boolean).join(" ").toLocaleLowerCase("zh-CN").includes(query);
}

function questionFamilySearchMatchInfo(family, query) {
  const normalized = normalizeQuestionFamilyWorkspaceQuery(query);
  if (!normalized) return {
    matched: true,
    priority: 0,
    score: 0,
    reasonLabel: "",
    questionIds: new Set(),
    questionCount: 0,
  };
  const searchMatch = family.searchMatch && typeof family.searchMatch === "object" ? family.searchMatch : {};
  const metadataFields = new Set((Array.isArray(searchMatch.metadataFields) ? searchMatch.metadataFields : []).map((field) => String(field)));
  const fields = new Set([
    ...(Array.isArray(searchMatch.fields) ? searchMatch.fields : []),
    ...metadataFields,
  ].map((field) => String(field)));
  const includes = (value) => String(value || "").toLocaleLowerCase("zh-CN").includes(normalized);
  const nameMatched = searchMatch.kind === "family_name" || fields.has("name") || includes(family.name);
  const pathFieldNames = ["knowledgePath", "primaryKnowledgePoint", "chapter"];
  const pathMatched = pathFieldNames.some((field) => fields.has(field))
    || [family.knowledgePath, family.primaryKnowledgePoint, family.chapter].some(includes);
  const familyMetadataFieldNames = ["id", "reason", "assessmentAction", "inclusionBoundary", "exclusionBoundary", "coreKnowledgeNodeId", "requiredKnowledgeNodeIds", "textbookAnchorNodeIds"];
  const backendMemberOnly = searchMatch.kind === "member_question" && metadataFields.size === 0;
  const genericMetadataMatched = !backendMemberOnly && (
    [family.id, family.reason, family.assessmentAction, family.inclusionBoundary, family.exclusionBoundary].some(includes)
      || familyMetadataFieldNames.some((field) => metadataFields.has(field))
      || ["family_metadata", "mixed"].includes(searchMatch.kind)
  );
  const questionIds = new Set([
    ...(Array.isArray(searchMatch.questionIds) ? searchMatch.questionIds : []),
    ...(family.matchedQuestions || []).map((question) => question?.id),
    ...(family.members || [])
      .filter((member) => questionMatchesFamilyWorkspaceQuery(member.question, normalized))
      .map((member) => member.questionId || member.question?.id),
  ].filter(Boolean).map(String));
  const questionCount = Math.max(questionIds.size, Number(searchMatch.questionCount) || 0);
  const metadataMatched = nameMatched || pathMatched || genericMetadataMatched;
  const matched = metadataMatched || questionCount > 0 || Boolean(searchMatch.kind);
  const priority = nameMatched ? 4 : (pathMatched ? 3 : (genericMetadataMatched ? 2 : (questionCount ? 1 : 0)));
  const score = Number.isFinite(Number(searchMatch.score))
    ? Number(searchMatch.score)
    : priority * 100 + Math.min(questionCount, 99);
  let reasonLabel = "所属题族集命中";
  if (nameMatched) reasonLabel = "题族名称命中";
  else if (pathMatched) reasonLabel = "知识路径命中";
  else if (genericMetadataMatched) reasonLabel = "题族信息命中";
  else if (questionCount) reasonLabel = `成员题命中 ${questionCount} 道`;
  if (metadataMatched && questionCount) reasonLabel += ` · 成员题 ${questionCount} 道`;
  return { matched, priority, score, reasonLabel, questionIds, questionCount };
}

function compareQuestionFamilySearchMatches(left, right) {
  if (left.priority !== right.priority) return right.priority - left.priority;
  if (left.score !== right.score) return right.score - left.score;
  return 0;
}

function questionFamilySetSearchOrder(setId, context, trail = new Set()) {
  if (context.setSearchOrderCache.has(setId)) return context.setSearchOrderCache.get(setId);
  if (trail.has(setId)) return { priority: 0, score: 0 };
  const set = context.maps.setById.get(setId);
  if (!set) return { priority: 0, score: 0 };
  const nextTrail = new Set(trail).add(setId);
  const includes = (value) => String(value || "").toLocaleLowerCase("zh-CN").includes(context.query);
  let best = includes(set.name)
    ? { priority: 5, score: 500 }
    : (includes(set.knowledgePath) ? { priority: 4, score: 400 } : (includes(set.description) ? { priority: 2, score: 200 } : { priority: 0, score: 0 }));
  const consider = (candidate) => {
    if (compareQuestionFamilySearchMatches(best, candidate) > 0) best = candidate;
  };
  questionFamilySetItems(set, "family").forEach((item) => consider(context.familySearchInfoById.get(item.id) || { priority: 0, score: 0 }));
  const childIds = new Set([
    ...questionFamilySetItems(set, "set").map((item) => item.id),
    ...state.questionFamilySets.filter((candidate) => context.maps.setParent.get(candidate.id) === setId).map((candidate) => candidate.id),
  ]);
  childIds.forEach((childId) => consider(questionFamilySetSearchOrder(childId, context, nextTrail)));
  context.setSearchOrderCache.set(setId, best);
  return best;
}

function questionFamilySetItemSearchOrder(item, context) {
  return item.type === "set"
    ? questionFamilySetSearchOrder(item.id, context)
    : (context.familySearchInfoById.get(item.id) || { priority: 0, score: 0 });
}

function questionFamilyMatchesWorkspaceQuery(family, query) {
  return !query || questionFamilySearchMatchInfo(family, query).matched;
}

function questionFamilyRowHtml(family, options = {}) {
  const reviewCounts = questionFamilyMemberReviewCounts(family);
  const confirmedMembers = (family.members || []).filter((member) => questionFamilyMemberReviewStatus(member, family) === "confirmed");
  const formalFamily = { ...family, members: confirmedMembers };
  const roleCounts = questionFamilyCounts(formalFamily, "role", Object.keys(questionFamilyRoleLabels));
  const levelCounts = questionFamilyCounts(formalFamily, "trainingLevel", Object.keys(trainingLevelLabels));
  const confidenceTone = family.confidence >= 0.85 ? "high" : (family.confidence >= 0.7 ? "medium" : "low");
  const confidenceLabel = family.source === "manual_empty_family" ? "人工" : `${Math.round(family.confidence * 100)}%`;
  const requiredPaths = (family.coverageKnowledgeNodes || family.requiredKnowledgeNodes || []).map((node) => node.path || node.displayTitle || node.title).filter(Boolean);
  const query = normalizeQuestionFamilyWorkspaceQuery(options.query || document.querySelector("#question-family-search")?.value);
  const searching = Boolean(query);
  const searchInfo = options.searchInfo || questionFamilySearchMatchInfo(family, query);
  const matchedIds = searchInfo.questionIds;
  const members = Array.isArray(family.members) ? family.members : [];
  const workspaceMemberIds = Array.isArray(family.workspaceMemberIds) ? new Set(family.workspaceMemberIds) : null;
  const filteredMembers = workspaceMemberIds ? members.filter(member => workspaceMemberIds.has(member.questionId)) : members;
  const singletonLabel = confirmedMembers.length === 1
    ? (family.status === "confirmed" ? "单题待扩充" : "样本不足")
    : "";
  const matchedMembers = filteredMembers.filter((member) => matchedIds.has(String(member.questionId || member.question?.id || "")));
  const unmatchedMembers = filteredMembers.filter((member) => !matchedIds.has(String(member.questionId || member.question?.id || "")));
  const showAllMembers = searching && state.questionFamilySearchShowAllIds.has(family.id);
  const visibleMembers = searching && !showAllMembers ? matchedMembers : [...matchedMembers, ...unmatchedMembers];
  const expanded = searching
    ? state.questionFamilySearchExpandedIds.has(family.id)
    : state.expandedQuestionFamilyIds.has(family.id);
  const membersHtml = visibleMembers.length ? visibleMembers.map((member, index) => questionFamilyPreviewHtml(member.question || {}, {
    index,
    member,
    family,
    currentFamilyId: family.id,
    matched: matchedIds.has(String(member.questionId || member.question?.id || "")),
  })).join("") : (members.length
    ? '<div class="question-family-preview-empty"><strong>题族信息已命中</strong><span>当前成员题没有直接命中关键词，可查看全部成员继续核对。</span></div>'
    : '<div class="question-family-preview-empty"><strong>空题族</strong><span>尚未加入题目，可进入调整后添加成员。</span></div>');
  const memberReviewCopy = `正式 ${reviewCounts.confirmed} · 待审 ${reviewCounts.pending_fit}${reviewCounts.inactive ? ` · 已失效 ${reviewCounts.inactive}` : ""}`;
  const previewLabel = searching
    ? (showAllMembers ? `筛选内成员 ${filteredMembers.length} 道 · 命中 ${matchedMembers.length} 道` : (matchedMembers.length ? `成员题命中 ${matchedMembers.length} 道` : "没有成员题直接命中"))
    : `筛选内 ${filteredMembers.length} 道 / 全族 ${members.length} 道 · ${memberReviewCopy}`;
  const memberToggle = searching && filteredMembers.length > matchedMembers.length
    ? `<button class="question-family-member-visibility" data-question-family-action="show-all-members" data-id="${escapeHtml(family.id)}" type="button">${showAllMembers ? "仅看命中题" : `查看全部 ${filteredMembers.length} 道`}</button>`
    : "";
  const definitionStatusLabel = questionFamilyStatusLabels[family.status] || family.status;
  const combinedStatusLabel = family.status === "confirmed" && reviewCounts.pending_fit
    ? `${definitionStatusLabel} · ${reviewCounts.pending_fit} 个成员待审`
    : definitionStatusLabel;
  return `<section class="question-family-row ${options.inSet ? "is-in-family-set" : ""} ${expanded ? "is-expanded" : ""} ${reviewCounts.pending_fit ? "has-pending-members" : ""}" data-question-family-id="${escapeHtml(family.id)}">
    <div class="question-family-row-main">
      <button class="question-family-expand" data-question-family-action="toggle" data-id="${escapeHtml(family.id)}" type="button" aria-expanded="${expanded}" title="${expanded ? "收起题目" : "展开题目"}"><span>›</span></button>
      <div class="question-family-title"><div class="question-family-title-line"><em>题族</em><strong>${escapeHtml(family.name)}</strong>${searching ? `<span class="question-family-search-match">${escapeHtml(searchInfo.reasonLabel)}</span>` : ""}</div><span>${escapeHtml(family.knowledgePath || `${family.primaryKnowledgePoint} · ${family.chapter}`)}</span>${options.parentSetName ? `<small class="question-family-parent-set">所属题族集：${escapeHtml(options.parentSetName)}</small>` : ""}${requiredPaths.length > 1 ? `<small class="question-family-required-paths">最小充分知识集：${escapeHtml(requiredPaths.join(" · "))}</small>` : ""}<small>${escapeHtml(family.reason)}</small></div>
      <div class="question-family-structure"><strong>${confirmedMembers.length} 道正式成员</strong><span>原型 ${roleCounts.prototype} · 同类 ${roleCounts.similar} · 变式 ${roleCounts.variant}</span><div class="question-family-tags"><span class="foundation">基础 ${levelCounts.foundation}</span><span class="advanced">拔高 ${levelCounts.advanced}</span><span class="transfer">迁移 ${levelCounts.transfer}</span></div>${reviewCounts.pending_fit ? `<small class="question-family-pending-member-copy">另有 ${reviewCounts.pending_fit} 个成员归属待审核</small>` : ""}</div>
      <div class="question-family-state"><strong class="${confidenceTone}">${escapeHtml(confidenceLabel)}</strong><span class="${escapeHtml(family.status)}">${escapeHtml(combinedStatusLabel)}</span><small class="question-family-member-state-copy">定义：${escapeHtml(definitionStatusLabel)} · 成员：${escapeHtml(memberReviewCopy)}</small>${singletonLabel ? `<small class="question-family-sample-warning">${escapeHtml(singletonLabel)}</small>` : ""}</div>
      <button class="secondary-action question-family-review" data-question-family-action="review" data-id="${escapeHtml(family.id)}" type="button">${family.status === "pending_review" ? "审核" : "查看 / 调整"}</button>
    </div>
    <div class="question-family-preview-list" ${expanded ? "" : "hidden"}>
      <div class="question-family-preview-head"><span>${escapeHtml(previewLabel)}</span><div><small>题目只保存一份，此处展示题族归属关系</small>${memberToggle}</div></div>
      ${membersHtml}
    </div>
  </section>`;
}

function questionFamilySetDescendantFamilyIds(setId, maps, seen = new Set()) {
  if (!setId || seen.has(setId)) return new Set();
  seen.add(setId);
  const set = maps.setById.get(setId);
  const ids = new Set(questionFamilySetItems(set, "family").map((item) => item.id));
  const childIds = new Set([
    ...questionFamilySetItems(set, "set").map((item) => item.id),
    ...state.questionFamilySets.filter((candidate) => candidate.parentSetId === setId).map((candidate) => candidate.id),
  ]);
  childIds.forEach((childId) => questionFamilySetDescendantFamilyIds(childId, maps, seen).forEach((id) => ids.add(id)));
  return ids;
}

function questionFamilySetRowHtml(setId, context, depth = 0) {
  if (depth > 12 || context.renderedSetIds.has(setId)) return "";
  const set = context.maps.setById.get(setId);
  if (!set || !context.visibleSetIds.has(setId)) return "";
  context.renderedSetIds.add(setId);
  const expanded = state.expandedQuestionFamilySetIds.has(set.id) || Boolean(context.query);
  const directItems = [...(set.items || [])].sort((left, right) => Number(left.orderIndex || 0) - Number(right.orderIndex || 0));
  const listedChildIds = new Set(directItems.filter((item) => item.type === "set").map((item) => item.id));
  state.questionFamilySets.filter((candidate) => candidate.parentSetId === set.id && !listedChildIds.has(candidate.id))
    .forEach((candidate) => directItems.push({ type: "set", id: candidate.id, orderIndex: Number.MAX_SAFE_INTEGER }));
  if (context.query) directItems.sort((left, right) => compareQuestionFamilySearchMatches(
    questionFamilySetItemSearchOrder(left, context),
    questionFamilySetItemSearchOrder(right, context),
  ));
  const childrenHtml = directItems.map((item) => {
    if (item.type === "set") return questionFamilySetRowHtml(item.id, context, depth + 1);
    const family = context.familyById.get(item.id);
    return family && context.visibleFamilyIds.has(family.id)
      ? questionFamilyRowHtml(family, { inSet: true, parentSetName: set.name, query: context.query, searchInfo: context.familySearchInfoById.get(family.id) })
      : "";
  }).join("");
  return `<section class="question-family-set-row ${expanded ? "is-expanded" : ""}" data-question-family-set-id="${escapeHtml(set.id)}" style="--family-set-depth:${Math.min(depth, 8)}">
    <div class="question-family-set-row-main">
      <button class="question-family-set-expand" data-question-family-set-action="toggle" data-id="${escapeHtml(set.id)}" type="button" aria-expanded="${expanded}" title="${expanded ? "收起题族集" : "展开题族集"}"><span>›</span></button>
      <div class="question-family-set-title"><div><em>题族集</em><strong>${escapeHtml(set.name)}</strong></div><span>${escapeHtml(set.knowledgePath || "未标注教材位置")}</span>${set.description ? `<small>${escapeHtml(set.description)}</small>` : ""}</div>
      <div class="question-family-set-counts"><strong>${escapeHtml(set.familyCount || 0)} 个题族</strong><span>直属 ${escapeHtml(set.directFamilyCount || 0)} 个 · 下级集 ${escapeHtml(set.setCount || 0)} 个</span></div>
      <div class="question-family-set-state"><strong>${escapeHtml(set.questionCount || 0)} 道</strong><span>按题目 ID 去重</span></div>
      <button class="secondary-action question-family-set-review" data-question-family-set-action="edit" data-id="${escapeHtml(set.id)}" type="button">查看 / 调整</button>
    </div>
    <div class="question-family-set-children" ${expanded ? "" : "hidden"}>${childrenHtml || '<div class="question-family-set-empty">当前题族集还没有可见内容</div>'}</div>
  </section>`;
}

function renderQuestionFamilyTable() {
  const body = document.querySelector("#question-family-table-body");
  if (!state.questionFamilies.length && !state.questionFamilySets.length && !state.ungroupedQuestions.length) {
    body.innerHTML = '<div class="question-table-empty">当前筛选下没有题族。可新建题族集、空题族，或按知识指纹生成候选题族。</div>';
    renderQuestionFamilyManagement();
    return;
  }
  const query = syncQuestionFamilySearchView(document.querySelector("#question-family-search").value);
  const maps = questionFamilySetMaps();
  const familyById = new Map(state.questionFamilies.map((family) => [family.id, family]));
  const familySearchInfoById = new Map(state.questionFamilies.map((family) => [family.id, questionFamilySearchMatchInfo(family, query)]));
  const scopeNodeIds = questionFamilySetScopeNodeIds();
  const scopedSetIds = new Set(state.questionFamilySets
    .filter((set) => !scopeNodeIds || scopeNodeIds.has(set.knowledgeNodeId))
    .map((set) => set.id));
  const matchedSetIds = new Set(state.questionFamilySets
    .filter((set) => scopedSetIds.has(set.id) && (!query || `${set.name} ${set.description || ""} ${set.knowledgePath || ""}`.toLocaleLowerCase("zh-CN").includes(query)))
    .map((set) => set.id));
  const visibleFamilyIds = new Set(state.questionFamilies
    .filter((family) => !query || familySearchInfoById.get(family.id).matched)
    .map((family) => family.id));
  if (query) matchedSetIds.forEach((setId) => questionFamilySetDescendantFamilyIds(setId, maps).forEach((familyId) => {
    if (familyById.has(familyId)) visibleFamilyIds.add(familyId);
  }));
  else state.questionFamilies.forEach((family) => visibleFamilyIds.add(family.id));

  const visibleSetIds = query ? new Set(matchedSetIds) : new Set(scopedSetIds);
  if (query) {
    state.questionFamilySets.forEach((set) => {
      if (!scopedSetIds.has(set.id)) return;
      if (questionFamilySetItems(set, "family").some((item) => visibleFamilyIds.has(item.id))) visibleSetIds.add(set.id);
    });
    let changed = true;
    while (changed) {
      changed = false;
      [...visibleSetIds].forEach((setId) => {
        const parentId = maps.setParent.get(setId);
        if (parentId && scopedSetIds.has(parentId) && !visibleSetIds.has(parentId)) {
          visibleSetIds.add(parentId);
          changed = true;
        }
      });
    }
    matchedSetIds.forEach((setId) => {
      const pending = [setId];
      while (pending.length) {
        const parent = pending.shift();
        state.questionFamilySets.filter((candidate) => maps.setParent.get(candidate.id) === parent && scopedSetIds.has(candidate.id)).forEach((candidate) => {
          if (visibleSetIds.has(candidate.id)) return;
          visibleSetIds.add(candidate.id);
          pending.push(candidate.id);
        });
      }
    });
  }

  const renderedSetIds = new Set();
  const context = {
    maps,
    familyById,
    familySearchInfoById,
    visibleFamilyIds,
    visibleSetIds,
    renderedSetIds,
    setSearchOrderCache: new Map(),
    query,
  };
  const rootSets = state.questionFamilySets.filter((set) => visibleSetIds.has(set.id) && !visibleSetIds.has(maps.setParent.get(set.id)));
  const looseFamilies = state.questionFamilies.filter((family) => visibleFamilyIds.has(family.id) && !visibleSetIds.has(maps.familyParent.get(family.id)));
  let rowsHtml = "";
  if (query) {
    const searchRows = [
      ...(state.ungroupedQuestions.length ? [{ type: "ungrouped", order: { priority: 1, score: state.ungroupedQuestions.length } }] : []),
      ...rootSets.map((set) => ({ type: "set", value: set, order: questionFamilySetSearchOrder(set.id, context) })),
      ...looseFamilies.map((family) => ({ type: "family", value: family, order: familySearchInfoById.get(family.id) })),
    ].sort((left, right) => compareQuestionFamilySearchMatches(left.order, right.order));
    rowsHtml = searchRows.map((row) => {
      if (row.type === "ungrouped") return ungroupedQuestionFamilyHtml();
      if (row.type === "set") return questionFamilySetRowHtml(row.value.id, context);
      return questionFamilyRowHtml(row.value, {
        parentSetName: maps.setById.get(maps.familyParent.get(row.value.id))?.name || "",
        query,
        searchInfo: familySearchInfoById.get(row.value.id),
      });
    }).join("");
  } else {
    rowsHtml = `${ungroupedQuestionFamilyHtml()}${rootSets.map((set) => questionFamilySetRowHtml(set.id, context)).join("")}${looseFamilies.map((family) => questionFamilyRowHtml(family, { parentSetName: maps.setById.get(maps.familyParent.get(family.id))?.name || "" })).join("")}`;
  }
  body.innerHTML = rowsHtml || '<div class="question-table-empty">没有匹配的题族集、题族或题目。</div>';
  renderQuestionFamilyManagement();
}

function questionFamilyMatchedOptionsHtml(options = []) {
  const items = (Array.isArray(options) ? options : []).filter((option) => option?.text);
  if (!items.length) return "";
  return `<div class="question-option-list compact">${items.map((option, index) => `<div class="question-option-item"><b>${escapeHtml(option.key || String.fromCharCode(65 + index))}</b><span>${escapeHtml(option.text)}</span></div>`).join("")}</div>`;
}

function setQuestionFamilyFeedback(message = "", tone = "") {
  const element = document.querySelector("#question-family-feedback");
  element.hidden = !message;
  element.textContent = message;
  element.className = `question-family-feedback${tone ? ` ${tone}` : ""}`;
}

function questionFamilyWorkspaceBookId() {
  const selectedBookId = document.querySelector("#question-book-filter").value;
  return selectedBookId && selectedBookId !== "all" ? selectedBookId : "";
}

async function loadQuestionFamilies() {
  const controller = beginQuestionWorkspaceLoad();
  const loadSequence = Number(state.questionFamilyLoadSequence || 0) + 1;
  state.questionFamilyLoadSequence = loadSequence;
  const isCurrentLoad = () => loadSequence === Number(state.questionFamilyLoadSequence || 0) && !controller.signal.aborted;
  state.questionFamilyCatalogTreeSummary = null;
  state.questionFamilyTreeError = "";
  renderKnowledgeTree();
  try {
    if (libraryWorkspace.needsDirectorySelection()) {
      state.questionFamilies = []; state.questionFamilySets = []; state.ungroupedQuestions = [];
      state.questionSelectedIds = []; state.questionFamilySummary = null; state.questionFamilyCatalogTreeSummary = null;
      renderQuestionFamilySummary(); renderKnowledgeTree(); renderQuestionFamilyTable();
      setQuestionFamilyFeedback("请先选择左侧题库节点；多项映射已高亮，无映射可通过「映射编辑」设置。");
      return false;
    }
    await loadQuestionCatalog();
    if (!isCurrentLoad()) return false;
    const workspaceQuery = document.querySelector("#question-family-search").value.trim();
    const normalizedWorkspaceQuery = workspaceQuery.toLocaleLowerCase("zh-CN");
    const queryMatchesKnownSet = normalizedWorkspaceQuery && state.questionFamilySets.some((set) => `${set.name} ${set.description || ""} ${set.knowledgePath || ""}`.toLocaleLowerCase("zh-CN").includes(normalizedWorkspaceQuery));
    const query = new URLSearchParams({
      ...questionWorkspaceFilters(),
      query: queryMatchesKnownSet ? "" : workspaceQuery,
    });
    const [payload, batchPayload] = await Promise.all([
      requestJson(`/api/admin/question-families?${query}`, { signal: controller.signal }),
      requestJson("/api/admin/questions/import-batches", { signal: controller.signal }),
    ]);
    if (!isCurrentLoad()) return false;
    state.questionImportBatches = batchPayload.batches || [];
    renderQuestionImportBatchFilter();
    state.questionFamilies = payload.families || [];
    state.questionFamilySets = payload.familySets || [];
    state.ungroupedQuestions = queryMatchesKnownSet
      ? (payload.ungroupedQuestions || []).filter((question) => [
        question.id,
        question.stem,
        ...(question.options || []).map((option) => option.text),
      ].filter(Boolean).join(" ").toLocaleLowerCase("zh-CN").includes(normalizedWorkspaceQuery))
      : (payload.ungroupedQuestions || []);
    state.questionFamilySummary = payload.summary || null;
    state.questionFamilyCatalogTreeSummary = payload.catalogTreeSummary || null;
    if (state.questionFamilyManagementMode) {
      const visibleIds = new Set(questionFamilyVisibleQuestions().map((question) => question.id));
      state.questionSelectedIds = state.questionSelectedIds.filter((id) => visibleIds.has(id));
      state.questionFamilySelectionSources = Object.fromEntries(Object.entries(state.questionFamilySelectionSources)
        .filter(([questionId]) => visibleIds.has(questionId)));
    }
    renderQuestionFamilySummary();
    renderKnowledgeTree();
    renderQuestionFamilyTable();
    setQuestionFamilyFeedback();
    return true;
  } catch (error) {
    if (!isCurrentLoad()) return false;
    state.questionFamilyTreeError = "正式投影读取失败，请刷新重试";
    renderKnowledgeTree();
    document.querySelector("#question-family-table-body").innerHTML = `<div class="question-table-empty">读取失败：${escapeHtml(friendlyError(error))}</div>`;
    return false;
  } finally {
    if (isCurrentLoad()) {
      state.questionWorkspaceAbortController = null;
      setQuestionWorkspaceLoading(false);
    }
  }
}

function questionFamilySetsFromPayload(payload = {}) {
  return Array.isArray(payload.familySets) ? payload.familySets : (Array.isArray(payload.sets) ? payload.sets : []);
}

function questionFamilySetFromPayload(payload = {}) {
  return payload.familySet || payload.set || null;
}

function knowledgeNodeContains(ancestorId, nodeId) {
  if (!ancestorId || !nodeId) return false;
  const byId = new Map((state.questionFamilySetStructure?.nodes || state.knowledgeStructure?.nodes || []).map((node) => [node.id, node]));
  let current = byId.get(nodeId);
  while (current) {
    if (current.id === ancestorId) return true;
    current = current.parentId ? byId.get(current.parentId) : null;
  }
  return false;
}

function questionFamilySetItemKey(type, id) {
  return `${type}:${id}`;
}

function selectedQuestionFamilySetItems() {
  return new Set(state.questionFamilySetSelectedItems);
}

function currentQuestionFamilySetItemKeys() {
  return new Set((state.currentQuestionFamilySet?.items || []).map((item) => questionFamilySetItemKey(item.type, item.id)));
}

function questionFamilySetMemberParent(type, id) {
  const maps = questionFamilySetMaps();
  return type === "family" ? maps.familyParent.get(id) : maps.setParent.get(id);
}

function questionFamilySetMemberDetail(type, id) {
  if (type === "family") {
    const catalog = state.questionFamilySetCatalogFamilies.find((family) => family.id === id);
    if (catalog) return catalog;
    for (const set of state.questionFamilySets) {
      const item = questionFamilySetItems(set, "family").find((candidate) => candidate.id === id);
      if (item) return item.family || item;
    }
    return null;
  }
  return state.questionFamilySets.find((set) => set.id === id) || null;
}

function questionFamilySetMemberCardHtml(type, id, options = {}) {
  const item = questionFamilySetMemberDetail(type, id) || { id, name: id };
  const parentId = questionFamilySetMemberParent(type, id);
  const parent = state.questionFamilySets.find((set) => set.id === parentId);
  const typeLabel = type === "family" ? "题族" : "题族集";
  const count = type === "family"
    ? `${Number(item.memberCount || item.members?.length || 0)} 道题`
    : `${Number(item.familyCount || 0)} 个题族 · ${Number(item.questionCount || 0)} 道题`;
  const relation = parentId
    ? (parentId === state.currentQuestionFamilySet?.id ? "当前题族集" : `当前在：${parent?.name || parentId}`)
    : "尚未归入题族集";
  const action = options.current
    ? `<button class="question-family-set-member-remove" data-question-family-set-remove-type="${escapeHtml(type)}" data-question-family-set-remove-id="${escapeHtml(id)}" type="button" title="从题族集中移出" aria-label="从题族集中移出${escapeHtml(item.name || id)}">×</button>`
    : `<input type="checkbox" data-question-family-set-candidate-type="${escapeHtml(type)}" data-question-family-set-candidate-id="${escapeHtml(id)}" ${options.selected ? "checked" : ""} />`;
  const tag = options.current ? "article" : "label";
  return `<${tag} class="question-family-set-member-card ${type === "set" ? "is-set" : ""} ${options.current ? "is-current" : ""}">
    ${action}
    <span class="question-family-set-member-type">${escapeHtml(typeLabel)}</span>
    <span class="question-family-set-member-main"><strong>${escapeHtml(item.name || id)}</strong><small>${escapeHtml(item.knowledgePath || "未标注教材位置")}</small><em>${escapeHtml(count)} · ${escapeHtml(relation)}</em></span>
  </${tag}>`;
}

function renderQuestionFamilySetLocationOptions() {
  const select = document.querySelector("#question-family-set-location");
  const currentValue = select.value || state.currentQuestionFamilySet?.knowledgeNodeId || state.selectedKnowledgeNodeId;
  const query = document.querySelector("#question-family-set-location-search").value.trim().toLocaleLowerCase("zh-CN");
  const nodes = (state.questionFamilySetStructure?.nodes || state.knowledgeStructure?.nodes || []).filter((node) => !query || `${node.path} ${node.displayTitle || node.title}`.toLocaleLowerCase("zh-CN").includes(query));
  select.innerHTML = nodes.length
    ? nodes.map((node) => `<option value="${escapeHtml(node.id)}" ${node.id === currentValue ? "selected" : ""}>${escapeHtml(node.path || node.displayTitle || node.title)}</option>`).join("")
    : '<option value="" disabled>没有匹配的教材节点</option>';
  if (!nodes.some((node) => node.id === currentValue)) select.selectedIndex = -1;
  renderQuestionFamilySetParentOptions();
  renderQuestionFamilySetMembers();
}

function questionFamilySetDescendantSetIds(setId) {
  const maps = questionFamilySetMaps();
  const result = new Set();
  const pending = [setId];
  while (pending.length) {
    const parentId = pending.shift();
    state.questionFamilySets.filter((set) => maps.setParent.get(set.id) === parentId).forEach((set) => {
      if (result.has(set.id)) return;
      result.add(set.id);
      pending.push(set.id);
    });
  }
  return result;
}

function questionFamilySetDirectChildSetIds(set = state.currentQuestionFamilySet) {
  if (!set?.id) return [];
  const ids = new Set(questionFamilySetItems(set, "set").map((item) => item.id));
  state.questionFamilySets
    .filter((candidate) => candidate.parentSetId === set.id)
    .forEach((candidate) => ids.add(candidate.id));
  return [...ids];
}

function questionFamilySetCoveredContent(setIds = []) {
  const maps = questionFamilySetMaps();
  const familyIds = new Set();
  const descendantSetIds = new Set();
  [...new Set((Array.isArray(setIds) ? setIds : []).filter(Boolean))].forEach((setId) => {
    questionFamilySetDescendantFamilyIds(setId, maps, new Set()).forEach((familyId) => familyIds.add(familyId));
    questionFamilySetDescendantSetIds(setId).forEach((descendantId) => descendantSetIds.add(descendantId));
  });
  return { familyIds, setIds: descendantSetIds };
}

function normalizeQuestionFamilySetSelectedItems(items = state.questionFamilySetSelectedItems) {
  const keys = [...new Set((Array.isArray(items) ? items : []).filter((key) => /^(family|set):.+/.test(key)))];
  const selectedSetIds = new Set(keys.filter((key) => key.startsWith("set:")).map((key) => key.slice(4)));
  const coveredSelectedSetIds = new Set();
  selectedSetIds.forEach((setId) => {
    questionFamilySetDescendantSetIds(setId).forEach((descendantId) => {
      if (selectedSetIds.has(descendantId)) coveredSelectedSetIds.add(descendantId);
    });
  });
  const retainedSetIds = [...selectedSetIds].filter((setId) => !coveredSelectedSetIds.has(setId));
  const fixedChildSetIds = questionFamilySetDirectChildSetIds();
  const coverage = questionFamilySetCoveredContent([...fixedChildSetIds, ...retainedSetIds]);
  return keys.filter((key) => {
    const separator = key.indexOf(":");
    const type = key.slice(0, separator);
    const id = key.slice(separator + 1);
    if (type === "set") return !coveredSelectedSetIds.has(id) && !coverage.setIds.has(id);
    return !coverage.familyIds.has(id);
  });
}

function questionFamilySetMemberMatchesQuery(type, id, query) {
  if (!query) return true;
  const detail = questionFamilySetMemberDetail(type, id) || {};
  return `${detail.name || ""} ${detail.knowledgePath || ""} ${detail.id || id}`.toLocaleLowerCase("zh-CN").includes(query);
}

function setQuestionFamilySetMemberTab(value = "candidates") {
  state.questionFamilySetMemberTab = value === "current" ? "current" : "candidates";
  document.querySelectorAll("[data-question-family-set-member-tab]").forEach((button) => {
    const active = button.dataset.questionFamilySetMemberTab === state.questionFamilySetMemberTab;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-selected", String(active));
  });
  document.querySelector("#question-family-set-current-members").hidden = state.questionFamilySetMemberTab !== "current";
  document.querySelector("#question-family-set-member-candidates").hidden = state.questionFamilySetMemberTab !== "candidates";
  const search = document.querySelector("#question-family-set-member-search");
  const current = state.questionFamilySetMemberTab === "current";
  search.placeholder = current ? "搜索当前题族、题族集或知识路径" : "搜索可归入的题族、题族集或知识路径";
  search.setAttribute("aria-label", current ? "搜索当前内容" : "搜索可归入内容");
}

function renderQuestionFamilySetParentOptions() {
  const select = document.querySelector("#question-family-set-parent");
  if (!select) return;
  const current = state.currentQuestionFamilySet;
  const locationId = document.querySelector("#question-family-set-location")?.value || current?.knowledgeNodeId || state.selectedKnowledgeNodeId;
  const excluded = current ? questionFamilySetDescendantSetIds(current.id) : new Set();
  if (current) excluded.add(current.id);
  const previous = select.value || current?.parentSetId || "";
  const candidates = state.questionFamilySets.filter((set) => !excluded.has(set.id) && knowledgeNodeContains(set.knowledgeNodeId, locationId));
  select.innerHTML = `<option value="">无上级题族集</option>${candidates.map((set) => `<option value="${escapeHtml(set.id)}" ${set.id === previous ? "selected" : ""}>${escapeHtml(`${set.knowledgePath} > ${set.name}`)}</option>`).join("")}`;
  select.value = candidates.some((set) => set.id === previous) ? previous : "";
}

function renderQuestionFamilySetMembers(options = {}) {
  const current = state.currentQuestionFamilySet;
  const currentItems = Array.isArray(current?.items) ? current.items : [];
  const currentKeys = currentQuestionFamilySetItemKeys();
  state.questionFamilySetSelectedItems = normalizeQuestionFamilySetSelectedItems();
  const selected = selectedQuestionFamilySetItems();
  const locationId = document.querySelector("#question-family-set-location")?.value || current?.knowledgeNodeId || state.selectedKnowledgeNodeId;
  const query = document.querySelector("#question-family-set-member-search")?.value.trim().toLocaleLowerCase("zh-CN") || "";
  const excludedSets = current ? questionFamilySetDescendantSetIds(current.id) : new Set();
  if (current) {
    excludedSets.add(current.id);
    const maps = questionFamilySetMaps();
    let parentId = maps.setParent.get(current.id);
    while (parentId) {
      excludedSets.add(parentId);
      parentId = maps.setParent.get(parentId);
    }
  }
  const selectedSetIds = [...selected].filter((key) => key.startsWith("set:")).map((key) => key.slice(4));
  const fixedChildSetIds = questionFamilySetDirectChildSetIds(current);
  const coverage = questionFamilySetCoveredContent([...fixedChildSetIds, ...selectedSetIds]);
  const familyCandidates = state.questionFamilySetCatalogFamilies
    .filter((family) => family.status !== "rejected" && knowledgeNodeContains(locationId, family.knowledgeNodeId))
    .filter((family) => !currentKeys.has(questionFamilySetItemKey("family", family.id)))
    .filter((family) => !coverage.familyIds.has(family.id))
    .map((family) => ({ type: "family", id: family.id, detail: family }));
  const setCandidates = state.questionFamilySets
    .filter((set) => !excludedSets.has(set.id) && knowledgeNodeContains(locationId, set.knowledgeNodeId))
    .filter((set) => !currentKeys.has(questionFamilySetItemKey("set", set.id)))
    .filter((set) => !coverage.setIds.has(set.id))
    .map((set) => ({ type: "set", id: set.id, detail: set }));
  const candidatePool = [...setCandidates, ...familyCandidates];
  const candidates = candidatePool
    .filter(({ detail }) => !query || `${detail.name} ${detail.knowledgePath || ""} ${detail.id}`.toLocaleLowerCase("zh-CN").includes(query))
    .slice(0, 160);
  const visibleCurrentItems = currentItems.filter((item) => questionFamilySetMemberMatchesQuery(item.type, item.id, query));
  document.querySelector("#question-family-set-current-members").innerHTML = visibleCurrentItems.length
    ? `<div class="question-family-set-subhead"><strong>${query ? "当前内容搜索结果" : "当前内容"}</strong><span>${visibleCurrentItems.length}${query ? ` / ${currentItems.length}` : ""} 项</span></div>${visibleCurrentItems.map((item) => questionFamilySetMemberCardHtml(item.type, item.id, { current: true })).join("")}`
    : `<div class="question-family-set-current-empty">${currentItems.length && query ? "当前内容中没有匹配项" : "当前还是空题族集"}</div>`;
  document.querySelector("#question-family-set-member-candidates").innerHTML = candidates.length
    ? `<div class="question-family-set-subhead"><strong>${query ? "可归入内容搜索结果" : "可归入内容"}</strong><span>${candidates.length >= 160 ? "显示前 160 项，请搜索缩小范围" : `${candidates.length}${query ? ` / ${candidatePool.length}` : ""} 项`}</span></div>${candidates.map(({ type, id }) => questionFamilySetMemberCardHtml(type, id, { selected: selected.has(questionFamilySetItemKey(type, id)) })).join("")}`
    : '<div class="question-family-set-current-empty">当前范围内没有匹配的题族或题族集</div>';
  document.querySelector("#question-family-set-member-summary").textContent = `当前 ${currentItems.length} 项 · 待归入 ${selected.size} 项`;
  document.querySelector("#question-family-set-current-tab-count").textContent = currentItems.length;
  document.querySelector("#question-family-set-candidate-tab-count").textContent = candidatePool.length;
  setQuestionFamilySetMemberTab(state.questionFamilySetMemberTab);
  if (Number.isFinite(options.candidateScrollTop)) {
    document.querySelector("#question-family-set-member-candidates").scrollTop = Math.max(0, options.candidateScrollTop);
  }
}

async function loadQuestionFamilySetCatalog() {
  const bookId = state.currentQuestionFamilySet?.bookId || questionFamilyWorkspaceBookId();
  if (!bookId) throw new Error("请先选择一本教材");
  const [familyPayload, setPayload, structurePayload] = await Promise.all([
    requestJson(`/api/admin/question-family-options?bookId=${encodeURIComponent(bookId)}`),
    requestJson(`/api/admin/question-family-sets?bookId=${encodeURIComponent(bookId)}`),
    requestJson(`/api/admin/knowledge-structure?bookId=${encodeURIComponent(bookId)}&optional=true`),
  ]);
  state.questionFamilySetStructure = structurePayload.structure;
  state.questionFamilySetCatalogFamilies = familyPayload.families || [];
  state.questionFamilySets = questionFamilySetsFromPayload(setPayload);
  if (state.currentQuestionFamilySet) {
    state.currentQuestionFamilySet = state.questionFamilySets.find((set) => set.id === state.currentQuestionFamilySet.id) || null;
  }
}

function closeQuestionFamilySetDialog() {
  const dialog = document.querySelector("#question-family-set-dialog");
  if (dialog.open) dialog.close();
  state.currentQuestionFamilySet = null;
  state.questionFamilySetStructure = null;
  if (state.questionFamilySetWorkspaceSnapshot) {
    state.questionFamilySets = state.questionFamilySetWorkspaceSnapshot;
    state.questionFamilySetWorkspaceSnapshot = null;
  }
  state.questionFamilySetSelectedItems = [];
  state.questionFamilySetCatalogFamilies = [];
  state.questionFamilySetMemberTab = "candidates";
  setSmallDialogStatus("#question-family-set-dialog-status");
}

async function openQuestionFamilySetDialog(setId = "") {
  const node = state.knowledgeStructure?.nodes.find((item) => item.id === state.selectedKnowledgeNodeId);
  if (!setId && !node) {
    setQuestionFamilyFeedback("请先在左侧选择章、节或知识点，再创建题族集。", "error");
    return;
  }
  state.currentQuestionFamilySet = setId ? state.questionFamilySets.find((set) => set.id === setId) || null : null;
  if (setId && !state.currentQuestionFamilySet) {
    setQuestionFamilyFeedback("这个题族集已不存在，请刷新后重试。", "error");
    return;
  }
  state.questionFamilySetWorkspaceSnapshot = state.questionFamilySets;
  state.questionFamilySetStructure = null;
  state.questionFamilySetSelectedItems = [];
  state.questionFamilySetMemberTab = "candidates";
  const current = state.currentQuestionFamilySet;
  document.querySelector("#question-family-set-id").value = current?.id || "";
  document.querySelector("#question-family-set-revision").value = current?.revision || "";
  document.querySelector("#question-family-set-name").value = current?.name || "";
  document.querySelector("#question-family-set-description").value = current?.description || "";
  document.querySelector("#question-family-set-location-search").value = "";
  document.querySelector("#question-family-set-member-search").value = "";
  document.querySelector("#question-family-set-dialog-title").textContent = current ? `编辑题族集 · ${current.name}` : "新建题族集";
  document.querySelector("#question-family-set-dialog-copy").textContent = current
    ? `${current.familyCount || 0} 个题族 · ${current.questionCount || 0} 道去重题目 · v${current.revision || 1}`
    : "题族集可包含题族和下级题族集，不复制题目";
  document.querySelector("#delete-question-family-set").hidden = !current;
  document.querySelector("#delete-question-family-set").disabled = Boolean(current?.directSetCount || current?.setCount);
  document.querySelector("#delete-question-family-set").title = current?.directSetCount || current?.setCount ? "仍有下级题族集，请先移动或解散下级集" : "解散容器并保留全部题族和题目";
  document.querySelector("#save-question-family-set").textContent = current ? "保存题族集" : "创建题族集";
  setSmallDialogStatus("#question-family-set-dialog-status", "正在读取题族与题族集", "loading");
  document.querySelector("#question-family-set-dialog").showModal();
  try {
    await loadQuestionFamilySetCatalog();
    const refreshed = current ? state.questionFamilySets.find((set) => set.id === current.id) : null;
    state.currentQuestionFamilySet = refreshed || null;
    document.querySelector("#question-family-set-revision").value = refreshed?.revision || "";
    renderQuestionFamilySetLocationOptions();
    const location = document.querySelector("#question-family-set-location");
    location.value = refreshed?.knowledgeNodeId || node?.id || "";
    renderQuestionFamilySetParentOptions();
    if (refreshed?.parentSetId) document.querySelector("#question-family-set-parent").value = refreshed.parentSetId;
    renderQuestionFamilySetMembers();
    setSmallDialogStatus("#question-family-set-dialog-status");
    document.querySelector("#question-family-set-name").focus();
  } catch (error) {
    setSmallDialogStatus("#question-family-set-dialog-status", `读取失败：${friendlyError(error)}`, "error");
  }
}

async function submitQuestionFamilySet(event) {
  event.preventDefault();
  const current = state.currentQuestionFamilySet;
  const name = document.querySelector("#question-family-set-name").value.trim();
  const knowledgeNodeId = document.querySelector("#question-family-set-location").value;
  if (!name || !knowledgeNodeId) {
    setSmallDialogStatus("#question-family-set-dialog-status", !name ? "请填写题族集名称" : "请选择所在教材节点", "error");
    return;
  }
  const selected = [...selectedQuestionFamilySetItems()];
  const familyIds = selected.filter((key) => key.startsWith("family:")).map((key) => key.slice(7));
  const childSetIds = selected.filter((key) => key.startsWith("set:")).map((key) => key.slice(4));
  const affected = [
    ...familyIds.map((id) => {
      const family = questionFamilySetMemberDetail("family", id);
      return `${family?.name || id}（${Number(family?.memberCount || family?.members?.length || 0)} 道题）`;
    }),
    ...childSetIds.map((id) => {
      const set = questionFamilySetMemberDetail("set", id);
      return `${set?.name || id}（${Number(set?.questionCount || 0)} 道去重题目）`;
    }),
  ];
  if (current && (current.parentSetId || "") !== document.querySelector("#question-family-set-parent").value) {
    affected.push(`当前题族集层级（${Number(current.questionCount || 0)} 道去重题目）`);
  }
  if (affected.length && !window.confirm(`这次会调整整个题族或下级集的归集，不只影响当前题目。\n涉及：${affected.join("、")}\n确认提交？`)) return;
  const button = document.querySelector("#save-question-family-set");
  button.disabled = true;
  setSmallDialogStatus("#question-family-set-dialog-status", current ? "正在保存题族集" : "正在创建题族集", "loading");
  try {
    let saved;
    if (!current) {
      const payload = await requestJson("/api/admin/question-family-sets", {
        method: "POST",
        body: JSON.stringify({
          bookId: questionFamilyWorkspaceBookId(),
          knowledgeNodeId,
          parentSetId: document.querySelector("#question-family-set-parent").value,
          name,
          description: document.querySelector("#question-family-set-description").value.trim(),
          mode: "move",
          familyIds,
          childSetIds,
        }),
      });
      saved = questionFamilySetFromPayload(payload);
    } else {
      const updated = await requestJson(`/api/admin/question-family-sets/${encodeURIComponent(current.id)}`, {
        method: "PATCH",
        body: JSON.stringify({
          expectedRevision: Number(document.querySelector("#question-family-set-revision").value) || current.revision,
          knowledgeNodeId,
          parentSetId: document.querySelector("#question-family-set-parent").value,
          name,
          description: document.querySelector("#question-family-set-description").value.trim(),
          mode: "move",
          familyIds,
          childSetIds,
        }),
      });
      saved = questionFamilySetFromPayload(updated) || current;
    }
    closeQuestionFamilySetDialog();
    await loadQuestionFamilies();
    setQuestionFamilyFeedback(`题族集“${saved?.name || name}”已保存；题族和题目仍保持原数据。`, "success");
  } catch (error) {
    setSmallDialogStatus("#question-family-set-dialog-status", `保存失败：${friendlyError(error)}`, "error");
  } finally {
    button.disabled = false;
  }
}

async function removeQuestionFamilySetMember(type, memberId) {
  const current = state.currentQuestionFamilySet;
  if (!current || !memberId) return;
  const detail = questionFamilySetMemberDetail(type, memberId);
  const affectedCount = type === "family" ? Number(detail?.memberCount || detail?.members?.length || 0) : Number(detail?.questionCount || 0);
  if (!window.confirm(`确定将“${detail?.name || memberId}”移出题族集吗？涉及 ${affectedCount} 道题的派生归集展示；${type === "family" ? "题族和题目不会被删除。" : "下级题族集及其内容都会保留。"}`)) return;
  setSmallDialogStatus("#question-family-set-dialog-status", "正在移出题族集", "loading");
  try {
    const payload = await requestJson(`/api/admin/question-family-sets/${encodeURIComponent(current.id)}/members/${encodeURIComponent(type)}/${encodeURIComponent(memberId)}`, {
      method: "DELETE",
      body: JSON.stringify({ expectedRevision: current.revision }),
    });
    state.currentQuestionFamilySet = questionFamilySetFromPayload(payload) || current;
    await loadQuestionFamilySetCatalog();
    document.querySelector("#question-family-set-revision").value = state.currentQuestionFamilySet?.revision || "";
    renderQuestionFamilySetMembers();
    setSmallDialogStatus("#question-family-set-dialog-status", "已移出，内容本身未删除", "success");
  } catch (error) {
    setSmallDialogStatus("#question-family-set-dialog-status", `移出失败：${friendlyError(error)}`, "error");
  }
}

async function deleteQuestionFamilySet() {
  const current = state.currentQuestionFamilySet;
  if (!current) return;
  if (current.directSetCount || current.setCount) {
    setSmallDialogStatus("#question-family-set-dialog-status", "请先移动或解散下级题族集", "error");
    return;
  }
  if (!window.confirm(`确定解散题族集“${current.name}”吗？其中的题族会回到教材知识树原位置，题目不会删除。`)) return;
  const button = document.querySelector("#delete-question-family-set");
  button.disabled = true;
  setSmallDialogStatus("#question-family-set-dialog-status", "正在解散题族集", "loading");
  try {
    await requestJson(`/api/admin/question-family-sets/${encodeURIComponent(current.id)}`, {
      method: "DELETE",
      body: JSON.stringify({ expectedRevision: current.revision }),
    });
    closeQuestionFamilySetDialog();
    await loadQuestionFamilies();
    setQuestionFamilyFeedback(`题族集“${current.name}”已解散；题族和题目均已保留。`, "success");
  } catch (error) {
    setSmallDialogStatus("#question-family-set-dialog-status", `解散失败：${friendlyError(error)}`, "error");
  } finally {
    button.disabled = false;
  }
}

async function generateQuestionFamilies() {
  libraryWorkspace.openCompletion(null, questionFamilyWorkspaceBookId());
}

function questionFamilyFingerprintSummary(fingerprint = {}) {
  const nodeById = new Map((state.knowledgeStructure?.nodes || []).map((node) => [node.id, node]));
  const primaryPath = fingerprint.knowledgePath
    || nodeById.get(fingerprint.primaryNodeId)?.path
    || fingerprint.primaryKnowledgePoint
    || "未标注";
  const requiredPaths = [...new Set((fingerprint.requiredNodeIds || [])
    .filter((nodeId) => nodeId && nodeId !== fingerprint.primaryNodeId)
    .map((nodeId) => nodeById.get(nodeId)?.path || nodeId)
    .filter(Boolean))];
  const primaryNodeRole = normalizeQuestionFingerprintPrimaryNodeRole(fingerprint.primaryNodeRole);
  if (primaryNodeRole === "scope_anchor") {
    return `范围锚点：${primaryPath}；作答必需：${requiredPaths.join("、") || "未标注"}`;
  }
  return requiredPaths.length ? `作答核心：${primaryPath}；另需 ${requiredPaths.join("、")}` : `作答核心：${primaryPath}`;
}

function questionFamilyDefinitionFingerprintSummary(family = {}) {
  const nodeById = new Map((state.knowledgeStructure?.nodes || []).map((node) => [node.id, node]));
  const scopeAnchorNodeId = String(family.scopeAnchorNodeId || family.coreKnowledgeNodeId || family.knowledgeNodeId || "");
  const coverageNodeIds = [...new Set((family.coverageKnowledgeNodeIds || family.requiredKnowledgeNodeIds || []).filter(Boolean))];
  const scopeAnchor = family.scopeAnchor?.path || family.coreKnowledgeNode?.path
    || nodeById.get(scopeAnchorNodeId)?.path || family.knowledgePath || family.primaryKnowledgePoint || "未标注";
  const coverage = coverageNodeIds.map((nodeId) => nodeById.get(nodeId)?.path || nodeId).filter(Boolean);
  return `后台目录锚点：${scopeAnchor}；覆盖知识：${coverage.join("、") || "未标注"}`;
}

function questionFamilyCompatibilityItemHtml(label, item = {}, role = "topic") {
  const statusLabels = {
    match: role === "related" && label === "本题贡献知识" ? "已覆盖" : "一致",
    partial: "部分重合",
    mismatch: "不一致",
    review: "需人工核对",
    unassessed: "未记录",
  };
  const status = item.status || "unassessed";
  return `<div class="question-family-compatibility-item is-${escapeHtml(status)}"><span>${escapeHtml(label)}</span><em>${escapeHtml(statusLabels[status] || status)}</em></div>`;
}

function questionFamilyMemberCompatibilityHtml(member = {}) {
  const compatibility = member.familyKnowledgeCompatibility || {};
  const role = compatibility.role || "topic";
  const overallStatus = compatibility.overallStatus || (compatibility.status === "compatible" ? "compatible" : "unassessed");
  const overallLabels = {
    compatible: "本题贡献匹配",
    partial: "部分重合",
    incompatible: "完全不一致",
    unassessed: "待正式指纹",
  };
  const items = compatibility.items || {};
  const warning = compatibility.fullyIncompatible
    ? '<p class="question-family-compatibility-warning"><strong>注意：题目正式指纹与当前题族指纹完全不一致</strong><span>请核对题族归属；需要修正题目指纹时前往题目编辑。本警告不会自动阻断题族确认。</span></p>'
    : (overallStatus === "partial"
      ? '<p class="question-family-compatibility-note">两份指纹只有部分知识重合，请结合题干、选项和题族边界人工判断。</p>'
      : (overallStatus === "unassessed"
        ? '<p class="question-family-compatibility-note">尚无已确认题目指纹，AI 候选不参与正式一致性结论。</p>'
        : ""));
  return `<div class="question-family-fingerprint-comparison is-${escapeHtml(overallStatus)}">
    <div class="question-family-fingerprint-comparison-head"><span>题目指纹 × 题族指纹</span><em>${escapeHtml(overallLabels[overallStatus] || overallStatus)}</em></div>
    <div class="question-family-compatibility-items">
      ${questionFamilyCompatibilityItemHtml("题目知识焦点", items.focusKnowledge || items.coreKnowledge, role)}
      ${questionFamilyCompatibilityItemHtml("本题贡献知识", items.contributionKnowledge || items.requiredKnowledge, role)}
      ${questionFamilyCompatibilityItemHtml("考查动作", items.assessmentAction, role)}
    </div>
    ${warning}
    <button class="secondary-action question-family-open-question-editor" data-open-question-fingerprint="${escapeHtml(member.questionId)}" type="button">前往题目编辑</button>
  </div>`;
}

function questionFamilyMemberKnowledgeFactsHtml(question = {}, member = {}, family = {}) {
  const formalKnowledge = [...new Set([
    question.primaryKnowledgePoint,
    ...(question.knowledgePoints || []),
  ].map((value) => String(value || "").trim()).filter(Boolean))];
  const confirmedFingerprint = question.knowledgeFingerprint || null;
  const candidateFingerprint = question.candidateKnowledgeFingerprint || null;
  return `<div class="question-family-member-knowledge-facts">
    <div class="is-formal"><span>题目原有知识标签</span><strong>${escapeHtml(formalKnowledge.join(" · ") || "未标注")}</strong><em>题目 v${escapeHtml(question.version || 1)}</em></div>
    ${confirmedFingerprint ? `<div class="is-confirmed"><span>已确认结构指纹</span><strong>${escapeHtml(questionFamilyFingerprintSummary(confirmedFingerprint))}</strong><em>人工确认</em></div>` : ""}
    ${candidateFingerprint ? `<div class="is-candidate"><span>AI 候选结构指纹</span><strong>${escapeHtml(questionFamilyFingerprintSummary(candidateFingerprint))}</strong><em>未确认</em></div>` : ""}
    <div class="is-family"><span>当前题族定义</span><strong>${escapeHtml(questionFamilyDefinitionFingerprintSummary(family))}</strong><em>${member.familyKnowledgeCompatibility?.role === "related" ? "关联题族" : "主题族"}</em></div>
  </div>${questionFamilyMemberCompatibilityHtml(member)}`;
}

function questionFamilyMemberContributionNodeIds(member = {}, family = {}) {
  const primaryNodeRole = normalizeQuestionFingerprintPrimaryNodeRole(member.primaryNodeRole);
  const questionRequired = [...new Set([
    ...(primaryNodeRole === "core" ? [member.knowledgeNodeId] : []),
    ...(member.requiredKnowledgeNodeIds || []),
  ].map(String).filter((nodeId) => nodeId && !(primaryNodeRole === "scope_anchor" && nodeId === String(member.knowledgeNodeId || ""))))];
  const familyCoverage = new Set((family.coverageKnowledgeNodeIds || family.requiredKnowledgeNodeIds || [])
    .map(String).filter(Boolean));
  const allowed = questionRequired.filter((nodeId) => familyCoverage.has(nodeId));
  if (Array.isArray(member.contributionKnowledgeNodeIds)) {
    return [...new Set(member.contributionKnowledgeNodeIds.map(String).filter((nodeId) => allowed.includes(nodeId)))];
  }
  return [];
}

function questionFamilyMemberContributionSuggestionNodeIds(member = {}, family = {}) {
  const primaryNodeRole = normalizeQuestionFingerprintPrimaryNodeRole(member.primaryNodeRole);
  const questionRequired = [...new Set([
    ...(primaryNodeRole === "core" ? [member.knowledgeNodeId] : []),
    ...(member.requiredKnowledgeNodeIds || []),
  ].map(String).filter((nodeId) => nodeId && !(primaryNodeRole === "scope_anchor" && nodeId === String(member.knowledgeNodeId || ""))))];
  const familyCoverage = new Set((family.coverageKnowledgeNodeIds || family.requiredKnowledgeNodeIds || [])
    .map(String).filter(Boolean));
  return questionRequired.filter((nodeId) => familyCoverage.has(nodeId));
}

function questionFamilyMemberContributionHtml(member = {}, family = {}) {
  const nodeById = new Map((questionFamilyEditingStructure()?.nodes || []).map((node) => [node.id, node]));
  const primaryNodeRole = normalizeQuestionFingerprintPrimaryNodeRole(member.primaryNodeRole);
  const questionRequired = [...new Set([
    ...(primaryNodeRole === "core" ? [member.knowledgeNodeId] : []),
    ...(member.requiredKnowledgeNodeIds || []),
  ].map(String).filter((nodeId) => nodeId && !(primaryNodeRole === "scope_anchor" && nodeId === String(member.knowledgeNodeId || ""))))];
  const familyCoverage = new Set((family.coverageKnowledgeNodeIds || family.requiredKnowledgeNodeIds || [])
    .map(String).filter(Boolean));
  const candidates = questionRequired.filter((nodeId) => familyCoverage.has(nodeId));
  const selected = new Set(questionFamilyMemberContributionNodeIds(member, family));
  const suggestion = questionFamilyMemberContributionSuggestionNodeIds(member, family);
  if (!candidates.length) {
    return '<div class="question-family-member-contribution is-empty"><span>本题贡献知识</span><small>题目最小充分知识与题族覆盖知识没有交集，请先修正指纹或题族定义。</small></div>';
  }
  return `<div class="question-family-member-contribution"><span>本题贡献知识${!selected.size && suggestion.length ? ` · 当前为空，建议 ${escapeHtml(suggestion.length)} 项` : ""}</span><div>${!selected.size && suggestion.length ? `<button class="is-suggestion" type="button" data-use-family-member-contribution-suggestion="${escapeHtml(member.questionId)}">采用建议</button>` : ""}${candidates.map((nodeId) => {
    const node = nodeById.get(nodeId);
    const label = node?.path || node?.displayTitle || node?.title || nodeId;
    const active = selected.has(nodeId);
    return `<button type="button" data-family-member-contribution-node="${escapeHtml(nodeId)}" aria-pressed="${active}" class="${active ? "is-selected" : ""}" title="${escapeHtml(label)}">${escapeHtml(label)}</button>`;
  }).join("")}</div></div>`;
}

function questionFamilyMemberHtml(member, index) {
  const question = member.question || {};
  const family = state.questionFamilies.find((item) => item.id === document.querySelector("#question-family-id").value) || {};
  const memberReviewStatus = questionFamilyMemberReviewStatus(member, family);
  const compatibilityStatus = member.familyKnowledgeCompatibility?.status || "unassessed";
  const overallStatus = member.familyKnowledgeCompatibility?.overallStatus || "unassessed";
  const provisionalKnowledge = compatibilityStatus.startsWith("provisional_") || member.fingerprintReviewStatus === "suggested";
  const invalidationReason = String(member.reviewInvalidationReason || "").trim();
  return `<div class="question-family-member is-member-${escapeHtml(memberReviewStatus)} ${member.familyKnowledgeCompatibility?.fullyIncompatible ? "has-knowledge-mismatch" : ""} ${overallStatus === "partial" ? "has-knowledge-partial" : ""} ${provisionalKnowledge ? "has-knowledge-provisional" : ""}" data-question-id="${escapeHtml(member.questionId)}">
    <button class="question-family-member-remove" data-remove-question-family-member="${escapeHtml(member.questionId)}" type="button" title="移出题族" aria-label="将这道题移出题族">×</button>
    <div class="question-family-member-index">${index + 1}</div>
    <div class="question-family-member-main">
      <div class="question-family-member-review-state"><span class="is-${escapeHtml(memberReviewStatus)}">${escapeHtml(questionFamilyMemberReviewStatusLabels[memberReviewStatus])}</span>${invalidationReason ? `<small>${escapeHtml(invalidationReason)}</small>` : ""}${questionFamilyMemberReviewActionsHtml(member, family)}</div>
      <strong>${escapeHtml(question.stem || "题目已不存在")}</strong>
      ${questionOptionListHtml(question.options)}
      <span>${escapeHtml(question.typeLabel || question.type || "未知题型")} · ${"★".repeat(Number(question.difficultyStars) || 1)} · ${escapeHtml(member.action)}</span>
      <small>${escapeHtml(member.reason)}</small>
      ${questionFamilyMemberKnowledgeFactsHtml(question, member, family)}
      ${questionFamilyMemberContributionHtml(member, family)}
    </div>
    <label><span>关系</span><select data-family-member-role>
      ${Object.entries(questionFamilyRoleLabels).map(([value, label]) => `<option value="${value}" ${member.role === value ? "selected" : ""}>${label}</option>`).join("")}
    </select></label>
    <label><span>训练层级</span><select data-family-member-level>
      ${Object.entries(trainingLevelLabels).map(([value, label]) => `<option value="${value}" ${member.trainingLevel === value ? "selected" : ""}>${label}</option>`).join("")}
    </select></label>
  </div>`;
}

function questionFamilyNodeIds(values) {
  return [...new Set((Array.isArray(values) ? values : []).map((value) => String(value?.id || value || "")).filter(Boolean))];
}

function questionFamilyKnowledgeNode(nodeId) {
  return (questionFamilyEditingStructure()?.nodes || []).find((node) => node.id === nodeId && node.kind === "knowledge");
}

function questionFamilyEditingStructure() {
  const familyId = document.querySelector("#question-family-id").value;
  const family = state.questionFamilies.find(item => item.id === familyId);
  return family && state.questionFamilyEditorStructure?.bookId === family.bookId
    ? state.questionFamilyEditorStructure : state.knowledgeStructure;
}

function setQuestionFamilyDefinitionState(family = {}, fallbackNodeId = "") {
  const coreKnowledgeNodeId = String(family.backendDirectoryAnchorNodeId
    || family.scopeAnchorNodeId
    || family.coreKnowledgeNodeId
    || family.coreKnowledgeNode?.id
    || fallbackNodeId
    || family.knowledgeNodeId
    || "");
  const requiredKnowledgeNodeIds = questionFamilyNodeIds(family.coverageKnowledgeNodeIds || family.requiredKnowledgeNodeIds || family.requiredKnowledgeNodes);
  const textbookAnchorNodeIds = questionFamilyNodeIds(family.textbookAnchorNodeIds || family.textbookAnchors);
  const primaryAnchorNodeId = String(family.userDirectoryAnchorNodeId
    || family.locationNodeId
    || family.knowledgeNodeId
    || textbookAnchorNodeIds[0]
    || fallbackNodeId
    || "");
  state.questionFamilyCoreKnowledgeNodeId = coreKnowledgeNodeId;
  state.questionFamilyRequiredKnowledgeNodeIds = [...new Set(requiredKnowledgeNodeIds.filter(Boolean))];
  state.questionFamilyMoveKnowledgeNodeId = primaryAnchorNodeId;
  state.questionFamilyTextbookAnchorNodeIds = [...new Set([primaryAnchorNodeId, ...textbookAnchorNodeIds].filter(Boolean))];
  document.querySelector("#question-family-focus-key").value = family.focusKey || "";
  document.querySelector("#question-family-assessment-action").value = family.assessmentAction
    || family.members?.find((member) => member.action)?.action
    || family.focus?.action
    || "";
  document.querySelector("#question-family-inclusion-boundary").value = family.inclusionBoundary || family.boundaries?.inclusion || "";
  document.querySelector("#question-family-exclusion-boundary").value = family.exclusionBoundary || family.boundaries?.exclusion || "";
}

function questionFamilyDefinitionPayload() {
  const coreKnowledgeNodeId = String(state.questionFamilyCoreKnowledgeNodeId || "");
  const primaryAnchorNodeId = String(state.questionFamilyMoveKnowledgeNodeId || "");
  return {
    focusKey: document.querySelector("#question-family-focus-key").value.trim(),
    // New explicit names are the source of truth; legacy aliases below keep
    // older API clients and frozen records readable.
    backendDirectoryAnchorNodeId: coreKnowledgeNodeId,
    userDirectoryAnchorNodeId: primaryAnchorNodeId,
    coreKnowledgeNodeId,
    scopeAnchorNodeId: coreKnowledgeNodeId,
    locationNodeId: primaryAnchorNodeId,
    knowledgeNodeId: primaryAnchorNodeId,
    requiredKnowledgeNodeIds: [...new Set(state.questionFamilyRequiredKnowledgeNodeIds.filter(Boolean))],
    coverageKnowledgeNodeIds: [...new Set(state.questionFamilyRequiredKnowledgeNodeIds.filter(Boolean))],
    textbookAnchorNodeIds: [...new Set([primaryAnchorNodeId, ...state.questionFamilyTextbookAnchorNodeIds].filter(Boolean))],
    assessmentAction: document.querySelector("#question-family-assessment-action").value.trim(),
    inclusionBoundary: document.querySelector("#question-family-inclusion-boundary").value.trim(),
    exclusionBoundary: document.querySelector("#question-family-exclusion-boundary").value.trim(),
  };
}

function questionFamilyDefinitionOptions(nodes, selectedIds, lockedId = "") {
  const selected = new Set(selectedIds);
  return nodes.map((node) => `<option value="${escapeHtml(node.id)}" ${selected.has(node.id) ? "selected" : ""} ${node.id === lockedId ? "disabled" : ""}>${escapeHtml(node.path || node.displayTitle || node.title)}</option>`).join("");
}

function questionFamilyMultiselectConfig(type) {
  if (type === "core") {
    return {
      selectId: "question-family-core-knowledge",
      emptyLabel: "请选择后台目录锚点",
      multiple: false,
      lockedId: "",
      lockedLabel: "",
    };
  }
  if (type === "primary-anchor") {
    return {
      selectId: "question-family-location-node",
      emptyLabel: "请选择用户端目录锚点",
      multiple: false,
      lockedId: "",
      lockedLabel: "",
    };
  }
  if (type === "anchors") {
    return {
      selectId: "question-family-textbook-anchors",
      emptyLabel: "请选择教材锚点",
      multiple: true,
      lockedId: state.questionFamilyMoveKnowledgeNodeId,
      lockedLabel: "随主锚点保留",
    };
  }
  if (type === "blind-gold-primary") {
    return {
      selectId: "blind-gold-existing-family",
      emptyLabel: "请选择题族",
      emptyMessage: "没有匹配的题族",
      multiple: false,
      lockedId: "",
      lockedLabel: "",
    };
  }
  return {
    selectId: "question-family-required-knowledge",
    emptyLabel: "请选择覆盖知识",
    multiple: true,
    lockedId: "",
    lockedLabel: "",
  };
}

function questionFamilyMultiselectIsOpen(root) {
  const panel = root?.querySelector(".question-family-multiselect-panel");
  if (!panel) return false;
  try {
    return panel.matches(":popover-open") || root.classList.contains("is-open");
  } catch {
    return root.classList.contains("is-open");
  }
}

function renderQuestionFamilyMultiselect(type) {
  const root = document.querySelector(`[data-question-family-multiselect="${type}"]`);
  const config = questionFamilyMultiselectConfig(type);
  const select = document.querySelector(`#${config.selectId}`);
  if (!root || !select) return;
  const search = root.querySelector("[data-question-family-multiselect-search]");
  const query = search.value.trim().toLocaleLowerCase("zh-CN");
  const options = [...select.options].filter((option) => option.value);
  const selected = options.filter((option) => option.selected);
  const summary = root.querySelector("[data-question-family-multiselect-summary]");
  summary.textContent = selected.length > 1
    ? `${selected[0].textContent} · 另 ${selected.length - 1} 项`
    : (selected[0]?.textContent || config.emptyLabel);
  summary.title = selected.map((option) => option.textContent).join("\n");
  const visible = options.filter((option) => option.selected
    || !query
    || option.textContent.toLocaleLowerCase("zh-CN").includes(query));
  visible.sort((left, right) => {
    if (type === "blind-gold-primary") {
      const sourceOrder = Number(blindGoldFamilyPickerSource(left) === "historical_snapshot")
        - Number(blindGoldFamilyPickerSource(right) === "historical_snapshot");
      if (sourceOrder) return sourceOrder;
    }
    return Number(right.selected) - Number(left.selected)
      || String(left.textContent).localeCompare(String(right.textContent), "zh-CN");
  });
  const inputType = config.multiple ? "checkbox" : "radio";
  let optionIndex = 0;
  const renderOption = (option) => {
      const locked = option.value === config.lockedId;
      const pendingReview = type === "blind-gold-primary" && option.dataset.familyStatus === "pending_review";
      const historicalSnapshot = type === "blind-gold-primary" && option.dataset.familySource === "historical_snapshot";
      // Historical primary values are displayed for auditability but can
      // never be selected again as a current formal relation.
      const disabled = locked || option.disabled || select.disabled || historicalSnapshot;
      return `<label class="question-family-multiselect-option ${option.selected ? "is-selected" : ""} ${disabled ? "is-locked" : ""}">
        <input data-question-family-multiselect-option="${escapeHtml(type)}" type="${inputType}" ${config.multiple ? "" : `name="question-family-${escapeHtml(type)}"`} value="${escapeHtml(option.value)}" ${option.selected ? "checked" : ""} ${disabled ? "disabled" : ""} />
        <span>${escapeHtml(option.textContent)}</span>
        ${locked ? `<em>${escapeHtml(config.lockedLabel)}</em>` : (historicalSnapshot ? "<em>历史快照 · 仅供追溯，不可提交</em>" : (pendingReview ? "<em>待审核</em>" : ""))}
      </label>`;
    };
  const optionMarkup = type === "blind-gold-primary"
    ? blindGoldFamilyPickerGroups(visible).map((group) => `<section class="question-family-multiselect-group" data-family-group="${escapeHtml(group.source)}">
      <div class="question-family-multiselect-group-title">${escapeHtml(group.label)}</div>
      ${group.options.map(renderOption).join("")}
    </section>`).join("")
    : visible.map(renderOption).join("");
  root.querySelector("[data-question-family-multiselect-options]").innerHTML = visible.length
    ? optionMarkup
    : `<div class="question-family-multiselect-empty">${escapeHtml(config.emptyMessage || "没有匹配的知识点")}</div>`;
}

function renderQuestionFamilyMultiselects() {
  renderQuestionFamilyMultiselect("core");
  renderQuestionFamilyMultiselect("primary-anchor");
  renderQuestionFamilyMultiselect("required");
  renderQuestionFamilyMultiselect("anchors");
  renderQuestionFamilyMultiselect("blind-gold-primary");
}

// 下拉面板挂在顶层（popover + position:fixed），只按视口收敛时，弹窗里的选择器会伸到弹窗边框外面。
// 这里把最近的 <dialog> 也当作边界；不在弹窗里（或弹窗过小）时退回纯视口口径，行为与原先一致。
function questionFamilyMultiselectBounds(root) {
  const margin = 8;
  const container = root.closest("dialog[open]");
  const rect = container && container.getBoundingClientRect();
  if (!rect || rect.width < 120 || rect.height < 120) {
    return { left: margin, right: window.innerWidth - margin, top: margin, bottom: window.innerHeight - margin };
  }
  const inset = 10;
  const left = Math.max(0, rect.left) + inset;
  const right = Math.min(window.innerWidth, rect.right) - inset;
  const top = Math.max(0, rect.top) + inset;
  const bottom = Math.min(window.innerHeight, rect.bottom) - inset;
  if (right - left < 160 || bottom - top < 120) {
    return { left: margin, right: window.innerWidth - margin, top: margin, bottom: window.innerHeight - margin };
  }
  return { left, right, top, bottom };
}

// 面板的 left/top 是相对**包含块**写的，而 getBoundingClientRect 给的是视口坐标。
// 弹窗是顶层元素（modal dialog 会为它的 fixed 后代建立包含块），所以弹窗里的面板如果不减掉
// 弹窗原点，就会整体偏移弹窗自己的位置（实测弹窗 left=340 时，写 547px 实际渲染在 888px），
// 右边自然就跑到弹窗外面去了。offsetParent 正好给出这个包含块；没有包含块时它是 null。
function questionFamilyMultiselectOrigin(panel) {
  const offsetParent = panel && panel.offsetParent;
  if (!offsetParent || offsetParent === document.body || offsetParent === document.documentElement) {
    return { left: 0, top: 0, bottom: window.innerHeight };
  }
  const rect = offsetParent.getBoundingClientRect();
  return { left: rect.left, top: rect.top, bottom: rect.bottom };
}

function positionQuestionFamilyMultiselect(root) {
  const panel = root.querySelector(".question-family-multiselect-panel");
  const trigger = root.querySelector(".question-family-multiselect-trigger");
  if (!panel || !trigger) return;
  const rect = trigger.getBoundingClientRect();
  const margin = 8;
  const gap = 6;
  const origin = questionFamilyMultiselectOrigin(panel);
  const bounds = questionFamilyMultiselectBounds(root);
  const availableBelow = bounds.bottom - rect.bottom - gap;
  const availableAbove = rect.top - bounds.top - gap;
  const openAbove = availableBelow < 180 && availableAbove > availableBelow;
  const availableHeight = openAbove ? availableAbove : availableBelow;
  const maxHeight = Math.min(360, Math.max(160, availableHeight));
  const preferredWidth = root.matches("[data-blind-gold-knowledge-picker], [data-blind-gold-family-picker], .blind-gold-primary-family-picker") ? Math.max(rect.width, 420) : rect.width;
  const minLeft = Math.max(margin, bounds.left);
  const maxRight = Math.max(minLeft + 160, bounds.right);
  const width = Math.min(preferredWidth, maxRight - minLeft);
  const left = Math.max(minLeft, Math.min(rect.left, maxRight - width));
  panel.style.width = `${width}px`;
  panel.style.left = `${left - origin.left}px`;
  panel.style.maxHeight = `${maxHeight}px`;
  if (openAbove) {
    panel.style.top = "auto";
    panel.style.bottom = `${origin.bottom - rect.top + gap}px`;
  } else {
    panel.style.top = `${rect.bottom - origin.top + gap}px`;
    panel.style.bottom = "auto";
  }
}

function syncQuestionFamilyMultiselectOpenState(root, open) {
  const panel = root?.querySelector(".question-family-multiselect-panel");
  const trigger = root?.querySelector(".question-family-multiselect-trigger");
  const search = root?.querySelector("[data-question-family-multiselect-search]");
  if (!root?.isConnected || !panel || !trigger || !search) return;
  panel.hidden = !open;
  root.classList.toggle("is-open", open);
  trigger.setAttribute("aria-expanded", String(open));
  if (open) {
    positionQuestionFamilyMultiselect(root);
    // 面板是 fixed 定位、只按打开瞬间的位置算一次；打开后的这一帧里弹窗还会重排
    // （题族卡片展开、选项渲染、字体落地），量到的位置会变。再量一帧，并让触发器
    // 的尺寸变化继续带着面板走，避免面板停在旧位置、看起来伸到弹窗外面。
    trackQuestionFamilyMultiselectPosition(root);
    requestAnimationFrame(() => {
      if (questionFamilyMultiselectIsOpen(root)) positionQuestionFamilyMultiselect(root);
    });
    search.focus({ preventScroll: true });
  } else if (search.value) {
    search.value = "";
    renderQuestionFamilyMultiselect(root.dataset.questionFamilyMultiselect);
  }
}

// 只跟踪当前打开的选择器：触发器一旦改变尺寸（弹窗重排、卡片展开、窗口变化），
// 就重新把面板收回弹窗边界内。
let questionFamilyMultiselectResizeObserver = null;
function trackQuestionFamilyMultiselectPosition(root) {
  if (typeof ResizeObserver !== "function") return;
  const trigger = root.querySelector(".question-family-multiselect-trigger");
  if (!trigger) return;
  if (!questionFamilyMultiselectResizeObserver) {
    questionFamilyMultiselectResizeObserver = new ResizeObserver((entries) => {
      entries.forEach((entry) => {
        const tracked = entry.target.closest(".question-family-multiselect");
        if (tracked && questionFamilyMultiselectIsOpen(tracked)) positionQuestionFamilyMultiselect(tracked);
      });
    });
  }
  questionFamilyMultiselectResizeObserver.disconnect();
  questionFamilyMultiselectResizeObserver.observe(trigger);
}

function setQuestionFamilyMultiselectOpen(type = "", open = false) {
  let changed = false;
  document.querySelectorAll("[data-question-family-multiselect]").forEach((root) => {
    const shouldOpen = open && root.dataset.questionFamilyMultiselect === type;
    const panel = root.querySelector(".question-family-multiselect-panel");
    const wasOpen = questionFamilyMultiselectIsOpen(root);
    if (shouldOpen === wasOpen) {
      if (shouldOpen) syncQuestionFamilyMultiselectOpenState(root, true);
      return;
    }
    changed = true;
    if (shouldOpen) {
      renderQuestionFamilyMultiselect(type);
      panel.hidden = false;
      if (typeof panel.showPopover === "function") panel.showPopover();
      syncQuestionFamilyMultiselectOpenState(root, true);
    } else {
      if (typeof panel.hidePopover === "function") {
        try {
          if (panel.matches(":popover-open")) panel.hidePopover();
        } catch {
          root.classList.remove("is-open");
        }
      }
      syncQuestionFamilyMultiselectOpenState(root, false);
      panel.hidden = true;
    }
  });
  return changed;
}

function renderQuestionFamilyDynamicRelations(dynamicRelations) {
  const section = document.querySelector("#question-family-dynamic-relations");
  const list = document.querySelector("#question-family-dynamic-relation-list");
  const entries = [];
  const addEntry = (type, value) => {
    if (value == null || value === false) return;
    if (Array.isArray(value)) {
      value.forEach((item) => addEntry(type, item));
      return;
    }
    const item = typeof value === "object" ? value : { label: value };
    const label = item.targetName || item.familyName || item.name || item.label || item.path || item.targetId || item.familyId || item.id || (Number.isFinite(Number(item.count)) ? `${item.count} 项` : "已识别");
    entries.push({ type: item.type || item.relationType || type, label, note: item.reason || item.evidence || item.note || "" });
  };
  if (Array.isArray(dynamicRelations)) dynamicRelations.forEach((item) => addEntry(item?.type || item?.relationType || "similar", item));
  else if (dynamicRelations && typeof dynamicRelations === "object") Object.entries(dynamicRelations).forEach(([type, value]) => addEntry(type, value));
  section.hidden = entries.length === 0;
  list.innerHTML = entries.map((entry) => `<span class="question-family-dynamic-relation"><b>${escapeHtml(questionFamilyDynamicRelationLabels[entry.type] || entry.type || "关联")}</b><em>${escapeHtml(entry.label)}</em>${entry.note ? `<small>${escapeHtml(entry.note)}</small>` : ""}</span>`).join("");
}

function renderQuestionFamilyLocationOptions() {
  const primaryAnchorSelect = document.querySelector("#question-family-location-node");
  const coreSelect = document.querySelector("#question-family-core-knowledge");
  const requiredSelect = document.querySelector("#question-family-required-knowledge");
  const anchorsSelect = document.querySelector("#question-family-textbook-anchors");
  const family = state.questionFamilies.find((item) => item.id === document.querySelector("#question-family-id").value);
  const knowledgeNodes = (questionFamilyEditingStructure()?.nodes || []).filter((node) => node.kind === "knowledge");
  const knownIds = new Set(knowledgeNodes.map((node) => node.id));
  if (!knownIds.has(state.questionFamilyCoreKnowledgeNodeId)) state.questionFamilyCoreKnowledgeNodeId = family?.backendDirectoryAnchorNodeId || family?.coreKnowledgeNodeId || family?.knowledgeNodeId || state.creatingQuestionFamilyNodeId || "";
  if (!knownIds.has(state.questionFamilyMoveKnowledgeNodeId)) state.questionFamilyMoveKnowledgeNodeId = family?.userDirectoryAnchorNodeId || family?.locationNodeId || family?.knowledgeNodeId || state.creatingQuestionFamilyNodeId || "";
  state.questionFamilyRequiredKnowledgeNodeIds = [...new Set(state.questionFamilyRequiredKnowledgeNodeIds.filter((id) => knownIds.has(id)))];
  state.questionFamilyTextbookAnchorNodeIds = [...new Set([state.questionFamilyMoveKnowledgeNodeId, ...state.questionFamilyTextbookAnchorNodeIds].filter((id) => knownIds.has(id)))];
  const empty = '<option value="" disabled>没有匹配的具体知识点</option>';
  coreSelect.innerHTML = knowledgeNodes.length ? questionFamilyDefinitionOptions(knowledgeNodes, [state.questionFamilyCoreKnowledgeNodeId]) : empty;
  requiredSelect.innerHTML = knowledgeNodes.length ? questionFamilyDefinitionOptions(knowledgeNodes, state.questionFamilyRequiredKnowledgeNodeIds) : empty;
  primaryAnchorSelect.innerHTML = knowledgeNodes.length ? questionFamilyDefinitionOptions(knowledgeNodes, [state.questionFamilyMoveKnowledgeNodeId]) : empty;
  anchorsSelect.innerHTML = knowledgeNodes.length ? questionFamilyDefinitionOptions(knowledgeNodes, state.questionFamilyTextbookAnchorNodeIds, state.questionFamilyMoveKnowledgeNodeId) : empty;
  renderQuestionFamilyMultiselects();
}

async function openQuestionFamilyReview(familyId) {
  const family = state.questionFamilies.find((item) => item.id === familyId);
  if (!family) return;
  try {
    const payload = await requestJson(`/api/admin/knowledge-structure?bookId=${encodeURIComponent(family.bookId)}&optional=true`);
    state.questionFamilyEditorStructure = payload.structure;
    if (!payload.structure?.nodes?.length) {
      setQuestionFamilyFeedback("该题族教材暂无可用目录，请先补齐目录后编辑。", "error");
      return;
    }
  } catch (error) {
    setQuestionFamilyFeedback(`读取题族教材失败：${friendlyError(error)}`, "error");
    return;
  }
  const memberReviewCounts = questionFamilyMemberReviewCounts(family);
  state.creatingQuestionFamilyNodeId = "";
  document.querySelector("#question-family-id").value = family.id;
  document.querySelector("#question-family-dialog").classList.toggle("is-empty", family.members.length === 0);
  document.querySelector("#question-family-name").value = family.name;
  document.querySelector("#question-family-dialog-title").textContent = `审核题族 · ${family.name}`;
  const requiredPaths = (family.requiredKnowledgeNodes || []).map((node) => node.path || node.displayTitle || node.title).filter(Boolean);
  const singleton = family.members.length === 1;
  document.querySelector("#question-family-dialog-copy").textContent = `${family.primaryKnowledgePoint} · 题族覆盖知识 ${requiredPaths.length} 项 · ${family.members.length} 道题${singleton ? " · 单题可确认，暂无同类 / 变式训练" : ""} · 规则置信度 ${Math.round(family.confidence * 100)}%`;
  document.querySelector("#question-family-context").innerHTML = `<strong>当前题族依据</strong><span>${escapeHtml(family.reason || "请核对下方知识、考查动作和辨析边界后再确认题族。")}</span>`;
  setQuestionFamilyDefinitionState(family);
  document.querySelector("#question-family-location-editor").hidden = false;
  renderQuestionFamilyLocationOptions();
  renderQuestionFamilyDynamicRelations(family.dynamicRelations);
  document.querySelector("#question-family-members").innerHTML = family.members.length
    ? family.members.map(questionFamilyMemberHtml).join("")
    : '<div class="question-family-members-empty"><strong>这个题族目前还是空集</strong><span>题族骨架已保留，后续补充题目并审核后才会进入智能复习。</span></div>';
  document.querySelector("#question-family-member-review-summary").textContent = family.members.length
    ? `正式 ${memberReviewCounts.confirmed} · 待审 ${memberReviewCounts.pending_fit}${memberReviewCounts.inactive ? ` · 已失效 ${memberReviewCounts.inactive}` : ""} · 仅保留 1 道原型题`
    : "当前 0 道题";
  document.querySelector("#add-question-family-members").hidden = false;
  const deleteButton = document.querySelector("#delete-question-family");
  deleteButton.hidden = false;
  deleteButton.disabled = false;
  document.querySelector("#reject-question-family").hidden = family.status === "rejected";
  document.querySelector("#confirm-question-family").textContent = singleton ? "确认单题题族" : (family.members.length ? "确认题族" : "保存空题族");
  setSmallDialogStatus("#question-family-dialog-status");
  document.querySelector("#question-family-dialog").showModal();
}

function openEmptyQuestionFamilyDialog() {
  const node = state.knowledgeStructure?.nodes.find((item) => item.id === state.selectedKnowledgeNodeId);
  if (!node || node.kind !== "knowledge") {
    setQuestionFamilyFeedback("请先在左侧选择一个具体知识点，再创建空题族。", "error");
    return;
  }
  state.creatingQuestionFamilyNodeId = node.id;
  document.querySelector("#question-family-dialog").classList.add("is-empty");
  document.querySelector("#question-family-id").value = "";
  document.querySelector("#question-family-name").value = "";
  document.querySelector("#question-family-name").placeholder = `例如：${node.displayTitle}辨析`;
  document.querySelector("#question-family-dialog-title").textContent = "新建空题族";
  document.querySelector("#question-family-dialog-copy").textContent = "先建立题族骨架，后续再补充和审核题目";
  document.querySelector("#question-family-context").innerHTML = `<strong>起始教材位置：${escapeHtml(node.path)}</strong><span>先补充题族定义；题目可以稍后再加入。</span>`;
  setQuestionFamilyDefinitionState({}, node.id);
  document.querySelector("#question-family-location-editor").hidden = false;
  renderQuestionFamilyLocationOptions();
  renderQuestionFamilyDynamicRelations(null);
  document.querySelector("#question-family-members").innerHTML = '<div class="question-family-members-empty"><strong>暂不添加题目</strong><span>本次只创建空题族骨架。</span></div>';
  document.querySelector(".question-family-member-head span").textContent = "当前 0 道题";
  document.querySelector("#add-question-family-members").hidden = true;
  document.querySelector("#delete-question-family").hidden = true;
  document.querySelector("#reject-question-family").hidden = true;
  document.querySelector("#confirm-question-family").textContent = "创建空题族";
  setSmallDialogStatus("#question-family-dialog-status");
  document.querySelector("#question-family-dialog").showModal();
  document.querySelector("#question-family-name").focus();
}

function closeQuestionFamilyPicker() {
  const dialog = document.querySelector("#question-family-picker-dialog");
  if (dialog.open) dialog.close();
  state.questionFamilyPickerFamilyId = "";
  state.questionFamilyPickerQuestions = [];
  state.questionFamilyPickerSelectedIds = [];
  setSmallDialogStatus("#question-family-picker-status");
}

function closeQuestionGrouping() {
  const dialog = document.querySelector("#question-grouping-dialog");
  if (dialog.open) dialog.close();
  state.questionGroupingQuestions = [];
  state.questionGroupingFamilies = [];
  state.questionGroupingMode = "add";
  state.questionGroupingSourceFamilyId = "";
  state.questionGroupingFamilyId = "";
  state.questionGroupingKnowledgeNodeId = "";
  document.querySelector("#question-grouping-family-search").value = "";
  document.querySelector("#question-grouping-knowledge-search").value = "";
  setSmallDialogStatus("#question-grouping-status");
}

function renderQuestionGroupingSelection() {
  const questions = state.questionGroupingQuestions;
  const sourceFamily = state.questionFamilies.find((family) => family.id === state.questionGroupingSourceFamilyId);
  document.querySelector("#question-grouping-selected-summary").textContent = `${questions.length} 道 · ${questionBookName(questions[0]?.bookId || "")}${state.questionGroupingMode === "move" ? ` · 来源：${sourceFamily?.name || "当前题族"}` : ""}`;
  document.querySelector("#question-grouping-selected-list").innerHTML = questions.map((question, index) => `
    <article class="question-grouping-selected-item">
      <span>${index + 1}</span>
      <div><strong>${escapeHtml(question.stem)}</strong>${questionOptionListHtml(question.options, "compact")}<small>${escapeHtml(question.id)} · ${escapeHtml(question.typeLabel || question.type || "未知题型")}</small></div>
    </article>`).join("");
  const prototype = document.querySelector("#question-grouping-prototype");
  prototype.innerHTML = questions.map((question, index) => `<option value="${escapeHtml(question.id)}">${index + 1}. ${escapeHtml(String(question.stem || "").slice(0, 90))}</option>`).join("");
}

function questionGroupingAlreadyInFamilyCount(familyId) {
  return state.questionGroupingQuestions.filter((question) => (question.familyMemberships || []).some((membership) => membership.familyId === familyId)).length;
}

function renderQuestionGroupingFamilies() {
  const query = document.querySelector("#question-grouping-family-search").value.trim().toLocaleLowerCase("zh-CN");
  const moving = state.questionGroupingMode === "move";
  const families = state.questionGroupingFamilies
    .filter((family) => family.status !== "rejected")
    .filter((family) => !query || `${family.name} ${family.knowledgePath}`.toLocaleLowerCase("zh-CN").includes(query));
  document.querySelector("#question-grouping-family-list").innerHTML = families.length ? families.map((family) => {
    const alreadyCount = questionGroupingAlreadyInFamilyCount(family.id);
    const sourceFamily = moving && family.id === state.questionGroupingSourceFamilyId;
    const disabled = sourceFamily || (!moving && alreadyCount === state.questionGroupingQuestions.length);
    return `<label class="question-grouping-family-option ${disabled ? "is-disabled" : ""}">
      <input type="radio" name="question-grouping-family" value="${escapeHtml(family.id)}" ${state.questionGroupingFamilyId === family.id ? "checked" : ""} ${disabled ? "disabled" : ""} />
      <span><strong>${escapeHtml(family.name)}</strong><small>${escapeHtml(family.knowledgePath || "未标注知识路径")} · 当前 ${family.memberCount || 0} 道${sourceFamily ? " · 当前来源" : (alreadyCount ? ` · 所选中已有 ${alreadyCount} 道` : "")}</small></span>
      <em class="${escapeHtml(family.status)}">${escapeHtml(questionFamilyStatusLabels[family.status] || family.status)}</em>
    </label>`;
  }).join("") : `<div class="question-grouping-empty">没有匹配的可用题族，可切换到“${moving ? "新建题族并移动" : "新建题族并加入"}”。</div>`;
  updateQuestionGroupingConfirmState();
}

function renderQuestionGroupingKnowledgeOptions() {
  const select = document.querySelector("#question-grouping-knowledge-node");
  const query = document.querySelector("#question-grouping-knowledge-search").value.trim().toLocaleLowerCase("zh-CN");
  const knowledgeNodes = (state.knowledgeStructure?.nodes || []).filter((node) => node.kind === "knowledge");
  if (state.questionGroupingKnowledgeNodeId && !knowledgeNodes.some((node) => node.id === state.questionGroupingKnowledgeNodeId)) {
    state.questionGroupingKnowledgeNodeId = "";
  }
  const nodes = knowledgeNodes
    .filter((node) => !query || String(node.path || node.displayTitle).toLocaleLowerCase("zh-CN").includes(query));
  select.innerHTML = nodes.length
    ? nodes.map((node) => `<option value="${escapeHtml(node.id)}" ${node.id === state.questionGroupingKnowledgeNodeId ? "selected" : ""}>${escapeHtml(node.path)}</option>`).join("")
    : '<option value="" disabled>没有匹配的具体知识点</option>';
  if (!nodes.some((node) => node.id === state.questionGroupingKnowledgeNodeId)) select.selectedIndex = -1;
  updateQuestionGroupingConfirmState();
}

function updateQuestionGroupingConfirmState() {
  const button = document.querySelector("#confirm-question-grouping");
  if (!button) return;
  const creating = state.questionGroupingTab === "new";
  const moving = state.questionGroupingMode === "move";
  const name = document.querySelector("#question-grouping-family-name").value.trim();
  const focusKey = document.querySelector("#question-grouping-family-focus-key").value.trim();
  button.textContent = creating
    ? `${moving ? "创建并移动" : "创建并归入"} ${state.questionGroupingQuestions.length} 道题`
    : (moving ? `移动 ${state.questionGroupingQuestions.length} 道题` : "归入所选题族");
  button.disabled = creating
    ? !name || !focusKey || !state.questionGroupingKnowledgeNodeId || !state.questionGroupingQuestions.length
    : !state.questionGroupingFamilyId || !state.questionGroupingQuestions.length;
}

function setQuestionGroupingTab(tab) {
  state.questionGroupingTab = tab === "new" ? "new" : "existing";
  document.querySelectorAll("[data-question-grouping-tab]").forEach((button) => {
    const active = button.dataset.questionGroupingTab === state.questionGroupingTab;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-selected", String(active));
  });
  document.querySelector("#question-grouping-existing-panel").hidden = state.questionGroupingTab !== "existing";
  document.querySelector("#question-grouping-new-panel").hidden = state.questionGroupingTab !== "new";
  updateQuestionGroupingConfirmState();
}

async function openQuestionGrouping(mode = "add") {
  const byId = new Map(questionFamilyVisibleQuestions().map((question) => [question.id, question]));
  const questions = state.questionSelectedIds.map((id) => byId.get(id)).filter(Boolean);
  if (!questions.length) return;
  const moving = mode === "move";
  const sourceFamilyId = moving ? movableQuestionFamilySourceId() : "";
  const sourceFamily = state.questionFamilies.find((family) => family.id === sourceFamilyId);
  if (moving && !sourceFamily) {
    window.alert("移动仅支持在同一个题族内勾选题目；未成族或跨题族混选请使用“归入题族”。");
    return;
  }
  const workspaceBookId = questionFamilyWorkspaceBookId();
  const explicitBookIds = [...new Set(questions.map((question) => question.bookId).filter(Boolean))];
  if (!workspaceBookId || questions.some(question => !question.bookId) || explicitBookIds.length > 1 || (explicitBookIds.length === 1 && explicitBookIds[0] !== workspaceBookId)) {
    window.alert("请先筛选同一本教材，再批量归入题族。");
    return;
  }
  const bookId = explicitBookIds[0] || workspaceBookId;
  state.questionGroupingMode = moving ? "move" : "add";
  state.questionGroupingSourceFamilyId = sourceFamilyId;
  state.questionGroupingQuestions = questions.map((question) => question.bookId ? question : { ...question, bookId });
  state.questionGroupingFamilies = [];
  state.questionGroupingFamilyId = "";
  state.questionGroupingKnowledgeNodeId = "";
  document.querySelector("#question-grouping-title").textContent = moving ? "移动到题族" : "归入题族";
  document.querySelector("#question-grouping-copy").textContent = moving
    ? `${questions.length} 道题 · 从“${sourceFamily.name}”移动 · 其他题族归属保持不变`
    : `${questions.length} 道题 · ${questionBookName(bookId)} · 一次完成创建与归组`;
  const groupingTabs = document.querySelectorAll("[data-question-grouping-tab]");
  groupingTabs[0].textContent = moving ? "移动到已有题族" : "加入已有题族";
  groupingTabs[1].textContent = moving ? "新建题族并移动" : "新建题族并加入";
  document.querySelector("#question-grouping-family-search").value = "";
  document.querySelector("#question-grouping-knowledge-search").value = "";
  document.querySelector("#question-grouping-family-name").value = "";
  document.querySelector("#question-grouping-family-focus-key").value = "";
  renderQuestionGroupingSelection();
  setQuestionGroupingTab("existing");
  setSmallDialogStatus("#question-grouping-status", "正在读取题族和知识结构", "loading");
  document.querySelector("#question-grouping-dialog").showModal();
  try {
    const [familyPayload, structurePayload] = await Promise.all([
      requestJson(`/api/admin/question-family-options?bookId=${encodeURIComponent(bookId)}`),
      requestJson(`/api/admin/knowledge-structure?bookId=${encodeURIComponent(bookId)}&generate=true`),
    ]);
    state.questionGroupingFamilies = familyPayload.families || [];
    state.knowledgeStructure = structurePayload.structure;
    const primaryNodeIds = [...new Set(questions.map((question) => question.knowledgeFingerprint?.primaryNodeId).filter(Boolean))];
    const selectedNode = state.knowledgeStructure.nodes.find((node) => node.id === state.selectedKnowledgeNodeId && node.kind === "knowledge");
    state.questionGroupingKnowledgeNodeId = primaryNodeIds.length === 1 ? primaryNodeIds[0] : (selectedNode?.id || "");
    const primaryNames = [...new Set(questions.map((question) => question.knowledgeFingerprint?.primaryKnowledgePoint || question.primaryKnowledgePoint).filter(Boolean))];
    if (primaryNames.length === 1) document.querySelector("#question-grouping-family-name").value = `${primaryNames[0]}·专项辨析`;
    renderQuestionGroupingFamilies();
    renderQuestionGroupingKnowledgeOptions();
    if (!state.questionGroupingFamilies.some((family) => family.status !== "rejected")) setQuestionGroupingTab("new");
    setSmallDialogStatus("#question-grouping-status");
  } catch (error) {
    setSmallDialogStatus("#question-grouping-status", `读取失败：${friendlyError(error)}`, "error");
  }
}

async function confirmQuestionGrouping() {
  const questions = state.questionGroupingQuestions;
  if (!questions.length) return;
  const button = document.querySelector("#confirm-question-grouping");
  const creating = state.questionGroupingTab === "new";
  const moving = state.questionGroupingMode === "move";
  const sourceFamily = moving ? state.questionFamilies.find((family) => family.id === state.questionGroupingSourceFamilyId) : null;
  if (moving && !sourceFamily) {
    setSmallDialogStatus("#question-grouping-status", "来源题族已经变化，请关闭后重新选择", "error");
    return;
  }
  button.disabled = true;
  setSmallDialogStatus("#question-grouping-status", moving
    ? (creating ? "正在创建题族并移动所选题目" : "正在原子移动所选题目")
    : (creating ? "正在创建题族并加入所选题目" : "正在加入所选题族"), "loading");
  try {
    let familyId;
    let familyName;
    let addedCount;
    let sourceEmptied = false;
    if (moving) {
      const family = creating ? null : state.questionGroupingFamilies.find((item) => item.id === state.questionGroupingFamilyId);
      if (!creating && !family) throw new Error("question_family_not_found");
      const name = document.querySelector("#question-grouping-family-name").value.trim();
      const focusKey = document.querySelector("#question-grouping-family-focus-key").value.trim();
      const prototypeQuestionId = document.querySelector("#question-grouping-prototype").value;
      const payload = await requestJson(`/api/admin/question-families/${encodeURIComponent(sourceFamily.id)}/move-members`, {
        method: "POST",
        body: JSON.stringify({
          questionIds: questions.map((question) => question.id),
          target: creating
            ? {
              mode: "new",
              knowledgeNodeId: state.questionGroupingKnowledgeNodeId,
              name,
              focusKey,
              prototypeQuestionId,
            }
            : { mode: "existing", familyId: family.id },
        }),
      });
      familyId = payload.targetFamily.id;
      familyName = payload.targetFamily.name;
      addedCount = payload.movedCount;
      sourceEmptied = payload.sourceFamily.members.length === 0;
    } else if (creating) {
      const prototypeId = document.querySelector("#question-grouping-prototype").value;
      const questionIds = [prototypeId, ...questions.map((question) => question.id).filter((id) => id !== prototypeId)];
      const name = document.querySelector("#question-grouping-family-name").value.trim();
      const focusKey = document.querySelector("#question-grouping-family-focus-key").value.trim();
      const payload = await requestJson("/api/admin/question-families", {
        method: "POST",
        body: JSON.stringify({
          bookId: questions[0].bookId,
          knowledgeNodeId: state.questionGroupingKnowledgeNodeId,
          name,
          focusKey,
          questionIds,
        }),
      });
      familyId = payload.family.id;
      familyName = payload.family.name;
      addedCount = payload.addedCount || payload.family.members.length;
    } else {
      const family = state.questionGroupingFamilies.find((item) => item.id === state.questionGroupingFamilyId);
      if (!family) throw new Error("question_family_not_found");
      const payload = await requestJson(`/api/admin/question-families/${encodeURIComponent(family.id)}/members`, {
        method: "POST",
        body: JSON.stringify({ questionIds: questions.map((question) => question.id) }),
      });
      familyId = family.id;
      familyName = family.name;
      addedCount = payload.addedCount;
    }
    closeQuestionGrouping();
    clearQuestionFamilyManagementSelection();
    state.expandedQuestionFamilyIds.add(familyId);
    await loadQuestionFamilies();
    setQuestionFamilyFeedback(moving
      ? `已将 ${addedCount} 道题从“${sourceFamily.name}”移动到“${familyName}”；变动的成员归属待审核，题族定义状态保持不变${sourceEmptied ? "，来源题族已保留为空题族" : ""}。`
      : (creating
        ? `已创建待审核题族“${familyName}”，并加入 ${addedCount} 道待审核成员。`
        : `已向题族“${familyName}”加入 ${addedCount} 道题；新增成员归属待审核，题族定义状态保持不变。`), "success");
  } catch (error) {
    setSmallDialogStatus("#question-grouping-status", `${moving ? "移动" : "归组"}失败：${friendlyError(error)}`, "error");
    button.disabled = false;
  }
}

function renderQuestionFamilyPicker() {
  const family = state.questionFamilies.find((item) => item.id === state.questionFamilyPickerFamilyId);
  const selected = new Set(state.questionFamilyPickerSelectedIds);
  const existing = new Set((family?.members || []).map((member) => member.questionId));
  const questions = state.questionFamilyPickerQuestions.filter((question) => !existing.has(question.id));
  const visibleQuestions = questions.slice(0, 100);
  document.querySelector("#question-family-picker-dialog").classList.toggle("is-compact", visibleQuestions.length <= 3);
  document.querySelector("#question-family-picker-summary").textContent = questions.length > 100
    ? `已选 ${selected.size} 道 · 显示前 100 道，请继续搜索缩小范围`
    : `已选 ${selected.size} 道 · 找到 ${questions.length} 道可加入题目`;
  document.querySelector("#confirm-question-family-picker").disabled = selected.size === 0;
  document.querySelector("#question-family-picker-results").innerHTML = visibleQuestions.length ? visibleQuestions.map((question) => {
    const memberships = (question.familyMemberships || [])
      .filter((membership) => membership.familyId !== family?.id)
      .map((membership) => membership.familyName)
      .filter(Boolean);
    return `<label class="question-family-picker-item">
      <input type="checkbox" data-question-family-picker-id="${escapeHtml(question.id)}" ${selected.has(question.id) ? "checked" : ""} />
      <span class="question-family-picker-item-main">
        <strong>${escapeHtml(question.stem)}</strong>
        ${questionOptionListHtml(question.options, "compact")}
        <small>${escapeHtml(question.id)} · ${escapeHtml(question.typeLabel || question.type)} · ${escapeHtml(question.chapter || "未归类")}</small>
        ${memberships.length ? `<em>已归属：${escapeHtml(memberships.join(" · "))}</em>` : ""}
      </span>
    </label>`;
  }).join("") : '<div class="question-family-picker-empty">当前范围内没有可加入的题目</div>';
}

async function loadQuestionFamilyPicker() {
  const family = state.questionFamilies.find((item) => item.id === state.questionFamilyPickerFamilyId);
  if (!family) return;
  const query = new URLSearchParams({
    library: "official",
    status: "all",
    bookId: family.bookId,
    query: document.querySelector("#question-family-picker-search").value.trim(),
    knowledgeNodeId: document.querySelector("#question-family-picker-current-knowledge").checked ? family.knowledgeNodeId : "",
  });
  document.querySelector("#question-family-picker-results").innerHTML = '<div class="question-family-picker-empty">正在读取题目</div>';
  try {
    const payload = await requestJson(`/api/admin/questions?${query}`);
    state.questionFamilyPickerQuestions = (payload.questions || []).filter((question) => question.status !== "offline");
    renderQuestionFamilyPicker();
    setSmallDialogStatus("#question-family-picker-status");
  } catch (error) {
    setSmallDialogStatus("#question-family-picker-status", `读取失败：${friendlyError(error)}`, "error");
  }
}

async function openQuestionFamilyPicker() {
  const familyId = document.querySelector("#question-family-id").value;
  const family = state.questionFamilies.find((item) => item.id === familyId);
  if (!family) return;
  state.questionFamilyPickerFamilyId = family.id;
  state.questionFamilyPickerQuestions = [];
  state.questionFamilyPickerSelectedIds = [];
  document.querySelector("#question-family-picker-search").value = "";
  document.querySelector("#question-family-picker-current-knowledge").checked = true;
  document.querySelector("#question-family-picker-copy").textContent = `${family.name} · ${family.knowledgePath}`;
  document.querySelector("#question-family-picker-summary").textContent = "已选 0 道";
  document.querySelector("#confirm-question-family-picker").disabled = true;
  setSmallDialogStatus("#question-family-picker-status");
  document.querySelector("#question-family-picker-dialog").showModal();
  await loadQuestionFamilyPicker();
}

async function addSelectedQuestionFamilyMembers() {
  const familyId = state.questionFamilyPickerFamilyId;
  const questionIds = [...state.questionFamilyPickerSelectedIds];
  if (!familyId || !questionIds.length) return;
  const button = document.querySelector("#confirm-question-family-picker");
  button.disabled = true;
  setSmallDialogStatus("#question-family-picker-status", "正在加入题族", "loading");
  try {
    const payload = await requestJson(`/api/admin/question-families/${encodeURIComponent(familyId)}/members`, {
      method: "POST",
      body: JSON.stringify({ questionIds }),
    });
    closeQuestionFamilyPicker();
    document.querySelector("#question-family-dialog").close();
    await loadQuestionFamilies();
    if (state.questionFamilies.some((family) => family.id === familyId)) {
      openQuestionFamilyReview(familyId);
      setSmallDialogStatus("#question-family-dialog-status", `已加入 ${payload.addedCount} 道题；新增成员归属待审核，题族定义状态保持不变。`, "success");
    } else {
      setQuestionFamilyFeedback(`已加入 ${payload.addedCount} 道题；新增成员归属待审核，题族定义状态与当前筛选保持不变。`, "success");
    }
  } catch (error) {
    setSmallDialogStatus("#question-family-picker-status", `添加失败：${friendlyError(error)}`, "error");
    button.disabled = false;
  }
}

async function removeQuestionFamilyMember(questionId) {
  const familyId = document.querySelector("#question-family-id").value;
  if (!familyId || !window.confirm("确认将这道题移出当前题族？题目本身不会被删除。")) return;
  setSmallDialogStatus("#question-family-dialog-status", "正在移出题目", "loading");
  try {
    await requestJson(`/api/admin/question-families/${encodeURIComponent(familyId)}/members/${encodeURIComponent(questionId)}`, { method: "DELETE" });
    document.querySelector("#question-family-dialog").close();
    await loadQuestionFamilies();
    if (state.questionFamilies.some((family) => family.id === familyId)) {
      openQuestionFamilyReview(familyId);
      setSmallDialogStatus("#question-family-dialog-status", "题目归属已移除，题族定义状态保持不变。", "success");
    } else {
      setQuestionFamilyFeedback("题目归属已移除，题族定义状态与当前筛选保持不变。", "success");
    }
  } catch (error) {
    setSmallDialogStatus("#question-family-dialog-status", `移出失败：${friendlyError(error)}`, "error");
  }
}

function closeQuestionFamilyMemberReviewDialog() {
  const dialog = document.querySelector("#question-family-member-review-dialog");
  if (dialog.open) dialog.close();
  state.questionFamilyMemberReviewTarget = null;
  document.querySelector("#question-family-member-review-reason").value = "";
  setSmallDialogStatus("#question-family-member-review-dialog-status");
}

function openQuestionFamilyMemberRejection(familyId, questionId) {
  const family = state.questionFamilies.find((item) => item.id === familyId);
  const member = family?.members?.find((item) => item.questionId === questionId);
  if (!family || !member) return;
  state.questionFamilyMemberReviewTarget = {
    familyId,
    questionId,
    expectedRevision: Math.max(0, Number(member.membershipRevision) || 0),
  };
  document.querySelector("#question-family-member-review-question").textContent = member.question?.stem || questionId;
  document.querySelector("#question-family-member-review-family").textContent = `当前题族：${family.name}`;
  document.querySelector("#question-family-member-review-reason").value = "";
  setSmallDialogStatus("#question-family-member-review-dialog-status");
  document.querySelector("#question-family-member-review-dialog").showModal();
  document.querySelector("#question-family-member-review-reason").focus();
}

function currentQuestionFamilyMemberContribution(questionId, family, member) {
  const row = [...document.querySelectorAll("#question-family-members .question-family-member")]
    .find((candidate) => candidate.dataset.questionId === questionId);
  if (!row) return questionFamilyMemberContributionNodeIds(member, family);
  return [...row.querySelectorAll("[data-family-member-contribution-node][aria-pressed='true']")]
    .map((button) => button.dataset.familyMemberContributionNode).filter(Boolean);
}

async function reviewQuestionFamilyMember(familyId, questionId, status, note = "", expectedRevision = null) {
  const family = state.questionFamilies.find((item) => item.id === familyId);
  const member = family?.members?.find((item) => item.questionId === questionId);
  if (!family || !member) return;
  const familyDialog = document.querySelector("#question-family-dialog");
  const reopenFamilyDialog = familyDialog.open && document.querySelector("#question-family-id").value === familyId;
  const pendingMessage = status === "confirmed" ? "正在确认成员归属" : "正在驳回成员归属";
  const successMessage = status === "confirmed"
    ? `已确认该题归属于题族“${family.name}”，题族定义状态保持不变。`
    : `已驳回该题归属于题族“${family.name}”，题目本身不会删除。`;
  setQuestionFamilyFeedback(pendingMessage, "loading");
  if (status === "rejected") setSmallDialogStatus("#question-family-member-review-dialog-status", pendingMessage, "loading");
  try {
    await requestJson(`/api/admin/question-families/${encodeURIComponent(familyId)}/members/${encodeURIComponent(questionId)}/review`, {
      method: "PUT",
      body: JSON.stringify({
        status,
        contributionKnowledgeNodeIds: status === "confirmed"
          ? currentQuestionFamilyMemberContribution(questionId, family, member)
          : [],
        expectedRevision: expectedRevision == null
          ? Math.max(0, Number(member.membershipRevision) || 0)
          : Math.max(0, Number(expectedRevision) || 0),
        note: String(note || "").trim(),
      }),
    });
    if (status === "rejected") closeQuestionFamilyMemberReviewDialog();
    if (reopenFamilyDialog) familyDialog.close();
    await loadQuestionFamilies();
    if (reopenFamilyDialog && state.questionFamilies.some((item) => item.id === familyId)) openQuestionFamilyReview(familyId);
    setQuestionFamilyFeedback(successMessage, "success");
    if (reopenFamilyDialog) setSmallDialogStatus("#question-family-dialog-status", successMessage, "success");
  } catch (error) {
    const message = `成员归属审核失败：${friendlyError(error)}`;
    setQuestionFamilyFeedback(message, "error");
    if (status === "rejected") setSmallDialogStatus("#question-family-member-review-dialog-status", message, "error");
    else if (reopenFamilyDialog) setSmallDialogStatus("#question-family-dialog-status", message, "error");
  }
}

async function confirmQuestionFamilyMemberRejection() {
  const target = state.questionFamilyMemberReviewTarget;
  if (!target) return;
  const note = document.querySelector("#question-family-member-review-reason").value.trim();
  if (!note) {
    setSmallDialogStatus("#question-family-member-review-dialog-status", "请填写驳回原因", "error");
    return;
  }
  await reviewQuestionFamilyMember(target.familyId, target.questionId, "rejected", note, target.expectedRevision);
}

function currentQuestionFamilyMembers() {
  const familyId = document.querySelector("#question-family-id").value;
  const family = state.questionFamilies.find((item) => item.id === familyId);
  if (!family) return [];
  const currentById = new Map(family.members.map((member) => [member.questionId, member]));
  return [...document.querySelectorAll("#question-family-members .question-family-member")].map((row) => {
    const current = currentById.get(row.dataset.questionId) || {};
    return {
      ...current,
      question: undefined,
      questionId: row.dataset.questionId,
      role: row.querySelector("[data-family-member-role]").value,
      trainingLevel: row.querySelector("[data-family-member-level]").value,
      contributionKnowledgeNodeIds: [...row.querySelectorAll("[data-family-member-contribution-node][aria-pressed='true']")]
        .map((button) => button.dataset.familyMemberContributionNode).filter(Boolean),
    };
  });
}

async function deleteQuestionFamily() {
  const familyId = document.querySelector("#question-family-id").value;
  const family = state.questionFamilies.find((item) => item.id === familyId);
  if (!family) return;
  const memberCount = family.members.length;
  const impact = memberCount
    ? `其中仅归属于本题族的题目会回到“未成族”；仍有其他题族归属的题目会保留。${memberCount} 道题本身都不会被删除。`
    : "这是一个空题族，不会影响题库中的题目。";
  if (!window.confirm(`确认删除题族“${family.name}”吗？\n\n${impact}\n\n删除后无法直接恢复；如果以后重新生成候选且题目知识指纹未变，同类题族仍可能再次生成。`)) return;
  const button = document.querySelector("#delete-question-family");
  button.disabled = true;
  setSmallDialogStatus("#question-family-dialog-status", "正在删除题族", "loading");
  try {
    const payload = await requestJson(`/api/admin/question-families/${encodeURIComponent(familyId)}`, { method: "DELETE" });
    document.querySelector("#question-family-dialog").close();
    state.expandedQuestionFamilyIds.delete(familyId);
    await loadQuestionFamilies();
    const ungroupedCount = payload.ungroupedQuestionIds?.length || 0;
    setQuestionFamilyFeedback(`已删除题族“${payload.family.name}”${ungroupedCount ? `，${ungroupedCount} 道题已回到未成族` : "，题目内容未受影响"}。`, "success");
  } catch (error) {
    setSmallDialogStatus("#question-family-dialog-status", `删除失败：${friendlyError(error)}`, "error");
  } finally {
    button.disabled = false;
  }
}

async function saveQuestionFamily(status) {
  const familyId = document.querySelector("#question-family-id").value;
  const name = document.querySelector("#question-family-name").value.trim();
  const definition = questionFamilyDefinitionPayload();
  if (!name) {
    setSmallDialogStatus("#question-family-dialog-status", "请填写题族名称", "error");
    return;
  }
  if (!definition.focusKey) {
    setSmallDialogStatus("#question-family-dialog-status", "请填写题族判别焦点", "error");
    return;
  }
  if (!definition.coreKnowledgeNodeId) {
    setSmallDialogStatus("#question-family-dialog-status", "请选择后台目录锚点", "error");
    return;
  }
  if (!definition.requiredKnowledgeNodeIds.length) {
    setSmallDialogStatus("#question-family-dialog-status", "请至少选择一项题族覆盖知识", "error");
    return;
  }
  if (!definition.textbookAnchorNodeIds.length) {
    setSmallDialogStatus("#question-family-dialog-status", "请至少选择一个教材锚点", "error");
    return;
  }
  if (!familyId) {
    setSmallDialogStatus("#question-family-dialog-status", "正在创建空题族", "loading");
    try {
      await requestJson("/api/admin/question-families", {
        method: "POST",
        body: JSON.stringify({
          bookId: document.querySelector("#question-book-filter").value,
          knowledgeNodeId: definition.textbookAnchorNodeIds[0],
          name,
          ...definition,
        }),
      });
      document.querySelector("#question-family-dialog").close();
      state.creatingQuestionFamilyNodeId = "";
      await loadQuestionFamilies();
      setQuestionFamilyFeedback(`已在当前知识点下创建空题族“${name}”。`, "success");
    } catch (error) {
      setSmallDialogStatus("#question-family-dialog-status", `创建失败：${friendlyError(error)}`, "error");
    }
    return;
  }
  const members = currentQuestionFamilyMembers();
  const family = state.questionFamilies.find((item) => item.id === familyId);
  const effectiveStatus = status === "rejected"
    ? "rejected"
    : (members.length ? "confirmed" : (family?.status === "rejected" ? "rejected" : "pending_review"));
  const primaryAnchorNodeId = definition.textbookAnchorNodeIds[0];
  const primaryAnchorChanged = Boolean(family && String(family.knowledgeNodeId || "") !== primaryAnchorNodeId);
  if (effectiveStatus === "confirmed" && members.filter((member) => member.role === "prototype").length !== 1) {
    setSmallDialogStatus("#question-family-dialog-status", "确认题族前，必须且只能指定 1 道原型题", "error");
    return;
  }
  if (effectiveStatus === "confirmed" && !definition.assessmentAction) {
    setSmallDialogStatus("#question-family-dialog-status", "确认题族前，请填写明确的考查动作", "error");
    return;
  }
  if (primaryAnchorChanged) {
    const targetNode = questionFamilyKnowledgeNode(primaryAnchorNodeId);
    const targetLabel = targetNode?.path || targetNode?.displayTitle || targetNode?.title || primaryAnchorNodeId;
    if (!window.confirm(`用户端目录锚点已改为“${targetLabel}”。\n\n确认题族后将同步移动目录，题目成员不变。`)) return;
  }
  setSmallDialogStatus("#question-family-dialog-status", effectiveStatus === "confirmed" ? "正在确认题族" : (effectiveStatus === "rejected" ? "正在驳回题族" : "正在保存待审核题族"), "loading");
  try {
    await requestJson(`/api/admin/question-families/${encodeURIComponent(familyId)}`, {
      method: "PUT",
      body: JSON.stringify({
        name,
        status: effectiveStatus,
        members,
        knowledgeNodeId: primaryAnchorNodeId,
        ...definition,
      }),
    });
    document.querySelector("#question-family-dialog").close();
    if (primaryAnchorChanged && questionFamilyWorkspaceBookId() === family?.bookId) {
      state.selectedKnowledgeNodeId = primaryAnchorNodeId;
      state.expandedQuestionFamilyIds.add(familyId);
      renderKnowledgeTree();
    }
    await loadQuestionFamilies();
    setQuestionFamilyFeedback(effectiveStatus === "confirmed"
      ? (members.length === 1
        ? "单题题族已确认并进入教材目录；当前样本不足，暂不提供同类 / 变式训练。"
        : "题族已确认。")
      : (effectiveStatus === "rejected" ? "题族已驳回。" : "题族已保存为待审核。"), "success");
  } catch (error) {
    setSmallDialogStatus("#question-family-dialog-status", `保存失败：${friendlyError(error)}`, "error");
  }
}

async function openView(name) {  // 兼容旧入口：「题目完善」已从一级导航搬进「题库管理 → 完善题目」。
  // 旧链接 / 旧书签仍然带这个名字进来，统一落到题库管理并把子标签切到「完善题目」。
  const requestedEnrichment = name === "题目完善";
  if (requestedEnrichment) name = "题库管理";
  if (name === "题库管理（新）") name = "题库管理";
  // 兼容旧入口：「审核与举报 / 用户限制 / 公告管理」已并入「社区管理」二级菜单，旧名字落到对应子标签。
  const communitySubViews = { "审核与举报": "moderation", "用户限制": "restrictions", "公告管理": "announcements" };
  if (name === "审核与举报" || name === "用户限制" || name === "公告管理") {
    state.communityAdminTab = communitySubViews[name];
    name = "社区管理";
  }
  state.currentView = name;
  if (aiTaskRefreshTimer) {
    clearInterval(aiTaskRefreshTimer);
    aiTaskRefreshTimer = null;
  }
  if (name !== "模拟考试") stopExamImportPolling();
  if (name !== "题目完善") stopQuestionEnrichmentPolling();
  if (!["题库管理", "平台题库", "题族管理", "公共题库"].includes(name)) stopKnowledgeInspectionPolling();
  const communityAdminTab = ["moderation", "restrictions", "announcements"].includes(state.communityAdminTab)
    ? state.communityAdminTab
    : "moderation";
  // 二级菜单：手风琴——只展开“当前页所在的分组”，避免侧栏又长又同时高亮多处。
  const activeNavGroup = navGroupOfView(name);
  setNavGroupExpanded(activeNavGroup, Boolean(activeNavGroup));
  syncNavActive(name, communityAdminTab);
  document.querySelector("#view-title").textContent = name === "模拟考试" ? "试卷管理" : name;
  const isDashboard = name === "工作台";
  const isAiConfig = name === "AI 模型路由";
  const isAiTasks = name === "AI 任务记录";
  const isQuestionLibrary = ["题库管理", "平台题库", "题族管理", "公共题库"].includes(name);
  const isTextbookCatalog = name === "教材与目录";
  const isExamAdmin = name === "模拟考试";
  const isPackAdmin = name === "题包";
  const isCommunityAdmin = name === "社区管理";
  const isModeration = isCommunityAdmin && communityAdminTab === "moderation";
  const isAnnouncementAdmin = isCommunityAdmin && communityAdminTab === "announcements";
  // 平台设置（2026-10-05）：独立一级菜单，仅超级管理员可访问（后端默认拒绝运营）。
  const isPlatformContent = name === "平台设置";
  const isBilling = name === "订阅与豆币";
  const isOperationLogs = name === "操作日志";
  const isAdminAccounts = name === "后台账号";
  const isUserManagement = name === "用户管理";
  const isUserRestrictions = isCommunityAdmin && communityAdminTab === "restrictions";
  document.querySelector("#dashboard").hidden = !isDashboard;
  document.querySelector("#ai-config").hidden = !isAiConfig;
  if (isAiConfig) renderAiConfigProxyWarning();
  document.querySelector("#ai-tasks").hidden = !isAiTasks;
  document.querySelector("#question-library").hidden = !isQuestionLibrary;
  document.querySelector("#textbook-catalog").hidden = !isTextbookCatalog;
  document.querySelector("#exam-admin").hidden = !isExamAdmin;
  document.querySelector("#pack-admin").hidden = !isPackAdmin;
  document.querySelector("#announcement-admin").hidden = !isAnnouncementAdmin;
  document.querySelector("#platform-content-admin").hidden = !isPlatformContent;
  document.querySelector("#moderation").hidden = !isModeration;
  document.querySelector("#billing-admin").hidden = !isBilling;
  document.querySelector("#operation-logs").hidden = !isOperationLogs;
  document.querySelector("#admin-accounts").hidden = !isAdminAccounts;
  document.querySelector("#user-management").hidden = !isUserManagement;
  document.querySelector("#user-restrictions").hidden = !isUserRestrictions;
  document.querySelector("#placeholder").hidden = isDashboard || isAiConfig || isAiTasks || isQuestionLibrary || isTextbookCatalog || isExamAdmin || isPackAdmin || isAnnouncementAdmin || isCommunityAdmin || isBilling || isOperationLogs || isAdminAccounts || isUserManagement || isPlatformContent;
  document.querySelector("#placeholder-title").textContent = name;
  const placeholderCopy = document.querySelector("#placeholder-copy");
  if (placeholderCopy) {
    placeholderCopy.textContent = "后续开发将在此接入真实数据库、权限校验和具体操作流程。";
  }
  if (isUserRestrictions) await loadUserRestrictions();
  if (isUserManagement) await loadUserManagement();
  if (isAdminAccounts) await loadAdminAccounts();
  if (isAiConfig) await loadAiConfig();
  if (isAiTasks) {
    await loadAiTasks();
    aiTaskRefreshTimer = setInterval(() => {
      if (state.currentView === "AI 任务记录") loadAiTasks();
    }, 10000);
  }
  if (isQuestionLibrary) {
    state.questionLibrary = name === "公共题库" ? "public" : "official";
    document.querySelector("#question-library-heading").textContent = state.questionLibrary === "official" ? "题库管理" : "公共题库";
    document.querySelector("#question-library-copy").textContent = state.questionLibrary === "official"
      ? "按科目、教材、章节和多级知识点统一管理题目与题族"
      : "审核用户贡献题目，并管理公共、精选、下架与转入平台题库状态";
    // 「题目录入」「知识档案」「完善题目」「AI 巡检」「盲测金标」只在官方题库下有意义
    ["authoring", "inspections", "gold-review", "dossiers", "enrichment"].forEach((key) => {
      const button = document.querySelector(`[data-question-library-tab="${key}"]`);
      if (button) button.hidden = state.questionLibrary !== "official";
    });
    if (state.questionLibrary !== "official") {
      state.questionLibraryTab = "library";
      state.questionWorkspaceMode = "questions";
    }
    if (["题族管理"].includes(name)) {
      state.questionLibraryTab = "library";
      state.questionWorkspaceMode = "families";
    }
    // 旧入口「题目完善」落到本子标签
    if (requestedEnrichment) state.questionLibraryTab = "enrichment";
    await loadQuestionCatalog();
    syncQuestionFilterBooks();
    renderQuestionStatusFilter();
    await loadKnowledgeStructure();
    setQuestionLibraryTab(state.questionLibraryTab);
  }
  if (isTextbookCatalog) await loadTextbooks();
  if (isExamAdmin) await loadExams();
  if (isPackAdmin) await loadPacks();
  if (isAnnouncementAdmin) await loadAnnouncements();
  if (isPlatformContent) await loadPlatformContent();
  if (isModeration) await loadModeration();
  if (isBilling) {
    setBillingTab(state.billingTab);
    await loadBilling();
  }
  if (isOperationLogs) await loadOperationLogs();
}

// 管理端通用提示弹窗入口。
// options.confirmLabel 可改确认按钮文案；options.confirmOnly 为真时隐藏"取消"（纯告知类提示）。
function openDialog(title, copy, options = {}) {
  document.querySelector("#dialog-title").textContent = title;
  document.querySelector("#dialog-copy").textContent = copy;
  const cancelButton = document.querySelector("#action-dialog-cancel");
  const confirmButton = document.querySelector("#action-dialog-confirm");
  if (cancelButton) cancelButton.hidden = options.confirmOnly === true;
  if (confirmButton) confirmButton.textContent = options.confirmLabel || "知道了";
  const dialog = document.querySelector("#action-dialog");
  if (dialog && !dialog.open) dialog.showModal();
}

// 侧边导航二级菜单：分组用 data-nav-sub 容器登记，同一时间只展开一个（手风琴）。
function navGroupOfView(viewName) {
  const container = [...document.querySelectorAll("[data-nav-sub]")]
    .find((item) => [...item.querySelectorAll("[data-view]")].some((button) => button.dataset.view === viewName));
  return container ? container.dataset.navSub : "";
}

function setNavGroupExpanded(group, expanded) {
  document.querySelectorAll("[data-nav-sub]").forEach((container) => {
    container.hidden = !(expanded && container.dataset.navSub === group);
  });
  document.querySelectorAll("[data-nav-group]").forEach((button) => {
    button.classList.toggle("is-expanded", Boolean(expanded) && button.dataset.navGroup === group);
  });
}

/** 子项用强高亮；分组标题只在“当前页在这个分组里”时用淡高亮，避免两处都像被选中。 */
function syncNavActive(name, communityAdminTab) {
  document.querySelectorAll(".nav-item").forEach((item) => {
    if (item.dataset.communityAdminTab) {
      item.classList.toggle("active", name === "社区管理" && item.dataset.communityAdminTab === communityAdminTab);
      return;
    }
    const isGroupHeader = Boolean(item.dataset.navGroup);
    item.classList.toggle("active", !isGroupHeader && item.dataset.view === name);
    if (isGroupHeader) item.classList.toggle("has-active", navGroupOfView(name) === item.dataset.navGroup);
  });
}

document.querySelector("#nav").addEventListener("click", (event) => {
  const groupButton = event.target.closest("[data-nav-group]");
  if (groupButton) {
    const group = groupButton.dataset.navGroup;
    const container = document.querySelector(`[data-nav-sub="${group}"]`);
    const willExpand = Boolean(container && container.hidden);
    // 收起：只收起，不动当前页（页面还在，标题栏不变）。
    if (!willExpand) {
      setNavGroupExpanded(group, false);
      return;
    }
    setNavGroupExpanded(group, true);
    // 展开：当前页不在这个分组里才跳到分组默认子页，避免“点开等于重进当前页”。
    if (navGroupOfView(state.currentView) !== group) openView(groupButton.dataset.navDefault);
    return;
  }
  const item = event.target.closest(".nav-item");
  if (!item || !item.dataset.view) return;
  if (item.dataset.communityAdminTab) state.communityAdminTab = item.dataset.communityAdminTab;
  openView(item.dataset.view);
});

