document.querySelector("#exam-recognized-list").addEventListener("change", (event) => {
  const card = event.target.closest(".exam-recognized-card");
  if (!card) return;
  if (event.target.matches('[data-exam-field="included"]')) card.classList.toggle("is-excluded", !event.target.checked);
  if (event.target.matches('[data-exam-field="included"], [data-exam-field="answerReviewStatus"]')) renderExamReviewFilterBar();
  if (event.target.matches('[data-exam-field="subjectId"]')) {
    card.querySelector('[data-exam-field="bookId"]').innerHTML = examBookOptions(event.target.value);
  }
  if (event.target.matches('[data-exam-field="scoringMode"]')) {
    const oneCorrectScore = card.querySelector('[data-exam-field="oneCorrectScore"]');
    if (oneCorrectScore) {
      const allowsPartialScore = event.target.value === "double_choice_partial";
      if (!oneCorrectScore.disabled) oneCorrectScore.dataset.partialScore = oneCorrectScore.value || "1";
      oneCorrectScore.disabled = !allowsPartialScore;
      oneCorrectScore.value = allowsPartialScore ? (oneCorrectScore.dataset.partialScore || "1") : "0";
    }
  }
});
