document.querySelector("#provider-form").addEventListener("submit", async (event) => {
  event.preventDefault();
  const saveButton = document.querySelector("#save-provider");
  saveButton.disabled = true;
  saveButton.textContent = "保存中";
  setProviderFormStatus("正在保存供应商配置", "loading");
  try {
    const payload = {
      id: document.querySelector("#provider-id").value,
      name: document.querySelector("#provider-name").value,
      protocol: document.querySelector("#provider-protocol").value,
      baseUrl: document.querySelector("#provider-base-url").value,
      apiKey: document.querySelector("#provider-api-key").value,
      models: document.querySelector("#provider-models").value,
      timeoutMs: Number(document.querySelector("#provider-timeout").value),
      supportsJsonMode: document.querySelector("#provider-json-mode").checked,
      enabled: document.querySelector("#provider-enabled").checked,
    };
    const response = await requestJson("/api/admin/ai/providers", { method: "POST", body: JSON.stringify(payload) });
    document.querySelector("#provider-dialog").close();
    resetProviderForm();
    await loadAiConfig(`${response.provider.name} 已保存`);
  } catch (error) {
    setProviderFormStatus(`保存失败：${friendlyError(error)}`, "error");
  } finally {
    saveButton.disabled = false;
    saveButton.textContent = "保存供应商";
  }
});

document.querySelector("#provider-list").addEventListener("change", (event) => {
  const checkbox = event.target.closest("[data-select-provider]");
  if (!checkbox) return;
  if (checkbox.checked) state.selectedProviderIds.add(checkbox.dataset.selectProvider);
  else state.selectedProviderIds.delete(checkbox.dataset.selectProvider);
  checkbox.closest(".provider-row").classList.toggle("is-selected", checkbox.checked);
  renderProviderSelectionTools();
});
