document.querySelector("#question-text-file").addEventListener("change", (event) => {
  const file = event.target.files && event.target.files[0];
  if (!file) return;
  document.querySelector("#question-file-name").textContent = `${file.name} · ${(file.size / 1024).toFixed(1)} KB`;
  if (file.size > 2 * 1024 * 1024) {
    setSmallDialogStatus("#question-import-status", "文件超过 2 MB，请拆分后上传", "error");
    return;
  }
  const reader = new FileReader();
  reader.onload = () => {
    document.querySelector("#question-import-text").value = String(reader.result || "");
    state.questionImportPreview = null;
    document.querySelector("#commit-question-import").disabled = true;
    setSmallDialogStatus("#question-import-status", "文本已载入，请解析预览", "success");
  };
  reader.onerror = () => setSmallDialogStatus("#question-import-status", "文件读取失败，请改用粘贴文本", "error");
  reader.readAsText(file, "utf-8");
});
