document.querySelector("#blind-gold-review-list").addEventListener("click", (event) => {
  const button = event.target.closest("[data-blind-gold-question-id]");
  if (!button || state.blindGoldReviewSaving) return;
  state.blindGoldBusinessEditMode = false;
  state.blindGoldContentEditable = false;
  state.selectedBlindGoldQuestionId = button.dataset.blindGoldQuestionId;
  setBlindGoldReviewFeedback();
  updateBlindGoldReviewListSelection(state.selectedBlindGoldQuestionId);
  if (state.blindGoldReviewRenderTimer) clearTimeout(state.blindGoldReviewRenderTimer);
  const renderSequence = Number(state.blindGoldReviewRenderSequence || 0) + 1;
  state.blindGoldReviewRenderSequence = renderSequence;
  state.blindGoldReviewRenderTimer = setTimeout(() => {
    state.blindGoldReviewRenderTimer = null;
    if (renderSequence !== Number(state.blindGoldReviewRenderSequence || 0)) return;
    const item = selectedBlindGoldReviewItem();
    renderBlindGoldReviewDetail();
    if (item) {
      void ensureBlindGoldReviewCatalog(item, { quiet: true }).then((catalogLoaded) => {
        const current = selectedBlindGoldReviewItem();
        if (!catalogLoaded || !current || current.questionId !== item.questionId
          || Number(current.revision || 0) !== Number(item.revision || 0)
          || state.blindGoldReviewSaving
          || current.formalFamilySync?.status !== "drift"
          || blindGoldReviewItemIsReadOnly(current, state.blindGoldReviewBatch)) return;
        // Switching to a question after the catalog is already cached must
        // recover the same way as a full page refresh. Keep the historical
        // snapshot for audit, but align the unsaved selectors with the live
        // formal relation before the reviewer submits.
        applyBlindGoldFormalFamilySyncToDraft();
        setBlindGoldReviewFeedback("检测到正式题族关系已更新，已将当前关系临时填入待审草稿；未自动保存或确认，请核对后提交。", "success");
      });
    }
  }, 0);
});
