document.querySelector("#knowledge-tree").addEventListener("click", (event) => {
  if (Date.now() < knowledgeTreeSuppressClickUntil) {
    event.preventDefault();
    return;
  }
  const editButton = event.target.closest("[data-edit-knowledge-node-id]");
  if (editButton) {
    openKnowledgeNodeDialog(editButton.dataset.editKnowledgeNodeId);
    return;
  }
  const toggleButton = event.target.closest("[data-knowledge-tree-toggle]");
  if (toggleButton) {
    const nodeId = toggleButton.dataset.knowledgeTreeToggle;
    if (state.collapsedKnowledgeNodeIds.has(nodeId)) state.collapsedKnowledgeNodeIds.delete(nodeId);
    else state.collapsedKnowledgeNodeIds.add(nodeId);
    renderKnowledgeTree();
    return;
  }
  const button = event.target.closest("[data-knowledge-node-id]");
  if (!button) return;
  state.selectedKnowledgeNodeId = button.dataset.knowledgeNodeId || "";
  expandKnowledgeNodeAncestors(state.selectedKnowledgeNodeId);
  renderKnowledgeTree();
  loadCurrentQuestionLibraryContent();
});
