document.querySelector("#generate-knowledge-structure").addEventListener("click", async () => {
  const button = document.querySelector("#generate-knowledge-structure");
  const bookId = document.querySelector("#question-book-filter").value;
  if (!bookId || bookId === "all") return;
  if (!window.confirm(`从目录补漏《${bookId}》的知识树？\n\n只会补上目录里有、树里还没有的节点；已有的节点不改名、不移动、不删除。执行前会自动存一份档。`)) return;
  button.disabled = true;
  try {
    const payload = await loadKnowledgeStructure("fill-gaps");
    if (payload) {
      const added = Number(payload.addedNodeCount) || 0;
      window.alert(added
        ? `已从目录补入 ${added} 个节点；原有 ${Number(payload.existingNodeCount) || 0} 个节点未改动。`
        : "目录里没有需要补的节点，知识树没有变化。");
      await loadCurrentQuestionLibraryContent();
    } else {
      window.alert("补漏失败：请确认该教材的目录已确认、正文库已构建。");
    }
  } finally {
    button.disabled = false;
  }
});
