document.querySelector("#question-family-table-body").addEventListener("click", async (event) => {
  const memberReview = event.target.closest("[data-question-family-member-review]");
  if (memberReview) {
    const { familyId, questionId, questionFamilyMemberReview: status } = memberReview.dataset;
    if (status === "confirmed") await reviewQuestionFamilyMember(familyId, questionId, "confirmed", "人工确认成员归属");
    else openQuestionFamilyMemberRejection(familyId, questionId);
    return;
  }
  const questionAction = event.target.closest("[data-question-action]");
  if (questionAction) {
    const { id, targetId, questionAction: action } = questionAction.dataset;
    if (action === "edit") await openQuestionEditor(id);
    else if (action === "versions") await openQuestionVersions(id);
    else if (action === "open-merged-target") await openQuestionEditor(targetId);
    else await transitionQuestion(id, action);
    return;
  }
  const questionOpen = event.target.closest("[data-question-open]");
  if (questionOpen) {
    if (state.questionFamilyManagementMode) {
      const questionId = questionOpen.dataset.questionOpen;
      setQuestionFamilyQuestionSelected(questionId, !state.questionSelectedIds.includes(questionId), questionOpen.dataset.questionFamilySource);
    } else await openQuestionEditor(questionOpen.dataset.questionOpen);
    return;
  }
  const setButton = event.target.closest("[data-question-family-set-action]");
  if (setButton) {
    if (setButton.dataset.questionFamilySetAction === "toggle") {
      if (state.expandedQuestionFamilySetIds.has(setButton.dataset.id)) state.expandedQuestionFamilySetIds.delete(setButton.dataset.id);
      else state.expandedQuestionFamilySetIds.add(setButton.dataset.id);
      renderQuestionFamilyTable();
    } else await openQuestionFamilySetDialog(setButton.dataset.id);
    return;
  }
  const button = event.target.closest("[data-question-family-action]");
  if (!button) return;
  if (button.dataset.questionFamilyAction === "generate") {
    await generateQuestionFamilies();
    return;
  }
  if (button.dataset.questionFamilyAction === "show-all-members") {
    const familyId = button.dataset.id;
    if (state.questionFamilySearchShowAllIds.has(familyId)) state.questionFamilySearchShowAllIds.delete(familyId);
    else state.questionFamilySearchShowAllIds.add(familyId);
    state.questionFamilySearchExpandedIds.add(familyId);
    renderQuestionFamilyTable();
    return;
  }
  if (button.dataset.questionFamilyAction === "toggle") {
    const searching = Boolean(normalizeQuestionFamilyWorkspaceQuery(document.querySelector("#question-family-search").value));
    const expandedIds = searching ? state.questionFamilySearchExpandedIds : state.expandedQuestionFamilyIds;
    if (expandedIds.has(button.dataset.id)) expandedIds.delete(button.dataset.id);
    else expandedIds.add(button.dataset.id);
    renderQuestionFamilyTable();
    return;
  }
  openQuestionFamilyReview(button.dataset.id);
});
