document.querySelector("#question-family-members").addEventListener("click", (event) => {
  const suggestionButton = event.target.closest("[data-use-family-member-contribution-suggestion]");
  if (suggestionButton) {
    const family = state.questionFamilies.find((item) => item.id === document.querySelector("#question-family-id").value) || {};
    const member = family.members?.find((item) => item.questionId === suggestionButton.dataset.useFamilyMemberContributionSuggestion) || {};
    const suggestion = new Set(questionFamilyMemberContributionSuggestionNodeIds(member, family));
    const row = suggestionButton.closest(".question-family-member");
    row?.querySelectorAll("[data-family-member-contribution-node]").forEach((button) => {
      const selected = suggestion.has(button.dataset.familyMemberContributionNode);
      button.setAttribute("aria-pressed", String(selected));
      button.classList.toggle("is-selected", selected);
    });
    suggestionButton.remove();
    return;
  }
  const contributionButton = event.target.closest("[data-family-member-contribution-node]");
  if (contributionButton) {
    const selected = contributionButton.getAttribute("aria-pressed") !== "true";
    contributionButton.setAttribute("aria-pressed", String(selected));
    contributionButton.classList.toggle("is-selected", selected);
    return;
  }
  const memberReview = event.target.closest("[data-question-family-member-review]");
  if (memberReview) {
    const { familyId, questionId, questionFamilyMemberReview: status } = memberReview.dataset;
    if (status === "confirmed") reviewQuestionFamilyMember(familyId, questionId, "confirmed", "人工确认成员归属");
    else openQuestionFamilyMemberRejection(familyId, questionId);
    return;
  }
  const editButton = event.target.closest("[data-open-question-fingerprint]");
  if (editButton) {
    document.querySelector("#question-family-dialog").close();
    openQuestionEditor(editButton.dataset.openQuestionFingerprint);
    return;
  }
  const button = event.target.closest("[data-remove-question-family-member]");
  if (button) removeQuestionFamilyMember(button.dataset.removeQuestionFamilyMember);
});
