document.querySelector("#question-table-body").addEventListener("click", async (event) => {
  const groupButton = event.target.closest("[data-question-group-action]");
  if (groupButton) {
    const ids = String(groupButton.dataset.questionGroupIds || "").split(",").filter(Boolean);
    await transitionQuestionGroup(ids, groupButton.dataset.questionGroupAction);
    return;
  }
  const button = event.target.closest("[data-question-action]");
  if (!button) return;
  const { questionAction, id, targetId } = button.dataset;
  if (questionAction === "edit") await openQuestionEditor(id);
  else if (questionAction === "versions") openQuestionVersions(id);
  else if (questionAction === "open-merged-target") await openQuestionEditor(targetId);
  else await transitionQuestion(id, questionAction);
});
