document.querySelector("#question-family-membership-list").addEventListener("click", (event) => {
  const trigger = event.target.closest("[data-question-membership-contribution-picker] .question-family-multiselect-trigger");
  if (trigger) {
    const root = trigger.closest("[data-question-membership-contribution-picker]");
    setQuestionMembershipContributionPickerOpen(root, !questionFamilyMultiselectIsOpen(root));
    return;
  }
  const contributionOption = event.target.closest("[data-question-membership-contribution-option]");
  if (contributionOption) {
    const root = contributionOption.closest("[data-question-membership-contribution-picker]");
    const familyId = root?.dataset.questionMembershipContributionPicker;
    const membership = state.questionMembershipDraft.find((item) => item.familyId === familyId);
    if (!membership) return;
    const selectedIds = questionMembershipContributionSelectedIds(membership);
    if (contributionOption.checked) selectedIds.add(contributionOption.value);
    else selectedIds.delete(contributionOption.value);
    membership.contributionKnowledgeNodeIds = [...selectedIds];
    const select = root.querySelector("[data-question-membership-contribution-select]");
    [...(select?.options || [])].forEach((option) => { option.selected = selectedIds.has(option.value); });
    renderQuestionMembershipContributionPicker(root);
    return;
  }
  const roleButton = event.target.closest("[data-question-membership-role]");
  if (roleButton) {
    state.questionMembershipDraft = state.questionMembershipDraft.map((membership) => {
      if (membership.familyId !== roleButton.dataset.questionMembershipFamilyId || membership.isPrimary) return membership;
      const coverageRole = roleButton.dataset.questionMembershipRole;
      return {
        ...membership,
        coverageRole,
        contributionKnowledgeNodeIds: coverageRole === "reference" ? [] : membership.contributionKnowledgeNodeIds,
      };
    });
    renderQuestionMembershipEditor();
    return;
  }
  const suggestionButton = event.target.closest("[data-use-question-membership-suggestion]");
  if (suggestionButton) {
    state.questionMembershipDraft = state.questionMembershipDraft.map((membership) => membership.familyId === suggestionButton.dataset.useQuestionMembershipSuggestion
      ? { ...membership, contributionKnowledgeNodeIds: questionMembershipContributionSuggestion(membership) }
      : membership);
    renderQuestionMembershipEditor();
    return;
  }
  const button = event.target.closest("[data-remove-question-membership]");
  if (!button) return;
  state.questionMembershipDraft = state.questionMembershipDraft.filter((membership) => membership.familyId !== button.dataset.removeQuestionMembership);
  renderQuestionMembershipEditor();
});
